\section{Problem formulation}
\label{sec:2}
In the following, we present the nominal MI-MPC problem and the analogous formulation for DPC, specific to the numerical example presented in Section \ref{sec:4}. 

We assume the control problem of a linear time-invariant discrete-time deterministic system given by
\begin{equation}\label{eq:state-space}
    x_{k+1}=Ax_k+B_\mathrm{u}u_k+B_\delta\delta_k+Ed_k,
\end{equation}
where $u\in\mathbb{R}^{n_u}$ and $\delta\in\mathbb{Z}^{n_\delta}$ denote the continuous- and integer-valued control inputs, respectively, $d\in\mathbb{R}^{n_d}$ denotes the vector of known disturbances and $x\in\mathbb{R}^{n_x}$ is the state vector at discrete time step $k$. The matrices $A$, $B_u$, $B_\delta$, and $E$ are of respective dimensions. Furthermore, we assume that the system is controllable and is subjected to linear input and state constraints
\begin{equation}
    x_k\in\pazocal{X}, \;u_k\in\pazocal{F}, \;\delta_k\in\pazocal{D},\;\forall k\geq0,
\end{equation}
where $\pazocal{X}\subset\mathbb{R}^{n_x}$ and $\pazocal{F}\subset\mathbb{R}^{n_u}$  are compact convex sets. The constraints contained in the set of feasible integers $\pazocal{D}\subset\mathbb{Z}^{n_\delta}$ are commonly referred to as integrality constraints.

\subsection{Mixed-Integer Model Predictive Control}
For simplicity, we consider the nominal single-shooting MI-MPC formulation, with the control objective defined by stage cost $\ell_\pazocal{K}$ as the squared Euclidean weighted norm of the control error, integer-, and continuous-valued control inputs and a terminal cost $\ell_\pazocal{N}$. The control error is defined as the difference between the state $x$ and the reference $r\in\mathbb{R}^{n_x}$. We define stage and terminal costs as
\begin{subequations}
    \begin{align}
        \ell_\pazocal{K}(x_k,r_k,u_k,\delta_k)&=
       \!\|x_k\!-\!r_k\|_Q^2+\|u_k\|_R^2+\|\delta_k\|^2_\rho,\\
       \ell_\pazocal{N}(x_k,r_k)&=\|x_k\!-\!r_k\|_P^2,
    \end{align}
\end{subequations}
% where the weight matrices $P\succeq0$, $Q\succeq0$, $R\succ0$, $\rho\succ0$ are of obvious dimensions.
where the weight matrices $P$, $Q$, and $R$, $\rho$ are positive semi-definite and positive definite, respectively, and of obvious dimensions. 
Next, using these control objective components, let us formulate the MI-MPC problem as
\begin{subequations} \label{eq:mi-mpc}
    \begin{align}
       \min_{u,\delta}&\;\ell_\pazocal{N}(x_N,r_N)
       \!+\!\sum_{k=0}^{N-1}
       \ell_\pazocal{K}(x_k,r_k,u_k,\delta_k) \label{eq:mi-mpc-loss} \\
         \text{s.t.}& \;
        x_{k+1}  = Ax_k+B_\mathrm{u}u_k+B_\delta\delta_k+Ed_k, \label{eq:mi-mpc-model} \\
       &\quad u_k  \in \pazocal{F},\;\;\delta_k \in \pazocal{D}, \quad \forall k\in\{0,1,\dots,N\!-\!1\},\label{eq:mi-mpc-input-constraints}
       \\
        &\quad x_k  \in \pazocal{X}, \quad\quad\quad\quad\;\;\; \forall k\in\{0,1,\dots,N\}, \label{eq:mi-mpc-state-constraints}
    \end{align}
\end{subequations}
where $N\in\mathbb{Z}^+$ denotes the length of the prediction horizon.

Now, after substituting the system dynamics \eqref{eq:mi-mpc-model} into the loss function \eqref{eq:mi-mpc-loss} and transforming the constraints \eqref{eq:mi-mpc-input-constraints} and \eqref{eq:mi-mpc-state-constraints} accordingly, the original MI-MPC problem \eqref{eq:mi-mpc} can be cast as a mixed-integer quadratic program:
%\vspace{-1.5ex}
\begin{subequations} \label{eq:miqp}
    \begin{align}
       \min_{z_k}&\;z_k^\mathsf{T}\pazocal{H}_k z_k - \pazocal{G}_k^\mathsf{T}z_k\\
       \text{s.t.}&\;
       \Omega z_k\leq\omega_k,
    \end{align}
\end{subequations}
where
$z_k\!=\!\big[\upsilon_k^\mathsf{T},\upsilon_{k+1}^\mathsf{T}, \dots, \upsilon_{k+N-1}^\mathsf{T}\big]^\mathsf{T}\in\mathbb{R}^{N(n_u+n_\delta)}$ combines the integer- and continuous-valued control inputs $\upsilon_k\!=\!\big[u_k, \delta_k\big]^\mathsf{T}$ for the entire horizon length. 
% For a detailed mathematical derivation, we refer reader to \cite{maciejowski2007predictive}.

As mentioned above, due to the combinatorial nature, these problems are computationally demanding to solve, where finding the optimal solution may scale exponentially with the size of the problem. The goal of this paper is to avoid the computational burden of solving the given problem by formulating it within the DPC framework, which was shown to be computationally efficient in solving medium to large-scale MPC problems \cite{DRGONA2021buildings}.

\subsection{Parametric Mixed-Integer Optimal Control Problem}
 Considering the system \eqref{eq:state-space}, we formulate the parametric MI-OCP as
\begin{subequations} \label{eq:dpc}
    \begin{align}
       \min_{\theta}  \, \!\mathbb{E}_{  \xi_k \sim P_{ \xi} }\,&\!  
       \bigg[\ell_\pazocal{N}(x_N, r_N)+\sum_{k=0}^{N-1}\!\!   \ell_\pazocal{K}(x_k, r_k, u_k, \delta_k)\bigg]  \label{eq:dpcloss} \\
       \text{s.t.} \;
        x_{k+1} & = Ax_k+B_\mathrm{u}u_k+B_\delta\delta_k+Ed_k, \label{eq:dpc-model} \\
        [u_k,\;\delta_k] & = {\pi}_{\theta}(\xi_k), \label{eq:dpcinput} \\
         u_k  \in \pazocal{F}&,\;\delta_k \in \pazocal{D}, \quad \forall k\in\{0,1,\dots,N\!-\!1\}, \label{eq:dpcinputconstraint} \\
        x_k  \in \pazocal{X}&, \quad\quad\quad\quad\;\; \forall k\in\{0,1,\dots,N\},\label{eq:dpcstateconstraint}
        % \boldsymbol{\xi}_k & \in \Xi^{\mathrm{ctrl}} \subset \mathbb{R}^n,
    \end{align}
\end{subequations}
where \eqref{eq:dpcloss} represents a parametrized MPC objective function, sampled with control parameters $\xi_k$ of a known probability distribution $P_\xi$. The vector of control parameters consists of all known or estimated variables that are used to calculate the control input. For example, in the case of a constant reference $r$, constant state and input constraints, and known future disturbances $d$, the vector would be defined by initial condition $x_k$ and a sequence of future disturbances as $\xi_k\!=\![x_k^\mathsf{T},\,d_k^\mathsf{T},\dots,d_{k+N-1}^\mathsf{T}] \in \mathbb{R}^{n_\xi}$. These conditions hold for the numerical example presented in Section \ref{sec:4}; henceforth $\xi_k$ will be assumed as such. Here, the system dynamics model \eqref{eq:dpc-model}, is used to obtain the $N$-steps long closed-loop trajectories, where the control inputs $u_k$ and $\delta_k$ are calculated by the control policy $\pi_\theta\!:\! \mathbb{R}^{n_\xi}\!\mapsto\!\mathbb{R}^{n_u}\!\times \!\mathbb{R}^{n_\delta}$, which is parametrized by a set of parameters $\theta$. 



\section{Methodology}
\label{sec:3}

\subsection{Differentiable Predictive Control}
Differentiable predictive control (DPC) is an offline policy optimization method in which the parametric optimal control problem is formulated as a differentiable program~\cite{drgona2022,drgona2024}. Here, the control policy can be represented by an arbitrary differentiable function, most commonly a neural network, for its parameter efficiency and expressive capacity.
To be able to cast MI-OCP \eqref{eq:dpc} as a differentiable program, in DPC, we consider the relaxation of state and input constraints using the penalty, Lagrangian relaxation, or Barrier methods. This gives us a dual problem that is convex, assuming that the primal problem is convex \cite{boyd2004}.
With the penalty method-based relaxation, the problem is formulated as
\begin{subequations} \label{eq:dpc-dual-hard}
    \begin{align}
        \begin{split}
        \begin{aligned}[t]
       \min_{\theta}  \, \mathbb{E}_{\xi_k \sim P_{ \xi} }&\,  
       \bigg[\|x_N\!-\!r_N\|_P^2
       \!+\!\sum_{k=0}^{N-1}\!\|x_k\!-\!r_k\|_Q^2\\ +\|u_k\|_R^2&+\|\delta_k\|^2_\rho\!+\!c_xq(x_k, x_N)\!+\!c_up(u_k)\bigg]   
       \end{aligned}
       \end{split}
       \label{eq:dpc-dual-hard-loss} \\
       &\text{s.t.} \;
        x_{k+1}=Ax_k+B_\mathrm{u}u_k+B_\delta\delta_k+Ed_k, \label{eq:dpc-model-dual-hard}\\ 
       & \;[u_k,\;\delta_k] = {\pi}_{\theta}(\xi_k).& \label{eq:dpc-policy-hard}
    \end{align}
\end{subequations}


Assuming differentiability of the model \eqref{eq:dpc-model-dual-hard} and the con-trol policy \eqref{eq:dpc-policy-hard}, the parametric OCP \eqref{eq:dpc-dual-hard} can be implemented with a differentiable programming framework, such as PyTorch or Julia, where parameters of the control policy $\theta$ are optimized using some variant of stochastic gradient descent, so that the loss function \eqref{eq:dpc-dual-hard-loss} is minimized. To compute the gradients of the total loss $\ell$ with respect to the policy parameters, we employ the chain rule as
\begin{align}
\label{eq:grad}
    \nabla_{\theta} \ell = & \, \frac{ \uppartial\ell_\pazocal{K}}{\uppartial \theta}  +  
    \frac{ \uppartial \ell_\pazocal{N}}{\uppartial \theta} +
    \frac{ \uppartial q(x)}{\uppartial \theta} + 
    \frac{ \uppartial p(u)}{\uppartial \theta} \nonumber\\
     = & \, \frac{ \uppartial\ell_\pazocal{K}}{\uppartial x} \frac{ \uppartial x}{\uppartial u} \frac{ \uppartial u}{\uppartial \theta}
     +\frac{ \uppartial\ell_\pazocal{K}}{\uppartial x} \frac{ \uppartial x}{\uppartial \delta} \frac{ \uppartial \delta}{\uppartial \theta}
     +\frac{ \uppartial\ell_\pazocal{K}}{\uppartial u}  \frac{ \uppartial u}{\uppartial \theta} +\frac{ \uppartial\ell_\pazocal{K}}{\uppartial \delta}  \frac{ \uppartial \delta}{\uppartial \theta}\nonumber\\
    %  &+ \frac{ \uppartial q(x)}{\uppartial x}  \frac{ \uppartial x}{\uppartial \upsilon} \frac{ \uppartial \upsilon}{\uppartial \theta}
    % + \frac{ \uppartial p(u)}{\uppartial u} \frac{ \uppartial u}{\uppartial \theta} 
    &+ \frac{ \uppartial \ell_\pazocal{N}}{\uppartial x} \frac{ \uppartial x}{\uppartial u} \frac{ \uppartial u}{\uppartial \theta} + \frac{ \uppartial \ell_\pazocal{N}}{\uppartial x} \frac{ \uppartial x}{\uppartial \delta} \frac{ \uppartial \delta}{\uppartial \theta} + \frac{ \uppartial q(x)}{\uppartial x}  \frac{ \uppartial x}{\uppartial u} \frac{ \uppartial u}{\uppartial \theta}\nonumber\\
    &+ \frac{ \uppartial q(x)}{\uppartial x}  \frac{ \uppartial x}{\uppartial \delta} \frac{ \uppartial \delta}{\uppartial \theta}+ \frac{ \uppartial p(u)}{\uppartial u} \frac{ \uppartial u}{\uppartial \theta},
\end{align}
where $\sfrac{ \uppartial u}{\uppartial \theta}$ and $\sfrac{ \uppartial \delta}{\uppartial \theta}$ represent the gradients of continuous and discrete control inputs, respectively, computed using the backpropagation through time algorithm \cite{puskorius1994}. 


