%      \log L = {}& \mathbb{E}_{I_t}  \left[\int_0^\infty \ell \left(t\right) {\rm d} t\right], \\
%      \ell \left(t\right) := {}& \sum_{s=\left(\bar{\nu}, x,y,c\right)} \left[ \bar{r}^\text{NN}_{s} -  \bar{r}_{s}\log \bar{r}_{s}^\text{NN}  \right], 
% \end{align}
% \end{subequations}
% \begin{align}
%     \mathbb{E}_{I_t}  {}&  \left[\int_0^\infty \sum_{\bar{\nu},x,y,c} \left[ \bar{r}^\text{NN}_{\bar{\nu},x,y,c} \left(I_t,t\right ) \right. \right. \nonumber \\
%     {}& \left. \vphantom{\int_0^\infty} \left. -  \bar{r}_{\bar{\nu},x,y,c}\left(t\right)\log \bar{r}_{\bar{\nu},x,y,c}^\text{NN} \left(I_t,t\right ) \right] {\rm d} t \right] \label{eq:likelihood-cts}
% \end{align}
Because we only observe the process at discrete times prescribed in Eq.~\eqref{eq:observationTimes}, we approximate the continuous-time integration above by 
\begin{equation}
     \log L =\mathbb{E}_{I_{t_k}, k}  \left[ \left(t_k - t_{k-1}\right) \sum \left( \bar{r}^\text{NN} -  \bar{r}\log \bar{r}^\text{NN}  \right)\right], \label{eq:likelihood}
\end{equation}
