\section{Deriving reverse-time transition rates} \label{app:reverseRate}
Here, we derive the reverse-time transition rate. Because the particles are moving independently, it is sufficient to discuss $n$ particles colocalized at $(x,y)$ in channel $c$, and the conclusion applies to other locations and color channels. For brevity, we will drop the $(x,y,c)$ dependence in this section when the context is clear. Let us index the particles by $i=1\ldots n = \left[I_t\right]_{x,y,c}$. For each of the $n$ particles, the reverse-time transition rates moving to $(x+{\bar{\nu}}_x, y+{\bar{\nu}}_y)$, where $\left({\bar{\nu}}_x, {\bar{\nu}}_y\right) \in  \left\{\left(-1,0\right), \left(1,0\right),\left(0,-1\right), \left(0,1\right)\right\}$ is
\begin{equation}
    \bar{r}^{[i]}_{{\bar{\nu}}}(t) = r\frac{p_t\left(x+{\bar{\nu}}_x, y+{\bar{\nu}}_y, c\vert x_0^{[i]}, y_0^{[i]}, c_0^{[i]}\right)}{p_t\left(x,y,c\vert x_0^{[i]}, y_0^{[i]}, c_0^{[i]}\right)}, \label{eq:reverseRate-app}
\end{equation}
according to the general theory of reverse-time dynamics for continuous-time Markov systems \cite{campbell2022,blackout}. We now perform the survival analysis for the inhomogeneous process. Within time ${\rm d} t$, the probability that particle $i$ leaves $(x,y,c)$ and moves to $(x+{\bar{\nu}}_x, y+{\bar{\nu}}_y, c)$ is $\bar{r}_{\bar{\nu}}^{i} \left(t\right) {\rm d}t + \mathcal{O}\left({\rm d} t^2\right)$. As such, the probability of the particle remains at $(x,y,c)$ at time $t - {\rm d}t $ is $1- \sum_{{\bar{\nu}}} \bar{r}_{\bar{\nu}}^{[i]} \left(t\right) {\rm d}t + \mathcal{O}\left({\rm d} t^2\right) $. Thanks to the independence between the particle dynamics, the probability of \textit{all} $n$ particles remaining at $(x,y,c)$ at time $t - {\rm d}t $ (recall that we are evolving the reverse-time dynamics) is $1-\sum_{i=1}^n \sum_{{\bar{\nu}}} \bar{r}_{\bar{\nu}}^{[i]} \left(t\right) {\rm d}t + \mathcal{O}\left({\rm d} t^2\right) $. Then, the probability of \textit{no} particle leaving at a previous time $t-\Delta t$, where $\Delta t:=N {\rm d}t $ is
\begin{equation}
    \prod_{k=1}^N \left[1-\sum_{i=1}^n \sum_{{\bar{\nu}}} \bar{r}_{\bar{\nu}}^{[i]} \left( t-\left(k-1\right) {\rm d} t\right) {\rm d}t\right] + \mathcal{O}\left({\rm d} t^2\right),
\end{equation}
which by sending ${\rm d} t \downarrow 0$ leads to the continuous-time survival function:
\begin{equation}
    \mathbb{P}\left\{ \mathcal{T} > t\right\}= \exp \left[ - \int_0^t \sum_{i,{\bar{\nu}}} \bar{r}^{[i]}_{\bar{\nu}}(t') {\rm d} t' \right],
\end{equation}
where $\mathcal{T}$ is the random time of the first particle moving out of $(x,y,c)$, the sum is over all possible directions and all particle index $i\in \left\{1\ldots n\right\}$. Identifying the total rate $\sum_{i,{\bar{\nu}}} \bar{r}^{[i]}_{\bar{\nu}}(t') {\rm d} t'$ and the reverse-time transition rate for each particle and in each direction, Eq.~\eqref{eq:reverseRate-app}, we arrived at Eq.~\eqref{eq:reverseRates}.  

\section{Training and generation algorithms.}

Algorithm~\ref{alg:training} gives the training algorithm using standard gradient descent techniques, and Algorithm~\ref{alg:inference} gives the inference algorithm used in this work.
\begin{algorithm}[tb]
   \caption{DSD training}
   \label{alg:training}
\begin{algorithmic}
    \STATE Given the full transition probabilities $p_t(x',y',c'\vert x, y, c)$
   \REPEAT
   \STATE $I_0 \leftarrow $ a sample drawn from the training set
   \STATE Draw an index $k$ from $\left\{1, \ldots T\right\}$ uniformly
   \FOR {Each discrete intensity unit in $[I_0]_{x,y,c}$}
        \STATE  Draw $(x',y',c') \sim p_t(x',y',c'\vert x,y,c)$
        \STATE Move the unit from $(x,y,c)$ to $(x',y',c')$
   \ENDFOR
   \STATE $I_{t_k} \leftarrow $ the corrupted image
   \STATE Compute the reverse transition rate Eq.~\eqref{eq:reverseRates}
   \IF{Using $L^1$ rate-matching}
   \STATE $\text{Loss} \leftarrow \sum_{x,y,c,\bar{\nu}} \left\vert \bar{r}^\text{NN} - \bar{r} \right\vert $ 
   \ELSIF{Using likelihood loss}
   \STATE $\text{Loss} \leftarrow -\log L$, defined in Eq.~\eqref{eq:likelihood} 
   \ENDIF
   \STATE Take a gradient step on $\nabla_\theta \text{Loss}$
   \UNTIL{Converged}
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[tb]
   \caption{DSD inference}
   \label{alg:inference}
\begin{algorithmic}
   \STATE Given CFL condition number $\varepsilon <1$ and desired total intensities in the color channels, initiate an image $I_0$ with desired total intensities in the color channels
   \FOR {Each discrete intensity unit in $[I_0]_{x,y,c}$}
        \STATE  Draw $(x',y',c') \sim p_{1}(x',y',c'\vert x,y,c)$
        \STATE Move the unit from $(x,y,c)$ to $(x',y',c')$
   \ENDFOR
   \STATE $I_{1} \leftarrow $ the fully corrupted image, $t\leftarrow 1$
   \WHILE{$t>0$}
   \STATE Evaluate NN predicted reverse rates $\bar{r}^\text{NN}_{\bar{\nu},x,y,c}$
   \STATE $\tau \leftarrow \min \left\{t, \mathbf \varepsilon \min_{\bar{\nu}, x,y,c} \left(\bar{r}^\text{NN}_{\bar{\nu},x,y,c}\right)^{-1} \right\}$
   \FOR {each $(x,y,c)$}
   \STATE Sample total moving particles: 
   \STATE $n_\Sigma \sim \text{Binom}\left( \left[I_t\right]_{x,y,c}, \sum_{\bar{\nu}} \bar{r}^\text{NN}_{\bar{\nu},x,y,c} \right)$
   \STATE Sample a direction $\bar{\nu}$ for each moving particle:
   \STATE $n_{\bar{\nu}} \sim \text{Multinomial}\left(n_\Sigma, p_{\bar{\nu}} = \frac{\bar{r}^\text{NN}_{\bar{\nu},x,y,c} }{\sum_{\bar{\nu}'} \bar{r}^\text{NN}_{\bar{\nu}',x,y,c} }\right)$
   \STATE Move $n_{\bar{\nu}}$ intensity units to $(x+\bar{\nu}_x,y+\bar{\nu}_y)$
   \ENDFOR
   \STATE Advance time: $t \leftarrow t - \tau $
   \STATE $I_t \leftarrow $ the configuration after movements
   \ENDWHILE
\end{algorithmic}
\end{algorithm}



