\section{Spectral representation of DSD with periodic boundary conditions}\label{app:DSD-FT}

\newcommand{\dd}{\text{d}}
Let us consider the two-dimensional DSD with periodic boundary conditions, whose master equation \cite{weberMasterEquationsTheory2017} is
\begin{equation}
\frac{\dd }{\dd t} p_{k,\ell}(t) = r p_{k-1,\ell}(t) + rp_{k+1,\ell}(t) + rp_{k,\ell-1}(t) + rp_{k,\ell+1}(t)  - 4 r p_{k,\ell}(t).
\end{equation}
Here, we use periodic boundary conditions, $p_{i\pm N,\ell} = p_{k,\ell}$, $p_{k,\ell\pm N} = p_{k,\ell}$ over the domain $(k,\ell)\in \left\{1, \ldots N_x \right\} \times  \left\{1, \ldots N_y \right\}$. 
% Formally, we can write this master equation in the following form:
% \begin{equation}
% \frac{\dd }{\dd t} p_{k,l}(t) = r L p_{k,l}(t) := r \left(L_x + L_y\right) \, p_{k,l}(t),
% \end{equation}
% where $L_x$ and $L_y$ are one-dimensional discrete-state Laplace operators defined by
% \begin{subequations}
% \begin{align}
% L_x p_{k,l} \triangleq{}& p_{k+1,j} + p_{k-1,j} - 2 p_{k,l},\\
% L_y p_{k,l} \triangleq{}& p_{k,l+1} + p_{k,l-1} - 2 p_{k,l}. 
% \end{align}
% \end{subequations}
We can formally treat $p_{k,l}$ as a rank-2 tensor. 
We can write the one-dimensional discrete-space Laplace operator:
\begin{equation}
    \left[\mathbf{L}_{x,y}\right]_{\mu,\nu} := \delta_{\mu+1,\nu} + \delta_{\mu-1,\nu} -2 \delta_{\mu,\nu}
\end{equation}
where $\mathbf{L}_x$ is $N_x\times N_x$ and $\mathbf{L}_y$ is $N_y \times N_y$, $\delta$ is the Kronecker delta. 
Then, we can write the two-dimensional master equation succinctly as
\begin{equation}
    \frac{\dd}{\dd t} \mathbf{p}(t) = r \left(\mathbf{L}_x \otimes I + I\otimes \mathbf{L}_y \right) \mathbf{p}(t).
\end{equation}


We aim to identify the spectral representation of the full operator $L$. To achieve this, we first define the two-dimensional discrete Fourier and inverse Fourier transformations:
\begin{subequations}\label{eq:plainFourierTransform}
    \begin{align}
    k_{m,n} (t) :={}& \frac{1}{\sqrt{N}} \sum_{k=1}^{N_x} \sum_{\ell=1}^{N_y} e^{-2\pi i \left(\frac{m k}{N_x} + \frac{n \ell}{N_y}\right) } p_{k,\ell}(t), \\
    p_{k,\ell} (t) :={}& \frac{1}{\sqrt{N}} \sum_{m=1}^{N_x} \sum_{n=1}^{N_y} e^{2\pi i\left(\frac{m k}{N_x} + \frac{n \ell}{N_y}\right) } k_{m,n}(t).
    \end{align}
\end{subequations}
To simplify the notation, we write $U_x$ and $U_y$ as the one-dimensional inverse discrete Fourier transformation 
\begin{equation}
    \left[\mathbf{U}_{x,y}\right]_{\mu,\nu}= \frac{1}{\sqrt{N}} e^{2 \pi i \frac{\mu \nu}{N_{x,y}} }.
\end{equation}
and again use the tensor notation. Then, Eqs.~\eqref{eq:plainFourierTransform} can be succinctly represented as
\begin{subequations}\label{eq:FourierTransform}
    \begin{align}
    \mathbf{k} (t) :={}& \left(\mathbf{U}_x \otimes I \right)^\dagger \left(I\otimes \mathbf{U}_y \right)^\dagger \mathbf{p} (t), \\
    \mathbf{p} (t) :={}& \left(\mathbf{U}_x \otimes I \right) \left(I\otimes \mathbf{U}_y \right) \mathbf{k} (t).
    \end{align}
\end{subequations}

The master equation in the spectral space can be derived now:
\begin{align}
    \frac{\dd}{\dd t} \mathbf{k} (t) :={}& \left(\mathbf{U}_x \otimes I \right)^\dagger \left(I\otimes \mathbf{U}_y \right)^\dagger \frac{\dd}{\dd t} \mathbf{p} (t) \nonumber \\
    = {}&r \left(\mathbf{U}_x \otimes I \right)^\dagger \left(I\otimes \mathbf{U}_y \right)^\dagger \left(\mathbf{L}_x \otimes I + I\otimes \mathbf{L}_y \right) \mathbf{p}(t) \nonumber \\
    = {}& r\left(\mathbf{U}_x \otimes I \right)^\dagger \left(I\otimes \mathbf{U}_y \right)^\dagger \left(\mathbf{L}_x \otimes I + I\otimes \mathbf{L}_y \right) \left(\mathbf{U}_x \otimes I \right) \left(I\otimes \mathbf{U}_y \right) \mathbf{k} (t) \nonumber \\
    ={}& r \left(\mathbf{U}_x^\dagger \mathbf{L}_x \mathbf{U}_x \otimes I + I\otimes \mathbf{U}_y^\dagger \mathbf{L}_y \mathbf{U}_y  \right) \mathbf{k} (t)
\end{align}
because $\mathbf{U}_x^\dagger \mathbf{U}_x=\mathbf{U}_y^\dagger \mathbf{U}_y =\mathbf{I}$. 

Let us now explicitly compute $\mathbf{U}_x^\dagger \mathbf{L}_x \mathbf{U}_x$:
\begin{align}
\left[\mathbf{U}_x^\dagger \mathbf{L}_x \mathbf{U}_x\right]_{k,\ell} ={}& \sum_{m=1}^{N_x} \sum_{n=1}^{N_x} \left[\mathbf{U}_x\right]_{k, m}^{\dagger} \left[\mathbf{L}_x\right]_{m,n} \left[\mathbf{U}_x\right]_{n, \ell} \nonumber \\
={}& \sum_{m=1}^{N_x} \sum_{n=1}^{N_x} \frac{1}{N} e^{2\pi i \frac{mk-n\ell}{N_x}} \left(\delta_{m+1,n}+\delta_{m-1,n} - 2 \delta_{m,n}\right)\nonumber \\
={}& \sum_{m=1}^{N_x} \frac{1}{N} \left(e^{2\pi i \frac{mk-\left(m+1\right)\ell}{N_x}} + e^{2\pi i \frac{mk-\left(m-1\right)\ell}{N_x}} - 2 e^{2\pi i \frac{mk-m\ell}{N_x}} \right) \nonumber \\
={}& \sum_{m=1}^{N_x} \frac{1}{N} e^{2\pi i \frac{m \left(k-\ell\right)}{N_x}} \left(e^{-\frac{2\pi i \ell}{N_x} } + e^{+\frac{2\pi i \ell}{N_x}} - 2 \right) \nonumber \\
={}& \left( 2 \cos \left( \frac{2 \pi \ell}{N_x} \right) - 2 \right) \delta_{k,\ell} =  4 \sin^2 \left( \frac{2 \pi \ell}{N_x} \right) \delta_{k,\ell} .
\end{align}
This shows that the process in the spectral space is diagonal with a cosine spectrum. The same analysis applies to $\mathbf{U}_y^\dagger \mathbf{L}_y \mathbf{U}_y$. Thus, element-wise, in the discrete Fourier space, we have
\begin{equation}
    \frac{\dd}{\dd t} k_{m,n} (t) = 4 r \left[ \sin^2 \left(\frac{\pi m}{N_x}\right)+ \sin^2 \left(\frac{\pi n}{N_y}\right)\right] k_{m,n}(t),
\end{equation}
which means
\begin{equation}
    k_{m,n} (t) = e^{4  \left[ \sin^2 \left(\frac{\pi m}{N_x}\right)+ \sin^2 \left(\frac{\pi n}{N_y}\right)\right] rt } k_{m,n} (0). 
\end{equation}

In practice, we can always shift the particle of interest at $t=0$ at the origin, i.e., $p_{0,0}(0)=1$ and $p_{i,j}=0$ if $(i,j)\ne (0,0)$. Then, $k_{m,n}(0) = \frac{1}{N}$ and consequently
\begin{equation}
    k_{m,n}(t) =  \frac{1}{N} e^{4  \left[ \sin^2 \left(\frac{\pi m}{N_x}\right)+ \sin^2 \left(\frac{\pi n}{N_y}\right)\right] rt },
\end{equation}
so the analytical solution of $p_{k, \ell}$ can be expressed as
\begin{equation}
    p_{k,\ell}(t) =  \frac{1}{\sqrt{N}^3}  \sum_{m=1}^{N_x} \sum_{n=1}^{N_y} e^{2\pi i\left(\frac{m k}{N_x} + \frac{n \ell}{N_y}\right) + 4  \left[ \sin^2 \left(\frac{\pi m}{N_x}\right)+ \sin^2 \left(\frac{\pi n}{N_y}\right)\right] rt}. 
\end{equation}
Note that the double sum can be carried out in one two-dimensional Fast Fourier Transformation. The above equation allows us to compute the transition probability efficiently. 





