\subsection{Comparison with the Conventional ULA}
Next, we compare the proposed RAA with the conventional ULA with HBF, where the analog beamforming is implemented using discrete Fourier transform (DFT) codebook. % as illustrated in Fig. \ref{architecture3}.
The array response vector of the $M$-element ULA for the path angle $\phi$, denoted by $\vec{a}_{\text{ULA}}(\phi)\in \mathbb{C}^{M\times 1}$, is given by
\begin{equation}\label{ULA}
  \vec{a}_{\text{ULA}}(\phi)=\bigl[1,e^{j\pi\sin\phi},\cdots,e^{j\pi(M-1)\sin\phi}\bigl]^T.
\end{equation}

 The DFT codebook is denoted by $\vec{C}_{\text{DFT}}=[\vec{c}(\phi_n)]_{n\in \mathcal{N}'}\in \mathbb{C}^{M\times N'}$, where $\vec{c}(\phi_n)\in \mathbb{C}^{M\times 1}$ is the $n$th DFT codeword, given by
 \begin{equation}\label{DFT}
   \vec{c}(\phi_n)=\bigl[1,e^{j\pi\sin\phi_n},\cdots,e^{j\pi(M-1)\sin\phi_n}\bigl]^T, \forall n\in \mathcal{N}',
 \end{equation}
 with $\sin\phi_n=\frac{2n}{M}$, $N'=2\bigl\lfloor\frac{\sin\phi_{\text{max}}}{2/M} \bigl\rfloor+1$ being the number of DFT codewords \cite{pillai2012array}, and $\mathcal{N}'=\left\{-\frac{N'-1}{2},\cdots,0,\cdots,\frac{N'-1}{2}\right\}$ being the index set of DFT codewords.
 Consequently, considering the impact of antenna element pattern, the overall beam pattern of the ULA for DFT codeword $n$, denoted by $f_{\text{ULA}}(\phi,\phi_n)$, can be expressed as
%Then, the beam pattern incorporating the antenna pattern for the $n$th DFT codeword, which is implemented through the fully-connected architecture with phase shifter in Fig. \ref{architecture3}, denoted by $\vec{a}(\theta_n)=[e^{-j\frac{2\pi}{\lambda}d(m-1)\sin\theta_n}]_{1\leq m\leq M}\in \mathbb{C}^{M\times 1}$, is given by
\begin{equation}\label{steeringV1X}
\begin{aligned}
f_{\text{ULA}}(\phi,\phi_n)&=\sqrt{G_{\text{ULA}}(\phi)}\vec{c}^H(\phi_n)\vec{a}_{\text{ULA}}(\phi)\\%&=G^{\text{ULA}}(\theta)\vec{a}^H(\theta_n)\vec{a}(\theta)\\%=\vec{a}(\eta_n)^H\left(G(\theta-0.5\pi)\vec{a}(\theta-0.5\pi)\right)\\
&=\sqrt{G_{\text{ULA}}(\phi)}\underbrace{MH_M(\sin\phi-\sin\phi_n)}_{r_{\text{ULA}}(\phi,\phi_n)} ,
\end{aligned}
\end{equation}
where $G_{\text{ULA}}(\phi)$ is the antenna element pattern in the ULA, characterized by the peak antenna gain $G_{\text{ULA}}(0)$, the 3dB beamwidth $\phi_{\text{3dB}}^{\text{ULA}}$, and the total power gain  $G^{\text{ULA}}_{\text{sum}}$. %, with $\theta$ being the boresight of each element of the ULA.
%Accordingly, the beam patterns for the $N'$ DFT codewords is denoted by $\vec{f}_{\text{ULA}}(\phi)=[f_{\text{ULA}}(\phi,\phi_n)]_{n\in\mathcal{N}'}\in\mathbb{C}^{N'\times 1}$.


%By observing (\ref{steeringV1X}), it's found that $\underset{\theta}{\text{max}}|r_{\text{ULA}}(\theta,\theta_n)|=M$, and the maximum is achieved if and only if $\theta=\theta_n$. In addition, it's also found $\underset{\theta}{\text{min}}|r_{\text{ULA}}(\theta,\theta_n)|=0$, and the minimum is achieved if and only if $\theta=\arcsin\left(\sin\theta_n+\frac{2p}{M}\right)$, where $p=\left\lceil\frac{M(-\sin\theta_{\text{max}}-\sin\theta_n)}{2}\right\rceil,\cdots,-1,1,\cdots,\left\lfloor\frac{M(\sin\theta_{\text{max}}-\sin\theta_n)}{2}\right\rfloor$. Thus, the null-to-null beamwidth of the ULA's main lobe can be obtained directly, which is given in Lemma \ref{ULABW}.

For any given DFT codeword $n$, the path angle $\phi$ that has the maximum and minimum responses  $|r_{\text{ULA}}(\phi,\phi_n)|$ in (\ref{steeringV1X}) can be obtained as follows.

\begin{lem}\label{lemma001}
For any given DFT codeword $n$,
\begin{equation}\label{hu}
\begin{aligned}
  &\underset{|\phi|\leq\phi_{\text{max}}}{\text{max }}|r_{\text{ULA}}(\phi,\phi_n)|=M, \text{ and the maximum  } \\
  &\text{is achieved if and only if }\phi=\phi_n.
  \end{aligned}
\end{equation}
\end{lem}
\begin{pproof}
The
 function $|H_M(x)|$ in (\ref{H_M}) achieves the maximum value 1 when $x=0,\pm2,\pm4,\cdots$.
Consequently, $|H_M(\sin\phi-\sin\phi_n)|$ in (\ref{steeringV1X}) achieves the maximum value 1 if and only if $\phi=\phi_n$ due to $\phi_{\text{max}}<0.5\pi$.
%Lemma \ref{lemma001} can be easily proved by noting that the function $|H_M(\sin\phi-\sin\phi_n)|$ in (\ref{steeringV1X}) can achieve the maximum value 1 if and only if $\phi=\phi_n$.
    $\hfill\blacksquare$
\end{pproof}

\begin{lem}\label{lemma002}
For any given DFT codeword $n$,
\begin{equation}\label{hu}
\begin{aligned}
  &\underset{|\phi|\leq\phi_{\text{max}}}{\text{min }}|r_{\text{ULA}}(\phi,\phi_n)|=0, \text{and the minimum is achieved} \\
  &\text{if and only if } \phi=\arcsin\Bigl(\sin\phi_n+\frac{2p}{M}\Bigl), \forall p\in\mathcal{P}(\phi_n),
  \end{aligned}
\end{equation}
where $\mathcal{P}(\phi_n)=\bigl\{\left\lceil -\frac{M}{2} (\sin\phi_{\text{max}}+\sin\phi_n)\right\rceil,\cdots,-1,1,$
$\cdots,\left\lfloor \frac{M}{2} (\sin\phi_{\text{max}}-\sin\phi_n)\right\rfloor\bigl\}$.
\end{lem}
\begin{pproof}
If and only if $\sin\phi-\sin\phi_n=\frac{2p}{M}$, $\forall p\in \mathcal{P}(\phi_n)$, $|H_M(\sin\phi-\sin\phi_n)|$ in (\ref{steeringV1X}) can achieve the minimum value 0. Thus,
if and only if $\phi=\arcsin\left(\sin\phi_n+\frac{2p}{M}\right)$, $|r_{\text{ULA}}(\phi,\phi_n)|$ in (\ref{steeringV1X}) achieves the minimum value 0, $\forall p\in \mathcal{P}(\phi_n)$.
    $\hfill\blacksquare$
\end{pproof}

