\section{RAA-based Downlink Multi-user Communications}
In RAA-based downlink multi-user communication system,
the RF combiner of each sULA needs to be replaced by power splitter.
The downlink transmit information-bearing symbol vector is denoted by
$\vec{s}_{\text{DL}}=[s_{\text{DL},k}]_{1 \leq k\leq K}\in\mathbb{C}^{K\times 1}$, satisfying $\mathbb{E}[\vec{s}_{\text{DL}}\vec{s}^H_{\text{DL}}]=\vec{I}_{K}$.
The downlink baseband transmit beamforming matrix is denoted by $\vec{W}_{\text{DL}}=\left[\vec{w}_{\text{DL},k}\right]_{1\leq k \leq K}\in \mathbb{C}^{ N_{\text{RF}}\times K}$ with $\vec{w}_{\text{DL},k}\in\mathbb{C}^{ N_{\text{RF}}\times 1}$ being the transmit beamforming vector for user $k$. Thus, after undergoing the baseband processing and RSN, the transmit signal vector at the $N$ sULAs, denoted by $\vec{x}_{\text{DL}}\in\mathbb{C}^{N\times1}$, is given by
\begin{equation}
\vec{x}_{\text{DL}}=\vec{S}^H\vec{W}_{\text{DL}}\vec{s}_{\text{DL}}=\vec{S}^H\sum\nolimits_{k=1}\nolimits^{K}\vec{w}_{\text{DL},k}s_{\text{DL},k},
\end{equation}
where $\vec{S}\in\{0,1\}^{N_{\text{RF}}\times N}$ is the RSN matrix, and the transmit signal vector satisfies $\mathbb{E}[\|\vec{x}_{\text{DL}}\|^2]\leq P_{\text{DL}}$, with $P_{\text{DL}}$ being the downlink transmit total power. Thus, we have $\mathbb{E}[\|\vec{x}_{\text{DL}}\|^2]=\mathbb{E}[\|\vec{W}_{\text{DL}}\vec{s}_{\text{DL}}\|^2]=\sum_{k=1}^{K}\|\vec{w}_{\text{DL},k}\|^2\leq P_{\text{DL}}$, where the first equality holds due to $\vec{S}\vec{S}^H=\vec{I}_{N_\text{RF}}$.
Accordingly, the downlink received signal at user $k$ can be formulated as
\begin{equation}\label{hX}
%\begin{aligned}
    y_{\text{DL},k}=\left(\vec{h}^{\text{act}}_{{\text{DL}},k}\right)^H \left(\vec{x}_{\text{DL}}\otimes \bigl(\sqrt{1/M}\vec{1}_{M\times1}\bigl)\right)
    +z_k,
%\end{aligned}
\end{equation}
where $\vec{h}^{\text{act}}_{{\text{DL}},k}\in\mathbb{C}^{NM\times1}$ denotes the channel vector between all $NM$ antenna elements of RAA and user $k$, modeled as
\begin{equation}\label{h_DL}
\begin{aligned}
\vec{h}^{\text{act}}_{{\text{DL}},k}=\sum\nolimits_{l =1}^{L_k}\alpha_{k,l}\text{vec}\left(\vec{A}(\phi_{k,l})\right),
\end{aligned}
\end{equation}
%and  $\mathbb{E}[s_{\text{DL},k}s^\ast_{\text{DL},k}]=1$, $\forall k'\neq k$%, with $P_{\text{DL},k}$ and $P_{\text{DL}}=\sum_{k=1}^{K}P_{\text{DL},k}$ being the transmit power for user $k$ and total transmit power, respectively, $\forall k'\neq k$
 and $z_k\sim N_{\mathbb{C}}(0,\sigma^2)$ is the noise at user $k$, following CSCG distribution with variance $\sigma^2$.
%In addition, different from the uplink baseband processing, the downlink processing satisfies $\|\vec{w}_k\|^2=1$, $\forall k$.
By substituting (\ref{h_DL}) into (\ref{hX}), we have
\begin{equation}\label{hX0}
\begin{aligned}
    y_{\text{DL},k}%&=\frac{1}{\sqrt{M}}\sum\nolimits_{l =1}^{L_k}\alpha_{k,l}\vec{f}^H(\phi_{k,l}) \vec{S}^H\vec{W}\vec{s}_{\text{DL}}+z_k,\\
    &=\sqrt{1/M}\underbrace{\Bigl(\sum\nolimits_{l =1}^{L_k}\alpha_{k,l}\vec{f}(\phi_{k,l})\Bigl)^H}_{\vec{h}_{{\text{DL}},k}^H}\vec{x}_{\text{DL}}+z_k\\
    %&=\sqrt{1/M}\vec{h}_{{\text{DL}},k}^H\vec{S}^H\vec{W}\vec{s}_{\text{DL}}+z_k\\
    &=\sqrt{1/M}\vec{h}_{{\text{DL}},k}^H\vec{S}^H\sum\nolimits_{i=1}\nolimits^{K}\vec{w}_{\text{DL},i}s_{\text{DL},i}+z_k,
\end{aligned}
\end{equation}
where $\vec{h}_{{\text{DL}},k}\in\mathbb{C}^{N\times 1}$ is the effective channel between the $N$ sULA ports and user $k$, which is  identical to (\ref{h_up}). % and is given by
%\begin{equation}\label{hXx0}
%\begin{aligned}
%    \vec{h}_{{\text{DL}},k}=\sum\nolimits_{l =1}^{L_k}\alpha_{k,l}\vec{f}(\phi_{k,l}).
%\end{aligned}
%\end{equation}
Based on (\ref{hX0}), the SINR of user $k$ for the downlink RAA-based communications is given by
\begin{equation}\label{channel modelXX3}
     \text{SINR}_{\text{DL},k}=\frac{\frac{1}{M}\bigl|\vec{h}_{\text{DL},k}^H\vec{S}^H\vec{w}_{\text{DL},k}
    \bigl|^2}{\sum_{i\neq k}\frac{1}{M}\bigl|\vec{h}_{\text{DL},k}^H\vec{S}^H\vec{w}_{\text{DL},i}
    \bigl|^2+\sigma^2}.
\end{equation}
%where $\bar{P}_{\text{DL},k}=\frac{P_{\text{DL},k}}{\sigma^2}$ represents the downlink transmit SNR for user $k$.

In particular, the SNR for downlink single-user communications is
 \begin{equation}\label{DLSNR}
\text{SNR}_{\text{DL}}=\left|\vec{w}_{\text{DL}}^H\vec{S}\vec{h_{\text{DL}}}
    \right|^2/(M\sigma^2).
 \end{equation}

By observing (\ref{DLSNR}), the design of downlink joint RAA beamforming and ray selection is similar to the uplink counterpart.
Specifically, for a given ray selection matrix $\vec{S}$, the optimal baseband beamforming in (\ref{DLSNR}) is the MRT, i.e., $\vec{w}_{\text{DL}}(\vec{S})=\sqrt{P_{\text{DL}}}\frac{\vec{S}\vec{h_{\text{DL}}}}{\|\vec{S}\vec{h}_{\text{DL}}\|}$.
Accordingly, (\ref{DLSNR}) can be rewritten as a function of $\vec{S}$
 \begin{equation}\label{DL_SNR2}
\text{SNR}_{\text{DL}}(\vec{S})=\bar{P}_{\text{DL}}\|\vec{S}\vec{h}_{\text{DL}}\|^2/M,
 \end{equation}
where $\bar{P}_{\text{DL}}=\frac{P_{\text{DL}}}{\sigma^2}$ denotes the downlink transmit SNR.
Similar to the uplink case, the optimal $\vec{S}$ that maximizes the SNR also corresponds to selecting the $N_{\text{RF}}$ entries of $\mathbf h_{\text{DL}}$ with the largest magnitudes. Moreover, the downlink maximum SNR in (\ref{DL_SNR2}) is similar to the uplink counterpart in (\ref{SNR2}).
%Specifically, in the case of a single path, we have $h_{\text{DL},n}=M\alpha\sqrt{G(0)}$ when $\phi=\eta_n$. Thus, the resulting maximum downlink SNR in (\ref{DL_SNR2}) for the RAA is $M\bar{P}_{\text{DL}}|\alpha|^2G(0)$, which increases with $M$. Similar conclusions can also be obtained in the case of multiple paths.

For downlink multi-user RAA-based communications,
the problem of maximizing the minimum SINR is formulated as a joint optimization of $\vec{W}_{\text{DL}}$ and $\vec{S}$, as follows
\begin{equation}\label{SINR2}
\begin{aligned}
   \underset{\vec{W_{\text{DL}}},\vec{S}}{\text{max}}& \enspace \bigl(\underset{\forall k}{\text{min}}  \enspace\text{SINR}_{\text{DL},k}\bigl)\\
   \text{s.t.}& \quad(\text{C1}):
               \enspace\vec{S}\in \{0,1\}^{N_{\text{RF}}\times N},\\
               &\quad(\text{C2}):\enspace\left\|[\vec{S}]_{i,:}\right\|_0=1,\enspace 1\leq i\leq N_{\text{RF}},\\
               &\quad(\text{C3}):\enspace\left\|[\vec{S}]_{:,n}\right\|_0\leq 1,\enspace 1\leq n\leq N,\\
               &\quad(\text{C4}):\enspace\sum\nolimits_{k=1}\nolimits^{K}\|\vec{w}_{\text{DL},k}\|^2\leq P_{\text{DL}}.
   \end{aligned}
\end{equation}
%where $\gamma_{k}$ is the SINR target of user $k$.

Problem (\ref{SINR2}) is difficult to solve directly due to binary constraints and the tight coupling between $\vec{W}_{\text{DL}}$ and $\vec{S}$.
To address this issue, we propose an alternating optimization algorithm for downlink joint RAA beamforming and ray selection. % which yields a locally optimal solution with reasonable complexity.
We first fix $\vec{S}$, and then reformulate Problem (\ref{SINR2}) by introducing an auxiliary variable $\gamma$ to replace the minimum SINR objective, as follows%, transforming the Problem (\ref{SINR2}) into
%\begin{equation}\label{SINR3}
%\begin{aligned}
%   &\quad\quad\quad\underset{\vec{W},\vec{S},\gamma}{\text{max}} \enspace \gamma\\
%   \text{s.t.}& \quad(C1)-(C4) \text{ in Problem } (\ref{SINR2}),\\
 %               &\quad\text{SINR}_{\text{DL},k}\geq \gamma, \forall k.
%   \end{aligned}
%\end{equation}
%For any given $\vec{S}$, Problem (\ref{SINR3}) is reformulated as
\begin{equation}\label{SINR4}
\begin{aligned}
   \underset{\vec{W}_{\text{DL}},\gamma}{\text{max}}& \enspace \gamma\\
   \text{s.t.}
               &\quad(\text{C4}) \text{ in Problem } (\ref{SINR2}),\\
               % &\quad\frac{\frac{1}{M}\left|\vec{h}_{\text{DL},k}^H\vec{S}^H\vec{w}_k\right|^2}{\sum_{i\neq k}\frac{1}{M}\left|\vec{h}_{\text{DL},k}^H\vec{S}^H\vec{w}_i    \right|^2+\sigma^2}\geq \gamma, \forall k.\\
    &\quad\text{SINR}_{\text{DL},k}\geq \gamma, \forall k.\\
   \end{aligned}
\end{equation}

Problem in (\ref{SINR4}) can be efficiently solved by using bisection search and second-order cone programming (SOCP) to find the maximum feasible $\gamma^*$ and corresponding feasible $\vec{W}_{\text{DL}}^*$.
 %over $\gamma\in[\gamma_{\text{min}},\gamma_{\text{max}}]$ to find the maximum feasible $\gamma^*$.
 During the bisection search process, for the current $\gamma$, we solve the SOCP problem to determine whether a feasible solution $\vec{W}_{\text{DL}}$ exists. Then, based on the obtained feasible $\vec{W}_{\text{DL}}^*$, Problem (\ref{SINR2}) is reformulated as
 \begin{equation}\label{SINR5}
\begin{aligned}
   \underset{\vec{S}}{\text{max}} &\enspace \bigl(\underset{\forall k}{\text{min}}  \enspace\text{SINR}_{\text{DL},k}\bigl)\\
   \text{s.t.}& \quad(\text{C1})-(\text{C3}) \text{ in Problem } (\ref{SINR2}).
   \end{aligned}
\end{equation}

Exhaustive search is utilized to obtain the optimal solution $\vec{S}^*$ in Problem (\ref{SINR5}).
The above process continues until $\gamma^*$ converges. The proposed alternating optimization algorithm is summarized in Algorithm 2.

\begin{algorithm}[htb]
\caption{Alternating optimization algorithm for downlink RAA beamforming and ray selection}
\label{alg:Alternating}
\begin{algorithmic}[1]
\STATE \textbf{Input:} maximum iteration $T_{\text{max}}$, convergence threshold $\varepsilon_{\text{DL}}$.
\STATE Initialize $\mathbf{S}^{(0)}$, $\gamma^{(0)}=0$, $t=0$.
\REPEAT
    \STATE  Fix $\mathbf{S}^{(t)}$, use bisection and SOCP to solve Problem (\ref{SINR4}) to obtain maximum feasible $\gamma^{(t+1)}$ and $\mathbf{W}_{\text{DL}}^{(t+1)}$;
    \STATE  Fix $\mathbf{W}_{\text{DL}}^{(t+1)}$, use exhaustive search to solve Problem (\ref{SINR5}) to obtain the optimal $\mathbf{S}^{(t+1)}$;
    \IF {$|\gamma^{(t+1)} - \gamma^{(t)}| \leq \varepsilon_{\text{DL}}$ or $t+1 \geq T_{\text{max}}$}
        \STATE \quad break
    \ENDIF
    \STATE $t \leftarrow t + 1$
\UNTIL{convergence}
\STATE \textbf{Output:} $\mathbf{W}_{\text{DL}}^{(t+1)}$, $\mathbf{S}^{(t+1)}$, and $\gamma^{(t+1)}$.
\end{algorithmic}
\end{algorithm}


