\subsection{Supporting Lemmas and Formal Proofs for Theorems in Section~\ref{sec:lower}}\label{appendix_thm_lower_bound}
\subsubsection{Supporting Lemmas in Section~\ref{sec:lower}}\label{appendix_lemmas}
\begin{lemma}\label{lem: queuelength_lower_bound}
    Given the arrival process $\{A(t)\}_{t\geq 0}$ and scheduling set $\mathcal{D}$, for any scheduling policy, the total queue length satisfies
    \begin{align*}
    \sum_{i=1}^n Q_i(T)\geq &\max\bigg\{\sum_{s=0}^{T-2}\Big(\sum_{i=1}^nA_i(s)-M\Big),\sum_{s=1}^{T-2}\Big(\sum_{i=1}^nA_i(s)-M\Big),\dots,\\
    & \quad \quad \quad\quad\quad \quad \quad \sum_{i=1}^nA_i(T-2)-M,0\bigg\}+\sum_{i=1}^nA_i(T-1),
    \end{align*}
    where $M=\max\left\{\sum_{i=1}^n d_i, d\in \mathcal{D}\right\}.$
\end{lemma}
\begin{proof}
Let $D(t) \in \mathcal{D}$ denote the schedule selected by the scheduling policy at time $t$.
Let $\Delta(t)=A(t-1)-D(t)$ for all $t\geq 1$.  By \eqref{queue_recursion}, for $1\leq i\leq n$ and $T\geq 1$, we have
\begin{align}
    &Q_i(T)-A_i(T-1)\nonumber\\
    &=\max\{Q_i(T-1)-D_i(T-1),0\} \nonumber \\
          &=\max\{\max\{Q_i(T-2)-D_i(T-2),0\}+A_i(T-2)-D_i(T-1),0\} \nonumber \\
          &=\max\{Q_i(T-2)-D_i(T-2)+\Delta_i(T-1),\Delta_i(T-1),0\}\nonumber \\
          &=\max\bigg\{Q_i(1)-D_i(1)+\sum_{s=2}^{T-1}\Delta_i(s),\sum_{s=2}^{T-1}\Delta_i(s),\dots,\Delta_i(T-1),0\bigg\}\nonumber \\
          &=\max\bigg\{\sum_{s=1}^{T-1}\Delta_i(s),\sum_{s=2}^{T-1}\Delta_i(s),\dots,\Delta_i(T-1),0\bigg\},\label{queue_length}
    \end{align}
where the last equation follows that $Q_i(0)=0$ and then $Q_i(1)=A_i(0)$.

Since $\sum_{i=1}^n D_i(t)\leq M$ for all $t$, by equation \eqref{queue_length}, we have
\begin{align*}
    \sum_{i=1}^n Q_i(T)&=\sum_{i=1}^n\max\bigg\{\sum_{s=1}^{T-1}\Delta_i(s),\sum_{s=2}^{T-1}\Delta_i(s),\dots,\Delta_i(T-1),0\bigg\}+\sum_{i=1}^nA_i(T-1)\\
    &\geq \max\bigg\{\sum_{s=1}^{T-1}\sum_{i=1}^n\Delta_i(s),\sum_{s=2}^{T-1}\sum_{i=1}^n\Delta_i(s),\dots,\sum_{i=1}^n\Delta_i(T-1),0\bigg\}+\sum_{i=1}^nA_i(T-1)\\
    &\geq \max\bigg\{\sum_{s=0}^{T-2}\Big(\sum_{i=1}^nA_i(s)-M\Big),\sum_{s=1}^{T-2}\Big(\sum_{i=1}^nA_i(s)-M\Big),\dots,\\
    & \quad \quad \quad \quad\quad\quad\quad \quad \sum_{i=1}^nA_i(T-2)-M,0\bigg\}+\sum_{i=1}^nA_i(T-1).
    \end{align*}
\end{proof}
\begin{lemma}\label{lem:binary_lower_bound}
   Let $\{Z(t)\}_{t\geq 0}$ be a sequence of i.i.d. binary random variables, where each $Z(t)$ takes the value $K-1$ with probability $1/K$ and $-1$ with probability $(K-1)/K$, for some $K>1$. Define the partial sum $S(t)=\sum_{s=1}^tZ(s)$. Then we have 
\begin{align}
\mathbb{E}\big[\max\big\{S(t),0\big\}\big]\geq 
 \begin{cases}
    \frac{(K-1)t}{K^t}, & 1\leq t \leq \frac{K}{K-1};\\
    \frac{1-\delta_{t,K}}{\sqrt{2\pi}}\exp{\left(\frac{-K^2(t-1)}{12((K-1)t-K)(t-K)}\right)}\sqrt{(K-1)(t-1)},   & t> \frac{K}{K-1},
\end{cases} \label{ieq:S_lower_bound}
\end{align}
with $\delta_{t,K}= \max\left\{\frac{K}{t}, \frac{K}{t(K-1)}\right\}$.
\end{lemma}
\begin{proof}
    A simple calculation shows
\begin{align}\label{expression_s}
   \mathbb{E}\big[\max\big\{S(t),0\big\}\big]
=\sum_{k=k_0}^{t}(k K -t)\binom t k\Bigl(\tfrac1K\Bigr)^k\Bigl(\tfrac{K-1}K\Bigr)^{t-k}
=\frac{t\,(K-1)^{\,m_0+1}}{K^t}\;\binom{t-1}{m_0}, 
\end{align}
where $k_0=\Bigl\lfloor\tfrac tK\Bigr\rfloor+1$ and $m_0=t-k_0$.
In fact, we can prove by induction on $m$ that
\[
G_m: = \sum_{k=t-m}^{t}(k K -t)\binom t k\Bigl(K-1\Bigr)^{t-k}
=t\,(K-1)^{\,m+1}\;\binom{t-1}{m}
\]
for $0\leq m\leq t-1$. Note that when $m=0$, we have $G_0=t(K-1)$. So the identity holds in the base case. Now assume the equality holds for some $m>0$, and we prove it for $m+1$.
\begin{align*}
   G_{m+1}&=  \big((t-m-1) K -t\big)\binom{t}{t-m-1}\Bigl(K-1\Bigr)^{m+1}+G_m\\
   &=\Bigl(K-1\Bigr)^{m+1}\left(\big((t-m-1) K -t\big)\frac{t!}{(m+1)!(t-m-1)!} + \frac{t!}{(t-m-1)!m!}   \right)\\
   &= \Bigl(K-1\Bigr)^{m+1}\frac{t!}{(m+1)!(t-m-2)!}\left(\frac{\big((t-m-1) K -t\big)}{t-m-1} + \frac{m+1}{t-m-1}   \right)\\
   &= \Bigl(K-1\Bigr)^{m+2}\frac{t!}{(m+1)!(t-m-2)!}\\
   &= t\,(K-1)^{\,m+2}\;\binom{t-1}{m+1}.
   \end{align*}
Thus, we have completed the proof by induction.

Recall \eqref{expression_s}, if $m_0=0$, or equivalently, $t \leq K/(K-1)$, we have
\[
\mathbb{E}\big[\max\big\{S(t),0\big\}\big]
=\frac{(K-1)t}{K^t}.
\]
This completes the proof of the first part of \eqref{ieq:S_lower_bound}. We now focus on the case $m_0>0$, or equivalently, $t > K/(K-1)$, for the expression \eqref{expression_s}.
By the Stirling approximation, for any integer \(r\ge1\),
\[
\sqrt{2\pi r} \Bigl(\tfrac r e\Bigr)^r
\leq
r!
\leq 
\sqrt{2\pi r}\Bigl(\tfrac r e\Bigr)^r e^{\frac{1}{12r}}.
\]
Apply the lower bound to \((t-1)!\) and the upper bound to \(m_0!\) and \((t-1-m_0)!\).  Then

\[
\binom{t-1}{m_0}
=\frac{(t-1)!}{m_0!\,(t-1-m_0)!}
\geq
\frac{C_0(t)}{\sqrt{2\pi}}\,
\sqrt{\frac{t-1}{\,m_0\,(t-1-m_0)\,}}\;
\frac{(t-1)^{\,t-1}}{m_0^{m_0}\,(t-1-m_0)^{\,t-1-m_0}}
\]
with $C_0(t)=\exp{(-\frac{1}{12m_0}-\frac{1}{12(t-1-m_0)})}$.
Hence
\[
\mathbb{E}\big[\max\big\{S(t),0\big\}\big]
\geq
\frac{C_0(t) t\,(K-1)^{m_0+1}}{\sqrt{2\pi}K^t}
\sqrt{\frac{t-1}{\,m_0\,(t-1-m_0)\,}}\;
\frac{(t-1)^{\,t-1}}{m_0^{m_0}\,(t-1-m_0)^{\,t-1-m_0}}.
\]
And we can show that for $t > K/(K-1)$,
\begin{align}
 &\frac{(K-1)^{m_0+1}}{K^t}
\frac{(t-1)^{\,t-1}}{m_0^{m_0}\,(t-1-m_0)^{\,t-1-m_0}} \geq  \frac{K-1}{K}\min\left\{1-\frac{K}{t}, 1-\frac{K}{t(K-1)}\right\}. \label{lower_bound_approximate}
\end{align}
We defer its proof to later, assuming it holds, we immediately obtain
\begin{align}\label{equ:lowerbound_m_0}
    \mathbb{E}\big[\max\big\{S(t),0\big\}\big]
\geq
\min\left\{1-\frac{K}{t}, 1-\frac{K}{t(K-1)}\right\}\frac{K-1}{K}\frac{C_0(t)t}{\sqrt{2\pi}}\;
\sqrt{\frac{t-1}{\,m_0\,(t-1-m_0)\,}}.
\end{align}
Note that
\[
m_0=t-k_0\;\le\;t-\frac tK=\;t\,\frac{K-1}{K},\quad t-1-m_0 \;\le\ \frac tK.
\]
We have
\[
m_0(t-1-m_0)
\leq
t\frac{K-1}{K}\frac tK
=\frac{K-1}{K^2}\,t^2,
\]
and therefore
\[
\sqrt{\frac{t-1}{\,m_0\,(t-1-m_0)\,}}
=
\sqrt{\frac{t-1}{\tfrac{K-1}{K^2}\,t^2}}
=
\frac{K}{\sqrt{K-1}}\frac{\sqrt{t-1}}{t}.
\]
Plug this into \eqref{equ:lowerbound_m_0},  we have 
\begin{align*}
    \mathbb{E}\big[\max\big\{S(t),0\big\}\big]
\geq \frac{C_0(t)}{\sqrt{2\pi}}
\min\left\{1-\frac{K}{t}, 1-\frac{K}{t(K-1)}\right\}\sqrt{(K-1)(t-1)}.
\end{align*}
It is clear to see that
\begin{align*}
    C_0(t)&=\exp{\left(\frac{-(t-1)}{12m_0(t-1-m_0)}\right)}= \exp{\left(\frac{-(t-1)}{12(t-1-\lfloor t/K\rfloor)\lfloor t/K\rfloor}\right)}\\
    &\geq \exp{\left(\frac{-(t-1)}{12(t-1-t/K)( t/K-1)}\right)}=\exp{\left(\frac{-K^2(t-1)}{12((K-1)t-K)(t-K)}\right)}.
\end{align*}
Therefore, we have \eqref{ieq:S_lower_bound}.
To complete the proof, it suffices to show \eqref{lower_bound_approximate}.

Write $p_0=\frac{m_0}{t-1}$ and $H(p)=-\bigl[p\ln p+(1-p)\ln (1-p)\bigr]$.
Then
\[
\frac{(t-1)^{\,t-1}}{m_0^{m_0}\,(t-1-m_0)^{\,t-1-m_0}}
=\exp\!\bigl((t-1)\,H(p_0)\bigr)
\]
and
\[
\frac{(K-1)^{m_0+1}}{K^t}
=\exp\!\bigl((m_0+1)\ln(K-1)-t\ln K\bigr).
\]
To show \eqref{lower_bound_approximate}, we only need to prove that for $t > K/(K-1)$,
\begin{align}
 F(p_0,K): &= (t-1)\,H(p_0)\;+\;(m_0+1)\ln(K-1)\;-\;t\ln K \nonumber \\
 &\geq 
 \min \left\{\ln \frac{(t-K)(K-1)}{tK}, \ln \frac{t(K-1)-K}{tK}\right\}.\label{f(p,k)}
\end{align}
Note that
\[
F(p_0,K) \;=\; (t-1)\Bigl[\,H(p_0) + p_0\ln(K-1) - \ln K\Bigr] \;+\;\ln(K-1)- \ln K.
\]
A direct algebraic check shows, for $p_1= 1-1/K$,
\[
H(p_1) \;+\; p_1\ln(K-1) \;-\;\ln K \;=\; 0.
\]
By the mean value theorem, 
\begin{align*}
&(H(p_0) + p_0\ln(K-1) - \ln K)-(H(p_1) + p_1\ln(K-1) - \ln K) \\
&=(p_0-p_1)(H'(p)+\ln(K-1))
\end{align*}
for some $p\in [p_{\min}, p_{\max}]$ with $p_{\min}=\min\{p_0,p_1 \}$ and $p_{\max}=\max\{p_0,p_1 \}$.
Note that $H'(p) \;=\; \ln\frac{1-p}{p}$ is decreasing, therefore,
\begin{align*}
  (t-1)\Bigl[\,H(p_0) + p_0\ln(K-1) - \ln K\Bigr]
  &\geq(t-1)(p_0-p_1) (H'(p_0)+\ln(K-1))\\
  & =(\frac{t-1}{K}-\lfloor\tfrac tK\rfloor)\ln\frac{\lfloor\tfrac tK\rfloor(K-1)}{t-1-\lfloor\tfrac tK\rfloor}.
\end{align*}
For the first term, since
$\frac tK-1\leq \lfloor\tfrac tK\rfloor
\leq \frac tK$,
it follows that
$\frac{t-1}{K}-1\leq \lfloor\tfrac tK\rfloor-\frac{1}{K}
\leq\frac{t-1}{K}$.
Hence
\[
\Bigl|\frac{t-1}{K}-\lfloor \tfrac tK\rfloor\Bigr| \leq 1.
\]
For the second term, since
\begin{align*}
 \frac{t-K}{t} =\frac{(\tfrac tK-1)(K-1)}{t-\tfrac tK} \leq \frac{\lfloor\tfrac tK\rfloor(K-1)}{t-1-\lfloor\tfrac tK\rfloor}
   \leq \frac{\tfrac tK(K-1)}{t-1-\tfrac tK}=\frac{t(K-1)}{t(K-1)-K},
\end{align*}
and
\[
\frac{t-K}{t}<1; \ \frac{t(K-1)}{t(K-1)-K}>1,
\]
then
\begin{align*}
 \Bigl|  \ln\frac{\lfloor\tfrac tK\rfloor(K-1)}{t-1-\lfloor\tfrac tK\rfloor} \Bigr| \leq \max \left\{\ln \frac{t}{t-K}, \ln \frac{t(K-1)}{t(K-1)-K}\right\}.
\end{align*}
Thus,
\begin{align*}
   F(p_0,K)&\geq  -\max \left\{\ln \frac{t}{t-K}, \ln \frac{t(K-1)}{t(K-1)-K}\right\} +\ln(K-1) -\ln K \\
   &= \min \left\{\ln \frac{t-K}{t}, \ln \frac{t(K-1)-K}{t(K-1)}\right\} +\ln(K-1) -\ln K \\
   &= \min \left\{\ln \frac{(t-K)(K-1)}{tK}, \ln \frac{t(K-1)-K}{tK}\right\}.
\end{align*}
We complete the proof of \eqref{f(p,k)}.
\end{proof}
\subsubsection{Proof of Theorem \ref{thm_lower_bound}}\label{appendix_thm_lower_bound_general}
\begin{proof}[Proof of Theorem \ref{thm_lower_bound}.]
Fix a scheduling set $\mathcal{D}$ that satisfies the condition in model class $\mathcal{M}(C^2, B^2)$. By Lemma \ref{lem: queuelength_lower_bound}, 
for any arrival process $\{A(t)\}_{t\geq 0}$ and any scheduling policy, the total queue length satisfies
    \begin{align*}
\sum_{i=1}^n Q_i(T)\geq \max\bigg\{\sum_{t=0}^{T-2}\Big(\sum_{i=1}^nA_i(t)-M\Big), 0\bigg\}+\sum_{i=1}^nA_i(T-1),
\end{align*}
where $M=\max\left\{\sum_{i=1}^n d_i, d\in \mathcal{D}\right\}.$
Define
$S(T-1)= \sum_{t=0}^{T-2}X(t)$ with $ X(t)=\sum_{i=1}^nA_i(t)-M$. We can rewrite the lower bound as
 \begin{align*}
\sum_{i=1}^n Q_i(T)\geq \max\left\{S(T-1), 0\right\}+\sum_{i=1}^nA_i(T-1).
\end{align*}
Now consider the following construction of the arrival process $\{A(t)\}_{t\geq 0}$: for each $t$, 
\begin{align*}
    &\mathbb{P}\Big(A_1(t)=K\lambda_1, A_2(t)=K\lambda_2,\dots,A_n(t)=K\lambda_n\Big)=\frac{1}{K},\\
    &\mathbb{P}\Big(A_1(t)=0, A_2(t)=0,\dots,A_n(t)=0\Big)=\frac{K-1}{K},
\end{align*}
where 
\begin{align}\label{choice_lambda_K}
     \lambda \in \argmin_{\substack{
    \gamma \in \Pi \\
    \sum_{i=1}^n \gamma_i = M
}} \left\{ \sqrt{\frac{1}{n} \sum_{i=1}^n \gamma_i^2} \right\}\quad \mbox{and} \quad K=\frac{nC^2}{\sum_{i=1}^n\lambda_i^2}+1.
\end{align}
With this construction, we have
\begin{align}\label{eq:mean_variance}
   \mathbb{E}[A(t)]=\lambda, \quad \text{and} \quad \text{Var}(A_i(t))=\frac{(K-1)^2\lambda_i^2+\lambda_i^2(K-1)}{K}=(K-1)\lambda_i^2.
\end{align}
Such a construction ensures that
  $\frac{1}{n}\sum_{i=1}^n\text{Var}(A_i(t))=C^2$ and $\{X(t)\}_{t\geq 0}$ forms an i.i.d. sequence of binary random variables, taking the value $M(K-1)$ with probability $1/K$ and $-M$ with probability $(K-1)/K$, with variances of $M^2(K-1)$. Thus, by Lemma \ref{lem:binary_lower_bound}, we obtain a lower bound on $\mathbb{E}\left[\max\left\{S(T-1), 0\right\} \right]$ simply by scaling the corresponding bound in \eqref{ieq:S_lower_bound} by $M$.

 Now we consider the scheduling set
\[
\mathcal{D}=\left\{(x_1,x_2,\dots,x_n)| x_1+x_2+\cdots+x_n=\sqrt{n}B, x_i\geq 0\ \text{for} \ 1\leq i\leq n \right\}.
\]
Note that the specified pair $(A(\cdot),\mathcal{D})$ belongs to the model class $\mathcal{M}(C^2, B^2)$. In this case,  we have $\lambda=(B/\sqrt{n}, B/\sqrt{n},\dots,B/\sqrt{n})$ so that $M=\sqrt{n}B$ and $K-1=\frac{nC^2}{B^2}$. Substituting into \eqref{ieq:S_lower_bound} in Lemma \ref{lem:binary_lower_bound}, we recover the result in \eqref{ieq:lower_bound_dependent}.
\end{proof}
\subsubsection{Proof of Theorem \ref{thm:lower_bound_indep}}\label{appendix_thm_lower_bound_indep}
\begin{proof}[Proof of Theorem \ref{thm:lower_bound_indep}.]
 Fix a scheduling set $\mathcal{D}$ that satisfies the condition  in model class $\mathcal{M_I}(C^2, B^2)$.   We construct $\{A(t)\}_{t\geq 0}$ as follows. For each $t$, the components $A_i(t)$ are independent across $i$ and distributed as
\begin{align*}
    &\mathbb{P}\Big(A_i(t)=K\lambda_i\Big)=\frac{1}{K},\quad \mathbb{P}\Big(A_i(t)=0\Big)=\frac{K-1}{K},
\end{align*}
where the choices of $\lambda$ and $K$ follow those specified in \eqref{choice_lambda_K}. Thus, the mean and variance conditions in \eqref{eq:mean_variance} still holds.
In particular, the total variance across all queues is given by
\begin{align*}
    \sum_{i=1}^n\text{Var}(A_i(t))=\sum_{i=1}^n(K-1)\lambda_i^2=nC^2.
\end{align*}
This confirms that the constructed pair $(A(\cdot), \mathcal{D})$ belongs to the model class $\mathcal{M_I}(C^2, B^2)$. Furthermore, we have
\begin{align*}
&\mathbb{E}\left[\sum_{i=1}^n A_i(t)\right]=\sum_{i=1}^n \lambda_i=M \quad \text{and} \quad
\text{Var}\left[\sum_{i=1}^n A_i(t)\right]=\sum_{i=1}^n\text{Var}(A_i(t))=nC^2.
\end{align*}
By the central limit theorem and Fatou's lemma, it follows that
\begin{align*}
   \liminf_{T\rightarrow \infty}\frac{\mathbb{E}\Big[\max\Big\{\sum_{t=1}^{T-1}\big(\sum_{i=1}^nA_i(t)-M\big),0\Big\}\Big]}{\sqrt{T-1}}\geq \frac{\sqrt{n}C}{\sqrt{2\pi}}.
\end{align*}
Finally, applying Lemma \ref{lem: queuelength_lower_bound} yields the desired result in \eqref{lower_bound_independent}.
\end{proof}



\subsection{Formal Proof of the Upper Bound in \eqref{ieq:upp_bound}   from Section~\ref{sec:upper}}\label{appendix_thm_upper}
For any arrival processes and scheduling sets in $\mathcal{M}(C^2, B^2)$, and any scheduling sequence $\{D(t)\}_{t\geq 0}$, consider the one-step Lyapunov drift:
\begin{align*}
    &\mathbb{E}\left[V\big(Q(t+1)-A(t)\big)-V\big(Q(t)-A(t-1)\big)\mid \mathcal{H}_t\right]\\
    &=\mathbb{E}\left[\sum_{i=1}^n(\max\{Q_i(t)-D_i(t),0\})^2-\sum_{i=1}^n(Q_i(t)-A_i(t-1))^2\middle| \mathcal{H}_t\right]\\
    &\leq \sum_{i=1}^n\mathbb{E}\left[(Q_i(t)-D_i(t))^2-Q_i(t)^2+2Q_i(t)A_i(t-1)-A_i(t-1)^2\mid \mathcal{H}_t\right]\\
    &= \sum_{i=1}^n\mathbb{E}\left[D_i(t)^2-A_i(t-1)^2+2Q_i(t)\big(A_i(t-1)-D_i(t)\big)\mid \mathcal{H}_t\right]\\
    &= f(Q(t),D(t))+r(Q(t), A(t-1)),
\end{align*}
where
\begin{align*}\label{equ:f_drift+quadratic_app}
f(Q(t),d) = \mathbb{E}\bigg[\underbrace{2 \sum_{i=1}^n Q_i(t)\big(\lambda_i(t-1) - d_i\big)}_{\text{first-order term}}+\underbrace{\sum_{i=1}^n\left(d_i^2 - \lambda_i(t-1)^2\right)}_{\text{second-order term}} \biggm| \mathcal{H}_t\bigg],
\end{align*}
and 
\[
r(Q(t),A(t-1))=\sum_{i=1}^n \left[2Q_i(t)(A_i(t-1)-\lambda_i(t-1))+\lambda_i(t-1)^2-A_i(t-1)^2\right].
\]
Note that
\begin{align*}
   &\mathbb{E}\big[Q_i(t)A_i(t-1)\big] \\
   &=\mathbb{E}\left[\big(Q_i(t)-A_i(t-1)\big)A_i(t-1)\right]+\mathbb{E}\big[A_i(t-1)^2\big]\\
   &\overset{(a)}{=}\mathbb{E}\big[Q_i(t)-A_i(t-1)\big]\mathbb{E}\big[A_i(t-1)\big]+\mathbb{E}\big[A_i(t-1)^2\big]\\
   &\overset{(b)}{=}\mathbb{E}\big[Q_i(t)\big]\lambda_i(t-1)+\text{Var}(A_i(t-1)),
\end{align*}
where ($a$) follows from the independence between $Q_i(t)-A_i(t-1)$ and $A_i(t-1)$, and ($b$) follows from the relation $\mathbb{E}\big[A_i(t-1)^2\big]=\lambda_i(t-1)^2+\text{Var}(A_i(t-1))$. Then we have
\[
\mathbb{E}[r(Q(t),A(t-1))]=\sum_{i=1}^n\text{Var}(A_i(t-1)).
\]


By taking expectation and summing over for $1\leq t\leq T-1$, we have
\begin{align}
  \mathbb{E}[V(Q(T)-A(T-1)]&\leq \mathbb{E}[V(Q(1)-A(0))]+\sum_{t=1}^{T-1}\mathbb{E}[f(Q(t),D(t))]+\sum_{t=1}^{T-1}\sum_{i=1}^{n}\text{Var}(A_i(t-1))\nonumber\\
  &\leq\sum_{t=1}^{T-1}\mathbb{E}[f(Q(t),D(t))]+(T-1)nC^2,\label{ieq:drift_bound_app}
\end{align}
where the last inequality follows from the relation $Q(1)=A(0)$.
Note that
\begin{align*}
  \bigg(\mathbb{E}\Big[\sum_{i=1}^n\big(Q_i(T)-A_i(T-1)\big)\Big]\bigg)^2&\overset{(c)}{\leq} \mathbb{E}\Big[\big(\sum_{i=1}^n\big(Q_i(T)-A_i(T-1)\big)\big)^2\Big]\\
  &\overset{(d)}{\leq} n\mathbb{E}\Big[\sum_{i=1}^n \big(Q_i(T)-A_i(T-1)\big)^2\Big]\\&=n\mathbb{E}\big[V\big(Q(T)-A(T-1)\big)\big].
\end{align*}
Here ($c$) follows from Jensen's inequality and ($d$) follows from the Cauchy-Schwartz inequality.
Substituting this expression into \eqref{ieq:drift_bound_app}, we have
\begin{align*}
   \mathbb{E}\Big[\sum_{i=1}^n Q_i(T)]\Big]\leq 
   \sqrt{\sum_{t=1}^{T-1} n\mathbb{E} [f(Q(t),D(t))]+(T-1)n^2 C^2}+\sum_{i=1}^n \mathbb{E}[A_i(T-1)].
\end{align*}



