\subsection{Formal Proof of Theorem \ref{thm:lower_bound_maxweight} in Section~\ref{sec:upper}}\label{appendix_thm_lower_maxweight}
\begin{proof}[Proof of Theorem \ref{thm:lower_bound_maxweight}]
 Now we consider the MaxWeight policy under 
\begin{align}
    &\mathcal{D}=\{d \in \mathbb{R}^2: d=x(b,0)+(1-x)(0,1), 0\leq x \leq 1\}, \nonumber\\
    &A(t)=(1, (b-1)/b) \ \text{for all} \ t \geq 1, \ \text{and} \ A(0)=(1, (b-1)/b-\varepsilon), \label{appendix_constructed_model}
\end{align}  
where $b=\sqrt{2}B$, and $\varepsilon=0$ if $b$ is irrational; otherwise, $\varepsilon>0$ is a small irrational constant.  Here we choose $\varepsilon$ such that $\lceil b^2/(b-1)+\varepsilon \rceil = \lceil b^2/(b-1) \rceil$, which is always possible since $b^2/(b-1)$ is never an integer for $b\geq 6$.

  By the queue dynamics, $Q(1)=(1,1-1/b-\varepsilon)$. MaxWeight repeatedly selects $(b,0)$ until $Q_2(t)\geq b$. Thus $Q(t)=(1, (1-1/b)t-\varepsilon)$ for $1\leq t \leq \lceil b^2/(b-1)+\varepsilon\rceil=\lceil b^2/(b-1)\rceil$. And it is clear to see that $Q_2(t)$ can never be smaller than $b-1/b$, so the  $-\varepsilon$ term is always preserved in $Q_2(t)$, making it irrational for all $t$. In the following, we consider only time horizons where $Q_1(t) < b$ holds throughout, ensuring that $Q_1(t)$ always remains an integer.
 Consequently, there is never a tie in MaxWeight decisions, and it either selects $(b,0)$ or $(0,1)$. Therefore, we henceforth restrict our analysis to the MaxWeight policy under the system 
  \begin{align}
     &\mathcal{D}=\{(b,0),(0,1)\} \quad \text{for $b\geq 6$},\nonumber \\
     &A(t)=(1, (b-1)/b) \ \text{for all} \ t \geq 1, \ \text{and} \ A(0)=(1, (b-1)/b-\varepsilon), \label{appendix_reduced_model}
  \end{align}
where $b=\sqrt{2}B$, and $\varepsilon=0$ if $b$ is irrational; otherwise, $\varepsilon>0$ is a small irrational constant such that $\lceil b^2/(b-1)+\varepsilon \rceil = \lceil b^2/(b-1) \rceil$.




  At each time $t$, the MaxWeight policy will choose $(0,1)$ only when $Q_2(t)>bQ_1(t)$ and $(b,0)$ when $bQ_1(t)>Q_2(t)$.
  Let $t_0=0$ and
  \begin{align*}
      t_k=\min\{t: Q_2(t)\geq kb\} \ \text{for} \ 1\leq k\leq \lfloor b/2\rfloor.
  \end{align*}
We will show, by induction, that 
\begin{enumerate}
    \item[(i)] $t_k$ is well defined;
    \item[(ii)] $Q_1(t_k)=1$;
    \item[(iii)] For $t_{k-1}\leq t< t_k$, $1\leq Q_1(t)\leq k$; $(k-1)b-(k-1)/b\leq Q_2(t)<kb$.
\end{enumerate}
For $k=1$, by the above discussion,  $t_1=\lceil b^2/(b-1)\rceil$ is well defined, $Q_1(t_1)=1$, and (iii) naturally holds. And it is clear to see that $Q_2(t)$ can never be smaller than $b-1/b$.

Now suppose that (i)-(iii) hold for some $k-1$ with $k\geq 2$. We show (i)-(iii) hold for $k$. Note the fact that at any time $t$, choosing $(0,1)$ gives
\[
Q_1(t+1) = Q_1(t) + 1, Q_2(t+1) = Q_2(t) - \tfrac{1}{b},
\]
whereas choosing $(b,0)$ yields
\[
Q_1(t+1) = \max\{Q_1(t)-b,0\} + 1 = 1,
Q_2(t+1) = Q_2(t) + 1 - \tfrac{1}{b}.
\]
Thus $Q_1$ increases only when $(0,1)$ is used, and $Q_2$ increases only when $(b,0)$ is used. Starting from $t\geq t_{k-1}$, and noting $Q_1(t_{k-1})=1$,  consider the next $k$ time slots. There must be at least one use of $(b,0)$, because if the first $k-1$ departures were all $(0,1)$, then $Q_1(t_{k-1}+k-1)= k$,  forcing the $k$th departure to be $(b,0)$. Moreover, if only consider $k-1$ time slots after $t_{k-1}$, at most one $(b,0)$ can be used, because for $s\leq k$, $Q_2(t+s)\geq (k-1)b-s/b>(k-2)b$. Note that $Q_2(t_{k-1}+k)\geq (k-1)b+1-k/b>(k-1)b$.
By the same reasoning and the fact that $Q_2(t_{k-1}+k+s)\geq (k-1)b+1-(k+s)/b>(k-1)b$ for $s\leq k$, in each subsequent block of $k$ slots, $Q_2$ increases by exactly $1-k/b>0$. Hence $t_k$ is well defined, and since $Q_2$ only increases when $(b,0)$ is applied, we conclude $Q_2(t_k)=1$. Finally, (iii) follows directly from the analysis above. And we complete the induction. In addition, we also have
\begin{align*}
  \left\lceil\frac{k(b-1)}{1-k/b}\right\rceil-1 \leq t_k-t_{k-1}\leq \left\lceil \frac{kb}{1-k/b}\right\rceil.
\end{align*}
Therefore, by (iii), for all $t_{k-1}\leq t\leq t_k$, we have $Q_1(t)+Q_2(t)\geq (k-1)b$ and
\begin{align*}
    (k-1)b=\sqrt{t}b\frac{k-1}{\sqrt{t}}\geq \sqrt{t}b\frac{k-1}{\sqrt{t_k}}. 
\end{align*}
Note that
\begin{align*}
    t_k=t_1+\sum_{i=2}^{k-1}(t_k-t_{k-1})\leq \sum_{i=1}^{k-1}\left\lceil \frac{ib}{1-i/b}\right\rceil+1.
\end{align*}
\paragraph{Claim 1.} For $b\geq 4$ and $k\geq 2$,
\begin{align*}
    \frac{k-1}{\sqrt{t_k}}\geq \frac{1}{2\sqrt{b+1}}.
\end{align*}
With the help of Claim 1, for $t_1\leq t \leq t_{\lfloor\frac{b}{2}\rfloor} $,
\begin{align*}
    Q_1(t)+Q_2(t)\geq \frac{b\sqrt{t}}{2\sqrt{b+1}}\geq \frac{\sqrt{bt}}{3}.
\end{align*}
\paragraph{Claim 2.} For $b\geq 6$,
\begin{align*}
    t_{\lfloor\frac{b}{2}\rfloor} \geq \frac{b^3}{16}.
\end{align*}
Therefore, for $t_1\leq t\leq b^3/16$, 
\begin{align*}
    Q_1(t)+Q_2(t)\geq \frac{\sqrt{bt}}{3}.
\end{align*}
And for $t\leq t_1=\left\lceil\frac{b^2}{1-b}\right\rceil$,
\begin{align*}
    Q_1(t)+Q_2(t)\geq 1+(1-1/b)t-\varepsilon\geq (1-1/b)t.
\end{align*}





\end{proof}





\begin{proof}[Proof of Claim 1.]

For $2\le k\le \lfloor b/2\rfloor$ and each $1\le i\le k-1$ we have $1-i/b>1/2$.

Hence
\[
\left\lceil \frac{ib}{1 - i/b}\right\rceil
\leq \frac{ib}{1 - i/b} + 1 \leq 2ib + 1.
\]
Summing over \(i=1,2,\dots,k-1\) yields
\begin{align*}
t_k \leq \sum_{i=1}^{k-1}(2ib + 1)=(k-1)(bk + 1).
\end{align*}
It follows that
\[
\sqrt{t_k}\leq \sqrt{(k-1)(b\,k+1)}\leq \sqrt{k^2\,(b+1)}\leq k\sqrt{b+1}.
\]
Hence
\[
\frac{k-1}{\sqrt{t_k}}\geq
\frac{k-1}{k\,\sqrt{b+1}}=\frac{1-\tfrac1k}{\sqrt{b+1}}.
\]
Finally, since $k\ge2$ implies $1-\tfrac1k\ge\tfrac12$, we conclude
\[
\frac{k-1}{\sqrt{t_k}}\geq\frac{1}{2\sqrt{b+1}}.
\]
\end{proof}

\begin{proof}[Proof of Claim 2.]
   Note that
   \begin{align*}
       t_{\lfloor\frac{b}{2}\rfloor}= t_1+\sum_{i=2}^{\lfloor\frac{b}{2}\rfloor}(t_k-t_{k-1})\geq \sum_{i=1}^{\lfloor\frac{b}{2}\rfloor}\left(\left\lceil \frac{ib}{1-i/b}\right\rceil-1\right).
   \end{align*}
Let $k=\lfloor\frac{b}{2}\rfloor$.   Since $1\le i\le k\le \tfrac b2$, we have 
\begin{align*}
\sum_{i=1}^{k}\Bigl(\left\lceil \tfrac{ib}{1 - i/b}\right\rceil - 1\Bigr)
&\ge
\sum_{i=1}^k\Bigl(\frac{ib^2}{b-i} - 1\Bigr)
\geq\frac{b^2}{b-1}\cdot\frac{k(k+1)}{2} - k.
\end{align*}
Since $k=\lfloor b/2\rfloor\ge\frac{b-2}2$, we get
\[
\frac{b^2}{b-1}\cdot\frac{k(k+1)}{2}\geq \frac{b^2}{b-1}\cdot
\frac{(b-2)b}{8} \geq \frac{b^3(b-2)}{8(b-1)}.
\]
Therefore
\[
\sum_{i=1}^{k}\Bigl(\left\lceil \tfrac{ib}{1 - \tfrac{i}{b}}\right\rceil - 1\Bigr)\geq
\frac{b^3(b-2)}{8(b-1)} - k\geq 
\frac{b^3(b-2)}{8(b-1)} - \frac{b}{2}
\geq \frac{b^3}{16}.
\]
\end{proof}

