\indent The overall optimization process of the proposed APG strategy is summarized in Algorithm~\ref{alg:1}. This iterative procedure jointly optimizes stego audio quality, message recovery accuracy, and anti-steganalysis performance. Experiments show that the APG strategy has significant antagonism against the detection of multiple steganalyzers.
\begin{algorithm}[h]
\caption{Audio Adversarial Perturbation Generation (APG) Strategy}
\label{alg:1}
\begin{algorithmic}[1]
\REQUIRE Cover audio $A_c\in{R}^T$, secret bits $M\in\{0,1\}^L$, decoder $D_e(\cdot)$, detectors $\{J_k\}_{k=1}^K$,\\
\hspace{\algorithmicindent}hyperparameters $\alpha,\beta,\gamma,\epsilon,\eta$, max iterations $N$
\ENSURE Perturbation $\delta$
\STATE $\delta \leftarrow \mathbf{0}$
\FOR{$i = 1$ \TO $N$}
  \STATE $A_s \leftarrow \operatorname{project}(A_c + \delta,\,-1,1)$ \hfill \COMMENT{build stego audio}
  \STATE $\hat M \leftarrow D_e(A_s)$                   \hfill \COMMENT{decode bits}
  \STATE $\ell_1 \leftarrow \|A_s -A_c\|_2^2$         \hfill\COMMENT{audio distortion}
  \STATE $\ell_2 \leftarrow \mathrm{BCE}(M,\,\hat M)$ \hfill\COMMENT{bit‐recovery loss}
  \STATE $\ell_3 \leftarrow -\sum_{k=1}^K \log\bigl(1 - J_k(A_s)\bigr)$ \hfill\COMMENT{anti‐detection loss}
  \STATE $\ell \leftarrow \alpha\,\ell_1 + \beta\,\ell_2 + \gamma\,\ell_3$
  \STATE $\delta \leftarrow \operatorname{AdamStep}(\delta,\nabla_{\delta}\ell,\eta)$
  \STATE $\delta \leftarrow \operatorname{project}(\delta,\,-\epsilon,\epsilon)$
\ENDFOR
\RETURN $\delta$
\end{algorithmic}
\end{algorithm}
