On $R_1$, the only internal basis function $\phi_1$ and its gradient are 
\an{\label{phi-1} 
   & \phi_1=\begin{cases} -4z(x-1) &\t{on} \ T_1, \\
                -4z(y-1)&\t{on} \ T_2, \\
                -4x(y-1)&\t{on} \ T_3, \\
                -4x(z-1)&\t{on} \ T_4, \\
                -4y(z-1)&\t{on} \ T_5, \\
                -4y(x-1)&\t{on} \ T_6, \end{cases} }
and
  \an{\label{phi-1d} &\ad{ \nabla\phi_1|_{T_1}&= \p{-4z \\ 0\\ -4x+4  },
       &   \nabla\phi_1|_{T_2}&= \p{ 0 \\-4z \\ -4y+4 }, \\
      \nabla\phi_1|_{T_3}&=  \p{-4y+4\\ -4x \\0  },
       &   \nabla\phi_1|_{T_4}&=  \p{ -4z + 4 \\ 0 \\ -4x  }, \\
      \nabla\phi_1|_{T_5}&= \p{ 0 \\ -4z+4 \\ -4y  },
       &   \nabla\phi_1|_{T_4}&=  \p{-4y \\ -4x + 4 \\ 0 }. } }




On $R_1$, we need to show three cases that $p=x^3$, $p=x^2y$ and $p=xyz$, 
   due to $xyz$-symmetry of $R_1$.
 For $p=x^3$,  on the six tetrahedra $T_i$,  cf. Figure \ref{3r1}, we have
 \an{\label{1-p} \ad{ p-I_2 p &= \frac 12 x(x-1)(2x-1), \ \t{on} \ T_i, i=1,\dots, 6, \\
    \nabla(p-I_2p) &= 
        \p{\frac 12-3x+3x^2\\0\\0 }, \ \t{on} \ T_i, i=1,\dots, 6. } }
 By \eqref{phi-1},  \eqref{phi-1d} and  \eqref{1-p}, we find the integral on the
   six tetrahedra $T_i$, 
\a{  (\nabla p- \nabla I_2 p, \nabla \phi_1)_{R_1} 
                    &=-\frac 1{30}+0+\frac 1{30}+\frac 1{30}+0-\frac 1{30} =0.  }

For $p=x^2y$,   on $R_1$, we have 
 \an{\label{1-p2} \ad{ p-I_2 p &=\begin{cases}
      y(x-1)(2x-1)/2, & \t{on} \ T_i, i=1,5, 6, \\
      x(y-1)(2x-1)/2, & \t{on} \ T_i, i=2,3,4, \end{cases} \\ 
    \nabla(p-I_2p) &= \begin{cases}
      \p{-\frac 32 y+ 2x y \\-\frac 32 x+\frac 12 + x^2 \\0 }, & \t{on} \ T_i, i=1,5, 6, \\
      \p{ \frac12-2x -\frac 12 y+ 2x y \\-\frac 12 x+ x^2 \\0 }, & \t{on} \ T_i, i=2,3,4. \end{cases} } }
By \eqref{phi-1},  \eqref{phi-1d} and  \eqref{1-p2}, we find the integral on the
   six tetrahedra $T_i$ of $R_1$, 
\a{   (\nabla (p- I_2 p), \nabla \phi_1)_{R_1}  
    =-\frac 1{30}-\frac 1{60}+\frac 1{45}+\frac 1{30}+\frac 1{60}-\frac 1{45}
                     =0.  }

For $p=xyz$,     on $R_1$, we have 
 \an{\label{1-p3} \ad{ p-I_2 p &=\begin{cases}
      z(x-1)(2y-1)/2, & \t{on} \ T_1, \\
                   z(y-1)(2x-1)/2, & \t{on} \ T_2, \\
                   x(y-1)(2z-1)/2, & \t{on} \ T_3, \\
                   x(z-1)(2y-1)/2, & \t{on} \ T_4, \\
                   y(z-1)(2x-1)/2, & \t{on} \ T_5, \\
                   y(x-1)(2z-1)/2, & \t{on} \ T_6, \end{cases} } }
and $\nabla(p-I_2p)=$
\an{\label{1-p3d} \begin{cases}
    \p{-\frac 12 z+ y z  
               \\xz-z 
                \\ -\frac 12 x+\frac 12 -y + x y   }, &T_1, \\
     \p{y z-z
              \\-\frac 12 z+x z 
               \\ -\frac 12 y + \frac 12 - x + x y  }, &T_2, \\
     \p{ - \frac 1 2  y +  \frac 1 2  - z + y z
               \\- \frac 1 2  x + x z
                \\ x y - x }, &T_3, \end{cases} &&  \begin{cases}
    \p{- \frac 1 2  z +  \frac 1 2  - y + y z
            \\ x z - x
             \\ - \frac 1 2  x + x y   }, &T_4, \\
     \p{ y z - y
          \\ - \frac 1 2  z +  \frac 1 2  - x + x z
           \\ - \frac 1 2  y + x y   }, &T_5, \\
     \p{- \frac 1 2  y + y z
             \\- \frac 1 2  x +  \frac 1 2  - z + x z
              \\x y - y   }, &T_6. \end{cases} } 
By \eqref{phi-1},  \eqref{phi-1d},  \eqref{1-p3} and  \eqref{1-p3d}, 
    we find the integral on the six tetrahedra $T_i$ of $R_1$, 
\a{  (\nabla (p- I_2 p), \nabla \phi_1)_{R_1}  
    =-\frac 1{45}-\frac 1{90}+\frac 1{90}+\frac 1{45}+\frac 1{90}-\frac 1{90}
                     =0.  } 

  The proof is complete.
\end{proof}






















