 On the four tetrahedra of $R_2$,  we find
\an{\label{phi-2} \phi_2=\begin{cases}
   x (x - 1)(2 x - 1) /2 &\t{on }\ T_1, 
                    \\x (x - 1)(2 x - 1) /2 &\t{on }\ T_2, 
                    \\x (x + 1) (2 x + 1)/2 &\t{on }\ T_3, 
                    \\x (x + 1) (2 x + 1)/2 &\t{on }\ T_4, \end{cases} }
and
\an{\label{phi-2g}    \ad{
  \nabla\phi_2|_{T_1} &=  \p{  4 z - 4\\ -4 z + 4\\ 4 x - 4 y },         
      &\nabla\phi_2|_{T_3} &=   \p{  4 z \\ -4 z \\ 4 x - 4 y + 4  }, \\
       \nabla\phi_2|_{T_2} &=  \p{  4 y - 4 \\ 4 x - 4 z  \\ -4 y + 4  },      
      &\nabla\phi_2|_{T_4} &=  \p{   4 y\\ 4 x - 4 z + 4\\ -4 y  }. } }

On $R_2$, we need to show six cases that $p=x^3$, $p=x^2y$, $p=xy^2$,$p=y^3$, $p=y^2z$ and $p=xyz$, 
   due to a $yz$-symmetry of $R_2$.


 For $p=x^3$,  on the 4 tetrahedra $T_i$ of $R_2$,  cf. Figure \ref{3r2}, we have
\an{\label{2-p}  p-I_2 p=\begin{cases}
   x (x - 1)(2 x - 1) /2 &\t{on }\ T_1, T_2, 
   \\x (x + 1) (2 x + 1)/2 &\t{on }\ T_3,T_4, \end{cases} }
and
\an{\label{2-pd}     
  \nabla(p-I_2 p) =\begin{cases}
   \p{-3 x + 1/2 + 3 x^2 \\0\\0 } &\t{on }\ T_1, T_2, 
   \\\p{3 x^2 + 3 x + 1/2 \\0\\0 } &\t{on }\ T_3,T_4. \end{cases} }
 By \eqref{phi-2},  \eqref{phi-2g},  \eqref{2-p} and  \eqref{2-pd}, 
    we find the integral on the four tetrahedra $T_i$ of $R_2$, 
\a{  (\nabla (p- I_2 p), \nabla \phi_2)_{R_2}  
    =-\frac 1{30}-\frac 1{30}+\frac 1{30}+ \frac 1{30} =0.  }


For $p=x^2y$,  on the 4 tetrahedra $T_i$ of $R_2$,   cf. Figure \ref{3r2}, we have
\an{\label{2-p2}  p-I_2 p=\begin{cases}
   x (y - 1) (2 x - 1)/ 2 &\t{on }\ T_1, T_2, 
   \\ x y (2 x + 1)/ 2  &\t{on }\ T_3,T_4, \end{cases} }
and
\an{\label{2-p2d}     
  \nabla(p-I_2 p)=\begin{cases}
   \p{ 1/2 - 2 x -  y/2  + 2 x y \\ - x/2  + x^2 \\0 } &\t{on }\ T_1, T_2, 
   \\ \p{  y/2  + 2 x y \\  x/2  + x^2 \\0 } &\t{on }\ T_3,T_4. \end{cases} }
 By \eqref{phi-2},  \eqref{phi-2g},  \eqref{2-p2} and  \eqref{2-p2d}, 
    we find the integral on the four tetrahedra $T_i$ of $R_2$,  
\a{  (\nabla (p- I_2 p), \nabla \phi_2)_{R_2} 
   =-\frac 7{180}-\frac 1{60}+\frac 7{180}+ \frac 1{60} =0.  }

For $p=x y^2$, on the 4 tetrahedra $T_i$ of $R_2$,   cf. Figure \ref{3r2}, we have
\an{\label{2-p3}  p-I_2 p=\begin{cases}
   x (y - 1) (2 y - 1)/ 2  &\t{on }\ T_1, T_2, 
   \\x y (2 y- 1)/ 2    &\t{on }\ T_3,T_4, \end{cases} }
and
\an{\label{2-p3d}     
  \nabla(p-I_2 p)=\begin{cases}
   \p{ -\frac 32 y + \frac 12 + y^2 \\ -\frac 32 x + 2 x y \\0 } &\t{on }\ T_1, T_2, 
   \\ \p{ -\frac 12 y + y^2 \\  -\frac 12 x + 2 x y\\0 } &\t{on }\ T_3,T_4. \end{cases} }
 By \eqref{phi-2},  \eqref{phi-2g},  \eqref{2-p3} and  \eqref{2-p3d}, 
    we find the integral on the four tetrahedra $T_i$ of $R_2$,  
\a{  (\nabla (p- I_2 p), \nabla \phi_2)_{R_2} 
    =-\frac 1{20}-\frac 1{180}+\frac 1{20}+ \frac 1{180} =0.  }

For $p= y^3$,   on the 4 tetrahedra $T_i$ of $R_2$,   cf. Figure \ref{3r2}, we have
\an{\label{2-p4}  p-I_2 p=\frac{y \left(2 y -1\right) \left(y -1\right)}{2} 
   \ \t{on }\ T_1,T_2,T_3,T_4,  }
and
\an{\label{2-p4d}     
  \nabla(p-I_2 p)=\p{ 0 \\ \frac{1}{2}-3 y +3 y^{2} \\ 0  } 
   \ \t{on }\ T_1,T_2,T_3,T_4.  }
 By \eqref{phi-2},  \eqref{phi-2g},  \eqref{2-p4} and  \eqref{2-p4d}, 
    we find the integral on the four tetrahedra $T_i$ of $R_2$,  
\a{  (\nabla (p- I_2 p), \nabla \phi_2)_{R_2}
    =-\frac 1{60}-\frac 1{60}+\frac 1{60}+ \frac 1{60} =0.  }

For $p= y^2z$,  on the 4 tetrahedra $T_i$ of $R_2$,   cf. Figure \ref{3r2}, we have
\an{\label{2-p5}  p-I_2 p=\begin{cases}
    {y \left(z -1\right) \left(2 y -1\right)}/{2}  &\t{on }\ T_1, T_4, 
   \\  {z \left(2 y -1\right) \left(y -1\right)}/{2}   &\t{on }\ T_2,T_3, \end{cases} }
and
\an{\label{2-p5d}     
  \nabla(p-I_2 p)=\begin{cases}
  \p{ 0 \\ -\frac{1}{2} z +\frac{1}{2}-2 y +2 y z \\ -\frac{1}{2} y +y^{2} } &\t{on }\ T_1, T_4, 
   \\ \p{ 0 \\ -\frac{3}{2} z +2 y z  \\ -\frac{3}{2} y +\frac{1}{2}+y^{2} } &\t{on }\ T_2,T_3. \end{cases} }
 By \eqref{phi-2},  \eqref{phi-2g},  \eqref{2-p5} and  \eqref{2-p5d}, 
    we find the integral on the four tetrahedra $T_i$ of $R_2$,  
\a{  (\nabla (p- I_2 p), \nabla \phi_2)_{R_2}
     =-\frac 1{90}-\frac 1{60}+\frac 1{90}+ \frac 1{60} =0.  }


For $p= xyz$,   on the 4 tetrahedra $T_i$ of $R_2$,   cf. Figure \ref{3r2}, we have
\an{\label{2-p6}  p-I_2 p=\begin{cases} 
 {x \left(z -1\right) \left(2 y -1\right)}/{2}   &\t{on }\ T_1, \\
 {x \left(2 z -1\right) \left(y -1\right)}/{2}   &\t{on }\ T_2,\\ 
 {x z \left(2 y -1\right)}/{2}   &\t{on }\ T_3, \\ 
 {x y \left(2 z -1\right)}/{2}   &\t{on }\ T_4, \end{cases} }
and
\an{\label{2-p6d}     \ad{
  p_1'&=\p{ -\frac{1}{2} z +\frac{1}{2}-y +y z  \\ x z -x \\ -\frac{1}{2} x +x y   }, & 
 p_2' &=\p{ -\frac{1}{2} y +\frac{1}{2}-z +y z \\ -\frac{1}{2} x +x z \\ x y -x  },\\ 
  p_3' &=\p{ -\frac{1}{2} z +y z \\ x z  \\-\frac{1}{2} x +x y   }, & 
 p_4' &=\p{ -\frac{1}{2} y +y z \\ -\frac{1}{2} x +x z  \\ x y     }, } } 
where $p_i'=\nabla(p-I_2 p)|_{T_i}$, $i=1,2,3,4$.
 By \eqref{phi-2},  \eqref{phi-2g},  \eqref{2-p6} and  \eqref{2-p6d}, 
    we find the integral on the four tetrahedra $T_i$ of $R_2$,  
\a{  (\nabla (p- I_2 p), \nabla \phi_2)_{R_2}
   =-\frac 1{30}-\frac 1{36}+\frac 1{30}+ \frac 1{36} =0.  }

  The proof is complete.
\end{proof}





















