 On the six tetrahedra of $R_3$,  we find
\an{\label{phi-3} \phi_3=\begin{cases}
   4 \left(z -1\right) \left(x -z \right)  &\t{on }\ T_1, \\
4 \left(z -1\right) \left(y -z \right) &\t{on }\ T_2,\\
-4 \left(y -z \right) \left(x -z +1\right) &\t{on }\ T_3,\\
4 \left(x -z +1\right) z &\t{on }\ T_4, \\
4 z \left(y -z +1\right) &\t{on }\ T_5,\\
-4 \left(y -z +1\right) \left(x -z \right) &\t{on }\ T_6, \end{cases} }
and
\an{\label{phi-3g}    \ad{
  \nabla\phi_3|_{T_1} &=  \p{ 4 z -4\\ 0\\ 4 x -8 z +4 },         
      &\nabla\phi_3|_{T_2} &=  \p{     0 \\ 4 z -4 \\4 y -8 z +4 }, \\
       \nabla\phi_3|_{T_3} &=  \p{  -4 y +4 z \\ -4 x +4 z -4\\ 4 x +4 y -8 z +4 }, 
       & \nabla\phi_3|_{T_4} &= \p{  4 z \\ 0\\ 4 x -8 z +4 },  \\    
       \nabla\phi_3|_{T_5} &=   \p{ 0\\ 4 z \\ 4 y -8 z +4 }, 
    &\nabla\phi_3|_{T_6} &= \p{ -4 y +4 z -4 \\ -4 x +4 z \\ 4 x +4 y -8 z +4 }. } }





On $R_3$, we need to show three cases that $p=x^3$, $p=x^2y$, $p=x^2z$,
     $p=z^3$, $p=x z^2$ and $p=xyz$, 
   due to an $xy$-symmetry of $R_3$.


 For $p=x^3$,  on the six tetrahedra $T_i$ of $R_3$,  cf. Figure \ref{3r3},  we have
\an{\label{3-p1}  p-I_2 p=\begin{cases}
   {x \left(2 x -1\right) \left(x -1\right)}/{2}&\t{on }\ T_1, T_2, T_6,
   \\ {x \left(1+x \right) \left(2 x +1\right)}/{2} &\t{on }\ T_3,T_4,T_5, \end{cases} }
and
\an{\label{3-p1d}     
  \nabla(p-I_2 p) =\begin{cases}
   \p{-3 x +\frac{1}{2}+3 x^{2}\\0 \\ 0 } &\t{on }\ T_1, T_2, T_6,
   \\\p{ 3 x^{2}+3 x +\frac{1}{2} \\ 0 \\ 0   } &\t{on }\ T_3,T_4,T_5. \end{cases} }
 By \eqref{phi-3},  \eqref{phi-3g},  \eqref{3-p1} and  \eqref{3-p1d}, 
    we find the integral on the six tetrahedra $T_i$ of $R_3$, 
\a{  (\nabla (p- I_2 p), \nabla \phi_3)_{R_3} 
   = \frac 1{30}+0+\frac 1{30}-\frac 1{30}+0-\frac 1{30} =0.  }



For $p=x^2y$,   on the six tetrahedra $T_i$ of $R_3$,  cf. Figure \ref{3r3},  we have
\an{\label{3-p2}  p-I_2 p=\begin{cases}
  {y \left(2 x -1\right) \left(x -1\right)}/{2}&\t{on }\ T_1,\\
  {x \left(y -1\right) \left(2 x -1\right)} /{2}&\t{on }\  T_2,\\
  {x y \left(2 x +1\right)} /{2}&\t{on }\  T_3,\\
  {y \left(1+x \right) \left(2 x +1\right)} /{2}&\t{on }\ T_4,\\
  {x \left(y +1\right) \left(2 x +1\right)} /{2}&\t{on }\ T_5,\\
  {x y \left(2 x -1\right)} /{2}&\t{on }\ T_6,  \end{cases} }
and
\an{\label{3-p2d} \ad{  g_{1} &= \p{-\frac{3}{2} y +2 x y \\-\frac{3}{2} x +\frac{1}{2}+x^{2}\\ 0 }, 
  &   g_{2} &=\p{\frac{1}{2}-2 x -\frac{1}{2} y +2 x y \\ -\frac{1}{2} x +x^{2} \\ 0  },  \\
 g_{3} &= \p{ \frac{1}{2} y +2 x y \\ \frac{1}{2} x +x^{2} \\ 0  }, 
  &   g_{4} &= \p{\frac{3}{2} y +2 x y \\ \frac{3}{2} x +\frac{1}{2}+x^{2} \\ 0   },  \\
   g_{5} &= \p{ 2 x +\frac{1}{2} y +\frac{1}{2}+2 x y \\ \frac{1}{2} x +x^{2} \\ 0   }, 
  &   g_{6} &= \p{ -\frac{1}{2} y +2 x y  \\-\frac{1}{2} x +x^{2}  \\0  },  } }
  where $g_{i}=\nabla(p-I_2p)|_{T_i}$.
 By \eqref{phi-3},  \eqref{phi-3g},  \eqref{3-p2} and  \eqref{3-p2d}, 
    we find the integral on the six tetrahedra $T_i$ of $R_3$, 
\a{  (\nabla (p- I_2 p), \nabla \phi_3)_{R_3}  
  = \frac 1{30}+ \frac 1{180}+ \frac 1{60}-\frac 1{30}-\frac 1{180}-\frac 1{60} =0.  }




For $p=x^2z$,   on the six tetrahedra $T_i$ of $R_3$,  cf. Figure \ref{3r3},  we have
\an{\label{3-p3}  p-I_2 p=\begin{cases}
  {x \left(z -1\right) \left(2 x -1\right)}/{2}&\t{on }\ T_1,  T_2, T_6, \\
  {x z \left(2 x +1\right)}/{2}&\t{on }\  T_3,  T_4,  T_5,  \end{cases} }
and
\an{\label{3-p3d}\nabla(p-I_2p)=\begin{cases}
  \p{-2 x -\frac{1}{2} z +\frac{1}{2}+2 x z \\ 0 \\ -\frac{1}{2} x +x^{2} }&\t{on }\ T_1,  T_2, T_6, \\
  \p{ \frac{1}{2} z +2 x z  \\ 0 \\ \frac{1}{2} x +x^{2}  }&\t{on }\  T_3,  T_4,  T_5.  \end{cases} } 
 By \eqref{phi-3},  \eqref{phi-3g},  \eqref{3-p3} and  \eqref{3-p3d}, 
    we find the integral on the six tetrahedra $T_i$ of $R_3$, 
\a{  (\nabla (p- I_2 p), \nabla \phi_3)_{R_3} 
   = \frac 1{45}+ 0+ \frac 1{30}-\frac 1{45}-0-\frac 1{30} =0.  }



For $p=x^2z$,   on the six tetrahedra $T_i$ of $R_3$,  cf. Figure \ref{3r3},  we have
\an{\label{3-p4}  p-I_2 p= {z \left(2 z -1\right) \left(z -1\right)}/{2} \quad \
          \t{on }\ T_i, i=1,\dots,6, }
and
\an{\label{3-p4d}\nabla(p-I_2p)=\p{0 \\ 0 \\ -3 z +\frac{1}{2}+3 z^{2} }\quad \
          \t{on }\ T_i, i=1,\dots,6. }
 By \eqref{phi-3},  \eqref{phi-3g},  \eqref{3-p4} and  \eqref{3-p4d}, 
    we find the integral on the six tetrahedra $T_i$ of $R_3$, 
\a{  (\nabla (p- I_2 p), \nabla \phi_3)_{R_3}  = 0+0+0+0+0+ 0  =0.  }





For $p=x z^2$,    on the six tetrahedra $T_i$ of $R_3$,  cf. Figure \ref{3r3},  we have
\an{\label{3-p5}  p-I_2 p=\begin{cases}
  {x \left(2 z -1\right) \left(z -1\right)}/{2}&\t{on }\ T_1,  T_2, T_6, \\
  {x z \left(2 z -1\right)} /{2}&\t{on }\  T_3,  T_4,  T_5,  \end{cases} }
and
\an{\label{3-p5d}\nabla(p-I_2p)=\begin{cases}
  \p{ -\frac{3}{2} z +\frac{1}{2}+z^{2} \\ 0 \\ -\frac{3}{2} x +2 x z    } &\t{on }\ T_1,  T_2, T_6, \\
 \p{  -\frac{1}{2} z +z^{2} \\ 0 \\ -\frac{1}{2} x +2 x z    } &\t{on }\  T_3,  T_4,  T_5.  \end{cases} } 
 By \eqref{phi-3},  \eqref{phi-3g},  \eqref{3-p5} and  \eqref{3-p5d}, 
    we find the integral on the six tetrahedra $T_i$ of $R_3$, 
\a{  (\nabla (p- I_2 p), \nabla \phi_3)_{R_3}  = 0+0+0+0+0+ 0  =0.  }




For $p=xyz$,  on the six tetrahedra $T_i$ of $R_3$,  cf. Figure \ref{3r3},  we have
\an{\label{3-p6}  p-I_2 p=\begin{cases}
  {y \left(z -1\right) \left(2 x -1\right)} /{2}&\t{on }\ T_1,\\
  {x \left(z -1\right) \left(2 y -1\right)} /{2}&\t{on }\  T_2,\\
  {x y \left(2 z -1\right)} /{2}&\t{on }\  T_3,\\
  {y z \left(2 x +1\right)} /{2}&\t{on }\ T_4,\\
  {x z \left(1+2 y \right)} /{2}&\t{on }\ T_5,\\
  {x y \left(2 z -1\right)} /{2}&\t{on }\ T_6,  \end{cases} }
and
\an{\label{3-p6d} \ad{  g_{1} &= 
   \p{ y z -y  \\ -\frac{1}{2} z +\frac{1}{2}-x +x z  \\ -\frac{1}{2} y +x y   },
  &   g_{2} &=\p{   -\frac{1}{2} z +\frac{1}{2}-y +y z  \\ x z -x  \\ -\frac{1}{2} x +x y   },   \\
      g_{3} &= \p{ -\frac{1}{2} y +y z  \\ -\frac{1}{2} x +x z  \\ x y    }, 
  &   g_{4} &= \p{  y z  \\ \frac{1}{2} z +x z  \\ \frac{1}{2} y +x y   },   \\
   g_{5} &= \p{  \frac{1}{2} z +y z  \\ x z  \\ \frac{1}{2} x +x y   },  
  &   g_{6} &= \p{ -\frac{1}{2} y +y z  \\ -\frac{1}{2} x +x z  \\ x y      },   } }
  where $g_{i}=\nabla(p-I_2p)|_{T_i}$.
 By \eqref{phi-3},  \eqref{phi-3g},  \eqref{3-p6} and  \eqref{3-p6d}, 
    we find the integral on the six tetrahedra $T_i$ of $R_3$, 
\a{  (\nabla (p- I_2 p), \nabla \phi_3)_{R_3}  
  = \frac 1{45}+ \frac 1{90}+ \frac 1{180}- \frac 1{45}- \frac 1{90}-\frac 1{180}  =0.  }



  The proof is complete.
\end{proof}












