\section{Superconvergence}


We prove the $H^1$ and $L^2$ superconvergence in this section.


\begin{theorem}
Let $u \in H^4(\Omega) \cap H^1_0 (\Omega)$
    be the solution of the Poisson equation \eqref{e1-1}--\eqref{e1-2}. 
Let $u\in V_h $ of \eqref{V-h}
    be the solution of the finite element equation   \eqref{finite}.
It holds that   
\an{  \label{sup-1}  |I_h u -u_{h}|_{1} & \le  C h^4  |u|_{4}, }
where $I_h$ is the $P_2$ Lagrange interpolation operator. 
\end{theorem}
\begin{proof}  
 Multiplying \eqref{e1-1} by $  v_h\in  V_h$  and
  doing integration by parts,  we get
\an{\label{p-1}  
     ( \nabla  u,\nabla  v_h) &=(  f, v_h).
} 
 Subtracting \eqref{p-1} from \eqref{finite}, we get
\an{\label{p-2}  
     ( \nabla(  u- u_h), \nabla v_h )=0 \quad \forall v_h \in V_h .
} 

 By \eqref{p-2}, \eqref{d-3-1}, \eqref{d-3-2}, \eqref{d-3-3} and
   \eqref{d-3-4},we have, denoting $v_h=I_h u - u_h\in V_h$,
\a{  |I_h u-u_h|_1^2 &= (\nabla(I_h u-u), \nabla v_h) \\
 &=\quad \sum_{R_1\subset\Omega} c_{1,i}(\nabla(I-I_h)(I-P_{3,1}) u, \nabla \phi_1)_{R_1} \\
&\quad \ + \sum_{R_2\subset\Omega} c_{2,i}(\nabla(I-I_h)(I-P_{3,2}) u, \nabla\phi_2)_{R_2} \\
&\quad \ + \sum_{R_3\subset\Omega} c_{3,i}(\nabla(I-I_h)(I-P_{3,3}) u, \nabla\phi_3)_{R_3} \\
&\quad \ + \sum_{R_4\subset\Omega} c_{4,i}(\nabla(I-I_h)(I-P_{3,4}) u, \nabla\phi_4)_{R_4} \\
    &\le C \bigg(\sum_{j=1}^4 \Big(\sum_{R_j \subset\Omega} |(I-P_{3,j}) u|_{1,R_j}^2\Big)^{\frac 12}
              \bigg) |v_h|_1 \\
    &\le C \bigg(\sum_{j=1}^4 \Big(\sum_{R_j\subset\Omega } h^8|u|_{4,R_j}^2\Big)^{\frac 12}
              \bigg) |v_h|_1 \\
    & = C h^4 |u|_4 |v_h|_1,  }
where $P_{3,j}$ is the local $L^2$ projection operator on to $P_3(R_j)$,
   and $I-I_h$ is $H^1$-stable, cf. \cite{Scott-Zhang}.
Hence, canceling one $| v_h|_{1}$ on each side, we get \eqref{sup-1}.
The proof is complete.
\end{proof}




To prove the $L^2$-supconvergence we use the standard duality argument.  Let 
  $ w \in H^1_0(\Omega)$  such that
  \an{\label{e-w}   -  \Delta  w &=I_h u-u_h \qquad \hbox{in } \Omega.  } 
We assume the following full-regularity,
\an{\label{regularity} | w|_2 \le C \|I_h u-u_h\|_0.  }





\begin{theorem} 
Let $u \in H^4(\Omega) \cap H^1_0 (\Omega)$
    be the solution of the Poisson equation \eqref{e1-1}--\eqref{e1-2}. 
Let $u\in V_h $ of \eqref{V-h}
    be the solution of the finite element equation   \eqref{finite}.
Assuming the full regularity  \eqref{regularity}, it holds that    
\an{ \label{sup-2}
   \| I_h u - u_{h}\|_{0}  & \le  C h^4  | {u} |_{4} . } 
\end{theorem} 

\begin{proof} 
Multiplying \eqref{e-w} by $(I_h u - u_{h})$ and
  doing integration by parts,  we get
\an{\label{j1} \|I_h u - u_{h}\|_0^2  &=  (  \nabla  w , \nabla(I_h u - u_{h})) .
} 
Let $ w_h\in   V_h$  be the $P_2$ finite element solution for problem
    \eqref{e-w}, satisfying 
 \an{\label{j1-2}
    ( \nabla  w_h , \nabla v_h )  &=(I_h u - u_{h},  v_h)  \qquad  \forall  v_h & \in V_h . 
    }  
By \eqref{sup-1}, we can get the quasi-optimal error bound for $w_h$ that
\an{\label{h1} |w-w_h|_1 \le |w-I_h w |_1 + |I_h w-w_h|_1 \le Ch |w|_2. }


Subtracting \eqref{j1-2} from \eqref{j1}, by the quasi-optimal error bound \eqref{h1} and
    the assumed elliptic regularity \eqref{regularity},   we get
\an{\label{j3} \ad{ \|I_h u - u_{h} \|_0^2  &=
     ( \nabla( w- w_h), \nabla(I_h u - u_{h})) \\
           & \le C h |w|_2 h^3 |u|_4 \le Ch^4 |u|_4  \|I_h u - u_{h} \|_0. } } 
After canceling one $\|I_h u - u_{h}\|_0$, \eqref{sup-2} follows \eqref{j3}.
 The proof is complete.
\end{proof}








