\subsubsection{Practical FEM computation} \label{subsec:FEM}

We focus on solving the full diffusion-reaction boundary value problem
\begin{equation} \label{BVP}
\begin{split}
-\nabla \cdot \big(\cKx \, \nabla \ux\big) + \cMx \, \ux &= \fx \qquad \, \mbox{in} \:\: \Omega \, , \\
\ux &= \uDx \quad \,\,\, \mbox{on} \:\: \Gamma_D \subset \partial \Omega \, , \\
\frac{\partial \uL}{\partial n}(\x) &= 0 \qquad\quad\;\;\, \mbox{on} \:\: \Gamma_N \subset \partial \Omega \, . \\
\end{split}
\end{equation} 
We consider an L-shaped domain $\Omega$ given by the union of rectangles $$(0,\,0.25) \times (0,\,0.25) \, , \;\; (0,\,0.25) \times (0.25,\,1) \, , \;\; (0.25,\,1) \times (0,\,0.25)$$ and shown with its triangulation on the left part of 
Figure \ref{fig:Poisson}.
\begin{figure}
\centering
\begin{minipage}[c]{0.43\textwidth}
\includegraphics[width=\textwidth]{mesh_BVP_P2_lev_1_2.png}
\end{minipage} \:\:\:
\begin{minipage}[c]{0.52\textwidth}
\includegraphics[width=\textwidth]{solution_BVP_P2_lev_1.png}
\end{minipage}
\caption{The computational mesh for P2 elements (left) with $\nt = 112$ and $\nn =257$ (including mid-edge points) and the solution of \eqref{BVP} (right).}
\label{fig:Poisson}
\end{figure}
A non-homogeneous 
Dirichlet boundary condition is assumed on the upper edge $\Gamma_D$ (red nodes) and a zero Neumann boundary condition on the remaining part of the domain boundary $\Gamma_N = \partial \Omega \setminus \Gamma_D$.
One can show that the function
\begin{equation} \label{ux}
    u(\x) = \cos(4 \pi \, x_1) \, \cos(4 \pi \, x_2)
\end{equation}
is the solution of \eqref{BVP} for coefficient functions
$ c_K(\x) = 1 + x_1^2 - x_2 \, , \; c_M(\x) = 1 - x_1 + x_2^2 \, , $ \,
the right-hand side
\begin{equation} %\label{fx}
    \begin{split}
        f(\x) = 8 \pi x_1 \sin(4 \pi x_1) \cos(4 \pi x_2) + \cos(4 \pi x_1) \big( -4 \pi \sin(4 \pi x_2) + \\
        + \big(1 -x_1 + 32 \pi^2 (1 +x_1^2 -x_2) + x_2^2\big) \cos(4 \pi x_2) \big)
    \end{split}
\end{equation}
and the Dirichlet boundary condition
$\uDx = \cos(4 \pi x_1), \; x_1 \in [0,0.25], \; x_2 = 1.$ \\

\noindent
The script
\begin{verbatim}
  benchmark7_BVP_2D
\end{verbatim}
evaluates numerical solutions $\unumx$ (represented by vectors $\uvec$ of coefficients in a finite element basis) of the boundary value problem \eqref{BVP} for different mesh refinements using P1 or P2 finite elements. An example of a P2 solution is shown on the right part of Figure \ref{fig:Poisson}.
Practically, a linear system of equations
\begin{equation}\label{linear_system}
(K + M) \, \uvec = b
\end{equation}
is assembled in which entries of the right-hand size vector $b$ are given by 
\begin{equation} \label{bi}
    b_i = \int_{\Omega} f(\x) \, \Phi_i(\x) \, \dxdydz \, , \qquad i \in \{1, \hdots, \nn\} \, .
\end{equation}
Then it is solved for free entries of $\uvec$, i.e., to those not corresponding to the Dirichlet boundary conditions.


\subsubsection*{Evaluation of the right-hand side vector}
One can evaluate \eqref{bi} by $b = M_0 \, \fvec$, where $M_0$ is the mass matrix corresponding to $\cMx = 1$ and $\fvec$ is a vector of coefficients representing the approximation of $f(\x)$ in a finite element basis. However, this approach is computationally too expensive as long as an additional global mass matrix has to be assembled. Instead, we calculate scalar products of $f(\x)$ and local basis functions ($nlb$ denotes their number)
\begin{equation} \label{fphi}
    \int_{T_k} f(\x) \, \varphi_j(\x) \, , \qquad k \in \{1,\hdots,\nt\} \, , \quad j \in \{1,\hdots,nlb\} \, ,
\end{equation}
on each element. Consequently, any $b_i$ from \eqref{bi} is given as a sum of particular contributions from \eqref{fphi}.

\begin{mm}[caption={The right-hand side vector $b$.},label={rhs}]
function [b,b2D] = rhs_vectorP1(elems,coords,f_fun)

dim = size(coords,2);  % problem dimension
ne = size(elems,1);    % number of elements

gqo = 2;  [ip,w,nip] = intquad(gqo,dim);
coeffs = coeffs_in_ip(coords,elems,f_fun,gqo);  % nip x ne

sizes = sizes_of_elements(coords,elems);
detj_abs = sizes*factorial(dim);  % nip x ne

nlb = size(elems,2);

phiRef = shapefun(ip','P1');
b2D = zeros(nlb,ne);
for i=1:nip  % loop over all IPs
    phi1D = phiRef(:,i);  % in one IP
    integrand_i = coeffs(i,:).*phi1D;
    b2D = b2D + w(i)*detj_abs'.*integrand_i;
end

elems = elems';
b = accumarray(elems(:),b2D(:));
\end{mm}
The code \ref{rhs} evaluates the right-hand side vector $b$ from \eqref{bi} for P1 elements. The only loop starting at line 16 running over the number of integration points evaluates the scalar products \eqref{fphi} that are stored in a matrix \textbfn{b2D}.


\subsubsection*{Evaluation of (local) energies}
An alternative to solve the boundary value problem \eqref{BVP} is to minimize a quadratic energy functional (see \cite{MoVa} for details related to efficient minimization of nonlinear functionals)
\begin{equation}
J(v) = \int_{\Omega} \left( \frac{1}{2} \cKx \|\nabla \vx\|^2 +
\frac{1}{2} \cMx \, \vx^2 \, - \fx \, \vx \right) \dxdydz
\end{equation}
among all testing functions $\vx$ satisfying the Dirichlet boundary condition 
$\vx = \uDx \mbox{ on } \Gamma_D \subset \partial \Omega $.
The minimal value of the energy $J(v)$ is achieved for $v(\x) = u(\x)$, where the exact solution $u(\x)$ is given by \eqref{ux} and 
reads 
 $$ J(u) = \Ja(u) + \Jb(u) + \Jc(u) \approx -14.90302171 \, .$$
Its gradient, reactive and linear parts are
\begin{eqnarray*}
      &&  \Ja(u) = \frac{1}{2} \int_{\Omega} \cKx\ \|\nabla \ux\|^2 \, \dxdydz \,
        = \frac{289 \, \pi^2}{192} \approx 14.85581079 \, , \\
      &&  \Jb(u) = \frac{1}{2} \int_{\Omega} \cMx \, \ux^2 \, \dxdydz \, = \frac{578 \, \pi^2 + 21}{12228 \, \pi^2} \approx 0.04721091674 \, , \\
      &&  \Jc(u) = -\int_{\Omega} \fx \, \vx \, \dxdydz = -\frac{578 \, (32 \, \pi^4 + \pi^2) + 21}{6144 \, \pi^2} \approx -29.80604342 \, .   
\end{eqnarray*}
Using the global matrices $K, M$ and the global vector $b$, values of all three parts are approximated by
\begin{equation} \label{J_comps}
J_1(u) \approx \frac{1}{2} \uvec^T K \uvec \, , \qquad J_2(u) \approx \frac{1}{2} \uvec^T M \uvec \, , \qquad J_3(u) \approx -b^T \uvec \, .
\end{equation}
For any element $T_k$, $k \in \{1, \hdots, \nt\}$, we can also define the local (element-wise) contributions to the energy parts above by formulas
\begin{equation*}
    \begin{split}
        \Jak(u) &= \frac{1}{2} \int_{T_k} \cKx\ \|\nabla \ux\|^2 \, \dxdydz \, , \\
        \Jbk(u) &= \frac{1}{2} \int_{T_k} \cMx \, \ux^2 \, \dxdydz \, , \\
        \Jck(u) &= - \int_{T_k} \fx \, \ux \, \dxdydz \,  
    \end{split}
\end{equation*}
and it holds
\begin{equation*}
    J_i(u) = \sum_{k=1}^{\nt} J_{i,k}(u) \, , \qquad i = 1, \, 2, \, 3.
\end{equation*}
Since our implementation also provides local (element-wise) contributions of $K3D, \, M3D, \, b2D$, it is possible (similarly to \eqref{J_comps} to evaluate the approximations of $\Jak, \, \Jbk, \, \Jck$ for all elements $T_k, \; k \in \{1, \hdots, \nt\}$, at once by
\begin{equation} \label{Jk_comps}
\Jak(u) \, \approx \, \frac{1}{2} \, \uveck^T \, \Kk \, \uveck \, , \quad\; \Jbk(u) \, \approx \, \frac{1}{2} \, \uveck^T \, \Mk \, \uveck \, , \quad\; \Jck(u) \, \approx \, -\bk^T \, \uveck \, .
\end{equation}
Here, $\Kk$ and $\Mk$ are the local stiffness and mass matrices on the $k$-th element, respectively. Similarly, $\bk$ and $\uveck$ are restrictions of $b$ and $\uvec$ on the $k$-th element, respectively. Fig. \ref{fig:Jcomponents} depicts the approximations of energy components \eqref{Jk_comps} for level 4 computational mesh.

