\begin{center}
\Large\bf On existence of a variational regularization parameter under Morozov's discrepancy principle
\end{center}

\begin{center}
Liang Ding\footnote{Department of Mathematics, Northeast Forestry University, Harbin 150040, China;
e-mail: {\tt dl@nefu.edu.cn}. The work of this author was supported by the Fundamental Research Funds
for the Central Universities (no.\ 2572021DJ03).}\quad 
Long Li\footnote{Department of Mathematics, Northeast Forestry University, Harbin 150040, China;
e-mail: {\tt 15146259835@nefu.edu.cn}.}\quad
Weimin Han\footnote{Department of Mathematics, University of Iowa, Iowa City, IA 52242, USA;
e-mail: {\tt weimin-han@uiowa.edu}.}\quad
Wei Wang\footnote{Department of Mathematics, Jiaxing University, Jiaxing 314001, China;
e-mail: {\tt weiwang@zjxu.edu.cn}.}
\end{center}


\smallskip
\begin{quote}
{\bf Abstract.}
{Morozov's discrepancy principle is commonly adopted in Tikhonov regularization for choosing the regularization parameter. Nevertheless, for a general non-linear inverse problem, the discrepancy $\|F(x_{\alpha}^{\delta})-y^{\delta}\|_Y$ does not depend continuously on $\alpha$ and it is questionable whether there exists a regularization parameter $\alpha$ such that $\tau_1\delta\leq \|F(x_{\alpha}^{\delta})-y^{\delta}\|_Y\leq \tau_2 \delta$ $(1\le \tau_1<\tau_2)$. In this paper, we prove the existence of $\alpha$ under Morozov's discrepancy principle if $\tau_2\ge (3+2\gamma)\tau_1$, where $\gamma>0$ is a parameter in a tangential cone condition for the nonlinear operator $F$. Furthermore, we present results on the convergence of the regularized solutions under Morozov's discrepancy principle. Numerical results are reported on the efficiency of the proposed approach.}

\end{quote}

\smallskip
\noindent
{\bf Keywords.}  Non-linear inverse problem, Morozov's discrepancy principle, tangential cone condition, convex penalty


\section{Introduction}\label{sec1}

\par In this paper, we consider to solve an operator equation of the form
\begin{equation}\label{equ1.1}
    F(x)=y,
\end{equation}
where $F: X\rightarrow Y$ is a nonlinear operator between two reflexive Banach spaces $X$ and $Y$. We assume $y^{\delta}\in Y$ is known with $\|y^{\delta}-y\|_{Y}\leq \delta$ for a given $\delta\geq 0$. The commonly adopted technique to solve problem \eqref{equ1.1} is the Tikhonov regularization of the form
\begin{equation}\label{equ1.2}
    \min\limits_{x\in X}\bigg\{\mathcal{J}_{\alpha}^{\delta}(x)= \frac{1}{2}\|F(x)-y^{\delta}\|_Y^{2}+\alpha\mathcal{R}(x)\bigg\},
\end{equation}
where $\alpha>0$ and ${\cal R}$ is a convex penalty term, cf.\ the monographs \cite{F2010,SGGHL2009} and the special issues \cite{BB18,DDD16,JM12,JMS17} for many developments on regularization properties and minimization schemes.

\par In practice, it is crucial to choose an appropriate regularization parameter $\alpha$ for problem \eqref{equ1.2}. Morozov's discrepancy principle (MDP) is the most commonly adopted technique to determine the regularization parameter $\alpha=\alpha(\delta, y^{\delta})>0$ such that
\begin{equation}\label{equ1.3}
    \tau_1\delta\leq \|F(x_{\alpha}^{\delta})-y^{\delta}\|_Y\leq \tau_2 \delta,
\end{equation}
where $1\le\tau_1<\tau_2$ and $x_{\alpha}^{\delta}$ is a minimizer of $\mathcal{J}_{\alpha}^{\delta}(x)$ in \eqref{equ1.2}. If the minimizer of $\mathcal{J}_{\alpha}^{\delta}(x)$ is unique, there exists a regularization parameter $\alpha$ such that \eqref{equ1.3} holds (\cite{AD19,AR10,TA1977}). However, due to the non-linearity of $F$, there may exist multiple minimizers of $\mathcal{J}_{\alpha}^{\delta}(x)$, the discrepancy $\|F(x_{\alpha}^{\delta})-y^{\delta}\|_Y$ does not exhibit continuous dependence on $\alpha$ and one can not ensure the existence of $\alpha$ such that \eqref{equ1.3} holds (\cite{R02, TA1977}). Indeed, a weakness of MDP lies in the fact that a regularization parameter $\alpha$ satisfying \eqref{equ1.3}
might not exist for a general nonlinear operator equation. In some applications of non-linear inverse problems, one has to assume the existence of $\alpha$ such that \eqref{equ1.3} holds. Few results are available on the existence of $\alpha$ under MDP.

\subsection{Related works}\label{sec1.1}

\par The first theoretical analysis on MDP for the Tikhonov regularization dates back to 1966 (\cite{M66}). Several numerical algorithms have been proposed to compute the regularization parameter $\alpha$ for the classical quadratic Tikhonov regularization (\cite{FM99,L1989,MPRS01}). Subsequently, MDP is extended to general convex regularizations. If $\mathcal{R}(x)$ is convex, then $\left\|F\left(x_{\alpha}^{\delta}\right)-y^{\delta}\right\|_{Y}$ depends continuously on $\alpha$, and the existence of $\alpha$ follows. In \cite{B09}, MDP is applied to the Tikhonov regularization with convex penalty terms  more general than the classical quadratic one. In \cite{JZZ12}, two iterative parameter choice methods by MDP are proposed for non-smooth Tikhonov regularization with general convex penalty terms.

\par We note that the results cited in the previous paragraph are limited to linear ill-posed problems. Due to the existence of possibly multiple minimizers, the techniques for linear ill-posed problems can not be extended to nonlinear ill-posed operator equations directly. Special regularization techniques are needed to explore the existence of the regularization parameter $\alpha$ which is determined by MDP. In \cite{R02}, for the classical quadratic Tikhonov regularization, it is shown that if $\tau_1=1$ and
    \[ \tau_2> 1+\frac{L+2\|F'({x^{\dag}})\|}{L}\max\left\{\frac{4}{Q^2}, 1\right\}, \]
the existence of $\alpha$ can be guaranteed, where $x^{\dag}$ is an $\mathcal R$-minimum solution of the equation \eqref{equ1.1}, and the parameters $L$ and $Q$ depend on the source condition and the lower bound of $x^{\dag}$. In \cite{AR10}, for a general convex penalty term, the existence of $\alpha$ is proved under the following condition:
there is no $\alpha>0$ with minimizers $x_{\alpha}^{\delta,1},x_{\alpha}^{\delta,2}$ such that
    \[\|F(x_{\alpha}^{\delta,1})-y^{\delta}\|_{Y}<\tau_1\delta <\tau_2\delta<\|F(x_{\alpha}^{\delta,2})-y^{\delta}\|_{Y}.\]
In \cite{AR11}, convergence rates are investigated via variational inequalities, where the regularization parameter is determined by MDP. A relation between uniqueness of minimizers in Tikhonov-type regularization and Morozov-like discrepancy principles is shown in \cite{AD19}. In \cite{DH23}, the convex function $\mathcal{R}(x)$ is replaced by a non-convex penalty term $\alpha\ell_{1}(x)-\beta\ell_{2}(x)$, and the existence of the regularization parameter $\alpha$ is demonstrated. It is proven that there exists at least one $\alpha$ such that
\begin{equation}\label{equ1.4}
    \delta\le\|F(x_{\alpha,\beta}^{\delta})-y^{\delta}\|_{Y}\le \left(\max\left\{ \tau^{2}\delta^2,(3+2\gamma)\delta^{2}+\delta(2+2\gamma) \|y^{\delta}-F(0)\|_Y\right\}\right)^{\frac{1}{2}}.
\end{equation}
However, \eqref{equ1.4} does not give a same order for the lower and the upper bound. The upper bounded is only $O(\sqrt{\delta})$.

\subsection{Contribution and organization}

\par In this paper, we assume $\mathcal{R}$ is convex and the operator $F$ satisfies a tangential cone condition: there exists a constant $\gamma>0$ such that
for arbitrary $x_1, x_2\in \mathcal{L}_{\alpha}^{\delta}$,
    \[ \|F(x_2)-F(x_1)-F'(x_1)(x_2-x_1)\|_Y\leq \gamma\|F(x_2)-F(x_1)\|_Y,\]
where $\mathcal{L}_{\alpha}^{\delta}$ represents the set of all minimizers of the functional $\mathcal{J}_{\alpha}^{\delta}\left(x\right)$ defined in \eqref{equ1.2}. We will prove that there exists at least one $\alpha$ such that
\begin{equation}\label{equ1.5}
    \tau_1\delta\le\|F(x_{\alpha}^{\delta})-y^{\delta}\|_{Y}\le c\delta,
\end{equation}
where $c:=\max\left\{ \tau_2,\tau_1(3+2\gamma)\right\}$. This implies that if $\tau_2\ge \tau_1(3+2\gamma)$, the existence of $\alpha$ can be guaranteed.
Based on \eqref{equ1.5}, we will investigate the well-posedness and convergence rate of the regularized solution of the problem \eqref{equ1.2}. We will show that with the parameter choice rule \eqref{equ1.5}, $\alpha\rightarrow 0$ as the noise level $\delta\rightarrow 0$.

\par For the traditional MDP for linear ill-posed problems, the existence of $\alpha$ is guaranteed. However, for nonlinear ill-posed problems, the discrepancy term $\|F(x_{\alpha}^{\delta})-y^{\delta}\|_{Y}$ is not continuous with respect to $\alpha$. So it is challenging to choose appropriate values of $\tau_1$ and $\tau_2$ to ensure the existence of $\alpha$. We will prove that the modified MDP \eqref{equ1.5} can ensure the existence of $\alpha$ and we can apply Algorithm \ref{alg1} to determine the value of $\alpha$.
% So the upper bound $c\delta$ is natural for the development of the algorithm. 
We will present results from two numerical experiments to show that the upper bound $c\delta$ in \eqref{equ1.5} is actually needed, cf.\ Fig.\ \ref{fig6} and Fig.\ \ref{fig10}.

An outline of the rest of this paper is as follows. In the next section we introduce the notation and review some results on the Tihkonov regularization with a general convex penalty term. In Section \ref{sec3}, we investigate the existence of $\alpha$ determined by MDP \eqref{equ1.5}. In Section \ref{sec4}, we present results on the well-posedness and the convergence rate of the regularized solution under MDP \eqref{equ1.5}. In addition, we show that MDP \eqref{equ1.5} can guarantee $\alpha(\delta,y^{\delta})\rightarrow0$ as $\delta\rightarrow 0$. Finally, numerical results are reported in Section \ref{sec5} on a nonlinear compressive sensing problem and a nonlinear one-dimensional gravity inversion problem.


\section{Preliminaries}\label{sec2}

\par We first briefly introduce some notation for the Tikhonov regularization. Denote by
\begin{equation}\label{equ2.1}
    x^{\delta}_{\alpha}\in \mathop{\arg\min}_{x\in X}\left\{\frac{1}{2} \|F(x)-y^{\delta}\|_Y^{2}+\alpha\mathcal{R}(x)\right\}
\end{equation}
a minimizer of the regularization function $\mathcal{J}_{\alpha}^{\delta}(x)$ defined
in (\ref{equ1.2}). Let $\mathcal{L}^{\delta}_{\alpha}$ be the set of all such minimizers $x^{\delta}_{\alpha}$.
An element $x^{\dagger}\in X$ is called an $\mathcal R$-minimum solution of the equation \eqref{equ1.1} if
    \[ F(x^{\dagger})=y~~and~~ \mathcal R(x^{\dagger})
    =\min\limits_{x\in X}\{\mathcal R(x)\mid \, F(x)=y\}.\]

\par Throughout this paper, we will assume the operator $F$ and the data $y^\delta$ have the following properties.

\begin{condition}\label{con2.1}
{\rm(i)} $F: X \rightarrow Y$ is Fr\'{e}chet differentiable.

{\rm(ii)} $F: X \rightarrow Y$ is weakly sequentially closed, i.e.\ $x_n\rightharpoonup x$ in $X$ and $F(x_n)\rightharpoonup y$ in $Y$ imply that $F(x)=y$.

{\rm(iii)} There exists a constant $\gamma>0$ such that
\begin{equation}\label{equ2.2}
\|F(x_2)-F(x_1)-F'(x_1)(x_2-x_1)\|_Y\leq \gamma\,\|F(x_2)-F(x_1)\|_Y\quad\forall\, x_1, x_2\in \mathcal{L}_{\alpha}^{\delta}.
\end{equation}

{\rm(iv)} There exist $\delta>0$ and $\tau_2>\tau_1\ge 1$ such that
\begin{equation}\label{equ2.3}
\|y-y^{\delta}\|_Y\le \tau_1\delta<\tau_2\delta\le\|F(0)-y^{\delta}\|_Y.
\end{equation}
\end{condition}

The condition \eqref{equ2.2} was used in \cite[pp.\ 278--279]{EHN1996}, \cite[p.\ 6]{KNS2012}, \cite[pp.\ 69--70]{SKHK2012}. It follows from \eqref{equ2.2} that
    \[\|F'(x_1)(x_2-x_1)\|_Y\leq(1+\gamma)\|F(x_2)-F(x_1)\|_Y,\]
which has been adopted by several researchers. In \eqref{equ2.3}, we require $\|F(0)-y^{\delta}\|_Y\ge \tau\delta$, which is a reasonable assumption. Indeed, if $\|F(0)-y^{\delta}\|_Y< \tau\delta$, then $0$ can be viewed as a good approximation to the regularized solution $x_{\alpha}^{\delta}$. Moreover, practically, it is almost impossible to recover a solution from an observed data of a size in the same order as the noise.

\par Next, we assume the convex penalty term $\mathcal{R}$ has the following properties.

\begin{condition}\label{con2.2}

{\rm(i)}  $\mathcal{R}(x)$ is proper, and $\mathcal{R}(x)=0$ if and only if $x=0$.

{\rm(ii)  (Coercivity)} $\|x\|_{{X}}\rightarrow \infty$ implies $\mathcal{R}(x)\rightarrow \infty$.

{\rm(iii)  (Weak lower semi-continuity)} $x_n\rightharpoonup x$ in $X$ implies
$ \liminf_n\mathcal{R}(x_n)\geq\mathcal{R}(x)$.

{\rm (iv) (Radon-Riesz property)} $x_n\rightharpoonup x$ in $X$ and $\mathcal{R}(X_n)\rightarrow
\mathcal{R}(X)$ imply $x_n\rightarrow x$ in $X$.
\end{condition}

\begin{definition}\label{def2.3}
{\rm (Bregman distance)} A Bregman distance $D_{\mathcal{R}}^\xi: X\rightarrow \mathbb{R}^+$ of two element $x_1, x_2\in X$ is defined by
    \[  D_{\mathcal{R}}^\xi(x_1, x_2):= \mathcal{R}(x_1)-\mathcal{R}(x_2)-\langle \xi, x_1-x_2\rangle, \]
where $\xi\in \partial \mathcal{R}(x_2)$.
\end{definition}

\begin{definition}\label{def2.4}
{\rm  (Morozov's discrepancy principle)} Given $\tau_2>\tau_1\ge 1$, choose $\alpha=\alpha(\delta, y^{\delta})>0$ such that
\begin{equation}\label{equ2.4}
    \tau_1\delta\leq \|F(x_{\alpha}^{\delta})-y^{\delta}\|_Y\leq \tau_2 \delta
\end{equation}
holds for an element $x_{\alpha}^{\delta}\in \mathcal{L}^{\delta}_{\alpha}$.
\end{definition}

\par The following first order necessary condition for problem \eqref{equ1.2} is standard (\cite[Lemma 3.1]{DH20}).

\begin{lemma}\label{lem2.5}
If $\hat{x}$ is a minimizer of $\mathcal{J}_{\alpha}^{\delta}(x)$, then
\begin{equation}\label{equ2.5}
    \langle F'(\hat{x})(F(\hat{x})-{y^{\delta}}),z-\hat{x}\rangle\geq \alpha\mathcal{R}(\hat{x})-\alpha\mathcal{R}(z)\quad \forall\, z\in X.
\end{equation}
\end{lemma}


\section{Existence of regularization parameter}\label{sec3}

\par In this section, we discuss the existence of a regularization parameter $\alpha$ determined by MDP. In the rest of this paper, we view $\alpha$ as the regularization parameter.  For a fixed noise level $\delta>0$, define functions
\begin{align*}
    G(x_{\alpha}^{\delta}) &:=\frac{1}{2}\|F(x_{\alpha}^{\delta})-y^{\delta}\|_Y^{2},\\
    m(\alpha) &:=\mathcal{J}_{\alpha}^{\delta}(x_{\alpha}^{\delta})=\min \mathcal{J}_{\alpha}^{\delta}(x)
\end{align*}
for $\alpha\in (0, \infty)$.

