\par Although $m(\alpha)$ is continuous, the functions $G(x_{\alpha}^{\delta})$ and $\mathcal{R}(x_{\alpha}^{\delta})$ are not necessarily continuous with respect to $\alpha$. If \eqref{equ2.4} does not hold for any parameter $\alpha$, then $\|F(x_{\alpha}^{\delta})-y^{\delta}\|_{Y}$ has a jump at a certain parameter. Actually, we have the following lemma, which can be proved similar to that of Theorem 2.3 in \cite{TLY1998}.

\begin{lemma}\label{lem3.5}
Denote $G(x):=\|F(x)-y^{\delta}\|_Y$. For each ${\alpha}>0$, there exist $x_{\alpha}^{\delta,1}, x_{\alpha}^{\delta,2}\in \mathcal{L}^{\delta}_{{\alpha}}$ such that
\begin{align*}
    G(x_{\alpha}^{\delta,1})=\inf\limits_{x\in \mathcal{L}^{\delta}_{{\alpha}}}G(x),\quad G(x_{\alpha}^{\delta,2})=\sup\limits_{x\in \mathcal{L}^{\delta}_{{\alpha}}}G(x).
\end{align*}
\end{lemma}

\par A minimizer of $\mathcal{J}_{\alpha}^{\delta}\left(x\right)$ may be non-unique. Hence, the inequality \eqref{equ2.4} may not hold. More precisely, there may exist a regularization parameter $\alpha$ such that
\begin{equation}\label{equ3.1}
\|F(x_{\alpha}^{\delta,1})-y^{\delta}\|_{Y}<\tau_1\delta<\tau_2\delta<\|F(x_{\alpha}^{\delta,2})-y^{\delta}\|_{Y}.
\end{equation}
To prove the existence of a regularization parameter $\alpha$ satisfying \eqref{equ2.4}, it is sufficient to ensure that there are no minimizers $x_{\alpha}^{\delta,1}$, $x_{\alpha}^{\delta,2}$ of $\mathcal{J}_{\alpha}^{\delta}(x)$ for \eqref{equ3.1} to be valid. It can be shown that if there is no parameter $\alpha$ such that \eqref{equ3.1} holds, then there exists $\alpha$ satisfying \eqref{equ2.4}. The proof is similar to that of Theorem 3.10 in \cite{AR10}.

\begin{lemma}\label{lem3.6}
Assume Conditions \ref{con2.1} and \ref{con2.2}.  If there is no $\alpha>0$ with minimizers $x_{\alpha}^{\delta,1},x_{\alpha}^{\delta,2}\in \mathcal{L}_{{\alpha}}^{\delta}$ such that \eqref{equ3.1} is valid, then there exist $\alpha=\alpha(\delta,y^{\delta})>0$ and $x_{\alpha}^{\delta}\in\mathcal{L}_{\alpha}^{\delta}$
such that \eqref{equ2.4} holds.
\end{lemma}

\par Next we prove an estimate for $\|F(x_{\alpha}^{\delta,2})-y^{\delta}\|_{Y}$ if $x_{\alpha}^{\delta,1}$, $x_{\alpha}^{\delta,2}$ satisfy \eqref{equ3.1}.

\begin{lemma}\label{lem3.7}
Assume $x_{\alpha}^{\delta,1}$, $x_{\alpha}^{\delta,2}$ satisfy \eqref{equ3.1}. Then
    \[\tau_2\delta<\|F(x_{\alpha}^{\delta,2})-y^{\delta}\|_{Y}\le\tau_1 \left(3+2\gamma\right) \delta.\]
\end{lemma}
\begin{proof}
Denote $x_{1}:=x_{\alpha}^{\delta,1}$,
$x_{2}:=x_{\alpha}^{\delta,2}$.
From Lemma \ref{lem2.5}, we have
\begin{equation}\label{equ3.2}
    \left\langle F'(x_1)^*\left(F(x_1)-y^{\delta}\right),z-x_1\right\rangle\geq\alpha\mathcal{R}(x_1)- \alpha\mathcal{R}(z)\quad\forall\, z\in X.
 \end{equation}
Thus,
    \[\left\langle F'(x_1)^*\left(F(x_1)-y^{\delta}\right), x_2-x_{1}\right\rangle\geq \alpha\mathcal{R}(x_1)-\alpha\mathcal{R}(x_2)\label{equnew2},\]
which can be rewritten as
\begin{align*}
\alpha\mathcal{R}(x_1)-\alpha\mathcal{R}(x_2) \le \|F(x_{1})-y^{\delta}\|_{Y}\|F'(x_{1})(x_2-x_1)\|_{Y}.
\end{align*}
It follows from Condition \ref{con2.1} (iii) that
\begin{align}\label{equ3.3}
    \alpha\mathcal{R}(x_1)-\alpha\mathcal{R}(x_2)\le  \|F(x_{1})-y^{\delta}\|_{Y}\left(1+\gamma\right)\|F(x_2)-F(x_1)\|_Y.
\end{align}
In addition,
\begin{align}\label{equ3.4}
\frac{1}{2}\|F(x_{2})-y^{\delta}\|_{Y}^{2} &
=\frac{1}{2}\|F(x_{2})-y^{\delta}\|_{Y}^{2}+\alpha\mathcal{R}(x_2)-\alpha\mathcal{R}(x_2)\nonumber\\
&=\frac{1}{2} \|F(x_{1})-y^{\delta}\|_{Y}^{2}+\alpha\mathcal{R}(x_1)-\alpha\mathcal{R}(x_2).
\end{align}
A combination of \eqref{equ3.3} and \eqref{equ3.4} leads to
\begin{align}\label{equ3.5}
    \frac{1}{2}\|F(x_{2})-y^{\delta}\|_{Y}^{2}
    &\le\frac{1}{2}\tau_1^2\delta^{2}+\tau_1\delta(1+\gamma)\|F(x_{2})-y^{\delta}+y^{\delta}-F(x_1)\|_{Y}\nonumber\\
    &\le\frac{2\gamma+3}{2}\tau_1^2\delta^{2}+\tau_1\delta(1+\gamma)\|F(x_2)-y^{\delta}\|_{Y},
\end{align}
which is rewritten as
\begin{align}\label{equ3.6}
    \|F(x_{2})-y^{\delta}\|_{Y}^{2}-(2+2\gamma)\tau_1\delta\|F(x_2)-y^{\delta}\|_{Y} -(2\gamma+3)\tau_1^2\delta^{2}\leq 0.
\end{align}
The inequality \eqref{equ3.6} implies that 
\[-\tau_1\delta\le\|F(x_{2})-y^{\delta}\|_{Y}\le(2\gamma+3)\tau_1\delta.\]
This proves the lemma.
\end{proof}

\par From Lemmas \ref{lem3.6} and \ref{lem3.7}, we deduce the following result.

\begin{theorem}\label{the3.8}
Assume Conditions \ref{con2.1} and \ref{con2.2}. Then there exist a regularization parameter $\alpha$ and a minimizer $x_{\alpha}^{\delta}\in\mathcal{L}_{{\alpha}}^{\delta}$ such that
\begin{align}\label{equ3.7}
    \tau_1\delta\le\|F(x_{\alpha}^{\delta})-y^{\delta}\|_{Y}\le c\,\delta, \quad c:=\max\left\{ \tau_2,(3+2\gamma)\tau_1 \right\}.
\end{align}
\end{theorem}
\begin{proof}
By Lemma \ref{lem3.7}, if there exists a regularization parameter $\alpha$ such that $x_{\alpha}^{\delta,1}$, $x_{\alpha}^{\delta,2}$ satisfy \eqref{equ3.1}, then
    \[\tau_2\delta<\|F(x_{\alpha}^{\delta,2})-y^{\delta}\|_{Y}\leq \tau_1(3+2\gamma)\delta. \]
This implies that there exists a regularization parameter $\alpha$ such that \eqref{equ3.7} holds.
On the contrary, if there is no regularization parameter $\alpha$ with minimizers $x_{\alpha}^{\delta,1}$, $x_{\alpha}^{\delta,2}$ such that \eqref{equ3.1} is valid, by Lemma \ref{lem3.6}, there exist $\alpha$ and $x_{\alpha}^{\delta}\in\mathcal{L}_{\alpha}^{\delta}$
such that \eqref{equ2.4} holds. Obviously, \eqref{equ2.4} implies \eqref{equ3.7}. Hence, there exists a regularization parameter $\alpha$ such that \eqref{equ3.7} holds, which proves the theorem.
\end{proof}

\par In the following, we will show that for MDP, $\alpha\equiv \alpha(\delta,y^{\delta})\rightarrow 0$ as the noise level $\delta\rightarrow 0$.

\begin{lemma}\label{lem3.9}
Let $\alpha>0$ be fixed. If $F(x^*)=y$ and
    \[x^*\in \mathop{\arg\min}_{x\in X}\left\{\frac{1}{2}\|F(x)-y\|_Y^2+\alpha\mathcal{R}(x)\right\},\]
then $x^*=0$.
\end{lemma}
\begin{proof}
By the assumption, we have
\begin{align}\label{equ3.8}
    \alpha\mathcal{R}(x^*)&=\frac{1}{2}\|F(x^*)-y\|_Y^2+\alpha\mathcal{R}(x^*)\nonumber\\
    & \le \frac{1}{2}\|F((1-t)x^*)-y\|_Y^2+\alpha\mathcal{R}((1-t)x^*)\quad\forall\,t\in (0,1).
\end{align}
Since $\mathcal{R}((1-t)x^*)=(1-t)\mathcal{R}(x^*)$, we can rewrite \eqref{equ3.8} as
\[ 0\le \alpha\mathcal{R}(x^*) \le \frac{1}{2}\frac{\|F((1-t)x^*)-y\|_Y^2}{t}\quad\forall\,t\in (0,1).\]
Since
    \[ F((1-t)x^*)-y = F(x^*)+F'(x^*)(-tx^*)+o(\|-tx^*\|_{\ell_2})-y = F'(x^*)(-tx^*)+o(t),\]
we have
    \[ 0\le \alpha\mathcal{R}(x^*) \le \frac{t}{2}\,\|F'(x^*)x^*+o(t)\|_Y^2\quad\forall\,t\in (0,1).\]
Then take the limit as $t\to 0^+$ to obtain $\mathcal{R}(x^*)=0$.  By Condition \ref{con2.2}, $\mathcal{R}(x^*)=0$ implies that $x^*=0$.
\end{proof}

\begin{theorem}\label{the3.10}
Let $\delta_n\rightarrow 0$ and $y^{{\delta}_n}\rightarrow y$ as $n\rightarrow \infty$.  Let $\alpha_n:=\alpha(\delta_n, y^{\delta_n})$ be the regularization parameter obtained from MDP \eqref{equ3.7} with $\delta$ replaced by ${\delta_n}$.  Then $\alpha_n\rightarrow 0$ as $n\rightarrow \infty$.
\end{theorem}
\begin{proof}
We argue by contradiction.  Suppose $\alpha_n$ does not converge to 0, i.e.,
$\exists\,\alpha_0>0$, $\forall\,N\in \mathbb{N}^+$, $\exists\,n_0>N$ such that $|\alpha_{n_0}-0|\ge \alpha_0$.
This implies that there exists a subsequence of $\{\alpha_n\}$, still denoted by $\{\alpha_n\}$ such that $\alpha_n\ge\alpha_0$.
Denote
    \[x^{\alpha_0}_n\in \mathop{\arg\min}_{x\in X}\left\{\frac{1}{2}\|F(x)-y^{\delta_n}\|_Y^2+\alpha_0\mathcal{R}(x) \right\}\]
and
    \[x_n:=x_{\alpha_n}^{\delta_n}\in \mathop{\arg\min}_{x\in X}\left\{\frac{1}{2}\|F(x)-y^{\delta_n}\|_Y^2+{\alpha_n}\mathcal{R}(x) \right\}.\]
By Lemma \ref{lem3.1}, $\|F(x_{\alpha}^{\delta})-y^{\delta}\|_Y^2$ is non-decreasing with respect to $\alpha$. Hence,
\begin{align}\label{equ3.9}
    \frac{1}{2}\|F(x^{\alpha_0}_n)-y^{\delta_n}\|_Y^2&\le\frac{1}{2}\|F(x_n)-y^{\delta_n}\|_Y^2\nonumber\\
    & \le \frac{1}{2}\max\{{\tau_2}^2\delta_n^2,(3+2\gamma)^2{\tau_1}^2\delta_n^{2}\}\rightarrow 0.
\end{align}
By the definition of $x^{\alpha_0}_{n}$, there exist $x^*\in X$ and a subsequence $\{x^{\alpha_0}_{n_k}\}$ such that $x^{\alpha_0}_{n_k}\rightharpoonup x^*$ in $X$. Since $F$ is weakly sequently closed and $y^{{\delta}_n}\rightarrow y$,
$F(x^{\alpha_0}_{n_k})-y^{\delta_{n_k}}\rightharpoonup F(x^*)-y$, it follows from the weak lower semi-continuity of the norm that
\begin{align}\label{equ3.10}
0&\le \frac{1}{2}\|F(x^*)-y\|_Y^2\le \liminf\limits_{k\rightarrow\infty}\frac{1}{2}\|F(x^{\alpha_0}_{n_k})-y^{\delta_{n_k}}\|_Y^2\nonumber\\
 & \le \frac{1}{2}\max\{\tau_2^2\delta_{n_k}^2,(3+2\gamma)^2\tau_1^2\delta_{n_k}^{2}\}\rightarrow 0.
\end{align}
Hence, $F(x^*)=y$. In addition,
\begin{align}\label{equ3.11}
\frac{1}{2}\|F(x^*)-y\|_Y^2+\alpha_0\mathcal{R}(x^*)&\le \liminf\limits_{k\rightarrow \infty} \bigg\{\frac{1}{2}\|F(x^{\alpha_0}_{n_k})-y^{\delta_{n_k}}\|_Y^2+\alpha_0\mathcal{R}(x^{\alpha_0}_{n_k})\bigg\}\nonumber\\
& \le \liminf\limits_{k\rightarrow\infty}\bigg\{\frac{1}{2}\|F(x)-y^{\delta_{n_k}}\|_Y^2+\alpha_0\mathcal{R}(x)\bigg\}\nonumber\\
& = \frac{1}{2}\|F(x)-y\|_Y^2+\alpha_0\mathcal{R}(x)
\end{align}
for any $x\in X$. Thus, $x^*$ is a minimizer of $\frac{1}{2}\|F(x)-y\|_Y^2+\alpha_0\mathcal{R}(x)$. By Lemma \ref{lem3.9}, this implies that $x^*=0$. Then
$y=F(0)$. Hence, $\|F(0)-y^{\delta}\|_Y=\|y-y^{\delta}\|_Y\le \delta$, contradicting to $\|F(0)-y^{\delta}\|>\delta$ in Condition \ref{con2.1}\,(iv). This proves the theorem.
\end{proof}

\par For a numerical realization of MDP \eqref{equ3.7}, we can make use of an iterative algorithm described in \cite{R02}, cf.\ Algorithm \ref{alg1}. Even though $\alpha$ is determined from the upper bound: $\|F(x_{\alpha}^{\delta})-y^{\delta}\|_Y=c\delta$, we can still obtain the convergence of the regularized solution. Numerical simulation results reported in Section \ref{sec3} show that we can obtain better inversion results if $\alpha$ is determined by Algorithm \ref{alg1}.

\begin{algorithm}
\caption{Iterative algorithm for $\alpha$ under MDP \eqref{equ3.7}}
\label{alg1}
\begin{algorithmic}
\STATE{Choose $\tau>0$, $\eta=1$, $0<q<1$, $j=0$, $\alpha_0>0$ with $\|F(x_{\alpha_0}^{\delta})-y^{\delta}\|_Y>c\delta$ }
\STATE{for $j=1,2,\cdots$,}
\STATE{if $\|F(x_{\alpha_{j-1}}^{\delta})-y^{\delta}\|_Y>c\delta$}
\STATE{~~~~$\alpha_j=q\alpha_{j-1}$}
\STATE{~~~~compute $x_{\alpha_j}^{\delta}$}
\STATE{~~~~$\alpha_{j}^{\max}=\alpha_{j-1}$, $\alpha_{j}^{\min}=\alpha_{j}$}
\STATE{else}
\STATE{~~~~$\alpha_j=\left(\alpha_{j-1}^{\min}+\alpha_{j-1}^{\max}\right)/2$}
\STATE{~~~~compute $x_{\alpha_j}^{\delta}$} by iterative soft thresholding algorithm
\STATE{~~~~if $\|F(x_{\alpha_j}^{\delta})-y^{\delta}\|_Y> c\delta$ then $\alpha_{j}^{\max}=\alpha_j$}
\STATE{~~~~if $\|F(x_{\alpha_j}^{\delta})-y^{\delta}\|_Y< \tau_1\delta$ then $\alpha_{j}^{\min}=\alpha_j$}
\STATE{end}
\end{algorithmic}
\end{algorithm}

\par We note that the upper bound $c\delta$ from Theorem \ref{the3.8} is $O(\delta)$. Then the convergence of the regularized solution is standard (\cite{EHN1996}). Indeed, we can show the regularized solution $x_{\alpha}^{\delta}$ defined by (\ref{equ2.1}) converges to an $\mathcal R$-minimum solution
of problem $F(x)=y$.


\section{Regularization properties}\label{sec4}

\par In this section, we examine the well-posedness of the regularization method under MDP (\ref{equ3.7}). We prove that the regularized solution $x_{\alpha}^{\delta}$ defined by (\ref{equ2.1}) converges to an $\mathcal R$-minimum solution of the problem $F(x)=y$. In addition, we discuss the convergence rate of $x_{\alpha}^{\delta}$. The proofs are along the lines of standard quadratic Tikhonov regularization (\cite{EHN1996}) and sparsity regularization (\cite{GHS08,JLS09,SGGHL2009,WLMC13}). However, analysis of the convergence rate is different from that in \cite{DH19} since the regularization parameter $\alpha$ is now determined by \eqref{equ3.7}.

\begin{theorem}\label{the4.1} 
{\rm (Convergence)} Let $x_{\alpha_{n}}^{\delta_{n}}$ be a minimizer of $\mathcal{J}_{\alpha_n}^{\delta_n}(x)$ defined by \eqref{equ1.2} with the data $y^{\delta_n}$ satisfying $\| y-y^{\delta_n}\|\leq\delta_n$, where $\delta_n\rightarrow 0$ as $n\rightarrow \infty$ and $y^{\delta_n}$ belongs to the range of $F$. Let $\alpha_n$ be chosen by the Morozov's discrepancy principle \eqref{equ3.7}. Then there exists a subsequence of $\{x_{\alpha_{n}}^{\delta_{n}}\}$, still denoted by $\{x_{\alpha_{n}}^{\delta_{n}}\}$, that converges to an $\mathcal{R}$-minimizing solution $x^{\dag}$ in $X$. In addition, if the $\mathcal{R}$-minimizing solution $x^{\dag}$ is unique, then
    \[\lim\limits_{n \rightarrow \infty} \| x_{\alpha_{n}}^{\delta_{n}}-x^{\dag}\|_{X}=0.\]
\end{theorem}
\begin{proof}
Denote $y_{n}:=y^{\delta_{n}}$, $x_{n}:=x_{\alpha_{n}}^{\delta_{n}}$. By the definition of $x_{n}$, we obtain
\begin{align}\label{equ4.1}
    \frac{1}{2}\| F(x_{n})-y_{n}\|_Y^{2} +\alpha_{n}\mathcal{R}(x_{n})
    &\leq\frac{1}{2}\|F(x^{\dag})-y_n\|_Y^2+\alpha_{n}\mathcal{R}(x^{\dag})\nonumber\\
    &\leq\frac{1}{2}\delta_n^2+\alpha_{n}\mathcal{R}(x^{\dag}).
\end{align}
By \eqref{equ3.7}, this implies that $\mathcal{R}(x_n)\le \mathcal{R}(x^{\dag})$. Hence, the sequence $\{\mathcal{R}(x_n)\}$ is bounded. Denote
    \[c:=\max\left\{ \tau_2,(3+2\gamma)\tau_1 \right\}.\]
We have $c\delta_n\rightarrow 0$ as $\delta_n\rightarrow 0$. In addition,
\begin{equation}\label{equ4.2}
    \| F(x_{n})-y\|_Y\leq\| F(x_{n})-y_{n}\|_Y+\| y-y_{n}\|_Y\leq c\delta_n+\delta_{n}.
\end{equation}
Then
\begin{equation}\label{equ4.3}
\begin{array}{llc}
    \lim\limits_{n \to \infty}F(x_n)=y.
\end{array}
\end{equation}
On the other hand, it follows from (\ref{equ4.1}) that
\begin{equation}\label{equ4.4}
    \limsup\limits_{n \to \infty}\mathcal{R}(x_n)
    \leq\mathcal{R}(x^{\dag}).
\end{equation}
Since $ \mathcal{R}(x_n)$ is bounded, there exist an element $x^{*}\in X$
and a subsequence of $\{x_n\}$, still denoted by $\{x_n\}$, such that $x_{n}\rightharpoonup x^{*}$ in $X$.
Together with (\ref{equ4.3}), it follows that
    \[\|F(x^*)-y\|_Y\le \liminf\limits_{n \to \infty}\|F(x_n)-y\|_Y=0.\]
Hence, $F(x^*)=y$. Meanwhile, by Condition \ref{con2.2} (ii), we have
\begin{align}\label{equ4.5}
 \mathcal{R}(x^*)\leq\liminf\limits_{n}\mathcal{R}(x_n)\leq\mathcal{R}(x^{\dag}).
 \end{align}
By the definition of $x^{\dag}$, $x^{*}$ is an $\mathcal{R}$-minimizing solution. If the $\mathcal{R}$-minimizing solution is unique, then $x^{*}=x^{\dag}$. A combination of (\ref{equ4.4}) and (\ref{equ4.5}) implies $\mathcal{R}(x_n)\rightarrow\mathcal{R}(x^{\dag})$. Thus, $\mathcal{R}(x_n)\rightarrow \mathcal{R}(x^{\dag})$. Then $\lim\limits_{n \rightarrow \infty} \| x_{n}-x^{\dag} \|_{X}=0$ by Condition \ref{con2.2} (iii).
\end{proof}

\par Next, we present a result on the linear convergence rate $O(\delta)$ of the regularized solution $x_{\alpha}^{\delta}$ under the source condition and Bregman distance.  For this purpose, we introduce an assumption on an $\mathcal R$-minimizing solution $x^{\dagger}$ of the problem $F(x)=y$.

\begin{assumption}\label{ass4.2}
There exists an $\omega\in Y$ such that
\begin{equation}\label{equ4.6}
    F'(x^{\dag})^{*}\omega\in \partial\mathcal{R}(x^{\dag}).
\end{equation}
\end{assumption}

\begin{theorem}\label{the4.3} 
{\rm (Convergence rate)} Let $ x^{\delta}_{\alpha}$ be defined by \eqref{equ2.1}. Assume that there exist parameters $\alpha$ satisfying MDP \eqref{equ3.7}. Then, under Assumptions \ref{ass4.2}, there exists $d\in D_{\mathcal{R}}^\xi(x_{\alpha}^{\delta}, x^{\dag})$ such that $d=O(\delta)$.
\end{theorem}
\begin{proof} 
Due to MDP (\ref{equ3.7}) and the minimization property of $\displaystyle x^{\delta}_{\alpha}$,
\begin{align*}
\frac{1}{2}\delta^{2}+\alpha \mathcal{R}(x_{\alpha}^{\delta})
 & \leq\frac{1}{2}\|F(x_{\alpha}^{\delta})-y^{\delta}\|_{Y}^{2}+\alpha \mathcal{R}(x_{\alpha}^{\delta})\\
    & \leq\frac{1}{2}\|F(x^{\dagger})-y^{\delta}\|_{Y}^{2}+\alpha \mathcal{R}(x^{\dagger})\\
    & \leq\frac{1}{2}\delta^{2}+\alpha\mathcal{R}(x^{\dagger}).
\end{align*}
Then $\mathcal{R}(x_{\alpha}^{\delta})\leq \mathcal{R}(x^{\dagger})$. Consider the Bregman distance 
\begin{equation*}
    d= \mathcal{R}(x_{\alpha}^{\delta})-\mathcal{R}(x^{\dagger})-\langle F'(x^{\dagger})^{*}\omega, x_{\alpha}^{\delta}-x^{\dagger}\rangle.
\end{equation*}
Since $\mathcal{R}(x_{\alpha}^{\delta})\leq \mathcal{R}(x^{\dagger})$,
\begin{equation}\label{equ4.7}
    d\leq -\langle F^{'}(x^{\dagger})^{*}\omega,x_{\alpha}^{\delta}-x^{\dagger}\rangle\leq \|\omega\|\|F^{'}(x^{\dagger})(x_{\alpha}^{\delta}-x^{\dagger})\|_{Y}.
\end{equation}
A combination of \eqref{equ4.7} and the nonlinear condition \eqref{equ2.2} implies that
\begin{align*}
    d
    & \leq \|\omega\|(1+\gamma)\|F(x_{\alpha}^{\delta})-F(x^{\dagger})\|_{Y}\nonumber\\
    & \leq \|\omega\|(1+\gamma)(\|F(x_{\alpha}^{\delta})-y^{\delta}\|_{Y}+\|y-y^{\delta}\|_{Y}).
\end{align*}
By MDP \eqref{equ3.7}, $\|F(x_{\alpha}^{\delta})-y^{\delta}\|_{Y}\le c\delta$. Thus
    \[d \leq \|\omega\|(1+\gamma)(c+1)\delta,\]
i.e., $d=O(\delta)$.
\end{proof}


\section{Numerical experiments}\label{sec5}

\par In this section, we present two numerical examples to demonstrate the efficiency of MDP \eqref{equ3.7}. The relative error (Rerror) is utilized to measure the accuracy of the reconstruction $x^{*}$:
    \[  \mathrm{Rerror}:=\frac{\|x^{*}-x^{\dag}\|}{\|x^{\dag}\|}, \]
where $x^{\dag}$ is a true solution. The exact data $y^{\dag}$ is generated by $y^{\dag}=F(x^{\dag})$. The noise level $\delta$ is defined by $\delta:=\|F(x^{\dag})-y^{\delta}\|_2$. All numerical calculations were done using MATLAB R2010 on an i7-6500U 2.50GHz workstation with 8Gb RAM.


\subsection{A nonlinear compressive sensing problem}

First, we solve a nonlinear compressive sensing (CS) problem (\cite{BE13,B13,CL16,YWLJWJ15}) to demonstrate the efficiency of MDP for the $\ell_{1}$-regularization. The research of nonlinear CS is important not only in theoretical analysis but also in many applications where the observation system is often nonlinear. For example, in diffraction imaging, a charge coupled device (CCD) records the amplitude of the Fourier transform of the original signal. So one only obtains the nonlinear measurements of the original signal. Fortunately, as shown in \cite{B13}, if the system satisfies some nonlinear conditions then recovery is still possible. Under the nonlinear CS frame, the measurement system is nonlinear. Assume, therefore, that the observation model is
\begin{equation}\label{equ5.1}
    y=F(x)+\delta,
\end{equation}
where $F: \mathbb{R}^n\rightarrow \mathbb{R}^m$ is a nonlinear operator, $x\in \mathbb{R}^n$ and $\delta\in \mathbb{R}^m$ is a noise. It can be shown that if the linearization of $F$ at an exact solution $x^{\dag}$ satisfies the restricted isometry property (RIP), then the convergence property of the iterative hard thresholding algorithm (IHTA) is guaranteed (\cite{B13}). Next we illustrate the efficiency of the proposed algorithm by a nonlinear CS example of the form (\cite{B13})
\begin{equation}\label{equ5.2}
y=F(x):=\hat{a}(A\hat{b}(x)),
\end{equation}
where $A$ is a CS matrix, $\hat{a}$ and $\hat{b}$ are nonlinear operators, respectively. Here, $\hat{a}$ encodes nonlinearity after mixing by $A$ as well as nonlinear ``crosstalk'' between mixed elements, and $\hat{b}$ encodes the same system properties for the inputs before mixing. For simplicity, we write $\hat{a}(x)= x^c$ and $\hat{b}(x)= x+b(x)$, where $b$ is a nonlinear map. In particular, let $b(x)=x^d$, where $c, d \in \mathbb{N}^{+}$ and $x^c$ and $x^d$ should be understood in a componentwise sense.

\par Next, we consider the nonlinearity of the operator $F$. In \cite{B13}, it is shown that the Jacobian matrix of $\hat{a}(A\hat{b}(x))$ is of the form
    \[F'(x)=[a'_x(\Phi\hat{b}(x))][\Phi(I+b'_x(x))].\]
There exists a constant $\gamma>0$ such that
\[ \|F(x_1)-F(x_2)-F'(x_2)(x_1-x_2)\|_{Y}\leq L\|x_1-x_2\|_{\ell_2},\]
cf.\ \cite[Lemmas 3 \& 4]{B13}. For example, we let $c=1$, $d=3$, then $F(x)=A(x+x^3)$. Assume $A$ is bounded.  Then obviously,
\[ \|x_1-x_2\|_{\ell_2}\le K\|F(x_1)-F(x_2)\|_Y.\]
Consequently, $F$ satisfies the nonlinear condition \eqref{con2.2}.

\par In the experiment, an ST-($\alpha\ell_{1}-\beta\ell_{2}$) ($\beta=0$) algorithm for nonlinear ill-posed problems is used to compute the iterative solution, cf.\ \cite{DH24} for details of the algorithm.
The ST-($\alpha\ell_{1}-\beta\ell_{2}$) algorithm reduces to the form
\[ x^{k+1}=\mathbb{S}_{\alpha/\lambda} \left(x^k-\frac{1}{\lambda}F'(x^k)^*(F(x^k)-y^{\delta})\right). \]

\par Let $n = 200$, $m = 0.4n$, $p = 0.2m$, $\tau_1 = 1$ and $\tau_2 = 2$, where $p$ is the number of the impulses in the true solution. White Gaussian noise is added to the exact data $y^{\dag}$ by calling $\mathrm{y^{\delta}=awgn( F(x^{\dag}), \sigma})$ in MATLAB, where $\sigma$ is the added noise, measured in dB, which measures the ratio between the true (noise free) data $y^{\dag}$ or $F(x^{\dag})$ and Gaussian noise. Meanwhile, we let $\gamma=1/2$, $c=1$ and $d=3$. For the sparsity regularization of linear ill-posed problems,  the value of $\|A_{m\times n}\|_{\ell_{2}}$ needs to be less than 1 (\cite{DDD04}). This condition is also needed for the nonlinear CS problem \eqref{equ5.1}. Since the value of $\|A_{m\times n}\|_{\ell_{2}}$ is around 20, we re-scale the matrix $A_{m\times n}$ by $A_{m\times n}\rightarrow0.05A_{m\times n}$. The initial value $x^0=\mathrm{zeros}(n,1)$.

