\section*{Introduction}
Let $ (0, T) $ be a time-interval with a constant $ 0 < T < \infty $, and let $\Omega := (0, 1) \subset \R $ be a one-dimensional bounded domain with the boundary $ \Gamma := \partial \Omega =  \{ 0, 1 \} $. Additionally, we set $ Q := (0, T) \times \Omega $ and $ \Sigma := (0, T) \times \Gamma $. 
\medskip

Let $ \varepsilon \in (0, 1) $ be a fixed positive constant. In this paper, we consider the following system of parabolic PDEs, denoted by (S)$_{\varepsilon}$:
\medskip

%\noindent
~~~~\hypertarget{(S)}{(S)$_\varepsilon$}
%\vspace{-0ex}
\begin{equation}\label{1}
\left\{ \parbox{11.5cm}{
    $ \partial_{t} \eta - \kappa_0^2 \partial_x^2 \eta +c (\eta -1) +\kappa \eta \sqrt{\varepsilon^2 +|\partial_x \theta|^2} = 0 $ \quad in $ Q $,
\\[1ex]
    $ (-1)^{\ell -1} \partial_x \eta(t, \ell) = 0, \quad (t,\ell) \in \Sigma$,
\\[1ex]
$ \eta(0, x) = \eta_{0}(x),$ \quad $ x \in \Omega $;
}\right. 
\end{equation}
\begin{equation}\label{2}
\left\{\parbox{11.5cm}{
    $ \displaystyle \alpha_{0}(t, x) \partial_t \theta -\partial_x \! \left( \! \kappa \!\left( \frac{\eta^2}{2} +\delta_0 \right) \frac{\partial_x \theta}{\sqrt{\varepsilon^2 +|\partial_x \theta|^2}} +\nu^2 \partial_x \theta  \! \right) = 0 $ 
    \quad in $Q$,
\\[1ex]
    $ (-1)^{\ell -1} \partial_x \theta(t, \ell) = 0, \quad (t,\ell) \in \Sigma$,
    \\[1ex]
    $ \theta(0, x) = \theta_{0}(x),$ \quad $x \in \Omega $.
}\right. 
\end{equation}
This system is based on the Kobayashi--Warren--Carter system, which was originally proposed by Kobayashi--Warren--Carter \cite{MR1752970,MR1794359}, as a possible phase-field model of planar grain boundary motion. From these works, we can see that the system (S)$_\varepsilon$ is governed by the following \emph{free-energy,} denoted by $ \mathcal{F}_\varepsilon $:
\begin{align}\label{freeEnergyOrg}
    \mathcal{F}_\varepsilon : [{\eta}, {\theta}] \in & \KS{[H^1 (\Omega)]^2} \mapsto \mathcal{F}_\varepsilon({\eta}, {\theta}) := \frac{\kappa_0^2}{2} \int_\Omega |\partial_x {\eta}|^2 \, dx +\frac{c}{2}\int_\Omega (\eta -1)^2 \, dx
    \nonumber
    \\
    & +\kappa \int_\Omega \left( \frac{\eta^2}{2} +\delta_0 \right) \sqrt{\varepsilon^2 +|\partial_x \theta|^2} \, dx +\frac{\nu^2}{2} \int_\Omega |\partial_x {\theta}|^2 \, dx  \in [0, \infty].
\end{align}
The polycrystalline micro-structure, including the grain boundary, is described by a vector field $ \eta \bigl[ \cos \theta, \sin \theta \bigr] $ in $ Q $, consisting of two unknown variables $ \eta $ and $ \theta $. 
In this context, $ \eta = \eta(t, x) $ and $ \theta = \theta(t, x) $ are  supposed to be the order parameters of the orientation order and orientation angle of crystallization, respectively. 
The constant $ \kappa_0 > 0 $ represents the spatial diffusion of $ \eta $, while the constant $ c > 0 $ is associated with a perturbation to control the range of $ \eta $. 
Additionally, $ \alpha_0 = \alpha_0(t, x) $ is a fixed positive-valued Lipschitz function, $ \delta_0 \in (0, 1) $, $ \kappa > 0 $, and $ \nu > 0 $ are fixed constants to characterize the phase-change of crystalline orientation.
%\medskip

    From the practical viewpoint, the mathematical model (S)$_\varepsilon$ is required to satisfy the following structural properties:
    \begin{description}
        \item[{\boldmath (a) (the range-preserving)}]$ 0 \leq \eta \leq 1 $ and $ \inf \theta_0(\Omega) \leq \theta \leq \sup \theta_0(\Omega) $ over $ Q $;
        \item[{\boldmath (b) (the energy-dissipation)}]$ \mathcal{F}_\varepsilon(\eta(t), \theta(t)) \leq \mathcal{F}_\varepsilon(\eta(s), \theta(s)) $ for all $ 0 \leq s \leq t \leq T $.
    \end{description}
    These properties have been principal issues in mathematical analysis (cf. \cite{MR4218112,MR4395725,MR3082861,MR3203495,MR3268865,MR3670006,MR4177183}), and indeed, some previous works (cf. \cite{MR4218112,MR4395725,MR3268865,MR3670006,MR4177183}) have established the time-discrete approximation scheme fulfilling (a) and (b). However, from scientific viewpoint, the line of works have a lot of remaining issues in numerics,  such as numerical experiment, convergence rate, error estimate, and so on.  
\medskip

In view of these, we set the goal of this paper to establish an effective structure-preserving scheme for the KWC system (S)$_\varepsilon$. Consequently, the Main Theorems concerned with:
\begin{description}
    \item[\textmd{(O)}]verification of the structural properties  (a) and (b);
        % \vspace{-2ex}
    \item[\textmd{(\,I\,)}]clarification of the convergence condition of the scheme;
        % \vspace{-2ex}
    \item[\textmd{(II)}]error estimate for the scheme;
\end{description}
will be demonstrated as evidence backing the effectiveness of our scheme. 
\medskip

The content of this paper is as follows. 
The Main Theorems will be stated in Section 2 on the basis of the preliminaries prepared in Section 1. 
In Section 3, we will give the proofs of Main Theorems. 


\section{Preliminaries} 
We begin by prescribing the notations used throughout this paper. 
\medskip

\noindent
\underline{\textbf{\textit{Basic notations.}}} 
For arbitrary $ r_0 $, $ s_0 \in [-\infty, \infty]$, we define:
\begin{equation*}
r_0 \vee s_0 := \max\{r_0, s_0 \}, 
\end{equation*}
and in particular, we set:
\begin{equation*}
    [r]^+ := r \vee 0. 
\end{equation*}    
For any dimension $ k \in \N $ and any set $ A $, we write:
\begin{equation*}
    [A]^k := \overbrace{A \times \cdots \times A}^{\mbox{$k$ times}}.
\end{equation*}

\noindent
\underline{\textbf{\textit{Abstract notations.}}}
For an abstract Banach space $ E $, we denote by $ |\cdot|_{E} $ the norm of $ E $, and denote by $ \langle \cdot, \cdot \rangle_E $ the duality pairing between $ E $ and its dual $ E^* $. Let $I_d : E \longrightarrow E $ be the identity map from $E$ onto $E$. In particular, when $ H $ is a Hilbert space, we denote by $ (\cdot,\cdot)_{H} $ the inner product of $ H $. 

For a proper functional $ \Psi : E \longrightarrow (-\infty, \infty] $ on a Banach space $ E $, we denote by $ D(\Psi) $ the domain of $ \Psi $, i.e., 
    $ D(\Psi) := \left\{ \begin{array}{l|l}
        z \in E & \Psi(z) < \infty
    \end{array} \right\} $.

For Banach spaces $ E_1, \dots, E_m $, with $ 1 < m \in \mathbb{N} $, let $ E_1 \times \dots \times E_m $ be the product Banach space endowed with the norm $ |\cdot|_{E_1 \times \cdots \times E_m} := |\cdot|_{E_1} + \cdots +|\cdot|_{E_m} $. However, when all $ H_1, \dots, H_m $ are Hilbert spaces, $ H_1 \times \dots \times H_m $ denotes the product Hilbert space endowed with the inner product $ (\cdot, \cdot)_{H_1 \times \cdots \times H_m} := (\cdot, \cdot)_{H_1} + \cdots +(\cdot, \cdot)_{H_m} $ and the norm $ |\cdot|_{H_1 \times \cdots \times H_m} := \bigl( |\cdot|_{H_1}^2 + \cdots +|\cdot|_{H_m}^2 \bigr)^{\frac{1}{2}} $. 
% \pagebreak
\medskip

\noindent 
\underline{\textbf{\textit{Basic notations of discrete operators.}}} 
Let $\Delta x$ be a space mesh size, i.e., $\Delta x := 1/K$, where $K$ is a positive integer. 
\begin{defn}[Average operators]
We define average operators $\mu_{k}^{+}$, $\mu_{k}^{-}$ concerning subscript $k$ by
\begin{equation*}
\mu_{k}^{+}f_{k} := \frac{f_{k} + f_{k+1}}{2}, \quad \mu_{k}^{-}f_{k} := \frac{f_{k} + f_{k-1}}{2}, 
\end{equation*}
for $\{f_{k}\}_{k=-s}^{K+s} \in \mathbb{R}^{K+1+2s}$, where $s \in \mathbb{N} \cup \{0\}$. 
\end{defn}

\begin{defn}[Difference operators] 
Let us define the difference operators $\delta_{k}^{+}$, $\delta_{k}^{-}$, $\delta_{k}^{\langle 1 \rangle}$, and $\delta_{k}^{\langle 2 \rangle}$ concerning subscript $k$ by 
\begin{align*}
\delta_{k}^{+}f_{k} := \frac{f_{k+1} - f_{k}}{\Delta x}, & & & \delta_{k}^{-}f_{k} := \frac{f_{k} - f_{k-1}}{\Delta x}, \\[-1pt]
\delta_{k}^{\langle 1 \rangle}f_{k} := \frac{f_{k+1} - f_{k-1}}{2\Delta x}, & & & \delta_{k}^{\langle 2 \rangle}f_{k} := \frac{f_{k+1} - 2f_{k} + f_{k-1}}{(\Delta x)^2},  
\end{align*}
for $\{f_{k}\}_{k=-s}^{K+s} \in \mathbb{R}^{K+1+2s}$, where $s \in \mathbb{N} \cup \{0\}$. 
\end{defn}

\begin{defn}[Summation operator] 
As a discretization of the integral, we define the summation operator $\sum _ {k=0}^{K}{}^{\prime \prime}$: $\mathbb{R}^{K+1+2s} \to \mathbb{R}$ by 
\begin{equation*}
\sum _ {k=0}^{K}{}^{\prime \prime} f_{k} := \frac{1}{2}f_{0} +\sum_{k=1}^{K-1}f_{k} +\frac{1}{2}f_{K} \quad \mbox{for\ } \{f_{k}\}_{k=-s}^{K+s} \in \mathbb{R}^{K+1+2s},\ \mbox{where\ } s \in \mathbb{N} \cup \{0\}. 
\end{equation*}
\end{defn}

\begin{defn}[Discrete norms]
We define the discrete $L^{\infty}$-norm $\|\cdot\|_{L_{\rm d}^{\infty}}$ and the discrete $L^{2}$-norm $\|\cdot\|_{L_{\rm d}^{2}}$ by 
\begin{equation*}
	\|\bm{f}\|_{L_{\rm d}^{\infty}} := \max_{k=0,1,\ldots,K}|f_{k}|, \quad 
    \|\bm{f}\|_{L_{\rm d}^{2}} := \sqrt{ \sum _ {k=0}^{K}{}^{\prime \prime}|f_{k}|^{2}\Delta x}
\end{equation*}
for $\bm{f} = \{f_{k}\}_{k=0}^{K} \in \mathbb{R}^{K+1}$. 
For $\bm{f} = \{f_{k}\}_{k=0}^{K} \in \mathbb{R}^{K+1}$, we define the discrete Dirichlet semi-norm $\|D\bm{f}\|$ of $\bm{f}$ by 
\begin{equation*}
\| D\bm{f}\| := \sqrt{ \sum _ {k=0}^{K-1}|\delta_{k}^{+}f_{k}|^{2}\Delta x}.  
\end{equation*}
\end{defn}

\begin{defn}[Difference quotient]
    For a function $F \in C^{1}(\Omega)$ and arbitrary $u, v \in \Omega$, the difference quotient $d F/d (u, v)$ of $F$ at $(u, v)$ is defined as follows: 
    \begin{numcases}
        {\frac{dF}{d (u, v)} :=}
        \frac{F(u) - F(v)}{u - v} & ($u \neq v$), \nonumber\\
        F'(v) & ($u = v$). \nonumber
    \end{numcases}
\end{defn}

\medskip

\section{Main Theorems}

We begin by setting up the assumptions and notations needed in our Main Theorems.
\begin{enumerate}
    \item[(A1)]
        \begin{itemize}
            \item $\varepsilon \in (0, 1)$, $ \delta_0 \in (0, 1) $, $ c > 0 $, $ \kappa_0 > 0 $, $ \kappa > 0 $, and $ \nu > 0 $ are fixed constants. 
                %Also, $ \alpha_0 \in W^{1, \infty}(Q) $ is a fixed function, such that $ \inf \alpha_0(Q) \geq \delta_0 $.
                Also, $ \alpha_0 : Q \longrightarrow \mathbb{R} $ is a fixed Lipschitz continuous function with a Lipschitz constant $ L_{\alpha_0} \geq 0 $, such that $ \delta_0 := \inf \alpha_0(Q) > 0 $. 
            \item $ \gamma_\varepsilon \in C^\infty(\R) $ is a function defined by $ \gamma_\varepsilon(\vartheta) := \sqrt{\varepsilon^2 +|\vartheta|^2} $ with its derivative $ \gamma_\varepsilon'(\vartheta) := \vartheta/\sqrt{\varepsilon^2 +|\vartheta|^2} $, for all $ \vartheta \in \R $.
            \item $ \alpha : \mathbb{R} \longrightarrow (0, \infty) $ is a function defined by $\alpha(\eta) := (\eta^{2}/2) + \delta_{0}$ with its derivative $ \alpha'(\eta) = \eta $, for all $\eta \in \R$. 
            \item $ [\eta_0, \theta_0] \in \KS{[H^1(\Omega)]^2} $ is a pair of initial data, such that $ 0 \leq \eta_0(x) \leq 1  $ for a.e. $ x \in \Omega $. 
        \end{itemize}
\end{enumerate}
With these assumptions, we define the solution to the system (S)$_\varepsilon$ as follows. 
\begin{defn}\label{DefOfSolToSys}
    A pair of functions $ [\eta, \theta] \in L^2(0, T; [L^2(\Omega)]^2) $ is called a solution to the system (S)$_\varepsilon$, iff. $ [\eta, \theta] $ fulfills the following items. 
    \begin{enumerate}[({S}1)]
        \item $ [\eta, \theta] \in W^{1, 2}(0, T; [L^2(\Omega)]^2) \cap L^\infty(0, T; \KS{[H^1(\Omega)]^2})$, and $ [\eta(0), \theta(0)] = [\eta_0, \theta_0] $ in $ [L^2(\Omega)]^2 $.
        \item $ \ds \int_\Omega \bigl( \partial_t \eta(t) +c(\eta(t) -1) +\kappa \alpha'(\eta(t)) \gamma_\varepsilon(\partial_x \theta(t)) \bigr) \varphi  \, dx +\kappa_0^2 \int_\Omega \partial_x \eta(t) \partial_x \varphi \, dx = 0 $, 
            \\ 
            \hspace*{4ex}for all $ \varphi \in H^1(\Omega) $.
        \item $ \ds \int_\Omega  \alpha_0(t) \partial_t \theta(t)  \psi \, dx +\int_\Omega \bigl( \kappa \alpha(\eta(t)) \gamma_\varepsilon'(\partial_x \theta(t)) +\nu^2 \partial_x \theta(t) \bigr) \partial_x \psi(t) \, dx = 0 $, 
            \\
            \hspace*{4ex}for all $ \psi \in \MO{H^1}(\Omega)$.
    \end{enumerate}
\end{defn}

Next, we present the numerical scheme designed to approximate the solution of the governing equations in system (S)$_\varepsilon$. 
The scheme is derived using a finite difference approach to discretize both space and time. 
In this scheme, the time step size is denoted by $ \Delta t $, and the unknowns, $H_k^{(j)}$ and $\Theta_k^{(j)}$, represent the discretized state variables $ \eta $ and $ \theta $ at time step $j \in \{0, 1, \dots \}$.

\subsection{Proposed scheme}
The concrete form of our scheme is as follows: for $j=0,1,\ldots$,
\begin{gather}
\begin{split}
\frac{ H_{k}^{(j+1)} - H_{k}^{(j)} }{\Delta t} 
	= & \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}H_{k}^{(j+1)} - c\left(H_{k}^{(j+1)} - 1 \right) \\
	& - \kappa H_{k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)  }{2} \quad (k=0, \ldots, K), 
\end{split} \label{sc1}\\[-2pt]
\begin{split}
\alpha_{0, k}^{(j+1)} \frac{ \Theta_{k}^{(j+1)} \! - \! \Theta_{k}^{(j)} }{\Delta t} 
	= & \frac{\kappa}{2}\!\left\{ \delta_{k}^{+}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1)} \!\right)\!\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \!\right) \! + \! \delta_{k}^{-}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1)} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \!\right) \!\right\} \\
	& + \nu^{2}\delta_{k}^{\langle 2 \rangle}\Theta_{k}^{(j+1)} \quad (k=0, \ldots, K), 
\end{split} \label{sc2}%\\[-2pt]
% \delta_{k}^{\langle 1 \rangle}H_{k}^{(j)} = 0 \quad (k=0, K), \label{bc1}\\[-2pt]
% \delta_{k}^{\langle 1 \rangle}\Theta_{k}^{(j)} = 0 \quad (k=0, K). \label{bc2} 
\end{gather}
\begin{gather}
	% \begin{split}
	% \frac{ H_{k}^{(j+1)} - H_{k}^{(j)} }{\Delta t} 
	% 	= & \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}H_{k}^{(j+1)} - c\left(H_{k}^{(j+1)} - 1 \right) \\
	% 	& - \kappa H_{k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)  }{2} \quad (k=0, \ldots, K), 
	% \end{split} \label{sc1}\\[-2pt]
	% \begin{split}
	% \alpha_{0, k}^{(j+1)} \frac{ \Theta_{k}^{(j+1)} \! - \! \Theta_{k}^{(j)} }{\Delta t} 
	% 	= & \frac{\kappa}{2}\!\left\{ \delta_{k}^{+}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1)} \!\right)\!\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \!\right) \! + \! \delta_{k}^{-}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1)} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \!\right) \!\right\} \\
	% 	& + \nu^{2}\delta_{k}^{\langle 2 \rangle}\Theta_{k}^{(j+1)} \quad (k=0, \ldots, K), 
	% \end{split} \label{sc2}\\[-2pt]
	\delta_{k}^{\langle 1 \rangle}H_{k}^{(j)} = 0 \quad (k=0, K), \label{bc1}\\[-2pt]
	\delta_{k}^{\langle 1 \rangle}\Theta_{k}^{(j)} = 0 \quad (k=0, K). \label{bc2} 
\end{gather}
The notations used in the above scheme are defined below. 

\begin{defn}
    \label{Def.TBA}
    Let $K$ be a natural number.
    We define $H_{k}^{(j)}$ and $\Theta_{k}^{(j)} \ (k \! = \! -1, 0, \ldots, K, K+1,\ j = 0,1,\ldots)$ to be the approximation to $\eta(t,x)$ and $\theta(t,x)$ at time $t = j\Delta t$ and location $x=k\Delta x$, respectively. 
    As a side note, 
    $\Delta t$ is a time mesh size. 
    They are also written in vector as 
    \begin{gather*}
        \bm{H}^{(j)} := (H_{0}^{(j)},\ldots,H_{K}^{(j)})^{\top} \quad \mbox{or} \quad \bm{H}^{(j)} := (H_{-1}^{(j)}, H_{0}^{(j)},\ldots,H_{K}^{(j)},H_{K+1}^{(j)})^{\top}, \\
        \bm{\Theta}^{(j)} := (\Theta_{0}^{(j)},\ldots,\Theta_{K}^{(j)})^{\top} \quad \mbox{or} \quad \bm{\Theta}^{(j)} := (\Theta_{-1}^{(j)}, \Theta_{0}^{(j)},\ldots,\Theta_{K}^{(j)},\Theta_{K+1}^{(j)})^{\top}. 
    \end{gather*}
    Guess the meanings of $\bm{H}^{(j)}$ and $\bm{\Theta}^{(j)}$ from the context. 
    Hereafter, in this paper, $\bm{H}^{(j)}$ and $\bm{\Theta}^{(j)}$ are obtained by the proposed scheme \eqref{sc1}--\eqref{bc2}. 
    $H_{-1}^{(j)}$, $H_{K+1}^{(j)}$, $\Theta_{-1}^{(j)}$, and $\Theta_{K+1}^{(j)}$ are artificial quantities and are determined by the imposed discrete boundary conditions \eqref{bc1}--\eqref{bc2}. 
    Namely, 
    \begin{gather*}
        H_{-1}^{(j)} = H_{1}^{(j)}, \quad H_{K+1}^{(j)} = H_{K-1}^{(j)} \quad (j = 0,1, \ldots), \\
        \Theta_{-1}^{(j)} = \Theta_{1}^{(j)}, \quad \Theta_{K+1}^{(j)} = \Theta_{K-1}^{(j)} \quad (j = 0,1, \ldots). 
    \end{gather*}
    Furthermore, we define $\alpha_{0, k}^{(j)}$ by $\alpha_{0, k}^{(j)} := \alpha_{0}(j\Delta t,k\Delta x) \ (k = 0, 1, \ldots, K,\ j = 0,1,\ldots)$. 
\end{defn}

Fix a natural number $N \in \mathbb{N}$. 
We compute $(\bm{H}^{(j)},\bm{\Theta}^{(j)})$ up to $j=N$ by our proposed scheme \eqref{sc1}--\eqref{bc2} and estimate the error between it and the solution to the problem \eqref{1}--\eqref{2} up to $T=N\Delta t$.
Moreover, 
    we extend the solution $\eta$ in $\overline{Q}$ to $\tilde{\eta}$ in $[0,T] \times [-\Delta x, 1 + \Delta x]$ as follows: 
\begin{equation}
    \tilde{\eta}(t,x) := \begin{cases}
    \displaystyle \eta(t,-x) 
    & (-\Delta x \leq x < 0), \\
    \eta(t,x) & (0 \leq x \leq 1), \\
    \displaystyle \eta(t,2 - x) 
    & (1 < x \leq 1 + \Delta x), 
    \end{cases} \label{def_ext}
\end{equation}
for $t \in [0,T]$. 
Similarly, an extension $\tilde{\theta}$ of $\theta$ is also defined.
From the direct calculation, we can check that the following properties hold: 
if $\partial_{t}^{l}\partial_{x}^{m}\eta, \partial_{t}^{l}\partial_{x}^{m}\theta \in C(\overline{Q}) \ (0 \leq l \leq 1,\ 0 \leq m \leq 2,\ l + m \leq 2)$, then 
\begin{gather*}
    \partial_{t}^{l}\partial_{x}^{m}\tilde{\eta}, \partial_{t}^{l}\partial_{x}^{m}\tilde{\theta} \in C([0,T] \times [-\Delta x,1 + \Delta x]) \quad (0 \leq l \leq 1,\ 0 \leq m \leq 2,\ l + m \leq 2), \\
    \tilde{\eta}(t,x) = \eta(t,x) \quad \mbox{for\ all\ } x \in [0,1], \\
    \tilde{\eta}(t,-\Delta x) = \tilde{\eta}(t,\Delta x), \quad \tilde{\eta}(t,1 + \Delta x) = \tilde{\eta}(t,1 - \Delta x), \\
    \tilde{\theta}(t,x) = \theta(t,x) \quad \mbox{for\ all\ } x \in [0,1], \\
    \tilde{\theta}(t,-\Delta x) = \tilde{\theta}(t,\Delta x), \quad \tilde{\theta}(t, 1 + \Delta x) = \tilde{\theta}(t, 1 - \Delta x). 
\end{gather*}

Let $H_{k}^{(0)} = \tilde{\eta}(0,k\Delta x), \Theta_{k}^{(0)} = \tilde{\theta}(0,k\Delta x) \ (k = -1,0,\ldots, K,K+1)$. 
In addition, we define the errors $e_{\eta,k}^{(j)}$ and $e_{\theta,k}^{(j)}$ by 
\begin{gather*}
e_{\eta,k}^{(j)} := H_{k}^{(j)} - \tilde{\eta}(j\Delta t, k\Delta x) \quad (k=-1,0,\ldots, K,K+1,\ j=0,1,\ldots, N), \\
e_{\theta,k}^{(j)} := \Theta_{k}^{(j)} - \tilde{\theta}(j\Delta t, k\Delta x) \quad (k = -1,0,\ldots, K,K + 1,\ j = 0,1,\ldots, N).
\end{gather*}
Additionally, we use the following vector notations: 
\begin{gather*}
    \bm{e}_{\eta}^{(j)} := (e_{\eta,-1}^{(j)}, e_{\eta,0}^{(j)},\ldots,e_{\eta,K}^{(j)},e_{\eta,K+1}^{(j)})^{\top} \in \mathbb{R}^{K+3}, \\ 
    \bm{e}_{\theta}^{(j)} := (e_{\theta,-1}^{(j)}, e_{\theta,0}^{(j)},\ldots,e_{\theta,K}^{(j)},e_{\theta,K+1}^{(j)})^{\top} \in \mathbb{R}^{K+3},
\end{gather*}
for $ j = 0, 1, \dots, N$.
For simplicity, we use the expression $\tilde{\eta}_{k}^{(j)} := \tilde{\eta}(j\Delta t, k\Delta x)$ and $\tilde{\theta}_{k}^{(j)} := \tilde{\theta}(j\Delta t, k\Delta x)$ from now on.  
Also, the expressions $\delta_{k}^{\ast}f_{l}$ means $\left. \delta_{k}^{\ast}f_{k} \right|_{k=l}$, where the symbol ``$\ast$" denotes $+$, $\langle 1 \rangle$, or $\langle 2 \rangle$. 

\begin{rem}
    We remark on the existence of a solution to the scheme \eqref{sc1}--\eqref{bc2}. 
    For any given $(\bm{H}^{(j)},\bm{\Theta}^{(j)})$, if $\Delta t$ satisfies 
    \begin{equation}
        \Delta t < \frac{\nu^{2}\varepsilon^{2}}{4\kappa^{2}\delta_{0}\left(\delta_{0} + \dfrac{1}{2}\right)^{2}}(\Delta x)^{2}, \label{exist_cond}
    \end{equation}
    then there exists a unique solution $(\bm{H}^{(j + 1)},\bm{\Theta}^{(j + 1)})$ satisfying \eqref{sc1}--\eqref{sc2} with \eqref{bc1}--\eqref{bc2}.

    More precisely, the existence and uniqueness of $\bm{H}^{(j + 1)}$ are unconditionally obtained from the regularity of the coefficient matrix of $\bm{H}^{(j + 1)}$ 
    since scheme \eqref{sc1} is linear and implicit (cf. Lemma \ref{exist1}). 
    On the other hand, the existence and uniqueness of $\bm{\Theta}^{(j + 1)}$ can be obtained by the method of Banach's fixed point theorem, e.g., as in the first author's results \cite{MO2018JIAM, MO2020DCDS}, 
    since scheme \eqref{sc2} is nonlinear and implicit (cf. Lemma \ref{exist2}). 
    Note that the condition \eqref{exist_cond} above is a sufficient condition for the existence and uniqueness of $\bm{\Theta}^{(j + 1)}$.
\end{rem}

\begin{rem}
    \eqref{exist_cond} is only a sufficient condition, and a weaker assumption, i.e., a coarser $\Delta t$, could still yield a solvability result.
\end{rem}

Henceforth, we discuss under the assumption of condition \eqref{exist_cond} above. 
Now, the goal of this paper is to prove the following Main Theorems.
\begin{mainthm}
    Let us assume (A1) and assume that {$ \bigl\{ (\bm{H}^{(j)},\bm{\Theta}^{(j)}) \bigr\}_{j = 0}^{N} $ is a sequence consisting of the solutions $ (\bm{H}^{(j)},\bm{\Theta}^{(j)}) $, $ j = 0, 1, \ldots, N $, to the proposed scheme \eqref{sc1}--\eqref{bc2}.} 
    Then, the followings hold: 
    \begin{enumerate}
        \item[(O)] 
            \begin{enumerate}
                \item[(a)]if the initial data satisfies that
        \begin{gather}
            0 \leq H_{k}^{(0)} \leq 1 \quad (k = 0,1,\ldots,K), \quad \left|\Theta_{k}^{(0)}\right| \leq \xi_{0} \quad (k = 0,1,\ldots,K) %~\mbox{ for $ k = 0,1,\ldots,K $,} 
            \notag\\
            \mbox{with a constant  $\xi_{0} > 0$ independent of $k$ and $j$,} \label{ass_bd}
        \end{gather}
        then it holds that:
        \begin{equation}
            0 \leq H_{k}^{(j)} \leq 1 \quad (k = 0,1,\ldots,K), \quad \left|\Theta_{k}^{(j)}\right| \leq \xi_{0} \quad (k = 0,1,\ldots,K). 
            \label{bound}
        \end{equation}
    \item[(b)] 
        we define discrete global energy $\mathscr{F}_{1, \rm d}$: $\mathbb{R}^{K+3} \times \mathbb{R}^{K+3} \to \mathbb{R}$ as follows: 
        \begin{align*}
        \mathscr{F}_{1, \rm d}(\bm{H}, \bm{\Theta}) \! 
            := & \frac{\kappa_{0}^{2}}{2}\sum_{k=0}^{K}{}^{\prime\prime}\frac{ \left| \delta_{k}^{+}H_{k} \right|^{2} + \left| \delta_{k}^{-}H_{k} \right|^{2} }{2}\Delta x + \frac{c}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left| H_{k} - 1 \right|^{2} \Delta x  \\[-1pt]
            & + \! \frac{ \nu^{2} }{2}\!\sum_{k=0}^{K}\!{}^{\prime\prime}\frac{ \left| \delta_{k}^{+}\Theta_{k} \right|^{2} \!\! + \! \left| \delta_{k}^{-}\Theta_{k} \right|^{2} }{2}\Delta x 
            \\[-1pt]
            & + \! \kappa\!\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left( H_{k} \right)\!\frac{ \gamma_{\varepsilon}( \delta_{k}^{+}\Theta_{k}) \! + \! \gamma_{\varepsilon}( \delta_{k}^{-}\Theta_{k}) }{2} \Delta x, \\
            & \qquad\qquad \mbox{for}\ (\bm{H}, \bm{\Theta}) = (\{H_{k}\}_{k = -1}^{K+1}, \{\Theta_{k}\}_{k = -1}^{K+1}) \in \mathbb{R}^{K+3} \times \mathbb{R}^{K+3},
        \end{align*}
        then, the following dissipative property holds: 
        \begin{align}
            & \frac{ \mathscr{F}_{1, \rm d}(\bm{H}^{(j+1)}, \bm{\Theta}^{(j+1)}) - \mathscr{F}_{1, \rm d}(\bm{H}^{(j)}, \bm{\Theta}^{(j)}) }{\Delta t} \nonumber\\
            \leq & - \sum_{k=0}^{K}{}^{\prime\prime}\left| \frac{ H_{k}^{(j+1)} - H_{k}^{(j)} }{\Delta t} \right|^{2}\Delta x - \sum_{k=0}^{K}{}^{\prime\prime}\alpha_{0,k}^{(j+1)} \left| \frac{ \Theta_{k}^{(j+1)} - \Theta_{k}^{(j)} }{\Delta t} \right|^{2}\Delta x \leq 0, 
            \label{d_en_ineq}
        \end{align}
        for $ j = 0, 1, \dots, N -1 $. 
            \end{enumerate}
        \item[(\,I\,)]In addition,  let us assume the following condition.
            \begin{enumerate}
                \item[(A2)] $\partial_{t}^{l}\partial_{x}^{m}\eta, \partial_{t}^{l}\partial_{x}^{m}\theta \in C(\overline{Q}) \ (0 \leq l \leq 1,\ 0 \leq m \leq 2,\ l + m \leq 2)$. 

            \end{enumerate}
            Under (A1) and (A2), if $\Delta t$ satisfies
        \begin{equation}
            \Delta t < \frac{1}{3a}, \label{dt_ass} 
        \end{equation}
        where $a := \max\{2(\kappa C_{1}/\nu )^{2} - (2\kappa\varepsilon + c), (L_{\alpha_{0}} + 1)/\delta_{0}\}$ 
            and also $L_{\alpha_{0}} \geq 0$ is the Lipschitz constant of $\alpha_{0}$ as defined in (A1), 
            and $C_{1}$ is the constant as defined in \eqref{eta_bound},  
        then it holds that: 
        \begin{gather}
            \sup_{0 \leq j \leq N} \bigl\| \bm{e}_\eta^{(j)} \bigr\|_{L_d^2} +\sup_{0 \leq j \leq N} \bigl\| \bm{e}_\theta^{(j)} \bigr\|_{L_d^2} \to 0, \mbox{ as $ \Delta x, \Delta t \to 0 $.}
            \label{conv}
        \end{gather}
    \end{enumerate}
\end{mainthm}
\begin{mainthm}
    In addition to (A1), (A2), and \eqref{dt_ass}, let us assume the following condition. 
    \begin{enumerate}
        \item[(A3)] $\partial_{t}\eta$, $\partial_{x}^{2}\eta$, $\partial_{t}\theta$, and $\partial_{x}^{2}\theta$ are H\"{o}lder continuous functions of order $\sigma \in (0,1)$.
    \end{enumerate}
    Then, the following item holds. 
    \begin{enumerate}
        \item[(II)]There exists a constant $C$ independent of $k$ and $j$ such that 
    \begin{gather}
        \left\|\bm{e}_{\eta}^{(j)}\right\|_{L_{\rm d}^{2}} 
        \leq C\bigl( (\Delta x)^{\sigma} + (\Delta t)^{\sigma} + \Delta t + \Delta x + (\Delta x)^{2} \bigr) \quad (j = 1, \ldots, N), 
        \label{e_err_est}\\
        \left\|\bm{e}_{\theta}^{(j)}\right\|_{L_{\rm d}^{2}}
        \leq C\bigl( (\Delta x)^{\sigma} + (\Delta t)^{\sigma} + \Delta t + \Delta x + (\Delta x)^{2} \bigr) \quad (j = 1, \ldots, N). 
        \label{t_err_est}
    \end{gather}
    \end{enumerate}
\end{mainthm}


\begin{rem}
    In other words, from \eqref{e_err_est} and \eqref{t_err_est}, the convergence rates of the solutions to our proposed scheme \eqref{sc1}--\eqref{bc2} are $O((\Delta x)^{\sigma} + (\Delta t)^{\sigma})$.
\end{rem}


\section{Proofs of Main Theorems}

\subsection{Proof of Main Theorem 1}

\subsubsection{Proof of (O)(a)}
First, we estimate $\bm{H}^{(j+1)}$. 
It is seen that 
\begin{equation}
\frac{1}{\Delta t}(0-0)
	\leq \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}0 - c\left(0 - 1 \right) - \kappa \cdot 0 \cdot \frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)  }{2} \quad (k=0, \ldots, K). \label{eta_tool_0}
\end{equation}
Substracing \eqref{sc1} from \eqref{eta_tool_0}, we obtain 
\begin{align}
\frac{1}{\Delta t}\left\{\! \left(-H_{k}^{(j+1)}\right) \! - \! \left(-H_{k}^{(j)}\right) \!\right\}
	\leq & \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}\left(-H_{k}^{(j+1)}\right)
	-c\left(-H_{k}^{(j+1)}\right) \nonumber\\
	& - \kappa \!\left(\! -H_{k}^{(j+1)} \!\right) \frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) \! + \! \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)  }{2} \quad (k=0, \ldots, K). \label{eta_tool_0-sc1}
\end{align}
Let us multiply both sides of \eqref{eta_tool_0-sc1} by $[-H_{k}^{(j+1)}]^{+}$ and sum each of the resulting equality over $k = 0,1, \ldots, K$. 
Then, by using the summation by parts formula (Lemma \ref{sbp5}) and \eqref{bc1}, we have  
\begin{align*}
& \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left| [-H_{k}^{(j+1)}]^{+}\right|^{2}\Delta x 
+ \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}H_{k}^{(j)}[-H_{k}^{(j+1)}]^{+}\Delta x \\
	\leq & \kappa_{0}^{2}\sum_{k=0}^{K}{}^{\prime\prime}\left\{\delta_{k}^{\langle 2 \rangle}\left(-H_{k}^{(j+1)}\right)\right\}[-H_{k}^{(j+1)}]^{+}\Delta x
	- c\sum_{k=0}^{K}{}^{\prime\prime}\left| [-H_{k}^{(j+1)}]^{+}\right|^{2}\Delta x \\
	& - \kappa\sum_{k=0}^{K}{}^{\prime\prime}\left| [-H_{k}^{(j+1)}]^{+}\right|^{2}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)  }{2}\Delta x \\
	\leq & -\kappa_{0}^{2}\sum_{k=0}^{K-1}\left\{\delta_{k}^{+}\left(-H_{k}^{(j+1)}\right)\right\}\left\{\delta_{k}^{+}[-H_{k}^{(j+1)}]^{+}\right\}\Delta x 
	\leq -\kappa_{0}^{2}\sum_{k=0}^{K-1}\left|\delta_{k}^{+}[-H_{k}^{(j+1)}]^{+}\right|^{2}\Delta x
	\leq 0. 
\end{align*}
From the above inequality and the assumptions \eqref{ass_bd}, it is seen that 
\begin{equation*}
	\frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left| [-H_{k}^{(j+1)}]^{+}\right|^{2}\Delta x \leq 0. 
\end{equation*}
Namely, we have $0 \leq H_{k}^{(j+1)} \ (k=0, \ldots, K)$. 
It follows from this inequality and \eqref{sc1} that 
\begin{equation}
	\frac{ H_{k}^{(j+1)} - H_{k}^{(j)} }{\Delta t} 
	\leq \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}H_{k}^{(j+1)} - c\left(H_{k}^{(j+1)} - 1 \right) \quad (k=0, \ldots, K). \label{eta_tool_sc1}
\end{equation}
Furthermore, it holds that 
\begin{equation}
\frac{1}{\Delta t}(1-1)
	= \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}1 - c\left(1 - 1 \right). \label{eta_tool_1}
\end{equation}
Substracing \eqref{eta_tool_1} from \eqref{eta_tool_sc1}, we obtain 
\begin{equation}
\frac{1}{\Delta t}\left\{\! \left(H_{k}^{(j+1)} - 1\right) \! - \! \left(H_{k}^{(j)} - 1\right) \!\right\}
	\leq \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}\!\left(H_{k}^{(j+1)} - 1\right)
	-c\!\left(H_{k}^{(j+1)} - 1\right) \quad (k=0, \ldots, K). \label{eta_tool_sc1-1}
\end{equation}
Let us multiply both sides of \eqref{eta_tool_sc1-1} by $[H_{k}^{(j+1)} - 1]^{+}$ and sum each of the resulting equality over $k = 0,1, \ldots, K$. 
Then, by using the summation by parts formula (Lemma \ref{sbp5}) and \eqref{bc1}, we have  
\begin{align*}
& \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left| [H_{k}^{(j+1)} - 1]^{+}\right|^{2}\Delta x 
+ \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left( 1 - H_{k}^{(j)}\right)[H_{k}^{(j+1)} - 1]^{+}\Delta x \\
	\leq & \kappa_{0}^{2}\sum_{k=0}^{K}{}^{\prime\prime}\left\{\delta_{k}^{\langle 2 \rangle}\left(H_{k}^{(j+1)} - 1\right)\right\}[H_{k}^{(j+1)} - 1]^{+}\Delta x
	- c\sum_{k=0}^{K}{}^{\prime\prime}\left| [H_{k}^{(j+1)} - 1]^{+}\right|^{2}\Delta x \\
	\leq & - \! \kappa_{0}^{2}\sum_{k=0}^{K-1}\!\left\{\!\delta_{k}^{+}\!\left(\! H_{k}^{(j+1)} - 1 \!\right)\!\right\}\!\left\{\delta_{k}^{+}[H_{k}^{(j+1)} - 1]^{+}\right\}\Delta x 
	\leq -\kappa_{0}^{2}\sum_{k=0}^{K-1}\left|\delta_{k}^{+}[H_{k}^{(j+1)} - 1]^{+}\right|^{2}\Delta x
	\leq 0. 
\end{align*}
% Thus, we get 
% \begin{equation*}
% 	\frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left| [H_{k}^{(j+1)} - 1]^{+}\right|^{2}\Delta x \leq 0.
% \end{equation*}
In other words, we see from the above inequality and the assumptions \eqref{ass_bd} that $H_{k}^{(j+1)} \leq 1 \ (k=0, \ldots, K)$. 
As a result, we obtain $0 \leq H_{k}^{(j+1)} \leq 1 \ (k=0, \ldots, K)$. 

Next, we estimate $\bm{\Theta}^{(j+1)}$. 
It follows from \eqref{sc2} that  
\begin{align}
& \alpha_{0,k}^{(j+1)}\frac{ \Theta_{k}^{(j+1)} - \Theta_{k}^{(j)} }{\Delta t} - \nu^{2}\delta_{k}^{\langle 2 \rangle}\Theta_{k}^{(j+1)} \nonumber\\
	= & \frac{\kappa}{2}\left\{ \delta_{k}^{+}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \right) + \delta_{k}^{-}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}'(\delta_{k}^{+}\Theta_{k}^{(j+1)})\right) \right\} \quad (k=0, \ldots, K). \label{theta_tool_sc2}
\end{align}
Besides, it is seen that 
\begin{align}
\alpha_{0,k}^{(j+1)}\frac{ \xi_{0} - \xi_{0} }{\Delta t} - \nu^{2}\delta_{k}^{\langle 2 \rangle}\xi_{0} 
	= & \frac{\kappa}{2}\left\{ \delta_{k}^{+}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\xi_{0}) \right) + \delta_{k}^{-}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}'(\delta_{k}^{+}\xi_{0})\right) \right\} \nonumber\\
	= & \frac{\kappa}{2}\left\{ \delta_{k}^{+}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (0) \right) + \delta_{k}^{-}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}'(0)\right) \right\} \nonumber\\
	(= & 0) \quad (k=0, \ldots, K). \label{theta_tool_xi0}
\end{align}
Substracing \eqref{theta_tool_xi0} from \eqref{theta_tool_sc2}, we obtain 
\begin{align}
	& \alpha_{0,k}^{(j+1)}\frac{ (\Theta_{k}^{(j+1)} - \xi_{0}) - (\Theta_{k}^{(j)} - \xi_{0}) }{\Delta t} - \nu^{2}\delta_{k}^{\langle 2 \rangle}(\Theta_{k}^{(j+1)} - \xi_{0}) \nonumber\\
	= & \frac{\kappa}{2}\left\{ \delta_{k}^{+}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \right) + \delta_{k}^{-}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}'(\delta_{k}^{+}\Theta_{k}^{(j+1)})\right) \right\} \quad (k=0, \ldots, K). \label{theta_tool_xi0-sc2}
\end{align}
Let us multiply both sides of \eqref{theta_tool_xi0-sc2} by $[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}$ and sum each of the resulting equality over $k = 0,1, \ldots, K$. 
Then, by using the summation by parts formula (Lemma \ref{sbp2}), we can transform the right-hand side of the resulting equality as follows:
\begin{align}
& \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left\{ \delta_{k}^{+}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \right)\right\}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \notag\\
& + \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left\{ \delta_{k}^{-}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \right)\right\}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \notag\\
	= & \frac{\kappa}{2}\left\{ -\sum_{k=1}^{K} \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \delta_{k}^{-}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \right. \notag\\
	& \left. + \left[ \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \mu_{k}^{-}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+} \right]_{0}^{K}\right\} \notag\\
	& + \frac{\kappa}{2}\left\{ -\sum_{k=0}^{K-1} \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \delta_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \right. \notag\\
	& \left. + \left[ \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \mu_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+} \right]_{0}^{K}\right\}. \label{theta_tool_sum}
\end{align}
Here, it holds from \eqref{bc2} that
\begin{gather*}
\left. \delta_{k}^{+}\Theta_{k}^{(j+1)} \right|_{k=K} = \left. - \delta_{k}^{-}\Theta_{k}^{(j+1)} \right|_{k=K}, \quad 
\left. \delta_{k}^{-}\Theta_{k}^{(j+1)} \right|_{k=0} = \left. - \delta_{k}^{+}\Theta_{k}^{(j+1)} \right|_{k=0}, \\
\left. \mu_{k}^{+}[\Theta_{k}^{(j+1)} \! - \! \xi_{0}]^{+}\right|_{k=K} \! = \! \left. \mu_{k}^{-}[\Theta_{k}^{(j+1)} \! - \! \xi_{0}]^{+}\right|_{k=K} \! , \quad 
\left. \mu_{k}^{-}[\Theta_{k}^{(j+1)} \! - \! \xi_{0}]^{+}\right|_{k=0} \! = \! \left. \mu_{k}^{+}[\Theta_{k}^{(j+1)} \! - \! \xi_{0}]^{+}\right|_{k=0}. 
\end{gather*}
From the above and the fact that $\gamma_{\varepsilon}'$ is an odd function, we check that 
\begin{align*}
	& \mbox{(The right-hand side of \eqref{theta_tool_sum})} \\
% & \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left\{ \delta_{k}^{+}\left( \alpha\left( H_{k}^{(j+1)} \right)\mo{\gamma_{\varepsilon}'} (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \right)\right\}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
% & + \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left\{ \delta_{k}^{-}\left( \alpha\left( H_{k}^{(j+1)} \right)\mo{\gamma_{\varepsilon}'} (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \right)\right\}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	= & -\frac{\kappa}{2}\sum_{k=1}^{K} \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \delta_{k}^{-}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	& -\frac{\kappa}{2}\sum_{k=0}^{K-1} \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \delta_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	= & -\frac{\kappa}{2}\sum_{k=1}^{K} \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k-1}^{(j+1)}) \delta_{k}^{+}[\Theta_{k-1}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	& -\frac{\kappa}{2}\sum_{k=0}^{K-1} \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \delta_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	= & -\frac{\kappa}{2}\sum_{k=0}^{K-1} \left\{ \alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right) \right\} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \delta_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	% = & -\frac{\kappa}{2}\sum_{k=0}^{K-1} \frac{ \alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right) }{\mo{\gamma_{\varepsilon}} (\delta_{k}^{+}\Theta_{k}^{(j+1)})}\left(\delta_{k}^{+}\Theta_{k}^{(j+1)} \right)\delta_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	= & -\frac{\kappa}{2}\sum_{k=0}^{K-1} \frac{ \alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right) }{\gamma_{\varepsilon} (\delta_{k}^{+}\Theta_{k}^{(j+1)})}\left\{\delta_{k}^{+}\left(\Theta_{k}^{(j+1)} - \xi_{0}\right) \right\}\delta_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	\leq & -\frac{\kappa}{2}\sum_{k=0}^{K-1} \frac{ \alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right) }{\gamma_{\varepsilon} (\delta_{k}^{+}\Theta_{k}^{(j+1)})}\left| \delta_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+} \right|^{2}\Delta x 
	\leq 0.
\end{align*}
Meanwhile, it follows from (A1), the summation by parts formula (Lemma \ref{sbp5}), and \eqref{bc2} that 
\begin{align*}
& \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\alpha_{0,k}^{(j+1)}\left| [\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\right|^{2}\Delta x 
+ \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\alpha_{0,k}^{(j+1)}\left( \xi_{0} - \Theta_{k}^{(j)} \right)[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
& - \nu^{2}\sum_{k=0}^{K}{}^{\prime\prime}\left\{ \delta_{k}^{\langle 2 \rangle}\left(\Theta_{k}^{(j+1)} - \xi_{0}\right) \right\}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\
	\geq & \frac{\delta_{0}}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\!\left| [\Theta_{k}^{(j+1)} \! - \xi_{0}]^{+}\right|^{2}\!\Delta x 
	+ \frac{\delta_{0}}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\!\left( \xi_{0} - \Theta_{k}^{(j)} \right)\![\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\Delta x \\ 
	& + \nu^{2}\sum_{k=0}^{K-1}\left| \delta_{k}^{+}[\Theta_{k}^{(j+1)} \! - \xi_{0}]^{+} \right|^{2}\!\Delta x. 
\end{align*}
From the above inequalities and the assumptions \eqref{ass_bd}, we obtain  
\begin{equation*}
	\frac{\delta_{0}}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left| [\Theta_{k}^{(j+1)} - \xi_{0}]^{+}\right|^{2}\Delta x 
	\leq -\nu^{2}\sum_{k=0}^{K-1}\left| \delta_{k}^{+}[\Theta_{k}^{(j+1)} - \xi_{0}]^{+} \right|^{2}\Delta x
	\leq 0.
\end{equation*}
Namely, it holds that $\Theta_{k}^{(j+1)} \leq \xi_{0} \ (k=0, \ldots, K)$. 
Similarly, we have $-\xi_{0} \leq \Theta_{k}^{(j+1)} \ (k=0, \ldots, K)$. 
Thus, we conclude that $|\Theta_{k}^{(j+1)}| \leq \xi_{0} \ (k=0, \ldots, K)$. 

\subsubsection{Proof of (O)(b)}
Multiplying both sides of \eqref{sc1} by $H_{k}^{(j + 1)} - H_{k}^{(j)}$ and summing each of the resulting equality over $k = 0,1, \ldots, K$, we have 
\begin{align*}
	0 = & \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left|H_{k}^{(j + 1)} - H_{k}^{(j)}\right|^{2}\Delta x 
		- \kappa_{0}^{2}\sum_{k=0}^{K}{}^{\prime\prime}\left(\delta_{k}^{\langle 2 \rangle}H_{k}^{(j + 1)}\right)\left(H_{k}^{(j + 1)} - H_{k}^{(j)}\right)\Delta x \\
	    &   + c\sum_{k=0}^{K}{}^{\prime\prime}\left(H_{k}^{(j + 1)} - 1\right)\left(H_{k}^{(j + 1)} - H_{k}^{(j)}\right)\Delta x \\
	    &	+ \kappa\sum_{k=0}^{K}{}^{\prime\prime}H_{k}^{(j + 1)}\left(H_{k}^{(j + 1)} - H_{k}^{(j)}\right)\frac{\gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)}{2}\Delta x.
\end{align*}
By using the summation by parts formula (Lemma \ref{sbp5}), \eqref{bc1}, and the following inequality: 
\begin{equation}
	a(a - b) \geq \frac{1}{2}a^{2} - \frac{1}{2}b^{2} \quad \mbox{for all} \ a, b \in \mathbb{R}, \label{tool_ineq}
\end{equation}
we obtain 
\begin{align*}
	- \kappa_{0}^{2}\sum_{k=0}^{K}{}^{\prime\prime}\!\left(\delta_{k}^{\langle 2 \rangle}H_{k}^{(j + 1)}\right)\!\!\left(\! H_{k}^{(j + 1)} \! - \! H_{k}^{(j)}\!\right)\Delta x 
	= & \kappa_{0}^{2}\sum_{k=0}^{K-1}\left(\delta_{k}^{+}H_{k}^{(j + 1)}\right)\!\left\{\delta_{k}^{+}\!\left(H_{k}^{(j + 1)} - H_{k}^{(j)}\right)\right\}\Delta x \\
	& - \kappa_{0}^{2}\left[\left(\delta_{k}^{\langle 1 \rangle}H_{k}^{(j + 1)}\right)\left(H_{k}^{(j + 1)} - H_{k}^{(j)}\right)\right]_{0}^{K} \\
	= & \kappa_{0}^{2}\sum_{k=0}^{K-1}\left(\delta_{k}^{+}H_{k}^{(j + 1)}\right)\left(\delta_{k}^{+}H_{k}^{(j + 1)} - \delta_{k}^{+}H_{k}^{(j)}\right)\Delta x \\
	\geq & \frac{\kappa_{0}^{2}}{2}\sum_{k=0}^{K-1}\left|\delta_{k}^{+}H_{k}^{(j + 1)}\right|^{2}\Delta x - \frac{\kappa_{0}^{2}}{2}\sum_{k=0}^{K-1}\left|\delta_{k}^{+}H_{k}^{(j)}\right|^{2}\Delta x. 
\end{align*}
Similarly, it follows from \eqref{tool_ineq} that 
\begin{gather*}
	c\sum_{k=0}^{K}{}^{\prime\prime}\!\left(\! H_{k}^{(j + 1)} \! - \! 1 \!\right)\!\!\left(\! H_{k}^{(j + 1)} \! - \! H_{k}^{(j)}\!\right)\Delta x 
	\geq \frac{c}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left|H_{k}^{(j + 1)} - 1\right|^{2}\Delta x 
	     - \frac{c}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left|H_{k}^{(j)} - 1\right|^{2}\Delta x, \\
	\begin{split}
		& \kappa\sum_{k=0}^{K}{}^{\prime\prime}H_{k}^{(j + 1)}\left(H_{k}^{(j + 1)} - H_{k}^{(j)}\right)\frac{\gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)}{2}\Delta x \\
		\geq & \kappa\!\sum_{k=0}^{K}\!{}^{\prime\prime}\alpha\!\left(\!H_{k}^{(j + 1)}\!\right)\frac{\gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) \! + \! \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)}{2}\Delta x
		\! - \! \kappa\!\sum_{k=0}^{K}\!{}^{\prime\prime}\alpha\!\left(\!H_{k}^{(j)}\!\right)\frac{\gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) \! + \! \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)}{2}\Delta x.
	\end{split}
\end{gather*}
From the above, we obtain 
\begin{align*}
	0 \! \geq & \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left|H_{k}^{(j + 1)} - H_{k}^{(j)}\right|^{2}\Delta x 
		+ \frac{\kappa_{0}^{2}}{2}\sum_{k=0}^{K-1}\left|\delta_{k}^{+}H_{k}^{(j + 1)}\right|^{2}\Delta x - \frac{\kappa_{0}^{2}}{2}\sum_{k=0}^{K-1}\left|\delta_{k}^{+}H_{k}^{(j)}\right|^{2}\Delta x \\
	    &   + \frac{c}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left|H_{k}^{(j + 1)} - 1\right|^{2}\Delta x 
	    	- \frac{c}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left|H_{k}^{(j)} - 1\right|^{2}\Delta x \\
	    &	+ \!\kappa\!\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left(\!H_{k}^{(j + 1\!)}\!\right)\!\frac{\gamma_{\varepsilon}\!\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) \!\! + \! \gamma_{\varepsilon}\!\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)}{2}\Delta x
	    \! - \! \kappa\!\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left(\!H_{k}^{(j)}\!\right)\!\frac{\gamma_{\varepsilon}\!\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) \!\! + \! \gamma_{\varepsilon}\!\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)}{2}\Delta x.
\end{align*}
Moreover, multiplying both sides of \eqref{sc2} by $\Theta_{k}^{(j + 1)} - \Theta_{k}^{(j)}$ and summing each of the resulting equality over $k = 0,1, \ldots, K$, we have 
\begin{align*}
	0 = & \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\alpha_{0,k}^{(j + 1)}\left|\Theta_{k}^{(j + 1)} - \Theta_{k}^{(j)}\right|^{2}\Delta x 
		- \nu^{2}\sum_{k=0}^{K}{}^{\prime\prime}\left(\delta_{k}^{\langle 2 \rangle}\Theta_{k}^{(j + 1)}\right)\left(\Theta_{k}^{(j + 1)} - \Theta_{k}^{(j)}\right)\Delta x \\
	    &	- \! \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\left\{ \delta_{k}^{+}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1\! )} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \!\right) \!+ \! \delta_{k}^{-}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1\! )} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \!\right) \!\right\} \! \left(\! \Theta_{k}^{(j + 1)} \! - \! \Theta_{k}^{(j)} \!\right)\Delta x.
\end{align*}
In this part, we consider the third term in the right hand side of the above equality. 
We obtain the following equality by the summation by parts formula (Lemma \ref{sbp1}): 
\begin{align*}
	& - \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\left\{ \delta_{k}^{+}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1\! )} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \!\right) \!\right\} \! \left(\! \Theta_{k}^{(j + 1)} \! - \! \Theta_{k}^{(j)} \!\right)\Delta x \\
	= & \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime} \! \alpha\!\left(\! H_{k}^{(j+1\! )} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \delta_{k}^{-}\!\left(\! \Theta_{k}^{(j + 1)} \! - \! \Theta_{k}^{(j)} \!\right)\Delta x \\
	& \underset{\rm =: (d.B.T.)}{\underline{- \frac{\kappa}{4}\left[ \alpha\!\left(\! H_{k+1}^{(j+1\! )} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k+1}^{(j+1)}) \! \left(\! \Theta_{k}^{(j + 1)} \! - \! \Theta_{k}^{(j)} \!\right) + \alpha\!\left(\! H_{k}^{(j+1\! )} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \! \left(\! \Theta_{k-1}^{(j + 1)} \! - \! \Theta_{k-1}^{(j)} \!\right) \right]_{0}^{K} }} \\
	= & \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime} \alpha\!\left(\! H_{k}^{(j+1\! )} \!\right)\! \frac{\delta_{k}^{-}\Theta_{k}^{(j+1)}}{ \gamma_{\varepsilon}(\delta_{k}^{-}\Theta_{k}^{(j+1)}) } \! \left(\! \delta_{k}^{-}\Theta_{k}^{(j + 1)} \! - \! \delta_{k}^{-}\Theta_{k}^{(j)} \!\right)\Delta x + \mbox{(d.B.T.)}. 
\end{align*}
Besides, using the following inequality: 
\begin{equation*}
	\frac{a}{\gamma_{\varepsilon}(a)}(a - b) \geq \gamma_{\varepsilon}(a) - \gamma_{\varepsilon}(b) \quad \mbox{for all} \ a, b \in \mathbb{R}, 
\end{equation*}
we have 
\begin{align*}
	& - \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\left\{ \delta_{k}^{+}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1\! )} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \!\right) \!\right\} \! \left(\! \Theta_{k}^{(j + 1)} \! - \! \Theta_{k}^{(j)} \!\right)\Delta x \\
	\geq & \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left(\!H_{k}^{(j + 1\!)}\!\right)\!\gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j+1)}\bigr) \Delta x 
	- \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left(\!H_{k}^{(j + 1\!)}\!\right)\!\gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr) \Delta x + \mbox{(d.B.T.)}.
\end{align*}
In the same manner as above, it holds that 
\begin{align*}
	& - \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\left\{ \delta_{k}^{-}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1\! )} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) \!\right) \!\right\} \! \left(\! \Theta_{k}^{(j + 1)} \! - \! \Theta_{k}^{(j)} \!\right)\Delta x \\
	\geq & \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left(\!H_{k}^{(j + 1\!)}\!\right)\!\gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j+1)}\bigr) \Delta x 
	- \frac{\kappa}{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left(\!H_{k}^{(j + 1\!)}\!\right)\!\gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) \Delta x + \mbox{(d.B.T.)}.
\end{align*}
Since $\gamma_{\varepsilon}'$ is an odd function, it follows from \eqref{bc1} and \eqref{bc2} that $\mbox{(d.B.T.)} = 0$. 
Therefore, we obtain 
\begin{align*}
	0 \! \geq & \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\alpha_{0,k}^{(j + 1)}\left|\Theta_{k}^{(j + 1)} - \Theta_{k}^{(j)}\right|^{2}\Delta x
		+ \frac{\nu^{2}}{2}\sum_{k=0}^{K-1}\left|\delta_{k}^{+}\Theta_{k}^{(j + 1)}\right|^{2}\Delta x - \frac{\nu^{2}}{2}\sum_{k=0}^{K-1}\left|\delta_{k}^{+}\Theta_{k}^{(j)}\right|^{2}\Delta x \\
	    &	+ \!\kappa\!\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left(\!H_{k}^{(j + 1\!)}\!\right)\!\frac{\gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j+1)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j+1)}\bigr)}{2}\Delta x \\
	    & 	- \! \kappa\!\sum_{k=0}^{K}\!{}^{\prime\prime}\!\alpha\!\left(\!H_{k}^{(j+1\!)}\!\right)\!\frac{\gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)}{2}\Delta x.
\end{align*}
Here, for any $\{f_{k}\}_{k=-1}^{K+1} \in \mathbb{R}^{K+3}$ satisfying the discrete homogeneous Neumann boundary condition $\delta_{k}^{\langle 1 \rangle}f_{k} = 0 \ (k = 0,K)$, 
the following equality holds: 
\begin{equation*}
	\sum _ {k=0}^{K}{}^{\prime \prime}\frac{ |\delta_{k}^{+} f_{k}|^{2} + | \delta_{k}^{-} f_{k} |^{2} }{2}\Delta x = \sum _ {k=0}^{K-1} |\delta_{k}^{+} f_{k}|^{2} \Delta x. \vspace{-1mm} 
\end{equation*}
Consequently, we conclude that 
\begin{align*}
        0 \geq & \mathscr{F}_{1, \rm d}(\bm{H}^{(j+1)}, \bm{\Theta}^{(j+1)}) - \mathscr{F}_{1, \rm d}(\bm{H}^{(j)}, \bm{\Theta}^{(j)}) \\ 
	& + \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left|H_{k}^{(j + 1)} - H_{k}^{(j)}\right|^{2}\Delta x + \frac{1}{\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\alpha_{0,k}^{(j + 1)}\left|\Theta_{k}^{(j + 1)} - \Theta_{k}^{(j)}\right|^{2}\Delta x. 
\end{align*}

\subsubsection{Proof of (I)}
From (A1) and (A2), we see that 
\begin{equation*}
	\left|\xi_{i, k}^{(j+1)}\right| \to 0, \ \mbox{as} \ \Delta x, \Delta t \to 0 \quad (i = 1,2,\ldots, 6), 
\end{equation*}
where $\xi_{i, k}^{(j+1)} \ (k = 0,1,\ldots, K,\ j = 0,1,\ldots, N - 1,\ i = 1,2,\ldots, 6)$ are residual terms defined by \eqref{xi1}--\eqref{xi6}. 
Thus, we obtain from Lemma \ref{e_eta_theta_est} that 
\begin{equation*}
        \sup_{0 \leq n \leq N} \bigl\| \bm{e}_\eta^{(j)} \bigr\|_{L_{\rm d}^2} +\sup_{0 \leq n \leq N} \bigl\| \bm{e}_\theta^{(j)} \bigr\|_{L_{\rm d}^2} \to 0, \mbox{ as $ \Delta x, \Delta t \to 0 $.}
\end{equation*}

