Next, we estimate $\bm{\xi}_{6}^{(j+1)}$. 
For the purpose, we consider the following difference:  
\begin{equation*}
	\left\{\delta_{k}^{+}\left( \alpha( \tilde{\eta}_{k}^{(j+1)} ) \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}^{(j+1)}) \right) + \delta_{k}^{-}\left( \alpha( \tilde{\eta}_{k}^{(j+1)} ) \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}^{(j+1)}) \right)\right\} - 2\partial_{x}\left( \alpha( \eta_{k}^{(j+1)} ) \gamma_{\varepsilon}'(\partial_{x}\theta_{k}^{(j+1)}) \right). 
\end{equation*}
For reasons of space limitation, the superscript $(j+1)$ is omitted hereafter.
Here, we see from Lemma \ref{prod} that 
\begin{gather*}
	\begin{split}
		\delta_{k}^{+}\left( \alpha( \tilde{\eta}_{k} ) \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) 
			= & \frac{1}{2}\delta_{k}^{+}\left( \alpha( \tilde{\eta}_{k} ) \right) \left(\gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k+1}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k})\right) 
			+ \mu_{k}^{+}\left( \alpha( \tilde{\eta}_{k} ) \right)\delta_{k}^{+}\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) \\
			= & \frac{1}{2}\delta_{k}^{+}\left( \alpha( \tilde{\eta}_{k} ) \right) \left(\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k})\right) 
			+ \mu_{k}^{+}\left( \alpha( \tilde{\eta}_{k} ) \right)\delta_{k}^{+}\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right),
	\end{split}\\
	\begin{split}
		\delta_{k}^{-}\left( \alpha( \tilde{\eta}_{k} ) \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right) 
			= & \frac{1}{2}\delta_{k}^{-}\left( \alpha( \tilde{\eta}_{k} ) \right) \left(\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k-1})\right) 
			+ \mu_{k}^{-}\left( \alpha( \tilde{\eta}_{k} ) \right)\delta_{k}^{-}\left(  \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right) \\
			= & \frac{1}{2}\delta_{k}^{-}\left( \alpha( \tilde{\eta}_{k} ) \right) \left(\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k})\right) 
			+ \mu_{k}^{-}\left( \alpha( \tilde{\eta}_{k} ) \right)\delta_{k}^{-}\left(  \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right)
	\end{split}	
\end{gather*}
for $k=0, \ldots, K$. 
From the above, we obtain 
\begin{align*}
& \delta_{k}^{+}\left( \alpha( \tilde{\eta}_{k} ) \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) + \delta_{k}^{-}\left( \alpha( \tilde{\eta}_{k} ) \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right) \\
	= & \delta_{k}^{\langle 1 \rangle}\left( \alpha( \tilde{\eta}_{k} ) \right) \left(\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k})\right) 
	+ \mu_{k}^{+}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\!\delta_{k}^{+}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) 
	+ \mu_{k}^{-}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\!\delta_{k}^{-}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right)
\end{align*}
for $k=0, \ldots, K$. 
Thus, we have 
\begin{align}
	\left|\xi_{6, k}\right|
	\leq & \frac{\kappa}{2}\left(
		\left|\delta_{k}^{\langle 1 \rangle}\left( \alpha( \tilde{\eta}_{k} ) \right) \left(\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k})\right) - 2\partial_{x} \alpha( \eta_{k} ) \gamma_{\varepsilon}'(\partial_{x}\theta_{k})\right|
	\right. \notag\\
	& + \left|
		\mu_{k}^{+}\left( \alpha( \tilde{\eta}_{k} ) \right)\delta_{k}^{+}\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) 
		+ \mu_{k}^{-}\left( \alpha( \tilde{\eta}_{k} ) \right)\delta_{k}^{-}\left(  \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right) 
		- 2\alpha( \eta_{k} )\partial_{x}\gamma_{\varepsilon}'(\partial_{x}\theta_{k})
	\right| 
	\Bigr) \label{xi6_1} 
\end{align}
for $k=0, \ldots, K$. 
Next, we evaluate the first term on the right-hand side of \eqref{xi6_1}. 
Here, we see from (A2) and the mean value theorem that $| \delta_{k}^{\langle 1 \rangle}\left( \alpha( \tilde{\eta}_{k} ) \right) | \leq C \ (k=0, \ldots, K)$.
Hence, we obtain from the above inequality and the following inequality: $|\gamma_{\varepsilon}'(u)| \leq 1$ that 
\begin{align*}
	& \left|
		\delta_{k}^{\langle 1 \rangle}\left( \alpha( \tilde{\eta}_{k} ) \right) \left(\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k})\right) 
		- 2\partial_{x} \alpha( \eta_{k} ) \gamma_{\varepsilon}'(\partial_{x}\theta_{k})
	\right| \\ 
	\leq & 2\left|
		\delta_{k}^{\langle 1 \rangle}\left( \alpha( \tilde{\eta}_{k} ) \right) 
		- \partial_{x} \alpha( \eta_{k} ) 
	\right| 
	\left| \gamma_{\varepsilon}'(\partial_{x}\theta_{k}) \right|
	+ \left| \delta_{k}^{\langle 1 \rangle}\left( \alpha( \tilde{\eta}_{k} ) \right) \right|
	\left|
		\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) 
		- 2\gamma_{\varepsilon}'(\partial_{x}\theta_{k})
	\right| \\
	\leq & C\left(
		\left|
			\delta_{k}^{\langle 1 \rangle}\left( \alpha( \tilde{\eta}_{k} ) \right) 
			- \partial_{x} \alpha( \eta_{k} ) 
		\right| 
		+ \left|
			\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) 
			- 2\gamma_{\varepsilon}'(\partial_{x}\theta_{k})
		\right| 
	\right) \quad (k=0, \ldots, K).
\end{align*}
Moreover, we see from the chain rule, the mean value theorem, and (A2) that 
\begin{align*}
	\left| \delta_{k}^{\langle 1 \rangle}\!\left( \alpha( \tilde{\eta}_{k} ) \right) - \partial_{x} \alpha( \eta_{k} ) \right|
	= & \left| \frac{ \tilde{\eta}_{k+1} + \tilde{\eta}_{k-1}}{2}\delta_{k}^{\langle 1 \rangle}\tilde{\eta}_{k} - \eta_{k} \partial_{x} \eta_{k} \right| \\
	\leq & \left|\frac{ \tilde{\eta}_{k+1} + \tilde{\eta}_{k-1}}{2} - \eta_{k}\right| \left|\delta_{k}^{\langle 1 \rangle}\tilde{\eta}_{k} \right| 
	+ \left|\eta_{k}\right| \left|\delta_{k}^{\langle 1 \rangle}\tilde{\eta}_{k} - \partial_{x} \eta_{k}\right| \\ 
	\leq & C\left(
		\left|\frac{\tilde{\eta}_{k+1} + \tilde{\eta}_{k-1}}{2} - \eta_{k}\right| 
		+ \left|\delta_{k}^{\langle 1 \rangle}\tilde{\eta}_{k} - \partial_{x} \eta_{k}\right|
		\right) 
		\quad (k=0, \ldots, K). 
\end{align*}
Additionally, substituting $t=(j + 1)\Delta t$ in \eqref{eta_avg} and using (A2), we get
\begin{equation*}
	\left|\frac{\tilde{\eta}_{k+1} + \tilde{\eta}_{k-1}}{2} - \eta_{k}\right| 
	\leq \frac{(\Delta x)^{2}}{4}\left( \left|\partial_{x}^{2} \tilde{\eta}_{k + r_{1} }\right| + \left|\partial_{x}^{2} \tilde{\eta}_{k - r_{1} }\right| \right) 
	\leq C(\Delta x)^{2} \quad (k=0, \ldots, K). %\label{eta_avg1}
\end{equation*}
On another note, for $k=0, \ldots, K$, applying the Taylor theorem to $\tilde{\eta}$, there exists $r_{2} \in (0,1)$ such that 
\begin{equation*}
	\frac{\tilde{\eta}_{k+1} - \tilde{\eta}_{k-1}}{2\Delta x} - \partial_{x}\tilde{\eta}_{k} 
	= \frac{\Delta x}{4}\left( \partial_{x}^{2} \tilde{\eta}_{k + r_{2} } - \partial_{x}^{2} \tilde{\eta}_{k - r_{2} } \right) \quad (k=0, \ldots, K). %\label{eta_avg3}
\end{equation*}
Namely, we see from the definition of $\tilde{\eta}$ and (A2) that 
\begin{align*}
	\left|\delta_{k}^{\langle 1 \rangle}\tilde{\eta}_{k} - \partial_{x} \eta_{k}\right| 
	= \left|\frac{\tilde{\eta}_{k+1} - \tilde{\eta}_{k-1}}{2\Delta x} - \partial_{x}\tilde{\eta}_{k}\right| 
	\leq & \frac{\Delta x}{4}\left( \left|\partial_{x}^{2} \tilde{\eta}_{k + r_{2} } \right|
	+ \left|\partial_{x}^{2} \tilde{\eta}_{k - r_{2} }\right| \right) \\
	\leq & C\Delta x \quad (k=0, \ldots, K). 
\end{align*}
As a result, we have 
\begin{equation*}
	\left| \delta_{k}^{\langle 1 \rangle}\!\left( \alpha( \tilde{\eta}_{k} ) \right) - \partial_{x} \alpha( \eta_{k} ) \right| 
	\leq C\left( \Delta x + (\Delta x)^{2} \right) \quad (k=0, \ldots, K). 
\end{equation*}
Next, we consider the following difference:  
\begin{align*}
& \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) - 2\gamma_{\varepsilon}'(\partial_{x}\theta_{k}) \\
	% = & \frac{\delta_{k}^{+}\theta_{k}^{(j+1)}}{ \mo{\gamma_{\varepsilon}}(\delta_{k}^{+}\theta_{k}^{(j+1)}) }
	%  + \frac{\delta_{k}^{-}\theta_{k}^{(j+1)}}{ \mo{\gamma_{\varepsilon}}(\delta_{k}^{-}\theta_{k}^{(j+1)}) }
	%  - \frac{2\partial_{x}\theta_{k}^{(j+1)}}{ \mo{\gamma_{\varepsilon}}(\partial_{x}\theta_{k}^{(j+1)}) } \\
	= & \frac{\delta_{k}^{+}\tilde{\theta}_{k}}{ \gamma_{\varepsilon}(\delta_{k}^{+}\tilde{\theta}_{k}) }
	 - \frac{\partial_{x}\theta_{k}}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) }
	 + \frac{\delta_{k}^{-}\tilde{\theta}_{k}}{ \gamma_{\varepsilon}(\delta_{k}^{-}\tilde{\theta}_{k}) }
	 - \frac{\partial_{x}\theta_{k}}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } \\
	= & \frac{\delta_{k}^{+}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}}{ \gamma_{\varepsilon}(\delta_{k}^{+}\tilde{\theta}_{k}) } \! + \! \partial_{x}\theta_{k} \! \left(\! \frac{1}{ \gamma_{\varepsilon}(\delta_{k}^{+}\tilde{\theta}_{k}) } \! - \! \frac{1}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } \!\right) \\
	& + \frac{\delta_{k}^{-}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}}{ \gamma_{\varepsilon}(\delta_{k}^{-}\tilde{\theta}_{k}) } \! + \! \partial_{x}\theta_{k} \! \left(\! \frac{1}{ \gamma_{\varepsilon}(\delta_{k}^{-}\tilde{\theta}_{k}) } \! - \! \frac{1}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } \!\right) \quad (k=0, \ldots, K). 
\end{align*}
By direct calculation, we see that 
\begin{align*}
	\frac{1}{ \gamma_{\varepsilon}(\delta_{k}^{\ast}\tilde{\theta}_{k}) } - \frac{1}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } 
	= & \frac{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) - \gamma_{\varepsilon}(\delta_{k}^{\ast}\tilde{\theta}_{k}) }{ \gamma_{\varepsilon}(\delta_{k}^{\ast}\tilde{\theta}_{k}) \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } \\
	= & \frac{ \left(\gamma_{\varepsilon}(\partial_{x}\theta_{k}) \right)^{2} - \left(\gamma_{\varepsilon}(\delta_{k}^{\ast}\tilde{\theta}_{k}) \right)^{2} }{ \gamma_{\varepsilon}(\delta_{k}^{\ast}\tilde{\theta}_{k}) \gamma_{\varepsilon}(\partial_{x}\theta_{k}) \left(\gamma_{\varepsilon}(\partial_{x}\theta_{k}) + \gamma_{\varepsilon}(\delta_{k}^{\ast}\tilde{\theta}_{k})\right) } \\
	= & \frac{ \partial_{x}\theta_{k} + \delta_{k}^{\ast}\tilde{\theta}_{k} }{ \gamma_{\varepsilon}(\delta_{k}^{\ast}\tilde{\theta}_{k}) \gamma_{\varepsilon}(\partial_{x}\theta_{k}) \left(\gamma_{\varepsilon}(\partial_{x}\theta_{k}) \! + \! \gamma_{\varepsilon}(\delta_{k}^{\ast}\tilde{\theta}_{k})\right) } \left(\partial_{x}\theta_{k} - \delta_{k}^{\ast}\tilde{\theta}_{k}\right)
\end{align*}
for $k=0, \ldots, K$, where the symbol ``$\ast$'' denotes $+$ or $-$. 
From the above, we obtain from (A2) and the inequality $1/\gamma_{\varepsilon}(u) \leq 1/\varepsilon$ that 
\begin{align*}
	& \left|\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) - 2\gamma_{\varepsilon}'(\partial_{x}\theta_{k})\right| \\
	\leq & \frac{ |\delta_{k}^{+}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}| }{ \gamma_{\varepsilon}(\delta_{k}^{+}\tilde{\theta}_{k}) } \! + \! |\partial_{x}\theta_{k}| \! \left| \frac{1}{ \gamma_{\varepsilon}(\delta_{k}^{+}\tilde{\theta}_{k}) } \! - \! \frac{1}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } \right| 
	+ \frac{ |\delta_{k}^{-}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}| }{ \gamma_{\varepsilon}(\delta_{k}^{-}\tilde{\theta}_{k}) } \! + \! |\partial_{x}\theta_{k}| \! \left| \frac{1}{ \gamma_{\varepsilon}(\delta_{k}^{-}\tilde{\theta}_{k}) } \! - \! \frac{1}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } \right| \\
	\leq & \frac{1}{\varepsilon}|\delta_{k}^{+}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}| \! + \! C \left| \frac{1}{ \gamma_{\varepsilon}(\delta_{k}^{+}\tilde{\theta}_{k}) } \! - \! \frac{1}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } \right| 
	+ \frac{1}{\varepsilon}|\delta_{k}^{-}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}| \! + \! C \left| \frac{1}{ \gamma_{\varepsilon}(\delta_{k}^{-}\tilde{\theta}_{k}) } \! - \! \frac{1}{ \gamma_{\varepsilon}(\partial_{x}\theta_{k}) } \right| \\
	\leq & C\left(
		|\delta_{k}^{+}\tilde{\theta}_{k} - \partial_{x}\theta_{k}| 
		+ |\delta_{k}^{-}\tilde{\theta}_{k} - \partial_{x}\theta_{k}|
	\right) \quad (k=0, \ldots, K). 
\end{align*}
Here, 
% for $k=0, \ldots, K$, applying the Taylor theorem to $\theta$, there exists $r_{3} \in (0,1)$ such that 
% \begin{equation*}
% \partial_{x} \theta_{k}^{(j+1)} - \delta_{k}^{-}\theta_{k}^{(j+1)}  
% 	= \frac{\Delta x}{2}\partial_{x}^{2} \theta_{k-r_{3}}^{(j+1)} \quad (k=0, \ldots, K). %\label{et1}
% \end{equation*}
% Likewise, for $k=0, \ldots, K$, applying the Taylor theorem to $\theta$, there exists $r_{4} \in (0,1)$ such that 
% \begin{equation*}
% \partial_{x} \theta_{k}^{(j+1)} - \delta_{k}^{+}\theta_{k}^{(j+1)}  
% 	= - \frac{\Delta x}{2}\partial_{x}^{2} \theta_{k+r_{4}}^{(j+1)} \quad (k=0, \ldots, K). %\label{et1}
% \end{equation*}
applying the Taylor theorem to $\tilde{\theta}$, we see from the definition of $\tilde{\theta}$ and (A2) that 
\begin{equation*}
	\left|\delta_{k}^{+}\tilde{\theta}_{k} - \partial_{x}\theta_{k}\right| 
	\leq C\Delta x \quad (k=0, \ldots, K), \quad 
	\left|\delta_{k}^{-}\tilde{\theta}_{k} - \partial_{x}\theta_{k}\right| 
	\leq C\Delta x \quad (k=0, \ldots, K).
\end{equation*}
Therefore, we have 
\begin{equation*}
	\left|\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) + \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) - 2\gamma_{\varepsilon}'(\partial_{x}\theta_{k})\right|
	\leq C\Delta x \quad (k=0, \ldots, K).
\end{equation*}
From the above, we estimate the first term on the right-hand side of \eqref{xi6_1} as follows: 
\begin{equation*}
	\left|
		\delta_{k}^{\langle 1 \rangle} \! \left( \alpha( \tilde{\eta}_{k} ) \right) 
		\! \left(\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \! + \! \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k})\right) 
		\! - \! 2\partial_{x} \alpha( \eta_{k} ) \gamma_{\varepsilon}'(\partial_{x}\theta_{k})
	\right| 
	\leq C\!\left( \Delta x \! + \! (\Delta x)^{2} \right) \quad (k=0, \ldots, K). 
\end{equation*}
Lastly, we evaluate the second term on the right-hand side of \eqref{xi6_1}. 
By direct calculation, we have 
\begin{align*}
	& \left| \mu_{k}^{+}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\!\delta_{k}^{+}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) 
	+ \mu_{k}^{-}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\!\delta_{k}^{-}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right) 
	- 2\alpha( \eta_{k} )\partial_{x}\gamma_{\varepsilon}'(\partial_{x}\theta_{k}) 
	\right| \\
	\leq & \left|
		\mu_{k}^{+}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\!\delta_{k}^{+}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) 
		- \alpha( \eta_{k} )\partial_{x}\gamma_{\varepsilon}'(\partial_{x}\theta_{k}) 
	\right| \\
	& + \left|
		\mu_{k}^{-}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\!\delta_{k}^{-}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right) 
		- \alpha( \eta_{k} )\partial_{x}\gamma_{\varepsilon}'(\partial_{x}\theta_{k}) 
	\right|
	\quad (k=0, \ldots, K).
\end{align*}
Moreover, we see from (A2), the following inequality: $\gamma_{\varepsilon}''(u) \leq 1/\varepsilon$, and \eqref{diff_f} that 
\begin{align*}
	& \left| \mu_{k}^{+}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\delta_{k}^{+}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) - \alpha( \eta_{k} )\partial_{x}\gamma_{\varepsilon}'(\partial_{x}\theta_{k}) \right| \\
	\leq & \left| \mu_{k}^{+}\!\left( \alpha( \tilde{\eta}_{k} ) \right) \right| 
	\left|\delta_{k}^{+}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) - \partial_{x}\gamma_{\varepsilon}'(\partial_{x}\theta_{k}) \right| 
	+ \left|\mu_{k}^{+}\!\left( \alpha( \tilde{\eta}_{k} ) \right) - \alpha( \eta_{k} )\right| |\partial_{x}\gamma_{\varepsilon}'(\partial_{x}\theta_{k})| \\
	\leq & C \left|
		\frac{d\gamma_{\varepsilon}'}{d(\delta_{k}^{-}\tilde{\theta}_{k+1}, \delta_{k}^{-}\tilde{\theta}_{k})}\delta_{k}^{\langle 2\rangle}\tilde{\theta}_{k}
		- \gamma_{\varepsilon}''(\partial_{x}\theta_{k})\partial_{x}^{2}\theta_{k} 
		\right| 
	+ \frac{1}{4}|\tilde{\eta}_{k+1} + \tilde{\eta}_{k}| |\tilde{\eta}_{k+1} - \tilde{\eta}_{k}| 
	\left|\gamma_{\varepsilon}''(\partial_{x}\theta_{k}) \right| \left|\partial_{x}^{2}\theta_{k} \right| \\
	\leq & C\left(
		\left|\frac{d\gamma_{\varepsilon}'}{d(\delta_{k}^{-}\tilde{\theta}_{k+1}, \delta_{k}^{-}\tilde{\theta}_{k})}\right| 
		\left| \delta_{k}^{\langle 2\rangle}\tilde{\theta}_{k} - \partial_{x}^{2}\theta_{k}\right| 
		+ \left| \frac{d\gamma_{\varepsilon}'}{d(\delta_{k}^{-}\tilde{\theta}_{k+1}, \delta_{k}^{-}\tilde{\theta}_{k})} - \gamma_{\varepsilon}''(\partial_{x}\theta_{k})\right| 
		\left|\partial_{x}^{2}\theta_{k} \right|
	\right) \\
	& + C|\tilde{\eta}_{k+1} - \tilde{\eta}_{k}| \\
	\leq & C\left(
		\left| \delta_{k}^{\langle 2\rangle}\tilde{\theta}_{k} - \partial_{x}^{2}\theta_{k}\right| 
		+ \left| \frac{d\gamma_{\varepsilon}'}{d(\delta_{k}^{-}\tilde{\theta}_{k+1}, \delta_{k}^{-}\tilde{\theta}_{k})} - \gamma_{\varepsilon}''(\partial_{x}\theta_{k})\right| 
		+ |\tilde{\eta}_{k+1} - \tilde{\eta}_{k}| 
	\right) \quad (k=0, \ldots, K).
\end{align*}
Additionally, applying the Taylor theorem to $\tilde{\eta}$, we see from the definition of $\tilde{\eta}$ and (A2) that 
\begin{equation*}
	|\tilde{\eta}_{k + 1} - \tilde{\eta}_{k}| \leq C\Delta x \quad (k=0, \ldots, K). 
\end{equation*}
Furthermore, it holds from Lemma \ref{lem:4.2} that 
\begin{align*}
	\frac{d\gamma_{\varepsilon}'}{d(\delta_{k}^{-}\tilde{\theta}_{k+1}, \delta_{k}^{-}\tilde{\theta}_{k})} \! - \! \gamma_{\varepsilon}''(\partial_{x}\theta_{k}) 
	= & \frac{d\gamma_{\varepsilon}'}{d(\delta_{k}^{-}\tilde{\theta}_{k+1}, \delta_{k}^{-}\tilde{\theta}_{k})} - \frac{d\gamma_{\varepsilon}'}{d(\partial_{x}\theta_{k}, \partial_{x}\theta_{k})} \\
	= & \frac{1}{2}\overline{\gamma_{\varepsilon}'}^{\prime\prime}(\delta_{k}^{-}\tilde{\theta}_{k+1},\partial_{x}\theta_{k}; \delta_{k}^{-}\tilde{\theta}_{k},\partial_{x}\theta_{k})(\delta_{k}^{-}\tilde{\theta}_{k+1} \! - \! \partial_{x}\theta_{k}) \\
	& + \frac{1}{2}\overline{\gamma_{\varepsilon}'}^{\prime\prime}\!(\delta_{k}^{-}\tilde{\theta}_{k},\partial_{x}\theta_{k}; \delta_{k}^{-}\tilde{\theta}_{k+1},\partial_{x}\theta_{k})(\delta_{k}^{-}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}) \\
	= & \frac{1}{2}\overline{\gamma_{\varepsilon}'}^{\prime\prime}(\delta_{k}^{-}\tilde{\theta}_{k+1},\partial_{x}\theta_{k}; \delta_{k}^{-}\tilde{\theta}_{k},\partial_{x}\theta_{k})(\delta_{k}^{+}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}) \\
	& + \frac{1}{2}\overline{\gamma_{\varepsilon}'}^{\prime\prime}\!(\delta_{k}^{-}\tilde{\theta}_{k},\partial_{x}\theta_{k}; \delta_{k}^{-}\tilde{\theta}_{k+1},\partial_{x}\theta_{k})(\delta_{k}^{-}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k})
\end{align*}
for $k=0, \ldots, K$. 
In addition, it follows from Lemma \ref{lem:4.1} that 
\begin{equation*}
	|\overline{\gamma_{\varepsilon}'}^{\prime\prime}(s_{1}, s_{2}; s_{3}, s_{4})| \leq \sup_{s \in \mathbb{R}}|\gamma_{\varepsilon}'''(s)| \quad \mbox{for all} \ s_{1}, s_{2}, s_{3}, s_{4} \in \mathbb{R}.
\end{equation*}
Thus, from the following inequality: 
\begin{equation*}
	|\gamma_{\varepsilon}'''(u)| 
	= \frac{3\varepsilon^{2}|u|}{(\varepsilon^{2} + u^{2})^{\frac{5}{2}}}
	\leq \frac{3\varepsilon^{2}(\varepsilon^{2} + u^{2})^{\frac{1}{2}}}{(\varepsilon^{2} + u^{2})^{\frac{5}{2}}}
	= \frac{3\varepsilon^{2}}{(\varepsilon^{2} + u^{2})^{2}}
	\leq \frac{3\varepsilon^{2}}{\varepsilon^{4}} 
	= \frac{3}{\varepsilon^{2}} \quad \mbox{for all} \ u \in \mathbb{R}, 
\end{equation*}
we obtain 
\begin{equation*}
	\left| \frac{d\gamma_{\varepsilon}'}{d(\delta_{k}^{-}\tilde{\theta}_{k+1}, \delta_{k}^{-}\tilde{\theta}_{k})} \! - \! \gamma_{\varepsilon}''(\partial_{x}\theta_{k})\right| 
	\! \leq \! \frac{3}{2\varepsilon^{2}}\!\left(
		\left|\delta_{k}^{+}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}\right| 
		\! + \! \left|\delta_{k}^{-}\tilde{\theta}_{k} \! - \! \partial_{x}\theta_{k}\right| 
	\right)
	\! \leq \! C\Delta x \quad (k=0, \ldots, K). 
\end{equation*}
From the above, we estimate the second term on the right-hand side of \eqref{xi6_1} as follows: 
\begin{align*}
	& \left| \mu_{k}^{+}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\!\delta_{k}^{+}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{-}\tilde{\theta}_{k}) \right) 
	+ \mu_{k}^{-}\!\left( \alpha( \tilde{\eta}_{k} ) \right)\!\delta_{k}^{-}\!\left(  \gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}) \right) 
	- 2\alpha( \eta_{k} )\partial_{x}\gamma_{\varepsilon}'(\partial_{x}\theta_{k}) 
	\right| \\
	\leq & C\left( (\Delta x)^{\sigma} + \Delta x \right) \quad (k=0, \ldots, K). 
\end{align*}
Therefore, we estimate $\bm{\xi}_{6}^{(j+1)}$ as follows: 
\begin{equation}
	\left|\xi_{6, k}^{(j+1)}\right| \leq C\left( (\Delta x)^{\sigma} + \Delta x + (\Delta x)^{2} \right) \quad (k=0, \ldots, K).
	\label{xi6_est}
\end{equation}
Hence, we obtain from \eqref{xi1_est}, \eqref{xi2_est}, and \eqref{xi3_est} that 
\begin{align*}
	\left\| \bm{\xi}_{1-3}^{(j + 1)} \right\|_{ L_{\rm d}^{2} }^{2} 
	\leq & \left(\left\| \bm{\xi}_{1}^{(j + 1)} \right\|_{ L_{\rm d}^{2} } + \left\| \bm{\xi}_{2}^{(j + 1)} \right\|_{ L_{\rm d}^{2} } + \left\| \bm{\xi}_{3}^{(j + 1)} \right\|_{ L_{\rm d}^{2} } \right)^{2} \\
	\leq & C^{2}\left(
		(\Delta t)^{\sigma} + (\Delta x)^{\sigma} + \Delta t + \Delta x + (\Delta x)^{2}
	\right)^{2} \quad (j = 0,1,\ldots, N - 1), 
\end{align*}
where $\bm{\xi}_{1-3}^{(j + 1)} := \{\xi_{1-3,k}^{(j + 1)}\}_{k=0}^{K} = \bm{\xi}_{1}^{(j + 1)} + \bm{\xi}_{2}^{(j + 1)} + \bm{\xi}_{3}^{(j + 1)} \ \in \mathbb{R}^{K+1}$. 
Similarly, we have from \eqref{xi4_est}, \eqref{xi5_est}, and \eqref{xi6_est} that 
\begin{align*}
	\left\| \bm{\xi}_{4-6}^{(j + 1)} \right\|_{ L_{\rm d}^{2} }^{2} 
	\leq & \left(\left\| \bm{\xi}_{4}^{(j + 1)} \right\|_{ L_{\rm d}^{2} } + \left\| \bm{\xi}_{5}^{(j + 1)} \right\|_{ L_{\rm d}^{2} } + \left\| \bm{\xi}_{6}^{(j + 1)} \right\|_{ L_{\rm d}^{2} } \right)^{2} \\
	\leq & C^{2}\left(
		(\Delta t)^{\sigma} + (\Delta x)^{\sigma} + \Delta t + \Delta x + (\Delta x)^{2}
	\right)^{2} \quad (j = 0,1,\ldots, N - 1), 
\end{align*}
where $\bm{\xi}_{4-6}^{(j + 1)} := \{\xi_{4-6,k}^{(j + 1)}\}_{k=0}^{K} = \bm{\xi}_{4}^{(j + 1)} + \bm{\xi}_{5}^{(j + 1)} + \bm{\xi}_{6}^{(j + 1)} \ \in \mathbb{R}^{K+1}$. 
As a result, we see from the above estimates and Lemma \ref{e_eta_theta_est} that 
\begin{align*}
	\left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} 
	+ \left\| \sqrt{\bm{\alpha_{0}^{(j)}}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} 
	\leq & C\sum_{i=0}^{j-1}\left( \left\| \bm{\xi}_{1-3}^{(j-i)} \right\|_{L_{\rm d}^{2}}^{2} + \left\| \bm{\xi}_{4-6}^{(j-i)} \right\|_{L_{\rm d}^{2}}^{2}\right)\Delta t \\
	\leq & C\left(
		(\Delta t)^{\sigma} + (\Delta x)^{\sigma} + \Delta t + \Delta x + (\Delta x)^{2}
	\right)^{2}\sum_{i=0}^{N-1} \Delta t\\
	= & CT\left(
		(\Delta t)^{\sigma} + (\Delta x)^{\sigma} + \Delta t + \Delta x + (\Delta x)^{2}
	\right)^{2} \quad (j=1,\ldots,N),
\end{align*} 
where $\sqrt{\bm{\alpha_{0}^{(j)}}}\bm{e}_{\theta}^{(j)}$ is defined by \eqref{vec_a_th} in Lemma \ref{e_theta_est}. 
In other words, we conclude that 
\begin{equation*}
	\sqrt{
		\left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} 
		+ \left\| \sqrt{\bm{\alpha_{0}^{(j)}}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2}
	}
	\leq C \left(
		(\Delta t)^{\sigma} + (\Delta x)^{\sigma} + \Delta t + \Delta x + (\Delta x)^{2}
	\right) \quad (j=1,\ldots,N). 
\end{equation*}
Here, since it holds from (A1) that $\alpha_{0} \geq \delta_{0}$, we obtain \eqref{e_err_est} and \eqref{t_err_est}. 

\section{Computation examples}
In this section, we demonstrate through computation examples that the numerical solution of our proposed scheme is efficient and that the scheme inherits the dissipative property from the original problem in a discrete sense. 
To obtain the next time-step for the numerical solutions to our nonlinear scheme, we use the package “NLsolve” in Julia, a computer language used in our numerical computations.

We choose $K = 50$ so that $\Delta x = 1/50$. 
Besides, we fix the parameters $\varepsilon = 0.01$, $\delta_{0} = 0.01$, $\nu = 0.01$, $\kappa_{0} = 0.01$, $c = 1.0$, and $\kappa = 0.1$. 

