\begin{gather*}
  \eta(0,x) = \eta_{0}(x) 
    = \begin{cases}
	A\cosh(x) + 1 & (0 \leq x < 0.5),\\
	B\cosh(x - 1) + 1 & (0.5 \leq x \leq 1),
      \end{cases}\\
      \theta(0,x) = \theta_{0}(x) = 0.5\pi x - 0.25\pi, 
\end{gather*}
where 
\begin{gather*}
	A = B = -\frac{1}{\cosh(0.5)}\frac{|\theta_{2} - \theta_{1}|}{|\theta_{2} - \theta_{1}| + \tanh(0.5) + \tanh(0.5)}, \\
	\theta_{1} = -0.25\pi, \quad \theta_{2} = 0.25\pi.
