Through the above computation examples, the following conjectures can be obtained. 
\begin{description}
	\item[(O)]The following convergences hold:
	\begin{description}
	\item[(i)]$ \eta(t) \to 1 $ in $ L^2(\Omega) $, as $ t \to \infty $,
	\item[(ii)]there exists $ \theta_\infty \in \theta_0(\Omega) $ such that  $ \theta(t) $ converges the constant $ \theta_\infty $, at a finite time.
	\end{description}
	\item[(I)]If $ \eta(t_0) $, at a time $ t_0 \geq 0 $, has two neighboring local minima $ 0 < x_0 < x_1 < 1 $, then $ \theta(t) $, for $ t \geq t_0 $, tends to form a piecewise constant structure around the interval $ (x_0, x_1) $.
	\item[(II)]If $ \eta(t_*) $, at a large time $ t_* \gg 0 $, has a unique local minimum (global minimum) $ x_* \in \Omega $, then $ \theta(t) $, for $t \geq t_* $, tends to a piecewise constant structure, with a single discontinuity point $ x_* $.
\end{description}
Regarding (II), all numerical data generally show a tendency consistent with the conjecture. 
However, in example 3, it should be noted that $\eta$ takes a unique minimum on a (single) closed interval. 
In view of this, it is considered necessary to make the following revision to the conjecture (II). 
\begin{description}
	\item[(II)']If $ \eta(t_*) $, at a large time $ t_* \gg 0 $, has a unique local minimum (global minimum) on a closed interval $ I_* \in \Omega $, then $ \theta(t) $, for $t \geq t_* $, tends to a piecewise constant structure, with a discontinuity point in $ I_* $.
\end{description}

\section{Appendix} 
\subsection{Preparation}

\begin{lem}\label{prod}
	The following product rules hold: 
	\begin{gather*}
		\delta_{k}^{+}(f_{k}g_{k}) = (\delta_{k}^{+}f_{k})(\mu_{k}^{+}g_{k}) + (\mu_{k}^{+}f_{k})(\delta_{k}^{+}g_{k}) \quad (k = 0,\ldots, K), \\
		\delta_{k}^{-}(f_{k}g_{k}) = (\delta_{k}^{-}f_{k})(\mu_{k}^{-}g_{k}) + (\mu_{k}^{-}f_{k})(\delta_{k}^{-}g_{k}) \quad (k = 0,\ldots, K)
	\end{gather*}
	for all $\{f_{k}\}_{k=-1}^{K+1}, \{g_{k}\}_{k=-1}^{K+1} \in \mathbb{R}^{K+3}$. 
\end{lem}

\begin{lem}\label{sbp1}
The following summation by parts formulas hold:
	\begin{equation*}
	\sum_{k=0}^{K}{}^{\prime\prime}f_{k}(\delta_{k}^{+}g_{k})\Delta x + \sum_{k=0}^{K}{}^{\prime\prime}(\delta_{k}^{-}f_{k})g_{k}\Delta x 
	= \left[\frac{ f_{k}g_{k+1} + f_{k-1}g_{k} }{2}\right]_{0}^{K} 
	\end{equation*}
	for all $\{f_{k}\}_{k=-1}^{K+1}, \{g_{k}\}_{k=-1}^{K+1} \in \mathbb{R}^{K+3}$. 
\end{lem}

\begin{lem}\label{sbp2}
	The following summation by parts formulas hold:
	\begin{gather*}
	\sum_{k=0}^{K-1}f_{k}(\delta_{k}^{+}g_{k})\Delta x + \sum_{k=0}^{K}{}^{\prime\prime}(\delta_{k}^{-}f_{k})g_{k}\Delta x 
	= \left[\left(\mu_{k}^{-}f_{k}\right)g_{k} \right]_{0}^{K}, \\
	\sum_{k=1}^{K}f_{k}(\delta_{k}^{-}g_{k})\Delta x + \sum_{k=0}^{K}{}^{\prime\prime}(\delta_{k}^{+}f_{k})g_{k}\Delta x 
	= \left[\left(\mu_{k}^{+}f_{k}\right)g_{k} \right]_{0}^{K} 
	\end{gather*}
	for all $\{f_{k}\}_{k=-1}^{K+1}, \{g_{k}\}_{k=-1}^{K+1} \in \mathbb{R}^{K+3}$. 
\end{lem}


\begin{lem}\label{sbp5}
	The following summation by parts formulas hold:
	\begin{equation*}
	\sum_{k=0}^{K-1}\left(\delta_{k}^{+}f_{k}\right)\left(\delta_{k}^{+}g_{k}\right)\Delta x = -\sum_{k=0}^{K}{}^{\prime\prime}\left(\delta_{k}^{\langle 2 \rangle}f_{k}\right)g_{k}\Delta x + \left[\left(\delta_{k}^{\langle 1 \rangle}f_{k}\right) g_{k}\right]_{0}^{K} 
	\end{equation*}
	for all $\{f_{k}\}_{k=-1}^{K+1}, \{g_{k}\}_{k=-1}^{K+1} \in \mathbb{R}^{K+3}$. 
\end{lem}

\begin{defn}
Let $\Omega$ be a domain in $\mathbb{R}$. 
For a function $F \in C^{2}(\Omega )$, let us define $\bar{F}''$: $\Omega^{4} \to \mathbb{R}$ by 
\begin{numcases}
	{\bar{F}'' (\xi, \tilde{\xi}; \eta, \tilde{\eta}) := \!} 
	\frac{1}{\xi - \tilde{\xi}}\!\left\{\! \left( \frac{dF}{d(\xi, \eta)} + \frac{dF}{d(\xi, \tilde{\eta})} \right) \! - \! \left( \frac{dF}{d(\tilde{\xi}, \eta)} + \frac{dF}{d(\tilde{\xi}, \tilde{\eta})} \right) \!\right\}, & ($\xi \neq \tilde{\xi}$), \nonumber\\
	{\partial}_{\xi} \left. \left( \frac{dF}{d(\xi, \eta)} + \frac{dF}{d(\xi, \tilde{\eta})} \right) \right|_{\xi = \tilde{\xi}} , & ($\xi = \tilde{\xi}$) \nonumber
\end{numcases}
for all $(\xi, \tilde{\xi}, \eta, \tilde{\eta}) \in \Omega^{4}$. 
\end{defn}

\begin{lem}[{\cite[Lemma 2.4]{YOSHIKAWA2017394}}] \label{lem:4.1}
Let $\Omega$ be a domain in $\mathbb{R}$. 
If $F \in C^{2}(\Omega)$, then $\bar{F}'' \in C(\Omega^{4})$. 
Moreover, we have 
\begin{equation*}
\left| \bar{F}'' (\xi, \tilde{\xi}; \eta, \tilde{\eta}) \right| \leq \sup_{\eta, \tilde{\eta} \in \Omega}\sup_{\xi \in \Omega}\left| \frac{\partial}{\partial \xi} \left( \frac{dF}{d(\xi, \eta)} + \frac{dF}{d(\xi, \tilde{\eta})} \right) \right| \leq \sup_{\xi \in \Omega}\left| F'' (\xi) \right| 
\quad \mbox{for all}\ \xi, \tilde{\xi}, \eta, \tilde{\eta} \in \Omega.
\end{equation*} 
\end{lem}

\begin{lem}[{\cite[Proposition 2.5]{YOSHIKAWA2017394}}] \label{lem:4.2}
Let $\Omega$ be a domain in $\mathbb{R}$ and assume that $F \in C^{2}(\Omega)$. For all $\xi$, $\tilde{\xi}$, $\eta$ and $\tilde{\eta} \in \Omega$, we have
\begin{equation*}
\frac{dF}{d(\xi, \eta)} - \frac{dF}{d(\tilde{\xi}, \tilde{\eta})} = \frac{1}{2}\bar{F}'' (\xi, \tilde{\xi}; \eta, \tilde{\eta})(\xi - \tilde{\xi}) + \frac{1}{2}\bar{F}'' (\eta, \tilde{\eta}; \xi, \tilde{\xi})(\eta - \tilde{\eta}). 
\end{equation*}
\end{lem}

\subsection{Auxiliary lemmas}

\begin{lem}\label{e_eq}
Let us assume (A1) and (A2). 
Then, we obtain the following equations on the errors: 
\begin{gather}
	\begin{split}
	\frac{e_{\eta,k}^{(j+1)} - e_{\eta,k}^{(j)}}{\Delta t} 
		= & \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}e_{\eta,k}^{(j+1)} - c e_{\eta,k}^{(j+1)} \\
		& - \frac{\kappa H_{k}^{(j+1)}}{2}\left( \frac{ d\gamma_{\varepsilon}} { d(\delta_{k}^{+}\Theta_{k}^{(j)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{+}e_{\theta,k}^{(j)} + \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{-}\Theta_{k}^{(j)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{-}e_{\theta,k}^{(j)} \!\right) \\
		& - \! \kappa e_{\eta,k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}\bigr) \! + \! \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}\bigr) }{2} \! + \! \xi_{1-3, k}^{(j+1)} \quad (k = 0,\ldots, K,\ j = 0,\ldots, N \! - \! 1), 
	\end{split} \label{e_eta_eq}
\end{gather}
\begin{gather}
	\begin{split}
	& \alpha_{0,k}^{(j+1)}\frac{e_{\theta,k}^{(j+1)} - e_{\theta,k}^{(j)} }{\Delta t} \\
		= & \frac{\kappa}{2}
		\left[\delta_{k}^{+}
			\left\{
				\frac{H_{k}^{(j+1)} + \eta_{k}^{(j+1)}}{2} \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)})e_{\eta,k}^{(j+1)} 
				+ \alpha\left( \eta_{k}^{(j+1)} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{-}\Theta_{k}^{(j+1)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j+1)}) }\delta_{k}^{-}e_{\theta,k}^{(j+1)}
			\right\} \right.\\
		& \left. + \delta_{k}^{-}
			\left\{
				\frac{H_{k}^{(j+1)} + \eta_{k}^{(j+1)}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)})e_{\eta,k}^{(j+1)} 
				+ \alpha\left( \eta_{k}^{(j+1)} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}^{(j+1)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j+1)}) }\delta_{k}^{+}e_{\theta,k}^{(j+1)}
			\right\}
		\right] \\
		& + \nu^{2}\delta_{k}^{\langle 2 \rangle}e_{\theta,k}^{(j+1)} + \xi_{4-6, k}^{(j+1)} \quad (k = 0,\ldots, K,\ j = 0,\ldots, N \! - \! 1), 
	\end{split} \label{e_theta_eq}\\
	\delta_{k}^{\langle 1 \rangle}e_{\eta,k}^{(j)} = 0 \quad (k=0,K,\ j=0,\ldots, N), \label{e_eta_nbc}\\
	\delta_{k}^{\langle 1 \rangle}e_{\theta,k}^{(j)} = 0 \quad (k=0,K,\ j=0,\ldots, N), \label{e_theta_nbc}
\end{gather}
where $\xi_{1-3}$ and $\xi_{4-6}$ are defined as follows: 
\begin{gather}
	\xi_{1-3, k}^{(j+1)} := \sum_{i=1}^{3}\xi_{i, k}^{(j+1)} \quad (k=0, \ldots, K), \notag\\
	\xi_{1, k}^{(j+1)} := \partial_{t}\eta_{k}^{( j + 1)} - \frac{\eta_{k}^{(j+1)} - \eta_{k}^{(j)}}{\Delta t} \quad (k=0, \ldots, K), \label{xi1}\\
	\xi_{2, k}^{(j+1)} := \kappa_{0}^{2}\left( \delta_{k}^{\langle 2 \rangle}\tilde{\eta}_{k}^{(j+1)} - \partial_{x}^{2}\eta_{k}^{( j + 1)} \right) \quad (k=0, \ldots, K), \label{xi2}\\
	\xi_{3, k}^{(j+1)} := - \kappa \eta_{k}^{(j+1)}\left(\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}\bigr) }{2} - \gamma_{\varepsilon}\bigl( \partial_{x}\theta_{k}^{(j+1)}\bigr) \right) \quad (k=0, \ldots, K), \label{xi3}\\
	\xi_{4-6, k}^{(j+1)} := \sum_{i=4}^{6}\xi_{i, k}^{(j+1)} \quad (k=0, \ldots, K), \notag\\
	\xi_{4, k}^{(j+1)} := - \alpha_{0,k}^{(j+1)}\left(\frac{ \theta_{k}^{(j+1)} - \theta_{k}^{(j)} }{\Delta t} - \partial_{t}\theta_{k}^{(j+1)}\right) \quad (k=0, \ldots, K), \label{xi4}\\
	\xi_{5, k}^{(j+1)} := \nu^{2}\left(\delta_{k}^{\langle 2 \rangle}\tilde{\theta}_{k}^{(j+1)} - \partial_{x}^{2}\theta_{k}^{( j + 1)}\right) \quad (k=0, \ldots, K), \label{xi5}\\
	\begin{split}
	\xi_{6, k}^{(j+1)} 
		& := \frac{\kappa}{2}\left\{ \delta_{k}^{+}\!\left( \alpha\!\left( \tilde{\eta}_{k}^{(j+1)} \right)\!\gamma_{\varepsilon}' (\delta_{k}^{-}\tilde{\theta}_{k}^{(j+1)}) \right) + \delta_{k}^{-}\!\left( \alpha\!\left( \tilde{\eta}_{k}^{(j+1)} \right)\!\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}^{(j+1)})\right) \right\} \\
		& \quad - \kappa\partial_{x}\!\left( \alpha( \eta_{k}^{(j+1)} ) \gamma_{\varepsilon}'(\partial_{x}\theta_{k}^{(j+1)}) \right) \quad (k=0, \ldots, K).
	\end{split} \label{xi6}
\end{gather}
\end{lem}

\begin{proof}
	For any fixed $j=0,1,\ldots, N-1$, from the definition of $\bm{e}_{\eta}$, we have 
	\begin{align*}
	\frac{e_{\eta,k}^{(j+1)} - e_{\eta,k}^{(j)}}{\Delta t} 
		& = \frac{H_{k}^{(j+1)} - H_{k}^{(j)}}{\Delta t} - \frac{\eta_{k}^{(j+1)} - \eta_{k}^{(j)}}{\Delta t} \nonumber\\
		& = \frac{H_{k}^{(j+1)} - H_{k}^{(j)}}{\Delta t} - \partial_{t}\eta_{k}^{( j + 1)} + \partial_{t}\eta_{k}^{( j + 1)} - \frac{\eta_{k}^{(j+1)} - \eta_{k}^{(n)}}{\Delta t} \nonumber\\
		& = \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}H_{k}^{(j+1)} - c( H_{k}^{(j+1)} - 1) - \kappa H_{k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr)  }{2} \nonumber\\
		& \quad  - \kappa_{0}^{2}\partial_{x}^{2}\eta_{k}^{( j + 1)} + c (\eta_{k}^{( j + 1)} - 1) + \kappa \eta_{k}^{( j + 1)} \gamma_{\varepsilon}\bigl( \partial_{x}\theta_{k}^{(j+1)}\bigr) 
		+ \xi_{1, k}^{(j+1)}. 
	\end{align*}
	Moreover, by direct calculation, we check that 
	\begin{gather*}
		c(H_{k}^{(j+1)} - 1) - c(\eta_{k}^{( j + 1)} - 1) = ce_{\eta,k}^{(j+1)} \quad (k=0, \ldots, K), \\
		\kappa_{0}^{2}(\delta_{k}^{\langle 2 \rangle}H_{k}^{(j+1)} - \partial_{x}^{2}\eta_{k}^{( j + 1)})
		= \kappa_{0}^{2}\left\{\delta_{k}^{\langle 2 \rangle}( e_{\eta,k}^{(j+1)} + \tilde{\eta}_{k}^{(j+1)} ) - \partial_{x}^{2}\eta_{k}^{( j + 1)} \right\} 
		= \kappa_{0}^{2}\delta_{k}^{\langle 2 \rangle}e_{\eta,k}^{(j+1)} + \xi_{2, k}^{(j+1)} 
	\end{gather*}
	for $k=0, \ldots, K$. 
	Furthermore, it follows from the property of the difference quotient that 
	\begin{align*}
		& \kappa\left\{ H_{k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr) }{2} - \eta_{k}^{( j + 1)} \gamma_{\varepsilon}\bigl( \partial_{x}\theta_{k}^{(j+1)}\bigr) \right\} \\
		= & \kappa\left\{  H_{k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr) }{2} - \eta_{k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}\bigr) }{2} \right. \\
		& \left. + \eta_{k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}\bigr) }{2} - \eta_{k}^{( j + 1)} \gamma_{\varepsilon}\bigl( \partial_{x}\theta_{k}^{(j+1)}\bigr) \right\} \\
		= & \kappa H_{k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{k}^{(j)}\bigr) - \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}\bigr) - \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}\bigr) }{2} \\
		& + \kappa \left(H_{k}^{(j+1)} - \eta_{k}^{(j+1)}\right)\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}\bigr) }{2} - \xi_{3, k}^{(j+1)} \\
		= & \kappa\frac{H_{k}^{(j+1)}}{2}\left( \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{+}\Theta_{k}^{(j)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{+}e_{\theta,k}^{(j)} + \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{-}\Theta_{k}^{(j)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{-}e_{\theta,k}^{(j)} \right) \\
		& + \kappa e_{\eta,k}^{(j+1)}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}\bigr) }{2} - \xi_{3, k}^{(j+1)} \quad (k=0, \ldots, K). 
	\end{align*}
	From the above, we obtain \eqref{e_eta_eq}. 
	Similarly, from the definition of $\bm{e}_{\theta}$, we have 
	\begin{gather*}
		\alpha_{0,k}^{(j+1)}\frac{\Theta_{k}^{(j+1)} - \Theta_{k}^{(j)} }{\Delta t} - \alpha_{0,k}^{(j+1)} \partial_{t}\theta_{k}^{(j+1)} 
		= \alpha_{0,k}^{(j+1)}\frac{e_{\theta,k}^{(j+1)} - e_{\theta,k}^{(j)} }{\Delta t} - \xi_{4, k}^{(j+1)} \quad (k=0, \ldots, K), \\ 
		\nu^{2}( \delta_{k}^{\langle 2 \rangle}\Theta_{k}^{(j+1)} - \partial_{x}^{2}\theta_{k}^{( j + 1)} )
		= \nu^{2}\delta_{k}^{\langle 2 \rangle}e_{\theta,k}^{(j+1)} + \xi_{5, k}^{(j+1)} \quad (k=0, \ldots, K). 
	\end{gather*}
	In addition, by direct calculation, we see that 
	\begin{align*}
	& \frac{\kappa}{2}\!\left\{\! \delta_{k}^{+}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1)} \!\right)\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \!\right) \! + \! \delta_{k}^{-}\!\left(\! \alpha\!\left(\! H_{k}^{(j+1)} \!\right)\! \gamma_{\varepsilon}'(\delta_{k}^{+}\Theta_{k}^{(j+1)}) \!\right) \!\right\}
	\!\! - \! \kappa\partial_{x}\!\!\left(\! \alpha( \eta_{k}^{(j+1)} ) \gamma_{\varepsilon}'(\partial_{x}\theta_{k}^{(j+1)}) \!\right) \\
		= & \frac{\kappa}{2}\left\{ \delta_{k}^{+}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) \right) + \delta_{k}^{-}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}'(\delta_{k}^{+}\Theta_{k}^{(j+1)})\right) \right\} \\
		& - \frac{\kappa}{2}\left\{ \delta_{k}^{+}\left( \alpha\left( \tilde{\eta}_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\tilde{\theta}_{k}^{(j+1)}) \right) + \delta_{k}^{-}\left( \alpha\left( \tilde{\eta}_{k}^{(j+1)} \right)\gamma_{\varepsilon}'(\delta_{k}^{+}\tilde{\theta}_{k}^{(j+1)})\right) \right\} + \xi_{6, k}^{(j+1)} \\
		= & \frac{\kappa}{2}
		\left[\delta_{k}^{+}\!
		\left\{
			\left(\! \alpha\!\left(\! H_{k}^{(j+1)} \!\right) \! - \! \alpha\!\left(\! \tilde{\eta}_{k}^{(j+1)} \!\right) \right)\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) 
			+ \alpha\!\left(\! \tilde{\eta}_{k}^{(j+1)} \!\right) \! \left(\! \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)}) - \gamma_{\varepsilon}' (\delta_{k}^{-}\tilde{\theta}_{k}^{(j+1)}) \!\right)
		\right\} \right.\\
		& \left. + \delta_{k}^{-}\!
		\left\{
			\left(\! \alpha\!\left(\! H_{k}^{(j+1)} \!\right) \! - \! \alpha\!\left(\! \tilde{\eta}_{k}^{(j+1)} \!\right) \right)\! \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) 
			+ \alpha\!\left(\! \tilde{\eta}_{k}^{(j+1)} \!\right) \! \left(\! \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\tilde{\theta}_{k}^{(j+1)}) \!\right)
		\right\}
		\right] \\
		& + \xi_{6, k}^{(j+1)}
	\end{align*}
	\begin{align*}
			= & \frac{\kappa}{2}
			\left[\delta_{k}^{+}
			\left\{
				\frac{H_{k}^{(j+1)} + \tilde{\eta}_{k}^{(j+1)}}{2} \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}^{(j+1)})e_{\eta,k}^{(j+1)} 
				+ \alpha\left( \tilde{\eta}_{k}^{(j+1)} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{-}\Theta_{k}^{(j+1)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j+1)}) }\delta_{k}^{-}e_{\theta,k}^{(j+1)}
			\right\} \right.\\
			& \left. + \delta_{k}^{-}
			\left\{
				\frac{H_{k}^{(j+1)} + \tilde{\eta}_{k}^{(j+1)}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}^{(j+1)})e_{\eta,k}^{(j+1)} 
				+ \alpha\left( \tilde{\eta}_{k}^{(j+1)} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}^{(j+1)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j+1)}) }\delta_{k}^{+}e_{\theta,k}^{(j+1)}
			\right\}
			\right] \\
			& + \xi_{6, k}^{(j+1)} \quad (k=0, \ldots, K). 
	\end{align*}
	From the above, we obtain \eqref{e_theta_eq}. 
	Lastly, it holds from the definitions of $\bm{e}_{\eta}$ and $\bm{e}_{\theta}$, \eqref{bc1}, \eqref{bc2}, and the definitions of $\tilde{\eta}$ and $\tilde{\theta}$ that 
	\begin{gather*}
		0 = \delta_{k}^{\langle 1 \rangle}H_{k}^{(j)} 
		= \delta_{k}^{\langle 1 \rangle}\!\left(\! e_{\eta,k}^{(j)} + \tilde{\eta}_{k}^{( j )} \!\right) 
		= \delta_{k}^{\langle 1 \rangle}e_{\eta,k}^{(j)} + \delta_{k}^{\langle 1 \rangle}\tilde{\eta}_{k}^{( j )} 
		= \delta_{k}^{\langle 1 \rangle}e_{\eta,k}^{(j)} \quad (k=0,K,\ j=0,1,\ldots, N), \\
		0 = \delta_{k}^{\langle 1 \rangle}\Theta_{k}^{(j)} 
		= \delta_{k}^{\langle 1 \rangle}\!\left( e_{\theta,k}^{(j)} + \tilde{\theta}_{k}^{( j )}\right) 
		= \delta_{k}^{\langle 1 \rangle}e_{\theta,k}^{(j)} + \delta_{k}^{\langle 1 \rangle}\tilde{\theta}_{k}^{( j )} 
		= \delta_{k}^{\langle 1 \rangle}e_{\theta,k}^{(j)} \quad (k=0,K,\ j=0,1,\ldots, N). 
	\end{gather*}
\end{proof}

\begin{lem}\label{e_eta_est}
Denotes the bounds by 
\begin{equation}
	\max_{0 \leq j \leq N}\left\{ \left\| \bm{H}^{(j)}\right\|_{L_{\rm d}^{\infty}}, \left\| \bm{\eta}^{(j)}\right\|_{L_{\rm d}^{\infty}}  \right\} \leq C_{1}, \label{eta_bound}
\end{equation}
where $\bm{\eta}^{(j)} := \{\eta_{k}^{(j)}\}_{k = 0}^{K} = \{\eta(j\Delta t, k\Delta x)\}_{k = 0}^{K} \in \mathbb{R}^{K+1}$.
Then, the following inequality holds:
\begin{align}
	\frac{1}{2\Delta t}\left( \left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} - \left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} \right)
	\leq & \left\{ \frac{1}{2}\left(\frac{\kappa C_{1} }{\nu}\right)^{2} - \left(\kappa\varepsilon + \frac{c}{2}\right)\right\} \left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} \notag\\
	& + \frac{\nu^{2} }{2}\left\| D\bm{e}_{\theta}^{(j)} \right\|^{2} + \frac{1}{2c}\left\| \bm{\xi}_{1-3}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2} \quad (j = 0,\ldots, N-1). \label{err_eta_est2}
\end{align}
\end{lem}

\begin{proof}
	Let us fix $j=0,1,\ldots, N-1$. 
	Also, let us multiply both sides of \eqref{e_eta_eq} by $e_{\eta,k}^{(j+1)}$ and sum each of the resulting equality over $k = 0,1, \ldots, K$. 
	Then, by using \eqref{tool_ineq}, we can estimate the left-hand side of the resulting equality as follows:
	\begin{align*}
	\sum_{k=0}^{K}{}^{\prime\prime}\frac{e_{\eta,k}^{(j+1)} - e_{\eta,k}^{(j)} }{\Delta t} e_{\eta,k}^{(j+1)}\Delta x
		& \geq \frac{1}{2\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left| e_{\eta,k}^{(j+1)} \right|^{2}\Delta x
		- \frac{1}{2\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left| e_{\eta,k}^{(j)} \right|^{2}\Delta x \\
		& = \frac{1}{2\Delta t}\left( \left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} - \left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} \right). 
	\end{align*} 
	Next, we estimate the right-hand side of the resulting equality. 
	It follows from \eqref{e_eta_nbc} and the summation by parts formula (Lemma \ref{sbp5}) that 
	\begin{align*}
	\kappa_{0}^{2}\sum_{k=0}^{K}\!{}^{\prime\prime}\!\left(\! \delta_{k}^{\langle 2 \rangle}e_{\eta,k}^{(j+1)} \!\right)\! e_{\eta,k}^{(j+1)} \! \Delta x
		= & - \kappa_{0}^{2}\sum_{k=0}^{K-1}\!\left| \delta_{k}^{+}e_{\eta,k}^{(j+1)} \right|^{2} \! \Delta x
		+ \kappa_{0}^{2}\left[ \left(\! \delta_{k}^{\langle 1 \rangle}e_{\eta,k}^{(j+1)} \!\right)\! e_{\eta,k}^{(j+1)} \right]_{0}^{K} \\
		= & - \kappa_{0}^{2}\!\left\| D\bm{e}_{\eta}^{(j+1)} \right\|^{2}. 
	\end{align*}
	From the definition of the discrete $L^{2}$-norm, we see that 
	\begin{equation*}
	- c\sum_{k=0}^{K}{}^{\prime\prime}\left| e_{\eta,k}^{(j+1)} \right|^{2} \Delta x
		= - c \left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}. 
	\end{equation*}
	Furthermore, it holds from the inequality $\gamma_{\varepsilon}(u) = \sqrt{\varepsilon^{2} + u^{2}} \geq \varepsilon$ that 
	\begin{equation*}
	-\kappa\sum_{k=0}^{K}{}^{\prime\prime}\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}\bigr) + \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}\bigr) }{2}\left| e_{\eta,k}^{(j+1)} \right|^{2} \Delta x
		\leq -\kappa\varepsilon\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}. 
	\end{equation*}
	By using \eqref{eta_bound} and the Young inequality, we have 
	\begin{align*}
	& -\frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}H_{k}^{(j+1)}\left( \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{+}\Theta_{k}^{(j)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{+}e_{\theta,k}^{(j)} + \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{-}\Theta_{k}^{(j)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{-}e_{\theta,k}^{(j)} \right) e_{\eta,k}^{(j+1)}\Delta x \\
		\leq & \frac{\kappa C_{1}}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left| \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{+}\Theta_{k}^{(j)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{+}e_{\theta,k}^{(j)} + \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{-}\Theta_{k}^{(j)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{-}e_{\theta,k}^{(j)} \right| \left| e_{\eta,k}^{(j+1)} \right| \Delta x \\
		\leq & \frac{\kappa C_{1}}{2} \cdot \frac{\kappa C_{1}}{\nu^{2}}\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2} \\
		& + \frac{\kappa C_{1}}{2} \cdot \frac{\nu^{2}}{4\kappa C_{1}}\sum_{k=0}^{K}{}^{\prime\prime}\left| \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{+}\Theta_{k}^{(j)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{+}e_{\theta,k}^{(j)} + \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{-}\Theta_{k}^{(j)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{-}e_{\theta,k}^{(j)} \right|^{2} \Delta x \\
		\leq & \frac{1}{2}\left( \frac{\kappa C_{1}}{\nu}\right)^{2}\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2} \\
		& + \frac{\nu^{2}}{4}\sum_{k=0}^{K}{}^{\prime\prime}\left( \left| \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{+}\Theta_{k}^{(j)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}) }\right|^{2} \left|\delta_{k}^{+}e_{\theta,k}^{(j)}\right|^{2} + \left|\frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{-}\Theta_{k}^{(j)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}) }\right|^{2} \left|\delta_{k}^{-}e_{\theta,k}^{(j)} \right|^{2} \right)\Delta x. 
	\end{align*}
	From \eqref{diff_f} and \eqref{e_theta_nbc}, we observe that 
	\begin{align*}
	& -\frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}H_{k}^{(j+1)}\left( \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{+}\Theta_{k}^{(j)}, \delta_{k}^{+}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{+}e_{\theta,k}^{(j)} + \frac{ d\gamma_{\varepsilon} }{ d(\delta_{k}^{-}\Theta_{k}^{(j)}, \delta_{k}^{-}\tilde{\theta}_{k}^{(j)}) }\delta_{k}^{-}e_{\theta,k}^{(j)} \right) e_{\eta,k}^{(j+1)}\Delta x \\
		\leq & \frac{1}{2}\left( \frac{\kappa C_{1}}{\nu}\right)^{2}\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}
		+ \frac{\nu^{2}}{2}\sum_{k=0}^{K}{}^{\prime\prime}\frac{ \left|\delta_{k}^{+}e_{\theta,k}^{(j)}\right|^{2} + \left|\delta_{k}^{-}e_{\theta,k}^{(j)} \right|^{2} }{2}\Delta x \\
		= & \frac{1}{2}\left( \frac{\kappa C_{1}}{\nu}\right)^{2}\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}
		+ \frac{\nu^{2}}{2}\left\| D\bm{e}_{\theta}^{(j)} \right\|^{2}. 
	\end{align*}
	Again from the Young inequality, we get 
	\begin{equation*}
	\sum_{k=0}^{K}{}^{\prime\prime}\xi_{1-3, k}^{(j+1)} e_{\eta,k}^{(j+1)}\Delta x
		\leq \frac{1}{2c}\left\| \bm{\xi}_{1-3}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2} + \frac{c}{2}\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}.
	\end{equation*}
	From the above, we obtain 
	\begin{align*}
	& \frac{1}{2\Delta t}\left( \left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} - \left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} \right) \\
		\leq & - \kappa_{0}^{2}\left\| D\bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2} - c \left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}
		- \kappa\varepsilon\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2} 
		+ \frac{1}{2} \left( \frac{\kappa C_{1}}{\nu} \right)^{2}\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2} \\
		& + \frac{\nu^{2}}{2}\left\| D\bm{e}_{\theta}^{(j)} \right\|^{2} 
		+\frac{1}{2c}\left\| \bm{\xi}_{1-3}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2} + \frac{c}{2}\left\| \bm{e}_{\eta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2} \\
		\leq & \left\{ \frac{1}{2}\left(\frac{\kappa C_{1} }{\nu}\right)^{2} - \left(\kappa\varepsilon + \frac{c}{2}\right)\right\} \left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2}  
		+ \frac{\nu^{2} }{2}\left\| D\bm{e}_{\theta}^{(j)} \right\|^{2} + \frac{1}{2c}\left\| \bm{\xi}_{1-3}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2}. 
	\end{align*}
\end{proof}

\begin{lem}\label{e_theta_est}
    Let us define $\tilde{L}_{\alpha_{0}} := L_{\alpha_{0}} + 1 > 0$ with the Lipschitz constant $ L_{\alpha_0} $ of $ \alpha_0 $. 
Then, the following inequality holds:	
\begin{align}
	& \frac{1}{2\Delta t}\left( \left\| \sqrt{\bm{\alpha_{0}}^{(j+1)}}\bm{e}_{\theta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} - \left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} \right) + \frac{\nu^{2}}{2}\left\| D\bm{e}_{\theta}^{(j+1)}\right\|^{2} \notag\\
		\leq &\frac{\tilde{L}_{\alpha_{0}}}{2\delta_{0} } \left\| \sqrt{\bm{\alpha_{0}}^{(j+1)}}\bm{e}_{\theta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{\tilde{L}_{\alpha_{0}}}{2\delta_{0} } \left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{1}{2}\left( \frac{\kappa C_{1} }{\nu} \right)^{2}\left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{1}{2\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}  \label{err_theta_est2}
\end{align}
	for $j = 0,\ldots, N-1$, where we use the following vector notation: 
	\begin{equation}
		\sqrt{\bm{\alpha_{0}}^{(j+1)}}\bm{e}_{\theta}^{(j+1)} := \left\{ \sqrt{\alpha_{0,k}^{(j+1)}}e_{\theta,k}^{(j+1)} \right\}_{k = 0}^{K} \quad \in \mathbb{R}^{K+1}. \label{vec_a_th}
	\end{equation}
\end{lem}

\begin{proof}
	Let us fix $j=0,1,\ldots, N-1$. 
	Also, let us multiply both sides of \eqref{e_theta_eq} by $e_{\theta,k}^{(j+1)}$ and sum each of the resulting equality over $k = 0,1, \ldots, K$. 
	Then, by using \eqref{tool_ineq}, we can estimate the left-hand side of the resulting equality as follows:
	\begin{align*}
	& \sum_{k=0}^{K}{}^{\prime\prime}\alpha_{0,k}^{(j+1)}\frac{e_{\theta,k}^{(j+1)} - e_{\theta,k}^{(j)} }{\Delta t} e_{\theta,k}^{(j+1)}\Delta x \\
		\geq & \frac{1}{2\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\alpha_{0,k}^{(j+1)}\left( \left| e_{\theta,k}^{(j+1)} \right|^{2} - \left| e_{\theta,k}^{(j)} \right|^{2} \right) \Delta x \\
		= & \frac{1}{2\Delta t}\sum_{k=0}^{K}{}^{\prime\prime}\left( 
			\alpha_{0,k}^{(j+1)} \left| e_{\theta,k}^{(j+1)} \right|^{2} 
			- \alpha_{0,k}^{(j+1)} \left| e_{\theta,k}^{(j)} \right|^{2} 
			+ \alpha_{0,k}^{(j)} \left| e_{\theta,k}^{(j)} \right|^{2}  
			- \alpha_{0,k}^{(j)} \left| e_{\theta,k}^{(j)} \right|^{2} 
		\right) \Delta x \\
		\geq & \frac{1}{2\Delta t}\!\left( \left\| \sqrt{\bm{\alpha_{0}}^{(j+1)}}\bm{e}_{\theta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} \! - \! \left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} \right) 
		-\frac{\tilde{L}_{\alpha_{0}}}{2}\left\| \bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2}. 
	\end{align*} 
	Next, we estimate the right-hand side of the resulting equality. 
	It follows from \eqref{e_theta_nbc} and the summation by parts formula (Lemma \ref{sbp5}) that 
	\begin{equation*}
	\nu^{2}\sum_{k=0}^{K}{}^{\prime\prime}\!\left( \delta_{k}^{\langle 2 \rangle}e_{\theta,k}^{(j+1)} \right)\! e_{\theta,k}^{(j+1)} \Delta x
		= - \nu^{2}\left\| D\bm{e}_{\theta}^{(j+1)} \right\|^{2}. 
	\end{equation*}
	Furthermore, we see from the Young inequality that 
	\begin{equation*}
	\sum_{k=0}^{K}{}^{\prime\prime}\xi_{4-6, k}^{(j+1)} e_{\theta,k}^{(j+1)}\Delta x
		\leq \frac{1}{2\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2} + \frac{\tilde{L}_{\alpha_{0}}}{2}\left\| \bm{e}_{\theta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}. 
	\end{equation*}
	For reasons of space limitation, the superscript $(j+1)$ is omitted hereafter. 
	Here, it holds from the summation by parts formula (Lemma \ref{sbp2}) that 
	\begin{align*}
	& \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left[\delta_{k}^{+}
	\left\{
		\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k})e_{\eta,k} 
		+ \alpha\left( \eta_{k} \right)  \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{-}\Theta_{k}, \delta_{k}^{-}\tilde{\theta}_{k}) }\delta_{k}^{-}e_{\theta,k}
	\right\}
	\right]e_{\theta,k}\Delta x \\
		= & - \frac{\kappa}{2}\sum_{k=1}^{K}
		\left(
			\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k})e_{\eta,k} 
			+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{-}\Theta_{k}, \delta_{k}^{-}\tilde{\theta}_{k}) }\delta_{k}^{-}e_{\theta,k}
		\right)
		\delta_{k}^{-}e_{\theta,k}\Delta x \\
		& + \underset{\rm =: (d.B.T.1)}{\underline{ \left[\left\{\mu_{k}^{+}
		\left(
			\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k})e_{\eta,k} 
			+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{-}\Theta_{k}, \delta_{k}^{-}\tilde{\theta}_{k}) }\delta_{k}^{-}e_{\theta,k}
		\right)
		\right\}
		e_{\theta,k} \right]_{0}^{K}
		}}.
	\end{align*}
	In the same manner as above, we observe that 
	\begin{align*}
	& \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left[\delta_{k}^{-}\!
	\left\{
		\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})e_{\eta,k} 
		+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}, \delta_{k}^{+}\tilde{\theta}_{k}) }\delta_{k}^{+}e_{\theta,k}
	\right\}
	\right]e_{\theta,k}\Delta x \\
		= & - \frac{\kappa}{2}\sum_{k=0}^{K-1}
		\left(
			\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})e_{\eta,k} 
			+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}, \delta_{k}^{+}\tilde{\theta}_{k}) }\delta_{k}^{+}e_{\theta,k}
		\right)
		\delta_{k}^{+}e_{\theta,k}\Delta x \\
		& + \underset{\rm =: (d.B.T.2)}{\underline{ \left[\left\{\mu_{k}^{-}
		\left(
			\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})e_{\eta,k} 
			+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}, \delta_{k}^{+}\tilde{\theta}_{k}) }\delta_{k}^{+}e_{\theta,k}
		\right)
		\right\}
		e_{\theta,k} \right]_{0}^{K}
		}}.
	\end{align*}
	It is seen from the direct calculation that 
	\begin{align*}
	& \sum_{k=1}^{K}
	\left\{
		\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k})e_{\eta,k} 
		+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{-}\Theta_{k}, \delta_{k}^{-}\tilde{\theta}_{k}) }\delta_{k}^{-}e_{\theta,k}
	\right\}
	\delta_{k}^{-}e_{\theta,k}\Delta x \\
		= &\sum_{k=1}^{K}
		\left\{
			\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k-1})e_{\eta,k} 
			+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k-1}, \delta_{k}^{+}\tilde{\theta}_{k-1}) }\delta_{k}^{+}e_{\theta,k-1}
		\right\}
		\delta_{k}^{+}e_{\theta,k-1}\Delta x \\
		= & \sum_{k=0}^{K-1}
		\left\{
			\frac{H_{k+1} + \eta_{k+1}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})e_{\eta,k+1} 
			+ \alpha\left( \eta_{k+1} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}, \delta_{k}^{+}\tilde{\theta}_{k}) }\delta_{k}^{+}e_{\theta,k}
		\right\}
		\delta_{k}^{+}e_{\theta,k}\Delta x. 
	\end{align*}
	Additionally, it follows from \eqref{bc1}--\eqref{bc2}, \eqref{e_eta_nbc}--\eqref{e_theta_nbc}, and the definitions of $\tilde{\eta}$ and $\tilde{\theta}$ that $\mbox{(d.B.C.1)} + \mbox{(d.B.C.2)} = 0$. 
	Thus, we obtain from the following inequalities: $d\gamma_{\varepsilon}'/d(u,v) \geq 0$ for all $u,v \in \mathbb{R}$, $|\gamma_{\varepsilon}'(u)| \leq 1$ for all $u\in \mathbb{R}$, and the H\"{o}lder inequality that  
	\begin{align*}
	& \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left[\delta_{k}^{+}
	\left\{
		\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k})e_{\eta,k} 
		+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{-}\Theta_{k}, \delta_{k}^{-}\tilde{\theta}_{k}) }\delta_{k}^{-}e_{\theta,k}
	\right\}
	\right]e_{\theta,k}\Delta x \\[-1pt]
	& + \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left[\delta_{k}^{-}
	\left\{
		\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})e_{\eta,k} 
		+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}, \delta_{k}^{+}\tilde{\theta}_{k}) }\delta_{k}^{+}e_{\theta,k}
	\right\}
	\right]e_{\theta,k}\Delta x \\[-1pt]
		= & - \frac{\kappa}{2}\sum_{k=0}^{K-1}
			\left(
				\frac{H_{k+1} + \eta_{k+1}}{2}e_{\eta,k+1} 
				+ \frac{H_{k} + \eta_{k}}{2}e_{\eta,k} 
			\right) \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})
			\delta_{k}^{+}e_{\theta,k}\Delta x \\[-1pt]
		& - \frac{\kappa}{2}\sum_{k=0}^{K-1}
		\left(
			\alpha\!\left( \eta_{k+1} \right) + \alpha\!\left( \eta_{k} \right)
		\right)\frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}, \delta_{k}^{+}\tilde{\theta}_{k}) }
		\left| \delta_{k}^{+}e_{\theta,k} \right|^{2} \Delta x \\[-1pt]
		\leq & - \frac{\kappa}{2}\sum_{k=0}^{K-1}
			\left(
				\frac{H_{k+1} + \eta_{k+1}}{2}e_{\eta,k+1} 
				+ \frac{H_{k} + \eta_{k}}{2}e_{\eta,k} 
			\right) \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})
			\delta_{k}^{+}e_{\theta,k}\Delta x \\[-1pt]
		\leq & \frac{\kappa}{2}\sum_{k=0}^{K-1}
		\left|
			\frac{H_{k+1} + \eta_{k+1}}{2}e_{\eta,k+1} 
			+ \frac{H_{k} + \eta_{k}}{2}e_{\eta,k} 
		\right| \left| \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \right|
		\left| \delta_{k}^{+}e_{\theta,k} \right| \Delta x \\[-1pt]
		\leq & \frac{\kappa}{2}\left\| D\bm{e}_{\theta} \right\|
		\left\{ 
		\sum_{k=0}^{K-1}
		\left|
			\frac{H_{k+1} + \eta_{k+1}}{2}e_{\eta,k+1} 
			+ \frac{H_{k} + \eta_{k}}{2}e_{\eta,k} 
		\right|^{2}\Delta x 
		\right\}^{\frac{1}{2}}. 
	\end{align*}
	Furthermore, by using \eqref{eta_bound}, we obtain 
	\begin{align*}
	& \left\{ 
		\sum_{k=0}^{K-1}
		\left|
			\frac{H_{k+1} + \eta_{k+1}}{2}e_{\eta,k+1} 
			+ \frac{H_{k} + \eta_{k}}{2}e_{\eta,k} 
		\right|^{2}\Delta x 
		\right\}^{\frac{1}{2}} \\[-1pt]
		\leq & \left\{ 
			\frac{1}{2}\sum_{k=0}^{K-1}
			\left(
			\left|
				H_{k+1} + \eta_{k+1}
			\right|^{2}
			\left|
				e_{\eta,k+1} 
			\right|^{2}
			+ \left|
				H_{k} + \eta_{k}
			\right|^{2}
			\left|
				e_{\eta,k} 
			\right|^{2}
			\right)\Delta x 
			\right\}^{\frac{1}{2}} \\[-1pt]
		\leq & \left[ 
			\sum_{k=0}^{K-1}
			\left\{
			\left(
			\left|
				H_{k+1} 
			\right|^{2}
			+ \left|
				\eta_{k+1}
			\right|^{2}
			\right)
			\left|
				e_{\eta,k+1} 
			\right|^{2}
			+ \left(
			\left|
				H_{k} 
			\right|^{2}
			+ \left|
				\eta_{k}
			\right|^{2}
			\right)
			\left|
				e_{\eta,k} 
			\right|^{2}
			\right\} \Delta x 
			\right]^{\frac{1}{2}} \\[-1pt]
		\leq & \left\{ 
			2C_{1}^{2}\sum_{k=0}^{K-1}
			\left(
			\left|
				e_{\eta,k+1}
			\right|^{2}
			+ \left|
				e_{\eta,k} 
			\right|^{2}
			\right) \Delta x 
			\right\}^{\frac{1}{2}} 
		= 2C_{1}\left\| \bm{e}_{\eta}\right\|_{ L_{\rm d}^{2} }. 
	\end{align*}
	Hence, by using the Young inequality, we get 
	\begin{align*}
		& \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left[\delta_{k}^{+}\!
		\left\{
			\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k})e_{\eta,k} 
			+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{-}\Theta_{k}, \delta_{k}^{-}\tilde{\theta}_{k}) }\delta_{k}^{-}e_{\theta,k}
		\right\}
		\right]e_{\theta,k}\Delta x \\[-1pt]
		& + \frac{\kappa}{2}\sum_{k=0}^{K}{}^{\prime\prime}\left[\delta_{k}^{-}\!
		\left\{
			\frac{H_{k} + \eta_{k}}{2} \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})e_{\eta,k} 
			+ \alpha\left( \eta_{k} \right) \frac{ d\gamma_{\varepsilon}' }{ d(\delta_{k}^{+}\Theta_{k}, \delta_{k}^{+}\tilde{\theta}_{k}) }\delta_{k}^{+}e_{\theta,k}
		\right\}
		\right]e_{\theta,k}\Delta x \\[-1pt]
		\leq & \kappa C_{1}\left\| \bm{e}_{\eta}\right\|_{ L_{\rm d}^{2} } 
		\left\| D\bm{e}_{\theta} \right\| \\[-1pt]
		\leq & \kappa C_{1} \! \left( \frac{\kappa C_{1}}{2\nu^{2}}\left\| \bm{e}_{\eta}\right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{\nu^{2}}{2\kappa C_{1}}\left\| D\bm{e}_{\theta} \right\| \right)
		= \frac{1}{2}\!\left(\frac{\kappa C_{1}}{\nu}\right)^{2}\!\left\| \bm{e}_{\eta}\right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{\nu^{2}}{2}\left\| D\bm{e}_{\theta} \right\|.
	\end{align*}
	As a result, we obtain 
	\begin{align*}
	& \frac{1}{2\Delta t}\!\left( \left\| \sqrt{\bm{\alpha_{0}}^{(j+1)}}\bm{e}_{\theta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} \! - \! \left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} \right) \\
		\leq & - \nu^{2}\left\| D\bm{e}_{\theta}^{(j+1)} \right\|^{2} 
		+ \frac{1}{2}\left(\frac{\kappa C_{1}}{\nu}\right)^{2}\left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{\nu^{2}}{2}\left\| D\bm{e}_{\theta}^{(j+1)} \right\| \\
		& + \frac{1}{2\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{\tilde{L}_{\alpha_{0}}}{2}\left\| \bm{e}_{\theta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}
		+ \frac{\tilde{L}_{\alpha_{0}}}{2}\left\| \bm{e}_{\theta}^{(j)} \right\|_{L_{\rm d}^{2}}^{2} \\
		\leq & \frac{1}{2}\!\left(\! \frac{\kappa C_{1} }{\nu} \!\right)^{2}\!\left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2}
		\! + \frac{\tilde{L}_{\alpha_{0}}}{2}\!\left\| \bm{e}_{\theta}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}
		\! + \frac{\tilde{L}_{\alpha_{0}}}{2}\!\left\| \bm{e}_{\theta}^{(j)} \right\|_{L_{\rm d}^{2}}^{2}
		\! + \frac{1}{2\tilde{L}_{\alpha_{0}}}\!\left\| \bm{\xi}_{4-6}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}
		\! - \frac{\nu^{2}}{2}\!\left\| D\bm{e}_{\theta}^{(j+1)}\right\|^{2}. 
	\end{align*}
	Here, it holds from $\alpha_{0,k}^{(j)} \geq \delta_{0} \ (k=0,\ldots,K,\ j=0,\ldots,N)$ that $1 \leq \alpha_{0,k}^{(j)}/\delta_{0} \ (k=0,\ldots,K,\ j=0,\ldots,N)$. 
	Thus, we observe that 
	\begin{equation*}
	\left\| \bm{e}_{\theta}^{(j)} \right\|_{L_{\rm d}^{2}}^{2} 
		= \sum_{k=0}^{K}{}^{\prime\prime}\left| e_{\theta,k}^{(j)} \right|^{2} \Delta x 
		\leq \sum_{k=0}^{K}{}^{\prime\prime}\frac{\alpha_{0,k}^{(j)}}{\delta_{0}}\left| e_{\theta,k}^{(j)} \right|^{2} \Delta x 
		= \frac{1}{\delta_{0}}\left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} \quad (j=0,\ldots, N). 
	\end{equation*}
	Thus, we obtain \eqref{err_theta_est2}. 
\end{proof}

\begin{lem}\label{e_eta_theta_est}
Let $a := \max\{2(\kappa C_{1} /\nu )^{2} - (2\kappa\varepsilon + c), \tilde{L}_{\alpha_{0}}/\delta_{0}\}$.  
If $\Delta t$ satisfies \eqref{dt_ass}, 
then, we have 
\begin{align}
& \left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} 
+ \left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} 
+ \frac{\Delta t}{1 - a\Delta t}\nu^{2}\left\| D\bm{e}_{\theta}^{(j)}\right\|^{2} \notag\\
	\leq & \frac{3}{2}e^{3aT}\sum_{i=0}^{j-1}\left( \frac{1}{c}\left\| \bm{\xi}_{1-3}^{(j-i)} \right\|_{L_{\rm d}^{2}}^{2} + \frac{1}{\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j-i)} \right\|_{L_{\rm d}^{2}}^{2}\right)\Delta t \quad (j=1,\ldots,N). \label{e_eta_theta_est2}
\end{align} 
\end{lem}

\begin{proof}
	Let us fix $j=0,1,\ldots, N-1$. 
	Summing up the sides of \eqref{err_eta_est2} (Lemma \ref{e_eta_est}) and \eqref{err_theta_est2} (Lemma \ref{e_theta_est}), it yields from the definition of $a$ that 
	\begin{align}
	& (1 - a\Delta t)\left( \left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2}
	+ \left\| \sqrt{\bm{\alpha_{0}}^{(j+1)}}\bm{e}_{\theta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2}\right) 
	+ \Delta t\nu^{2}\left\| D\bm{e}_{\theta}^{(j+1)}\right\|^{2} \nonumber\\
		\leq & \left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2}
		\! + \! (1 \! + \! a\Delta t )\!\left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2}
		\! + \! \Delta t\nu^{2}\!\left\| D\bm{e}_{\theta}^{(j)} \right\|^{2} 
		\! + \! \Delta t\!\left(\! \frac{1}{c}\!\left\| \bm{\xi}_{1-3}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{1}{\tilde{L}_{\alpha_{0}}}\!\left\| \bm{\xi}_{4-6}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2} \right). \label{total_est}
	\end{align}
	We see from the assumption $\Delta t < 1/(3a)$ that $1 -3a\Delta t > 0$. 
	Furthermore, we observe that 
	\begin{equation*}
	\frac{1}{1 - a\Delta t}
		< \frac{1 + a\Delta t}{1 - a\Delta t}
		< 1 + 3a\Delta t, \quad 
	\frac{1}{1 - a\Delta t} < \frac{3}{2}. 
	\end{equation*}
	Thus, dividing both sides of \eqref{total_est} by $1 - a\Delta t$, we have 
	\begin{align*}
	&  \left\| \bm{e}_{\eta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2}
	+ \left\| \sqrt{\bm{\alpha_{0}}^{(j+1)}}\bm{e}_{\theta}^{(j+1)}\right\|_{ L_{\rm d}^{2} }^{2}
	+ \frac{\nu^{2}\Delta t}{1 - a\Delta t}\left\| D\bm{e}_{\theta}^{(j+1)}\right\|^{2} \\
		\leq & (1 \! + \! 3a\Delta t )\!\left( \left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2}
		\! + \! \left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} \right)
		\! + \! \frac{\nu^{2}\Delta t}{1 - a\Delta t}\left\| D\bm{e}_{\theta}^{(j)} \right\|^{2} \\
		& + \! \frac{3}{2}\Delta t\left(\frac{1}{c}\left\| \bm{\xi}_{1-3}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{1}{\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}\right) \\ 
		\leq & (1 \! + \! 3a\Delta t )\!\left( \left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2}
		\! + \! \left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{\nu^{2}\Delta t}{1 - a\Delta t}\left\| D\bm{e}_{\theta}^{(j)} \right\|^{2} \right) \\
		& + \! \frac{3}{2}\Delta t\left(\frac{1}{c}\left\| \bm{\xi}_{1-3}^{(j+1)} \right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{1}{\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j+1)} \right\|_{L_{\rm d}^{2}}^{2}\right). 
	\end{align*}
	As a result, we obtain 
	\begin{align*}
	&  \left\| \bm{e}_{\eta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2}
	+ \left\| \sqrt{\bm{\alpha_{0}}^{(j)}}\bm{e}_{\theta}^{(j)}\right\|_{ L_{\rm d}^{2} }^{2}
	+ \frac{\nu^{2}\Delta t}{1 - a\Delta t}\left\| D\bm{e}_{\theta}^{(j)}\right\|^{2} \\
		\leq & (1 \! + \! 3a\Delta t )\!\left( \left\| \bm{e}_{\eta}^{(j-1)}\right\|_{ L_{\rm d}^{2} }^{2}
		\! + \! \left\| \sqrt{\bm{\alpha_{0}}^{(j-1)}}\bm{e}_{\theta}^{(j-1)}\right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{\nu^{2}\Delta t}{1 - a\Delta t}\left\| D\bm{e}_{\theta}^{(j-1)} \right\|^{2} \right) \\
		& + \frac{3}{2}\Delta t\left(\frac{1}{c}\left\| \bm{\xi}_{1-3}^{(j)} \right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{1}{\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j)} \right\|_{L_{\rm d}^{2}}^{2}\right) \\ 
		\leq & (1 \! + \! 3a\Delta t )^{2}\!\left( \left\| \bm{e}_{\eta}^{(j-2)}\right\|_{ L_{\rm d}^{2} }^{2}
		\! + \! \left\| \sqrt{\bm{\alpha_{0}}^{(j-2)}}\bm{e}_{\theta}^{(j-2)}\right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{\nu^{2}\Delta t}{1 - a\Delta t}\left\| D\bm{e}_{\theta}^{(j-2)} \right\|^{2} \right) \\
		& + \frac{3}{2}(1 + 3a\Delta t )\Delta t\!\left(\frac{1}{c}\!\left\| \bm{\xi}_{1-3}^{(j-1)} \right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{1}{\tilde{L}_{\alpha_{0}}}\!\left\| \bm{\xi}_{4-6}^{(j-1)} \right\|_{L_{\rm d}^{2}}^{2}\right)
		\! + \frac{3}{2}\Delta t \! \left(\frac{1}{c}\!\left\| \bm{\xi}_{1-3}^{(j)} \right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{1}{\tilde{L}_{\alpha_{0}}}\!\left\| \bm{\xi}_{4-6}^{(j)} \right\|_{L_{\rm d}^{2}}^{2}\right) \\ 
		\leq & \cdots \quad \text{(by repeating the above argument inductively)} \\
		\leq & (1 \! + \! 3a\Delta t )^{j}\!\left( \left\| \bm{e}_{\eta}^{(0)}\right\|_{ L_{\rm d}^{2} }^{2}
		\! + \! \left\| \sqrt{\bm{\alpha_{0}}^{(0)}}\bm{e}_{\theta}^{(0)}\right\|_{ L_{\rm d}^{2} }^{2} 
		\! + \! \frac{\nu^{2}\Delta t}{1 - a\Delta t}\left\| D\bm{e}_{\theta}^{(0)} \right\|^{2} \right) \\
		& + \frac{3}{2}\sum_{i=0}^{j-1}(1 + 3a\Delta t )^{i}\left(\frac{1}{c}\left\| \bm{\xi}_{1-3}^{(j-i)} \right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{1}{\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j-i)} \right\|_{L_{\rm d}^{2}}^{2}\right)\Delta t \\
		= & \frac{3}{2}\sum_{i=0}^{j-1}(1 + 3a\Delta t )^{i}\left(\frac{1}{c}\left\| \bm{\xi}_{1-3}^{(j-i)} \right\|_{ L_{\rm d}^{2} }^{2} 
		+ \frac{1}{\tilde{L}_{\alpha_{0}}}\left\| \bm{\xi}_{4-6}^{(j-i)} \right\|_{L_{\rm d}^{2}}^{2}\right)\Delta t \quad (j=1,\ldots, N). 
	\end{align*}
	Here, it holds that $(1 + 3a\Delta t )^{i} \leq (1 + 3a\Delta t )^{N} \leq \exp(N \cdot 3a\Delta t) = e^{3aT} \ (i=0,\ldots, N)$. 
	Therefore, we obtain \eqref{e_eta_theta_est2}. 
\end{proof}

\begin{lem}\label{exist1}
	Let us assume (A1). 
	Then, for any given $(\bm{H}^{(j)},\bm{\Theta}^{(j)})$, there exists a unique soluiton $\bm{H}^{(j + 1)}$ satisfying \eqref{sc1} with \eqref{bc1}--\eqref{bc2}.
\end{lem}

\begin{proof}
	From now on, we give the matrix expression of \eqref{sc1}. 
	For the purpose, let us define the $(K+1) \times (K+1)$ matrices $D_{2}$ and $V$ by
	\begin{gather*}
		D_{2} := \frac{1}{(\Delta x)^{2}}\left(
		\begin{array}{ccccc} 
		-2 & 2 & & &  \\
		1 & -2 & 1 & &  \\
		& \ddots & \ddots & \ddots & \\
		& & 1 & -2 & 1 \\
		& & & 2 & -2 \\
		\end{array}
		\right) \in \mathbb{R}^{(K+1) \times (K+1)}, \\
		V \! := \! \diag\!\left(\! 
			\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{0}^{(j)}\bigr) \! + \! \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{0}^{(j)}\bigr)  }{2}, 
			\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{1}^{(j)}\bigr) \! + \! \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{1}^{(j)}\bigr)  }{2}, 
			\ldots ,
			\frac{ \gamma_{\varepsilon}\bigl( \delta_{k}^{+}\Theta_{K}^{(j)}\bigr) \! + \! \gamma_{\varepsilon}\bigl( \delta_{k}^{-}\Theta_{K}^{(j)}\bigr)  }{2} 
		\!\right) . 
	\end{gather*}
	Then, we obtain the matrix expression of \eqref{sc1} as follows: 
	\begin{equation*}
		\left\{I + \Delta t\left(- \kappa_{0}^{2}D_{2} + cI + \kappa V \right)\right\}\bm{H}^{(j + 1)} = \bm{H}^{(j)} + c\Delta t\bm{1}. 
	\end{equation*}
	where $I$ is the $(K+1)$-dimensional identity matrix and $\bm{1} := (1,1,\ldots,1)^{\top} \in \mathbb{R}^{K+1}$. 
	For simplicity, let us denote the coefficient matrix of $\bm{H}^{(j + 1)}$ by $A \! := \! I + \Delta t\left(- \kappa_{0}^{2}D_{2} + cI + \kappa V \right)$. 
	By direct calculation, we see that $A$ is a strictly diagonally dominant matrix. 
	% Since a strictly diagonally dominant matrix is non-singular, 
	Namely, $A$ is nonsingular. 
\end{proof}

\begin{lem}\label{exist2}
	Let us assume (A1). 
	Then, for any given $(\bm{H}^{(j+1)},\bm{\Theta}^{(j)})$, if $\Delta t$ satisfies 
	\begin{equation}
	    \Delta t < \frac{\nu^{2}\varepsilon^{2}}{4\kappa^{2}\delta_{0}\left(\delta_{0} + \dfrac{1}{2}\right)^{2}}(\Delta x)^{2}, \label{exist_cond2}
	\end{equation}
	then there exists a unique soluiton $\bm{\Theta}^{(j + 1)}$ satisfying \eqref{sc2} with \eqref{bc1}--\eqref{bc2}. 
\end{lem}

\begin{proof}
	For any given $\bm{\Theta}^{(j)} = \{\Theta_{k}^{(j)}\}_{k=-1}^{K+1} \in \mathbb{R}^{K+3}$, we define the mapping $\Psi$: $\{\Theta_{k}\}_{k=-1}^{K+1} \mapsto \{\tilde{\Theta}_{k}\}_{k=-1}^{K+1}$ by 
	\begin{gather}
		\alpha_{0, k}^{(j+1)} \frac{ \tilde{\Theta}_{k} - \Theta_{k}^{(j)} }{\Delta t} 
		= \frac{\kappa}{2}\left\{ \delta_{k}^{+}\left( \alpha\!\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}) \right) + \delta_{k}^{-}\left( \alpha\!\left( H_{k}^{(j+1)} \right) \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \right) \right\} + \nu^{2}\delta_{k}^{\langle 2 \rangle}\tilde{\Theta}_{k} \quad (k=0, \ldots, K), \label{map}\\
		\delta_{k}^{\langle 1 \rangle}\tilde{\Theta}_{k} = 0 \quad (k=0, K), \label{map_bc} 
	\end{gather}
	where 
	\begin{equation}
		\Theta_{-1} = \Theta_{1}, \quad \Theta_{K + 1} = \Theta_{K - 1}. \label{map_bc0} 
	\end{equation}
	Firstly, we show that the mapping $\Psi$ is well-defined. 
	From \eqref{map_bc}, $\tilde{\Theta}_{-1}$ and $\tilde{\Theta}_{K+1}$ can be explicitly written as 
	\begin{equation}
		\tilde{\Theta}_{-1} = \tilde{\Theta}_{1}, \quad \tilde{\Theta}_{K + 1} = \tilde{\Theta}_{K - 1}. \label{map_bc2}
	\end{equation}
	Then, the coefficient matrix of $\bm{\tilde{\Theta}}$ by $B := W - \Delta t\nu^{2}D_{2}$, where 
	\begin{equation*}
		W := \diag(\alpha_{0, 0}^{(j+1)}, \alpha_{0, 1}^{(j+1)}, \dots, \alpha_{0, K}^{(j+1)}). 
	\end{equation*}
	By direct calculation, we see that $B$ is a strictly diagonally dominant matrix. 
	Namely, $B$ is nonsingular.
	Hence, the mapping $\Psi$ is well-defined. 

	Next, we prove the existence and uniqueness of the solution of the proposed scheme by the fixed-point theorem for a contraction mapping. 
	From \eqref{map_bc0} and \eqref{map_bc2}, it is sufficient to show the existence of a $K+1$-vector $\bm{\Theta}$ that satisfies $\tilde{\Theta}_{k} = \Theta_{k} \ (k=0, \ldots, K)$. 
	Here, 
	% we define the mapping $\Phi$: $\mathbb{R}^{K+1} \to \mathbb{R}^{K+1}$ by 
	% \begin{equation*}
	% 	\Phi( \bm{\Theta} ) := \{ \tilde{\Theta}_{k} \}_{k=0}^{K} = \{ \Psi_{k}( \bm{\Theta} ) \}_{k=0}^{K} \quad \mbox{for\ all\ } \bm{\Theta} \in \mathbb{R}^{K+1}, 
	% \end{equation*}
	% where $\Psi_{k}( \bm{\Theta})$ is the $k$-th element of $\Psi( \bm{\Theta} )$. 
	% Also, 
	let 
	\begin{equation*}
		X := \{\bm{f} \in \mathbb{R}^{K+3}; \|\bm{f} \|_{L_{\rm d}^{2}} \leq \sqrt{2} M \}, 
	\end{equation*}
	where $M := \|\bm{\Theta}^{(j)}\|_{L_{\rm d}^{2}}$. 
	We show that the mapping $\Psi$ is a contraction mapping on $X$. 
	If $\Psi$ is a contraction mapping, $\Psi$ has a unique fixed-point $\bm{\Theta}^{\ast}$ in the closed ball $X$ from the fixed-point theorem for a contraction mapping.
	This $\bm{\Theta}^{\ast}$ is the solution $\bm{\Theta}^{(j+1)}$ to the scheme \eqref{sc2} with \eqref{bc1}--\eqref{bc2}. 
	Firstly, we show $\Psi(X) \subset X$. 
	For any fixed $\bm{\Theta} \in X$, we have 
	\begin{align}
		& \sum _ {k=0}^{K}{}^{\prime \prime} \alpha_{0, k}^{(j+1)} \frac{ \tilde{\Theta}_{k} - \Theta_{k}^{(j)} }{\Delta t}\tilde{\Theta}_ {k}\Delta x \notag\\
		= & \frac{\kappa}{2}\sum _ {k=0}^{K}{}^{\prime \prime}\!\left\{ 
			\delta_{k}^{+}\left( \alpha\!\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}) \right) 
			+ \delta_{k}^{-}\left( \alpha\!\left( H_{k}^{(j+1)} \right) \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \right) 
		\right\} \tilde{\Theta}_ {k}\Delta x 
		+ \nu^{2}\sum _ {k=0}^{K}{}^{\prime \prime}\left(\delta_{k}^{\langle 2 \rangle}\tilde{\Theta}_{k}\right) \tilde{\Theta}_ {k}\Delta x. \label{tool1}
	\end{align}
	Firstly, by using \eqref{tool_ineq}, we evaluate the left-hand side of \eqref{tool1} as follows: 
	\begin{equation*}
		\frac{1}{\Delta t}\sum _ {k=0}^{K}{}^{\prime \prime}\alpha_{0, k}^{(j+1)}\!\left(\tilde{\Theta}_ {k} \! - \! \Theta_{k}^{(j)}\right)\!\tilde{\Theta}_ {k}\Delta x
		\geq \frac{1}{2\Delta t}\sum _ {k=0}^{K}{}^{\prime \prime}\alpha_{0, k}^{(j+1)}\!\left\{\tilde{\Theta}_{k}^{2} \! - \! \left(\Theta_{k}^{(j)}\right)^{\! 2} \right\}\Delta x 
		\geq \frac{1}{2\delta_{0}\Delta t}\left( \left\|\bm{\tilde{\Theta}}\right\|_{L_{\rm d}^2}^{2} - \left\|\bm{\Theta}^{(j)}\right\|_{L_{\rm d}^2}^{2} \right).
	\end{equation*}
	Next, we consider the right-hand side of \eqref{tool1}. 
	It holds from the summation by parts formula (Lemma \ref{sbp5}) and \eqref{map_bc2} that 
	\begin{equation*}
		\nu^{2}\sum _ {k=0}^{K}{}^{\prime \prime}\left(\delta_{k}^{\langle 2 \rangle}\tilde{\Theta}_{k}\right) \tilde{\Theta}_ {k}\Delta x
		= -\nu^{2}\sum _ {k=0}^{K-1}\left|\delta_{k}^{+}\tilde{\Theta}_{k}\right|^{2} \Delta x 
		+ \nu^{2}\left[\left(\delta_{k}^{\langle 1 \rangle}\tilde{\Theta}_{k}\right) \tilde{\Theta}_ {k}\right]_{0}^{K} 
		= -\nu^{2}\left\| D\bm{\tilde{\Theta}} \right\|^{2}.
	\end{equation*}
	Similarly, we see from the summation by parts formula (Lemma \ref{sbp2}), \eqref{bc1}, and \eqref{map_bc0} that 
	\begin{align*}
		& \frac{\kappa}{2}\sum _ {k=0}^{K}{}^{\prime \prime}\left\{ \delta_{k}^{+}\left( \alpha\!\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}) \right) + \delta_{k}^{-}\left( \alpha\!\left( H_{k}^{(j+1)} \right) \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \right) \right\} \tilde{\Theta}_ {k}\Delta x \\
		= & - \frac{\kappa}{2}\sum _ {k=1}^{K}\alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}) \delta_{k}^{-}\tilde{\Theta}_ {k}\Delta x 
		- \frac{\kappa}{2}\sum _ {k=0}^{K-1}\alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \delta_{k}^{+}\tilde{\Theta}_ {k}\Delta x \\
		& + \frac{\kappa}{2}\left[ 
			\left\{ 
				\mu_{k}^{+}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k}) \right) 
				+ \mu_{k}^{-}\left( \alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \right) 
			\right\} \tilde{\Theta}_ {k} 
		\right]_{0}^{K} \\
		= & - \frac{\kappa}{2}\sum _ {k=0}^{K-1}\alpha\left( H_{k+1}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{k+1}) \delta_{k}^{-}\tilde{\Theta}_ {k+1}\Delta x 
		- \frac{\kappa}{2}\sum _ {k=0}^{K-1}\alpha\left( H_{k}^{(j+1)} \right)\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \delta_{k}^{+}\tilde{\Theta}_ {k}\Delta x \\
		= & - \kappa\sum _ {k=0}^{K-1}\frac{\alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right)}{2}\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \delta_{k}^{+}\tilde{\Theta}_ {k}\Delta x. 
	\end{align*}
	As a result, we observe from the Young inequality that 
	\begin{align*}
		\frac{1}{2\delta_{0}\Delta t}\left( \left\|\bm{\tilde{\Theta}}\right\|_{L_{\rm d}^2}^{2} - \left\|\bm{\Theta}^{(j)}\right\|_{L_{\rm d}^2}^{2} \right) 
		\leq & -\nu^{2}\left\| D\bm{\tilde{\Theta}} \right\|^{2} 
		- \kappa\sum _ {k=0}^{K-1}\frac{\alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right)}{2}\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k}) \delta_{k}^{+}\tilde{\Theta}_ {k}\Delta x \\[-1pt]
		\leq & \frac{\kappa^{2}}{4\nu^{2}}\sum _ {k=0}^{K-1}\left|\frac{\alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right)}{2}\right|^{2}\left|\gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{k})\right|^{2} \Delta x \\[-1pt]
		= & \frac{\kappa^{2}}{4\nu^{2}}\sum _ {k=0}^{K-1}\left|\frac{\alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right)}{2}\right|^{2}\frac{\left|\delta_{k}^{+}\Theta_{k}\right|^{2}}{\left|\gamma_{\varepsilon} (\delta_{k}^{+}\Theta_{k})\right|^{2}} \Delta x.
	\end{align*}
	Here, we see from Main Theorem 1 (O)(a) that 
	\begin{equation}
		\left|\frac{\alpha\!\left( H_{k+1}^{(j+1)} \right) \! + \! \alpha\!\left( H_{k}^{(j+1)} \right)}{2}\right|^{2}
		\! \leq \! \frac{\left|\alpha\!\left( H_{k+1}^{(j+1)} \right)\right|^{2} \! + \! \left|\alpha\!\left( H_{k}^{(j+1)} \right)\right|^{2} }{2} 
		\! \leq \! \left(\! \delta_{0} + \frac{1}{2} \!\right)^{2} \quad (k = 0, \dots, K). \label{al_bd}
	\end{equation}
	Using \eqref{al_bd} and the following inequality: 
	\begin{equation*}
		0 \leq \frac{1}{\gamma_{\varepsilon}(u)} = \frac{1}{\sqrt{\varepsilon^{2} + u^{2}}} \leq \frac{1}{\varepsilon}, 
	\end{equation*}
	we have
	\begin{align*}
		\frac{1}{2\delta_{0}\Delta t}\left( \left\|\bm{\tilde{\Theta}}\right\|_{L_{\rm d}^2}^{2} - \left\|\bm{\Theta}^{(j)}\right\|_{L_{\rm d}^2}^{2} \right) 
		\leq \frac{\kappa^{2}}{4\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}\sum _ {k=0}^{K-1}\left|\delta_{k}^{+}\Theta_{k}\right|^{2}\Delta x 
		= & \frac{\kappa^{2}}{4\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}\sum _ {k=0}^{K-1}\left|\frac{\Theta_{k + 1} - \Theta_{k}}{\Delta x}\right|^{2}\Delta x \\[-1pt]
		\leq & \frac{\kappa^{2}}{2\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}\sum _ {k=0}^{K-1}\frac{\left|\Theta_{k + 1}\right|^{2} + \left|\Theta_{k}\right|^{2}}{(\Delta x)^{2}}\Delta x \\[-1pt]
		= & \frac{1}{(\Delta x)^{2}}\frac{\kappa^{2}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}\sum _ {k=0}^{K}{}^{\prime \prime}\left|\Theta_{k}\right|^{2}\Delta x \\[-1pt]
		= & \frac{1}{(\Delta x)^{2}}\frac{\kappa^{2}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}\left\|\bm{\Theta}\right\|_{L_{\rm d}^2}^{2}.
	\end{align*}
	Therefore, from the assumption \eqref{exist_cond}, we conclude that   
	\begin{equation*}
		\left\|\bm{\tilde{\Theta}}\right\|_{L_{\rm d}^2}^{2} 
		\leq \left\|\bm{\Theta}^{(j)}\right\|_{L_{\rm d}^2}^{2} 
		+ \frac{2\Delta t}{(\Delta x)^{2}}\frac{\kappa^{2}\delta_{0}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}\left\|\bm{\Theta}\right\|_{L_{\rm d}^2}^{2} 
		\leq \left\{
			1 + \frac{4\Delta t}{(\Delta x)^{2}}\frac{\kappa^{2}\delta_{0}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}
		\right\}M^{2} 
		\leq 2M^{2}. 
	\end{equation*} 
	Namely, $\Psi(\bm{\Theta}) = \bm{\tilde{\Theta}} \in X$. 

	Next, we show that $\Psi$ is a contraction mapping. 
	For any fixed $\bm{\Theta}_{1}, \bm{\Theta}_{2} \in X$ which satisfy \eqref{map_bc0}, 
	the vector $\{\tilde{\Theta}_{i,k}\}_{k=-1}^{K+1} = \{\Psi_{k}(\bm{\Theta}_{i})\}_{k=-1}^{K+1}$ satisfies \eqref{map}--\eqref{map_bc} ($i=1,2$) from the definition of $\Psi$, 
	where $\Psi_{k}( \bm{\Theta})$ is the $k$-th element of $\Psi( \bm{\Theta} )$. 
	Subtracting these relations, we obtain 
	\begin{gather}
		\begin{split}
			\alpha_{0, k}^{(j+1)} \frac{ \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} }{\Delta t} 
			= & \frac{\kappa}{2} \delta_{k}^{+}\left\{
					\alpha\!\left( H_{k}^{(j+1)} \right)\left( \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{2,k}) \right) 
			\right\} \\
			& + \frac{\kappa}{2}\delta_{k}^{-}\left\{
					\alpha\!\left( H_{k}^{(j+1)} \right)\left( \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right) 
			\right\} + \nu^{2}\delta_{k}^{\langle 2 \rangle}\left(\tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k}\right) \quad (k=0, \ldots, K), 
		\end{split} \label{tool2}\\
		\delta_{k}^{\langle 1 \rangle}\left(\tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k}\right) = 0 \quad (k=0, K). \label{tool3}
	\end{gather}
	Firstly, we see from \eqref{tool2} that 
	\begin{align*}
		\frac{1}{\delta_{0}\Delta t}\left\|\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right\|_{L_{\rm d}^{2}}^{2}
		\leq & \frac{1}{\Delta t}\sum _ {k=0}^{K}{}^{\prime \prime}\alpha_{0, k}^{(j+1)} \left| \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right|^{2} \Delta x \\
		= & \frac{\kappa}{2}\sum _ {k=0}^{K}{}^{\prime \prime} \delta_{k}^{+}\!\left\{\!
			\alpha\!\left( H_{k}^{(j+1)} \right)\!\left( \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{2,k}) \right) 
		\!\right\}\!\left(\! \tilde{\Theta}_{1, k} \! - \! \tilde{\Theta}_{2, k} \!\right)\!\Delta x \\
		& + \frac{\kappa}{2}\sum _ {k=0}^{K}{}^{\prime \prime} \delta_{k}^{-}\!\left\{\!
				\alpha\!\left( H_{k}^{(j+1)} \right)\!\left( \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right) 
		\!\right\}\!\left(\! \tilde{\Theta}_{1, k} \! - \! \tilde{\Theta}_{2, k} \!\right)\!\Delta x \\
		& + \nu^{2}\sum _ {k=0}^{K}{}^{\prime \prime}\left\{\delta_{k}^{\langle 2 \rangle}\left(\tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k}\right)\right\}\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right)\Delta x.
	\end{align*}
	Next, by the summation by parts formula (Lemma \ref{sbp5}) and \eqref{tool3}, we have  
	\begin{equation*}
		\nu^{2}\sum _ {k=0}^{K}{}^{\prime \prime}\left\{\!\delta_{k}^{\langle 2 \rangle}\!\!\left(\tilde{\Theta}_{1,k} - \tilde{\Theta}_ {2,k}\right)\!\right\}\!\left(\tilde{\Theta}_ {1,k} - \tilde{\Theta}_ {2,k}\right)\Delta x 
		= -\nu^{2}\left\| D\left(\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right)\right\|^{2}.
	\end{equation*}
	% \begin{align*}
	% 	\nu^{2}\sum _ {k=0}^{K}{}^{\prime \prime}\left\{\!\delta_{k}^{\langle 2 \rangle}\!\!\left(\tilde{\Theta}_{1,k} - \tilde{\Theta}_ {2,k}\right)\!\right\}\!\left(\tilde{\Theta}_ {1,k} - \tilde{\Theta}_ {2,k}\right)\Delta x 
	% 		= & -\nu^{2}\sum _ {k=0}^{K-1}\left|\delta_{k}^{+}\left(\tilde{\Theta}_{1,k} - \tilde{\Theta}_ {2,k}\right)\right|^{2}\Delta x \\ 
	% 		& + \nu^{2}\left[\left\{\!\delta_{k}^{\langle 1 \rangle}\!\!\left(\tilde{\Theta}_{1,k} - \tilde{\Theta}_ {2,k}\right)\!\right\}\!\left(\tilde{\Theta}_ {1,k} - \tilde{\Theta}_ {2,k}\right)\right]_{0}^{K} \\
	% 		= & -\nu^{2}\left\| D\left(\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right)\right\|^{2}.
	% \end{align*}
	Similarly, we observe from the summation by parts formul (Lemma \ref{sbp2}), \eqref{bc1}, and \eqref{bc2} that 
	\begin{align*}
		& \frac{\kappa}{2}\sum _ {k=0}^{K}{}^{\prime \prime} \delta_{k}^{+}\left\{
			\alpha\!\left( H_{k}^{(j+1)} \right)\left( \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{2,k}) \right) 
		\right\}\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right)\Delta x \\[-1pt]
		& + \frac{\kappa}{2}\sum _ {k=0}^{K}{}^{\prime \prime} \delta_{k}^{-}\left\{
				\alpha\!\left( H_{k}^{(j+1)} \right)\left( \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right) 
		\right\}\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right)\Delta x \\[-1pt]
		= & - \frac{\kappa}{2}\sum _ {k=1}^{K}\alpha\left( H_{k}^{(j+1)} \right)
			\left( \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{2,k}) \right)  
			\delta_{k}^{-}\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right)\Delta x \\[-1pt]
		& - \frac{\kappa}{2}\sum _ {k=0}^{K-1}\alpha\left( H_{k}^{(j+1)} \right)
			\left( \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right)  
			\delta_{k}^{+}\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right)\Delta x \\[-1pt]
		& + \frac{\kappa}{2}\left[ 
			\left\{ 
				\mu_{k}^{+}\left(
					\alpha\!\left( H_{k}^{(j+1)} \right)\left( \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{2,k}) \right) 
				\right)
		\right.\right. \\[-1pt] 
		& \qquad \left.\left. 
			+ \mu_{k}^{-}\left(
					\alpha\!\left( H_{k}^{(j+1)} \right)\left( \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right) 
				\right)
			\right\} 
			\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right) 
		\right]_{0}^{K} \\[-1pt]
		= & - \frac{\kappa}{2}\sum _ {k=0}^{K - 1}\alpha\left( H_{k + 1}^{(j+1)} \right)
			\left( \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{1,k + 1}) - \gamma_{\varepsilon}' (\delta_{k}^{-}\Theta_{2,k + 1}) \right)  
			\delta_{k}^{-}\left( \tilde{\Theta}_{1, k + 1} - \tilde{\Theta}_{2, k + 1} \right)\Delta x \\[-1pt]
		& - \frac{\kappa}{2}\sum _ {k=0}^{K-1}\alpha\left( H_{k}^{(j+1)} \right)
			\left( \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right)  
			\delta_{k}^{+}\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right)\Delta x \\[-1pt]
		= & - \kappa\sum _ {k=0}^{K-1}\frac{\alpha\left( H_{k+1}^{(j+1)} \right) + \alpha\left( H_{k}^{(j+1)} \right)}{2}
		\left( \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right)  
			\delta_{k}^{+}\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right)
		\Delta x. 
	\end{align*}
	Thus, using the Young inequality and Lemma \ref{lem:4.2}, we obtain 
	\begin{align*}
		& \frac{1}{\delta_{0}\Delta t}\left\|\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right\|_{L_{\rm d}^{2}}^{2} \\
		\leq & -\nu^{2}\left\| D\!\left(\! \bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2} \!\right)\right\|^{2} 
		- \kappa\sum _ {k=0}^{K-1}\frac{\alpha\!\left(\! H_{k+1}^{(j+1)} \!\right) \! + \! \alpha\!\left(\! H_{k}^{(j+1)} \!\right)}{2}
			\left( \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right)  
			\delta_{k}^{+}\!\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right)
		\Delta x \\
		\leq & -\nu^{2}\left\| D\left(\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right)\right\|^{2} \\
		& + \kappa\sum _ {k=0}^{K-1}\left\{
			\frac{\kappa}{4\nu^{2}}
			\frac{ \left|\alpha\!\left( H_{k+1}^{(j+1)} \right) + \alpha\!\left( H_{k}^{(j+1)} \right) \right|^{2}}{4}
			\left| \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{1,k}) - \gamma_{\varepsilon}' (\delta_{k}^{+}\Theta_{2,k}) \right|^{2} + \frac{\nu^{2}}{\kappa}
			\left| \delta_{k}^{+}\left( \tilde{\Theta}_{1, k} - \tilde{\Theta}_{2, k} \right) \right|^{2}
		\right\}\Delta x \\
		\leq & \frac{\kappa^{2}}{4\nu^{2}}\sum _ {k=0}^{K-1}
			\frac{ \left|\alpha\!\left( H_{k+1}^{(j+1)} \right) \right|^{2} + \left|\alpha\!\left( H_{k}^{(j+1)} \right) \right|^{2}}{2}
			\left| \frac{d\gamma_{\varepsilon}''}{d( \delta_{k}^{+}\Theta_{1,k} , \delta_{k}^{+}\Theta_{2,k} )} \right|^{2} 
			\left| \delta_{k}^{+}\left( \Theta_{1,k} - \Theta_{2,k} \right) \right|^{2}
		\Delta x. 
	\end{align*}
	Meanwhile, we see from $|uv| \leq \sqrt{\varepsilon^{2} + u^{2}}\sqrt{\varepsilon^{2} + v^{2}}$ that 
	\begin{align*}
		0 \leq \frac{d\gamma_{\varepsilon}''}{d(u,v)} 
		= & \frac{\varepsilon^{2} + \sqrt{\varepsilon^{2} + u^{2}}\sqrt{\varepsilon^{2} + v^{2}} - uv }{\sqrt{\varepsilon^{2} + u^{2}}\sqrt{\varepsilon^{2} + v^{2}}\left(\sqrt{\varepsilon^{2} + u^{2}} + \sqrt{\varepsilon^{2} + v^{2}}\right)} \\ 
		\leq & \frac{\varepsilon^{2} + 2\sqrt{\varepsilon^{2} + u^{2}}\sqrt{\varepsilon^{2} + v^{2}} }{\sqrt{\varepsilon^{2} + u^{2}}\sqrt{\varepsilon^{2} + v^{2}}\left(\sqrt{\varepsilon^{2} + u^{2}} + \sqrt{\varepsilon^{2} + v^{2}}\right)} \\
		\leq & \frac{\varepsilon^{2} }{\sqrt{\varepsilon^{2} + u^{2}}\sqrt{\varepsilon^{2} + v^{2}}\left(\sqrt{\varepsilon^{2} + u^{2}} + \sqrt{\varepsilon^{2} + v^{2}}\right)} 
		+ \frac{2}{\sqrt{\varepsilon^{2} + u^{2}} + \sqrt{\varepsilon^{2} + v^{2}}} \\
		\leq & \frac{\varepsilon^{2}}{\varepsilon \cdot \varepsilon (\varepsilon + \varepsilon)} + \frac{2}{\varepsilon + \varepsilon} = \frac{3}{2\varepsilon},
	\end{align*}
	Furthermore, by \eqref{al_bd} and the above inequality, we conclude that 
	\begin{align*}
		\frac{1}{\delta_{0}\Delta t}\left\|\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right\|_{L_{\rm d}^{2}}^{2} 
		\leq & \frac{9\kappa^{2}}{16\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}
		\sum _ {k=0}^{K-1}
			\left| \delta_{k}^{+}\left( \Theta_{1,k} - \Theta_{2,k} \right) \right|^{2}
		\Delta x \\
		= & \frac{9\kappa^{2}}{16\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}
		\sum _ {k=0}^{K-1}
			\frac{\left| \left( \Theta_{1,k+1} - \Theta_{2,k+1} \right) - \left( \Theta_{1,k} - \Theta_{2,k} \right) \right|^{2}}{(\Delta x)^{2}}
		\Delta x \\
		\leq & \frac{9}{8(\Delta x)^{2}}\frac{\kappa^{2}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}
		\sum _ {k=0}^{K-1}
			\left( \left|\Theta_{1,k+1} - \Theta_{2,k+1}\right|^{2} + \left|\Theta_{1,k} - \Theta_{2,k}\right|^{2} \right) 
		\Delta x \\
		= & \frac{9}{4(\Delta x)^{2}}\frac{\kappa^{2}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}
		\left\|\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right\|_{L_{\rm d}^{2}}^{2}. 
	\end{align*}
	Namely, we obtain 
	\begin{equation*}
		\left\|\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right\|_{L_{\rm d}^{2}}^{2} 
		\leq \frac{9\Delta t}{4(\Delta x)^{2}}\frac{\kappa^{2}\delta_{0}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2}
		\left\|\bm{\tilde{\Theta}}_{1} - \bm{\tilde{\Theta}}_{2}\right\|_{L_{\rm d}^{2}}^{2}. 
	\end{equation*}
	Since 
	\begin{equation*}
		0 \leq \frac{9\Delta t}{4(\Delta x)^{2}}\frac{\kappa^{2}\delta_{0}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2} < \frac{4\Delta t}{(\Delta x)^{2}}\frac{\kappa^{2}\delta_{0}}{\nu^{2}\varepsilon^{2}}\left(\delta_{0} + \frac{1}{2}\right)^{2} <1
	\end{equation*}
	from the assumption \eqref{exist_cond2}, the mapping $\Phi$ is contraction into $X$. 
	This completes the proof.  
\end{proof}

