A corollary of \Cref{coerecivity-lemma1} is
$$
\|\nabla\tau\|^2_{L^2}\leq 8\|\nabla\tau^D\|^2_{L^2}+16\|\div\tau\|^2_{L^2}.
$$  
The following result can be found in \cite[Proposition 9.1.1]{MixedFEMbook}.

\begin{lemma}
    For  $\tau\in \Sigma$ and 
    $\int_{\Omega}\mathrm{tr}(\tau)=0$, it holds that  
    % {\color{red}(Shudan: Actually we haven't this condition, it's ok? In Boffi's book, they assume solve the problem in a subspace satisfying this condiditon)} 
    $$
    \|\tau\|_{L^2}\lesssim (\|\tau^D\|_{L^2}+\|\div \tau\|_{L^2}).
    $$
    Here the hidden constant only depends on $\Omega$.
    \label{coerecivity-lemma2}
\end{lemma}

Based on the above lemmas, we can now derive the $\lambda$-independent coercivity, see the following lemma.

\begin{proposition}
For all $\tau\in Z$ (which implies that $\div \tau = 0$) and $\int_{\Omega}\mathrm{tr}(\tau)=0,$
\begin{equation} 
\iota^2(\nabla  \mathcal{A} \tau,\nabla  \tau)+( \mathcal{A}\tau, \tau) \gtrsim \|\tau\|^2_{\iota}.\
\label{coercivity-cont.}
\end{equation}
\end{proposition}
\begin{proof}
   \Cref{coerecivity-lemma2} and \eqref{Corecivity-elasticity-cont.} indicate that 
  $$
  \|\tau\|_{L^2}\lesssim \|\tau^D\|_{L^2}\leq 2\mu(\mathcal{A}\tau,\tau),
  $$
  when $\tau\in Z$ and $\int_{\Omega}\mathrm{tr}(\tau)=0$. Applying gradient operator to \eqref{Corecivity-elasticity-cont.}, we obtain 
  $$
  \|\frac{1}{4}\nabla\tau\|_{L^2}\leq \|\nabla\tau^D\|_{L^2}\leq 2\mu(\nabla\mathcal{A}\tau,\nabla\tau),~\forall \tau\in Z.
  $$
Thus we finish the proof.  
\end{proof}


%{\color{red}The inf-sup condition of $b(\sigma,v)$ can be obtained following the same step in Lemma 2.4 of \cite{GuzmanAfiled, PaulyZulehner23}(I move those two reference to the contribution of FEM for linear elasticity problem ),}
The following lemma gives the inf-sup condition of $b(\sigma,v)$, which is a standard result for linear elasticity equations \cite{MixedFEMbook}.
\begin{lemma}
    For any $v\in Q$, there exists a $\tau\in \Sigma$ such that
    $$
    \mathrm{div}\tau = v,~\|\tau\|_{\iota}\lesssim  \|v\|_{L^2}.
    $$
    \label{inf-sup-cont.}
\end{lemma}
\begin{proof} 
For all $v\in Q$, there exists a exact solution $u\in H^2(\Omega)\cap H_0^1(\Omega)$, such that
$$
-\div(2\mu \operatorname{sym} \operatorname{grad} (u)+\lambda\div uI)= v, 
$$
and $\|u\|_{H^2}+\lambda\|\div u\|_{L^2}\leq \|v\|_{L^2}$.
Let $$\tau = 2\mu \operatorname{sym} \operatorname{grad} (u)+\lambda\div u I\in \Sigma.$$ By noticing the fact $\|\tau\|_{\iota}\leq 2\|\tau\|_{H^1}$ we finish the proof.
\end{proof}
% By \eqref{coercivity-cont.} and Lemma \ref{inf-sup-cont.}, the well-known Brezzi Theorem shows the well-posedness of \eqref{lsg-weak}. 
By the Ladyzhenskaya-Babu\v{s}ka-Brezzi theory, we establish the wellposedness of problem \eqref{lsg-weak}.
\begin{theorem}
    For all $f\in L^2(\Omega;\mathbb R^2)$, there exists a unique solution pair $(\sigma_0,u_0)\in \Sigma\times Q$ of \eqref{lsg-weak}, such that
    $$
    \|\sigma_0\|_{\iota}+\|u_0\|_{L^2}\lesssim \|f\|_{L^2}.
    $$
    Here the hidden constant is independent of $\iota$ and $\lambda$.
\end{theorem}

\begin{proof}
Since $\|\sigma\|_{\iota}\geq \|\div\sigma\|_{L^2}$, the boundedness property of $b(\sigma,v)$ is trivial. By inf-sup stability, there exists unique $\sigma^{\perp}\in Z^{\perp}$, the orthogonal complement of $Z$ in $\Sigma$ with respect to $\iota$ norm, such that
$$
b(\sigma^{\perp},v)=(f,v),~\forall v\in Q, \text{ and } \|\sigma^{\perp}\|_{\iota}\lesssim \|f\|_{L^2}.
$$
By \eqref{Corecivity-elasticity-cont.}, and fact $\|\mathrm{tr}(\sigma)\|_{L^2}\leq 2\|\sigma\|_{L^2},$ we have  
$$
a_{\iota}(\sigma,\tau)\leq (\frac{1}{2\mu}+\frac{1}{(\lambda+\mu)})(\|\sigma\|_{L^2}\|\tau\|_{L^2}+\iota^2\|\nabla\sigma\|_{L^2}\|\nabla\tau\|_{L^2}),~\forall~\tau,\sigma\in \Sigma.
$$
By Lax-Milgram Theorem, there exists $\sigma^0\in Z$, such that
$$
a_{\iota}(\sigma^0,\tau_z)=-a_{\iota}(\sigma^{\perp},\tau_z),~\forall~\tau_z\in Z,
$$
and  $\|\sigma^0\|_{\iota}\lesssim \|\sigma^{\perp}\|_{\iota}.$ Then $\sigma_0 = \sigma^{\perp}+\sigma^0$ is the unique solution of \eqref{lsg-weak}. Finally, by the inf-sup condition again and the first equation of \eqref{lsg-weak}, we obtain there exists $u_0\in Q$, such that
$$
b(\tau,u_0)=-a_{\iota}(\sigma_0,\tau),~\forall~\tau\in Z^{\perp},
$$
and $\|u_0\|_{L^2}\lesssim\|\sigma_0\|_{\iota}.$ Thus we finish the proof.
%The inf-sup condition stated in Lemma 2.3 and the coercivity property given in Lemma 2.2 lead to this proof.
\end{proof}




\section{Stable Finite Element Pairs for stress gradient elasticity}
\label{sec:discrete}
This section constructs a family of stable pairs for stress gradient elasticity. Specifically, we seek a stress-displacement pair $(\Sigma_h, Q_h) \in H^1(\Omega; \mathbb{S}^2) \times L^2(\Omega; \mathbb{R}^2)$ such that the divergence operator $\div : \Sigma_h \to Q_h$ is surjective and admits a bounded (generalized) inverse. That is, for each $q_h \in Q_h$, there exists $\sigma_h \in \Sigma_h$ satisfying $\div \sigma_h = q_h$ and $\|\sigma_h\|_{H^1} \lesssim \|q_h\|_{L^2}$. For such a pair, we can consider the discrete problem
\begin{equation}
\begin{cases}
    a_{\iota}(\sigma_h,\tau_h)+b(\tau_h,u_h)=0,& \forall\tau_h\in\Sigma_h,\\
   b(\sigma_h,v_h)=(f,v_h), &\forall v_h\in Q_h.
\end{cases}
\label{lsg-discrete}
\end{equation}
The wellposedness and the error estimates of the discrete problem are discussed in \Cref{sec:error}. 

% As indicated in the introductory part, the primary objective of this section is to explore the CG-DG pair (Scott--Vogelius pair) in the context of stress gradient elasticity and to identify mesh conditions ensuring stability, which is the key to the error analysis.  

We define the following stress spaces
$$\Sigma^0_{k} = \{  \sigma \in C^0(\mathcal T;\mathbb S^2) : \sigma|_T \in P_{k} \otimes \mathbb S^2,  \sigma \in C^0(\mathcal V)\},$$
$$\Sigma^1_{k} = \{ \sigma \in C^0(\mathcal T;\mathbb S^2) : \sigma|_T \in P_{k} \otimes \mathbb S^2,  \sigma \in C^1(\mathcal V)\},$$
$$\Sigma^2_{k} = \{ \sigma \in C^0(\mathcal T;\mathbb S^2) : \sigma|_T \in P_{k} \otimes \mathbb S^2, \sigma \in C^2(\mathcal V)\}.$$
Here, $\sigma \in C^0(\mathcal V)$ means that $\sigma$ is continuous at vertices, $\sigma \in C^{r}(\mathcal V)$ means that $\nabla^{r'} \sigma$ is continuous at vertices for $0 \le r' \le r.$

Accordingly, we define the following displacement space.  
$$Q^{-1}_{k-1} = \{ q \in L^2(\mathcal T;\mathbb R^2) : q|_T \in P_{k-1} \otimes \mathbb R^2\},$$
$$Q^0_{k-1} = \{ q\in L^2(\mathcal T;\mathbb R^2) : q|_T \in P_{k-1} \otimes \mathbb R^2, q \in C^0(\mathcal V)\},$$
$$Q^1_{k-1} = \{ q \in L^2(\mathcal T;\mathbb R^2) : q|_T \in P_{k-1} \otimes \mathbb R^2,q\in C^1(\mathcal V)\}.$$

To address the rank deficiency and the stability issue caused by the geometric structure, we define two types of singularities, the first being the criss-cross singularity (Type I). Such singularities have been thoroughly investigated in the Stokes' pair \cite{ScottVogelius85,GuzmanScott19}, and the construction of the $C^1$ spline space on general triangular meshes \cite{MorganScott75}.

\begin{definition}[Type I Singularity]
A vertex $v$ is said to have a Type I singularity if and only if it is an interior vertex and all edges incident to $v$ lie on at most two distinct lines.
\end{definition}



The second type of singularity is the three-line-cross singularity (Type II), which is not fully addressed in the literature.

\begin{definition}[Type II Singularity]
A vertex $v$ is said to have a Type II singularity if and only if it is an interior vertex and all edges incident to $v$ lie on exactly three distinct lines. A singular vertex is called \emph{non-degenerate} if it is surrounded by six elements (see \Cref{fig:typeII-non}); otherwise, it is called \emph{degenerate} (see \Cref{fig:typeII-de}).
\end{definition}


