Using the notations introduced above, we can define a measure to quantify the extent to which a triangulation is singular or nearly singular with respect to Type I or Type II singularities. 
For any interior vertex $x \in \mathcal{V}$, we define
\begin{equation}
\label{eq:theta_I}
\Theta_I(x) := \max \{ |\sin(\theta_i + \theta_{i+1})| \},
\end{equation}
where the maximum is taken over all $i$ in the patch $\st x$. It can be verified that $\Theta_I(x) = 0$ if and only if $x \in \mathcal{V}_I$. Similarly, we define
\begin{equation}
\label{eq:theta_II}
\Theta_{II}(x) := \max \{ \min ( |\sin(\theta_i + \theta_{i+1} + \theta_{i+2})|, |\sin(\theta_i + \theta_{i+1})|, |\sin(\theta_{i+1} + \theta_{i+2})| ) \},
\end{equation}
for any interior vertex $x \in \mathcal{V}$, where the maximum is taken over all $i$ in the patch $\st x$. It can be verified that $\Theta_{II}(x) = 0$ if and only if $x \in \mathcal{V}_I$ or $x \in \mathcal{V}_{II}$.  

In this section, the hidden constants in $\lesssim$ might depend on the region $\Omega$, the polynomial degree $k$, and the shape regularity constant, but independent with the triangulation $\mathcal T$. The dependency on triangulations will be given explicitly via $\Theta_I(x)$ or $\Theta_{II}(x)$. 

\begin{remark}
The quantities mentioned above are defined only for the interior vertices. For the boundary vertices, we will see that they will never contribute to the cokernels of divergence operators.
\end{remark}


\subsection{The Pair $\Sigma_k^2 \times Q_{k-1}^1$: Unconditional Stability and Discrete Complexes} 

In this subsection, we show that the pair $\Sigma_k^2 \times Q_{k-1}^1$ is unconditionally stable with respect to both types of singularities. The main theorem is summarized as follows.
\begin{theorem}
\label{thm:c2}
The divergence operator $\div : \Sigma_k^2 \to Q_{k-1}^1$ is surjective for any mesh $\mathcal T$, provided that $k \ge 7$. Moreover, if $\mathcal T$ is shape regular, then for each $q  \in Q_{k-1}^1$, there exists $\sigma \in \Sigma_k^2$ such that $\div \sigma = q $ and $\|\sigma \|_{H^1} \lesssim \|q\|_{L^2}.$ 
\end{theorem}


\Cref{thm:c2} establishes that unconditional stability is achieved by imposing $C^2$ continuity at the vertices in the stress element space $\Sigma_k^2$ and $C^1$ continuity at the vertices in the displacement element space $Q_{k-1}^1$.

This theorem arises from a finite element discretization of the smoothed stress complex \eqref{eq:complex-sobolev}. To elucidate this, we recall the $H^3$-conforming finite element $U_{k+2}^4$ from \cite{Zenisek74,HuLinWu24}, defined for $k \ge 7$. The local shape function space of $U_{k+2}^4$ is the polynomial space $P_{k+2}$. For $u \in P_{k+2}$ on an element $T$, the degrees of freedom are given as follows:
\begin{enumerate}
	\item $\nabla^{\alpha} u(v)$ for each vertex $v$ with $|\alpha| \le 4$;
	\item $\int_e u \, p \, ds$ for $p \in P_{k-8}(e)$, $\int_e \frac{\partial u}{\partial n} p \, ds$ for $p \in P_{k-7}(e)$, and $\int_e \frac{\partial^2 u}{\partial n^2} p \, ds$ for $p \in P_{k-6}(e)$, for each edge $e$ of $T$;
	\item $\int_T u \, p \, dx$ for $p \in P_{k-7}(T)$.
\end{enumerate}
It can be readily checked that the finite element $U_{k+2}^4$ is unisolvent, and the resulting space is $H^3$-conforming.

The local shape function space of $\Sigma_k^2$ is $P_{k} \otimes \mathbb S^2$, and for $\sigma \in P_{k} \otimes \mathbb S^2$, the degrees of freedom are given as follows: 
\begin{enumerate}
    \item $\nabla^{\alpha} \sigma(v)$ for each vertex $v$ of $T$ and $|\alpha| \le 2$;
    \item $\int_e \sigma : p $ for $p \in P_{k-6}(e) \otimes \mathbb S^2$ for each edge $e$ of $T$; 
    \item $\int_ T \sigma : p $ for $p \in P_{k-3}^{(0)}(T) \otimes \mathbb S^2.$ 
     Here $P_{k-3}^{(0)}(T) := \{ p \in P_{k-3}(T) : p(v) = 0,\,\, \forall v \in \mathcal V(T)\}.$
\end{enumerate}

Then, we can construct the following sequence: 
\begin{equation}
\label{eq:complex-fe}
\mathbf{P}_1~ {\hookrightarrow}~ U^4_{k+2}(\mathcal T) \xrightarrow{\curl\curl^T} \Sigma_{k}^2 (\mathcal T) \xrightarrow{\div} Q_{k-1}^1(\mathcal T) \to 0.
\end{equation}

The exactness of \eqref{eq:complex-fe} can be checked from direct calculation.
\begin{proposition}
\label{prop:complex-fe}
The finite element sequence \eqref{eq:complex-fe} forms a complex. When $\Omega$ is topologically trivial, this sequence is exact.
\end{proposition}

\begin{proof}
To establish exactness, it suffices to verify the dimension count for the sequence \eqref{eq:complex-fe}. By direct calculation, we obtain the following dimensions:
\begin{align*}
\dim U_{k+2}^4(\mathcal{T}) &= \frac{1}{2}(k-6)(k-5) |\mathcal{T}| + (3k-21) |\mathcal{E}| + 15 |\mathcal{V}|, \\
\dim \Sigma_k^2(\mathcal{T}) &= \left( \frac{3}{2}(k+2)(k+1) - 9(k+1) \right) |\mathcal{T}| + (3k-18) |\mathcal{E}| + 18 |\mathcal{V}|, \\
\dim Q_{k-1}^1(\mathcal{T}) &= (k(k+1) - 18) |\mathcal{T}| + 6 |\mathcal{V}|.
\end{align*}
Since
\[
\dim U_{k+2}^4(\mathcal{T}) - \dim \Sigma_k^2(\mathcal{T}) + \dim Q_{k-1}^1(\mathcal{T}) = 3 (|\mathcal{T}| - |\mathcal{E}| + |\mathcal{V}|) = 3,
\]
where the final equality holds for a topologically trivial domain $\Omega$ by the Euler equation, it then follows that the finite element sequence is exact.
\end{proof}

To establish the stability results, we begin by proving the following results, which provides the exactness of the bubble stress complex. We define the local bubble spaces $\mathring{U}_{k+2}(T)$, $\mathring{\Sigma}_k(T)$, and $\mathring{Q}_{k-1}(T)$ on each element $T \in \mathcal{T}$ as follows respectively:
\begin{align*}
\mathring{U}_{k+2}(T) &:= \left\{ u \in P_{k+2}(T) : \nabla^{\alpha} u(v) = 0, \, \forall |\alpha| \le 4, \, u|_{\partial T} = \frac{\partial u}{\partial n}\big|_{\partial T} = \frac{\partial^2 u}{\partial n^2}\big|_{\partial T} = 0 \right\}, \\
\mathring{\Sigma}_k(T) &:= \left\{ \sigma \in P_k(T; \mathbb{S}^2) : \nabla^{\alpha} \sigma(v) = 0, \, \forall |\alpha| \le 2, \, \sigma|_{\partial T} = 0 \right\}, \\
\mathring{Q}_{k-1}(T) &:= \left\{ q \in P_{k-1}(T; \mathbb{R}^2) : \nabla^{\alpha} q(v) = 0, \, \forall |\alpha| \le 1 \right\}.
\end{align*}

\begin{proposition}
\label{prop:bubble-complex}
The following sequence on each element $T \in \mathcal{T}$:
\begin{equation}
\label{eq:bubble-complex}
0 \to \mathring{U}_{k+2}(T) \xrightarrow{\curl \curl^T} \mathring{\Sigma}_k(T) \xrightarrow{\div} \mathring{Q}_{k-1}(T) \cap \mathbf{RM}^{\perp} \to 0,
\end{equation}
forms a complex and is exact. {Here $\cap \mathbf{RM}^{\perp}$ means that the $\mathbf{RM}$ moment is zero.}
\end{proposition}

\begin{proof}
It is straightforward to see \eqref{eq:bubble-complex} is a complex. For exactness, it suffices to verify the dimension count. We compute the dimensions of the local bubble spaces as follows:
\begin{align*}
\dim \mathring{U}_{k+2}(T) &= \dim P_{k-7}(T) = \frac{1}{2}(k-6)(k-5), \\
\dim \mathring{\Sigma}_k(T) &= 3 \dim P_k(T) - 9(k+1) - 18 = \frac{3}{2}(k+2)(k+1) - 9(k+1) - 18, \\
\dim \mathring{Q}_{k-1}(T) &= 2 \dim P_{k-1}(T) - 12 = k(k+1) - 12.
\end{align*}
It follows that
\[
\dim \mathring{U}_{k+2}(T) - \dim \mathring{\Sigma}_k(T) + \dim \mathring{Q}_{k-1}(T) = 3 = \dim \mathbf P_1.
\]
Therefore, we conclude the exactness.
\end{proof}

By the surjectivity result and scaling argument, we have the bubble stability.

\begin{corollary}[Bubble Stability]
\label{cor:bubble-stable}
Suppose that $k \ge 7$. For any $q \in P_{k-1}(T; \mathbb{R}^2)$ satisfying:
\begin{enumerate}
	\item $q(v) = \nabla q(v) = 0$ for all vertices $v \in \mathcal{V}(T)$, and
	\item $\int_T q \cdot p \, dx = 0$ for all $p \in \mathbf{RM}$,
\end{enumerate}
there exists $\sigma \in \mathring{\Sigma}_k(T; \mathbb{S}^2)$ such that $\div \sigma = q$ and
\[
\|\sigma\|_{H^1} \lesssim \|q\|_{L^2},
\]
where the hidden constant depends only on the shape-regularity constant of $T$.
\end{corollary}


Now the proof of \Cref{thm:c2} follows a standard argument \cite{FalkNeilan13,HuZhang14}, with the help of discrete complexes. 
\begin{proof}[Proof of \Cref{thm:c2}]

Given any $q_h\in Q_{k-1}^1 \subset L^2(\mathbb R^2)$, it suffices to show that there exists $\tau\in H^1(\mathbb S^2)$ such that $\mathrm{div}\tau=q_h.$ The proof will be divided into two steps. 

In the first step, we select $\sigma^{(1)} \in \Sigma_k^2$ such that

\begin{enumerate}
    \item For all vertices $v$,$\sigma_{i,j}^{(1)}(v) = 0,  \partial_{x} \sigma_{i,j}^{(1)}(v)  = \partial_{x} \sigma_{i,j}^{(1)}(v) = \frac{1}{2}q_h(v),
$ and 
$ 
\partial_{xx} \sigma_{ij}^{(1)}(v)  =  \partial_{x} q_h(v), \partial_{yy} \sigma_{i,j}^{(1)}(v) =\partial_{y} q_h(v), \partial_{x,y} \sigma_{i,j}^{(1)}(v) = 0.
$
\item For all $e\in\mathcal{E}$ and $p \in P_{k-6}(T) \otimes \mathbb S^2$,  
$
\int_e\sigma^{(1)} : p=\int_e\tau_h : p.
$
Here $n_e$ is the unit normal vector of edge $e$. 
\item 
For all $T\in\mathcal{T}$, for all $p\in P_{k-3}^0(T) \otimes \mathbb{S}^2$, 
$
\int_T \sigma^{(1)} : p= \int_T \tau_h : p.
$
\end{enumerate}


It can be checked that at each vertex $v \in \mathcal V$, we have 
$
\mathrm{div}\sigma^{(1)}(v)=q_h(v),~\nabla\mathrm{div}\sigma^{(1)}(v) = \nabla q_h(v).
$
Moreover, for $k\geq 7$, it holds that
$$
\int_T\mathrm{div}\sigma^{(1)}\cdot p=\int_{\partial T}\sigma^{(1)}n_{\partial T} \cdot p=\int_{\partial T}\tau n_{\partial T}\cdot p=\int_T\mathrm{div}\tau\cdot p=\int_T q_h\cdot p,~p\in \mathbf{RM}.
$$
This comes from the fact that $p \cdot n_{e}$ is linear function for all $p \in \mathbf{RM}.$ 


In the second step, we notice that in each $T$, it holds that $q_h - \div \sigma^{(1)} \in \mathring{Q}_{k-1}(T) \cap \mathbf{RM}^{\perp}.$ 
By \Cref{cor:bubble-stable}, there exist $\sigma^{(2)}\in \Sigma,~\sigma^{(2)}|_T\in \mathring{\Sigma}_{k}(T) $, such that
$$
\mathrm{div}\sigma^{(2)} = q_h-\mathrm{div}\sigma^{(1)},\text{ and }\|\sigma^{2}\|_{H^1}\lesssim \| q_h-\div \sigma^{(1)}\|_{ L^2}. 
$$
Let $\sigma=\sigma^{(1)}+\sigma^{(2)}$ we finish the construction.

To complete the proof, it suffices to estimate $\|\sigma\|_{H^1}$. Since $\|\sigma\|_{H^1} \le \|\sigma^{(1)} \|_{H^1} + \|\sigma^{(2)}\|_{H^1} \lesssim \|\sigma^{(1)} \|_{H^1} + \|q_h\|_{L^2}$, it then suffices to estimate $\|\sigma^{(1)}\|_{H^1}.$


Now we give an estimate on $\sigma^{(1)}$.
Let $\tau_h \in \Sigma_k$ be the Scott-Zhang interpolant of $\tau$.
Then $(\sigma^{(1)}-\tau_h)|_T\in \mathcal{P}_k(T;\mathbb{S}^2)$. 

For $\Sigma_k^2$, let $\varphi_{v,0,i}$, $\varphi_{v,1,i}$, $\varphi_{v,2,i}$ be the nodal basis functions associated with function  value $(\cdot)(v) : p_j$ , gradient value $\nabla (\cdot)(v) : p_j$ and Hessian value $\nabla^2 (\cdot)(v) : p_j$, respectively. $\varphi_{e,j}$ is the nodal basis function corresponding to degrees of freedom $\int_e (\cdot) p_j$ and $\varphi_{T,j}$ for $\int_T(\cdot)p_j.$  
Expend $(\sigma^{(1)}-\tau_h)$ by the set of basis function of $\Sigma(T)$, we then have
\begin{align*}
    \|\sigma^{(1)}-\tau_h\|_{H^1(T)}&=\|\sum_{i=0}^{2}\sum_{v\in\mathcal{V}(T)}\nabla^i(\sigma^{(1)}-\tau_h)(v)\varphi_{v,i}+\sum_j\sum_{e\in\mathcal{E}(T)}\int_{e}(\sigma^{(1)}-\tau_h)p_j \varphi_{e,j} \\
    &+\sum_j\int_T(\sigma^{(1)}-\tau_h)p_j\varphi_{T,j}  \|_{H^1(T)}.
\end{align*}
By scaling argument, 
\begin{align*} 
&\|\sum_j \sum_{v\in\mathcal{V}(T)}\nabla^i(\sigma^{(1)}-\tau_h):p_j (v)\varphi_{v,i,j}\|^2_{H^1(T)}\lesssim \sum_{a\in \mathcal{V}(T)}(h_T^i|\nabla^i\tau_h(a)|^2+h_T^2|q_h(a)|^2+h_T^4|\nabla q_h(a)|^2);\\
&\|\sum_j\sum_{e\in\mathcal{E}(T)}\int_{e}(\sigma^{(1)}-\tau_h)q_j \varphi_{e,j}\|_{H^1(T)}=\|\sum_j\sum_{e\in\mathcal{E}(T)}\int_{e}(\tau-\tau_h)q_j \varphi_{e,j}\|_{H^1(T)}\lesssim h_T^{-1/2}\|\tau-\tau_h\|_{L^2(\partial T)};\\
&\|\sum_j\int_T(\sigma^{(1)}-\tau_h)q_j \varphi_{T,j}  \|_{H^1(T)}
\lesssim \|\sum_j\int_T(\tau-\tau_h)q_j\varphi_{T,j}  \|_{H^1(T)}
\lesssim h_T^{-1}\|\tau-\tau_h\|_{L^2(T)}.
\end{align*} 

By applying a scaling argument and the inverse inequality, we obtain
\[
\|\sigma^{(1)} - \tau_h\|_{H^1({T})} \lesssim \|\tau\|_{H^1(\widetilde{T})} + \|q_h\|_{L^2(\widetilde{T})},
\]
where $\tilde{T}$ denotes the union of all elements adjacent to $T$. Consequently, by shape regularity we have 
\[
\|\sigma^{(1)}\|_{H^1} \lesssim \|\tau_h\|_{H^1} + \|\tau\|_{H^1} + \|q_h\|_{L^2} \lesssim \|q_h\|_{L^2}.
\]





\end{proof}





