\begin{lemma}[Necessary condition for Type I singularity]
\label{lem:necessary-type-I}
Let $z$ be a Type I singular vertex, with four elements $T_1, T_2, T_3, T_4$ sharing $z$, as shown in Figure~\ref{fig:Type I}. Then for any continuous, piecewise $C^2$, symmetric matrix-valued function $\tau \in C^0(\st  z)$, it holds that
\begin{equation}\label{eq:type I}
J_{z,T_1} : \nabla \div \tau |_{T_1}(z) + J_{z,T_2} : \nabla \div \tau |_{T_2}(z) + J_{z,T_3} : \nabla \div \tau |_{T_3}(z) + J_{z,T_4} : \nabla \div \tau |_{T_4}(z) = 0.
\end{equation}
\end{lemma}
\begin{proof}
Without loss of generality, we rotate the edge $\overline{zy_1}$ to align with the $x$-axis, and set $z$ as the origin. In this case, $\alpha = 0$ and we define $\theta$ as the angle between $\overline{zy_2}$ and the $x$-axis. Consider the transformation:
\[
\begin{pmatrix}
\tilde{x} \\
\tilde{y}
\end{pmatrix}
=
\begin{pmatrix}
1 & 0 \\
\cos\theta & \sin\theta
\end{pmatrix}
\begin{pmatrix}
x \\
y
\end{pmatrix}.
\]
By direct computation within a single element, we obtain the following results when evaluating at $z$:
\begin{align*}
\partial_x(\mathrm{div}\tau)_1 &= \partial^2_{\tilde{x}}\tau_{11} + 2\cos\theta\partial^2_{\tilde{x}\tilde{y}}\tau_{11} + \sin\theta\partial^2_{\tilde{x}\tilde{y}}\tau_{12} + \cos^2\theta\partial^2_{\tilde{y}}\tau_{11} + \cos\theta\sin\theta\partial^2_{\tilde{y}}\tau_{12}, \\ 
\partial_y(\mathrm{div}\tau)_1 &= \sin\theta\partial^2_{\tilde{x}\tilde{y}}\tau_{11} + \sin\theta\cos\theta\partial^2_{\tilde{y}}\tau_{11} + \sin^2\theta\partial^2_{\tilde{y}}\tau_{12}, \\
\partial_x(\mathrm{div}\tau)_2 &= \partial^2_{\tilde{x}}\tau_{12} + 2\cos\theta\partial^2_{\tilde{x}\tilde{y}}\tau_{12} + \sin\theta\partial^2_{\tilde{x}\tilde{y}}\tau_{22} + \cos^2\theta\partial^2_{\tilde{y}}\tau_{12} + \sin\theta\cos\theta\partial^2_{\tilde{y}}\tau_{22}, \\
\partial_y(\mathrm{div}\tau)_2 &= \sin\theta\partial^2_{\tilde{x}\tilde{y}}\tau_{12} + \sin\theta\cos\theta\partial^2_{\tilde{y}}\tau_{12} + \sin^2\theta\partial^2_{\tilde{y}}\tau_{22}.
\end{align*}
Eliminating the mixed derivatives, we find the following identity holds at $z$:
\begin{align*} 
J_{z,T_1} &: \nabla\mathrm{div}\tau|_{T_1}= \sin\theta\partial^2_{\tilde{x}}\tau_{11} - \sin\theta\cos^2\theta\partial^2_{\tilde{y}}\tau_{11} - 3\cos\theta\sin^2\theta\partial^2_{\tilde{y}}\tau_{12} - \sin^3\theta\partial^2_{\tilde{y}}\tau_{22}.
\end{align*}
Since $\tau$ is continuous, it follows that $\partial^2_{\tilde{x}}\tau$ is continuous on $\overline{zy_1}, \overline{zy_3}$ and $\partial^2_{\tilde{y}}\tau$ is continuous on $\overline{zy_2}, \overline{zy_4}$. Therefore, for the values at $z$ we have 
$$J_{z,T_1} : \nabla\mathrm{div}\tau|_{T_1} + J_{z,T_2} : \nabla\mathrm{div}\tau|_{T_2} + J_{z,T_3} : \nabla\mathrm{div}\tau|_{T_3} + J_{z,T_4} : \nabla\mathrm{div}\tau|_{T_4}  = 0.$$
\end{proof}


