The above lemma implies that functions in $\Sigma_k^1$ supported on $T$ can be used to adjust the values of $\nabla \div \varphi$ when it lies in $\mathcal{N}_{z,T}$. We now proceed with the proof through a case-by-case analysis, starting with the nonsingular case. The proof strategy follows that of \cite{GuzmanScott19}. 

Suppose that $z\in \mathcal{V} \setminus \mathcal{V}_I$ is a nonsingular vertex.  The aim of the following analysis is to show that for any multi-valued vector-valued function $q \in Q_{k-1}^0$ we can find $\sigma \in \Sigma_k^1$ such that $\div \sigma(z) = q(z)$. Furthermore, we obtain bounded estimates whenever $\Theta_I(x)$ is bounded below. The following lemma provides the details.

\begin{lemma}[Gradient Value Modification for the Nonsingular Case]
\label{lem:hm-nonsingular}
For $z \in \mathcal{V} \setminus \mathcal{V}_I$ and any $p \in Q_{k-1}^0$, there exists $\sigma \in \Sigma_k^1$ satisfying:
\begin{enumerate}
\item $\sigma$ is supported in $\st(z)$.
\item $\mathrm{div} \sigma(v) = 0$ for all $v \in \mathcal{V}$.
\item $\nabla \mathrm{div} \sigma(v) = 0$ for all $v \neq z$.
\item $\nabla \mathrm{div} \sigma|_T(z) = \nabla q|_T(z)$ for all $T \in \st(z)$.
\end{enumerate}
Moreover, the bound $\displaystyle \|\sigma\|_{H^1} \lesssim \frac{1}{\Theta_I(z)^2} \|q\|_{L^2(\st(z))}$ holds.
\end{lemma}
\begin{proof}
The construction proceeds in several steps, with the following strategy. We first construct $\tau$ such that $\nabla \div \tau - \nabla q$ lies in the null space $\mathcal{N}_{z,T}$ for each $T \in \st(z)$. Then, we apply \Cref{lem:hm-nonsingular} to adjust the values lying in the null space. For brevity, we denote $J_{z,s} = J_{z,T_s}$ and $\mathcal{N}_{z,s} = \mathcal{N}_{z,T_s}$, where
\[
J_{z,s} = t_s n_{s-1}^T + t_{s-1} n_s^T.
\]

\textbf{Step 1:} We first consider a $T_s$ with $\sin(\theta_s + \theta_{s-1}) = \Theta_I(z) > 0$ and show how to modify the gradient value in $T_s$. 
For such an $s$, define $\sigma_s^+ = \psi_z^3 \psi_s^2 t_{s+1} t_{s+1}^T$. This $\sigma_s^+$ satisfies conditions (1), (2), and (3) of \Cref{lem:hm-nonsingular}. For condition (4), we compute the value separately:
\begin{itemize}
\item In $T_{s+1}$, 
\[
\nabla \div \sigma_s^+|_{T_{s+1}}(z) = (t_{s+1} \cdot \nabla \lambda_{y_s}) \nabla \lambda_{y_s} t_{s+1}^T = 0.
\]
\item In $T_s$,
\[
\nabla \div \sigma_s^+|_{T_s}(z) = (\nabla \lambda_{y_s} \cdot t_{s+1}) \nabla \lambda_{y_s} t_{s+1}^T = -\frac{\sin(\theta_s + \theta_{s+1})}{h_s^2} n_{s-1} t_{s+1}^T.
\]
\end{itemize}
Thus,
\begin{align*}
J_{z,s} : \nabla \div \sigma_s^+|_{T_s}(z) &= (t_s n_{s-1}^T + t_{s-1} n_s^T) : \left( -\frac{\sin(\theta_s + \theta_{s+1})}{h_s^2} n_{s-1} t_{s+1}^T \right) \\
&= \frac{\sin \theta_s}{h_s^2} \sin^2(\theta_s + \theta_{s+1}).
\end{align*}
Since $\sin(\theta_s + \theta_{s-1}) \neq 0$, we define
\[
\tau_s = \frac{h_s^2 (J_{z,s} : \nabla q(z))}{\sin \theta_s \sin^2(\theta_s + \theta_{s+1})} \sigma_s^+,
\]
ensuring $J_{z,s} : \nabla \div \tau_s(z) = J_{z,s} : \nabla q(z)$ in $T_s$. Moreover,
\[
\|\tau_s\|_{H^1} \lesssim \frac{h_s^2 |\nabla q(z)|}{\Theta_I(z)^2} \lesssim \frac{1}{\Theta_I(z)^2} \|q\|_{L^2(\st(z))}.
\]

\textbf{Step 2:} We now adjust the value for other $T_{s'}$, $s' \neq s$ to make sure the modified gradient is in the null space.
Without loss of generality, assume $s' = 1$. For each $r$, define $\sigma_r = \psi_z^3 \psi_r^2 t_r t_r^T$. In $T_r$,
\[
\nabla \div \sigma_r|_{T_r}(z) = (t_r \cdot \nabla \lambda_r) \nabla \lambda_r t_r^T = -\frac{\sin \theta_r}{h_r^2} n_{r-1} t_r^T,
\]
thus it holds that
\[
J_{z,r} : \nabla \div \sigma_r|_{T_r}(z) = (t_r n_{r-1}^T + t_{r-1} n_r^T) : \left( -\frac{\sin \theta_r}{h_r^2} n_{r-1} t_r^T \right) = \frac{\sin^3 \theta_r}{h_r^2}.
\]
In $T_{r+1}$,
\[
\nabla \div \sigma_r|_{T_{r+1}}(z) = \frac{\sin \theta_r}{h_r^2} n_{r+1} t_r^T,
\]
and
\[
J_{z,r+1} : \nabla \div \sigma_r|_{T_{r+1}}(z) = -\frac{\sin^3 \theta_{r+1}}{h_{r+1}^2}.
\]
% Define $A_r = \frac{\sin^3 \theta_r}{h_r^2}$ and $j_r = J_{z,r} : \nabla q(z)$. \lt{why we need to define this.} 
Let $\tilde{\sigma}_r = \frac{h_r^2}{\sin^3 \theta_r} \sigma_r$. Then we have
\[
\|\tilde{\sigma}_r\|_{H^1} \lesssim h_r^2, \quad |J_{z,r+1} : \nabla \div \tilde{\sigma}_r|_{T_{r+1}}(z)| \lesssim 1.
\]
Now let
\[
\tau_1 = \alpha_1 \tilde{\sigma}_1 + \cdots + \alpha_{s-1} \tilde{\sigma}_{s-1} + \tilde{\tau}_s,
\]
where $\alpha_1 = J_{z,1} : \nabla q(z)$, and $\alpha_r = \alpha_{r-1} (J_{z,r} : \nabla \div \tilde{\sigma}_{r-1}|_{T_r}(z))$ for $r = 2, \ldots, s-1$, sequentially. Define
\[
\tilde{\tau}_s = \alpha_{s-1} \frac{h_s^2 (J_{z,s} : \nabla q(z))}{\sin \theta_s \sin^2(\theta_s + \theta_{s+1})} \sigma_s^+.
\]
Thus, $|\alpha_r| \lesssim |\alpha_1| \lesssim |\nabla q(z)|$, and
\[
\|\alpha_r \tilde{\sigma}_r\|_{H^1} \lesssim |\nabla q(z)| h_r^2 \lesssim \|q\|_{L^2(\st(z))}, \quad \|\tilde{\tau}_s\|_{H^1} \lesssim \frac{1}{\Theta_I(z)^2} \|q\|_{L^2(\st(z))}.
\]
This $\tau_1$ satisfies $J_{z,1} : \nabla \div \tau_1|_{T_1}(z) = J_{z,1} : \nabla q(z)$, while $J_{z,s} : \nabla \div \tau_1|_{T_s}(z) = 0$ for $s \neq 1$. Similarly, we can construct $\tau_{s'}$ for other $s' \neq 1$.

\textbf{Step 3:} After the previous two steps, there exists $\tau \in \Sigma_0^k$ such that $\nabla \div \tau - \nabla q$ to lie in $\mathcal{N}_{z,T}$ for all $T \in \st(z)$. Using \Cref{lem:hm-nonsingular}, we conclude the proof.
\end{proof}

\begin{remark}
The above argument assumes that $z$ is an interior vertex. For the case that $z$ is a boundary vertex, we can choose any boundary element $T_s$ in Step 1 and then continue the remaining proof. 	
\end{remark}


Now we focus on the singular case. The idea behind the proof is similar to the non-singular case. 

\begin{lemma}[Gradient Value Modification for the Singular Case]
\label{lem:hm-singular}
For $z \in \mathcal V_I$, and any $q \in Q_{k-1}^0$ such that 
\eqref{eq:hm-cond} holds. 
There exists $\sigma \in \Sigma_{k}^{1}$, such that the following condition holds:
\begin{enumerate}
\item $\sigma$ is supported in $\st z$. 
\item 	$\mathrm{div}\sigma(v)=0,\text{ for all } v\in \mathcal{V}$,
\item	$\nabla\mathrm{div}\sigma(v)=0,~\text{for all } v\neq z$.
\item	$\nabla\mathrm{div}\sigma|_T(z)=\nabla q|_T(z)$ for all $T \in \st z$.
\end{enumerate}
Moreover, it holds that $\|\sigma\|_{H^1} \lesssim \|q\|_{L^2(\st(z))}.$
\end{lemma}
\begin{proof}
The proof is similar to the second step of \Cref{lem:hm-nonsingular}. Note in this case we have $J_{z,r+1} : \nabla \div \tilde \sigma_r|_{T_{r+1}}(z) = 1$. Therefore, we finish the proof.   
\end{proof}

The following theorem gives the full characterization of $\div \Sigma_k^1$. 
\begin{theorem}
\label{thm:hermite}
The divergence of the space $\Sigma_k^1$ is characterized as
\[
\div \Sigma_k^1 = \left\{ q \in Q_{k-1}^0 : J_z : \nabla q_1(v) + J_z : \nabla q_3(v) = J_z : \nabla q_2(v) + J_z : \nabla q_4(v), \ \forall v \in \mathcal{V}_I \right\},
\]
where $q_i := q|_{T_i}$ denotes the restriction of $q$ to element $T_i$ around a singular vertex. Moreover, if $\Theta_I(x) \geq \theta_I > 0$ for all $x \in \mathcal{V} \setminus \mathcal{V}_I$, then for any $q_h \in \div \Sigma_k^1$, there exists $\sigma \in \Sigma_k^1$ such that
\[
\div \sigma = q_h \quad \text{and} \quad \|\sigma\|_{H^1} \lesssim \theta_I^{-2} \|q_h\|_{L^2}.
\]
\end{theorem}

\begin{proof}
By \Cref{lem:hm-nonsingular,lem:hm-singular}, for each vertex $z \in \mathcal{V}$, there exists $\sigma_z \in \Sigma_k^1$ such that:
\begin{itemize}
\item $\sigma_z$ is supported in $\st(z)$,
\item $\nabla \div \sigma_z(v) = 0$ for all $v \neq z$,
\item $\nabla \div \sigma_z|_T(z) = \nabla q|_T(z)$ for all $T \in \st (z)$,
\end{itemize}
with the bound
\[
\|\sigma_z\|_{H^1} \lesssim \theta_I^{-2} \|q\|_{L^2(\st(z))}.
\]
Define $\sigma^{(1)} = \sum_{z \in \mathcal{V}} \sigma_z$. Then, $\nabla \div \sigma^{(1)} - \nabla q$ vanishes at each vertex in $\mathcal{V}$. Since each $\sigma_z$ is supported in $\st(z)$, it follows that
\[
\|\sigma^{(1)}\|_{H^1} \lesssim \theta_I^{-2} \|q\|_{L^2}.
\]
Next, observe that $q^{(1)} := q - \div \sigma^{(1)} \in Q_{k-1}^0$. By the surjectivity of the divergence operator from $\Sigma_k^2$ to $Q_{k-1}^0$, there exists $\sigma^{(2)} \in \Sigma_k^2$ such that
\[
\div \sigma^{(2)} = q^{(1)} = q - \div \sigma^{(1)},
\]
with
\[
\|\sigma^{(2)}\|_{H^1} \lesssim \|q^{(1)}\|_{L^2} \leq \|q\|_{L^2} + \|\div \sigma^{(1)}\|_{L^2} \lesssim \theta_I^{-2} \|q\|_{L^2}.
\]
Finally, set $\sigma = \sigma^{(1)} + \sigma^{(2)}$. Then,
\[
\div \sigma = \div \sigma^{(1)} + \div \sigma^{(2)} = \div \sigma^{(1)} + (q - \div \sigma^{(1)}) = q,
\]
and
\[
\|\sigma\|_{H^1} \leq \|\sigma^{(1)}\|_{H^1} + \|\sigma^{(2)}\|_{H^1} \lesssim \theta_I^{-2} \|q\|_{L^2},
\]
completing the proof.
\end{proof}

