\begin{lemma}[Sufficient Conditions for Nonsingular Vertex]
\label{lem:nonsingular-sufficient}
Suppose $z \in \mathcal{V} \setminus (\mathcal{V}_I \cup \mathcal{V}_{II})$. Then, for any $q \in Q_{k-1}^0$, there exists $\sigma \in \Sigma_k^0$ such that:
\begin{enumerate}
\item $\sigma$ is supported in $\st(z)$.
\item $\div \sigma(v) = 0$ for all $v \neq z$.
\item $\div \sigma|_T(z) = q|_T(z)$ for all $T \in \st(z)$.
\end{enumerate}
Moreover, the bound holds:
\[
\|\sigma\|_{H^1} \lesssim \Theta_{II}(z)^{-2} \|q\|_{L^2(\st(z))}.
\]
\end{lemma}

\begin{proof}
The construction proceeds in several steps.

\textbf{Step 1:}  
Choose an element $T_s \in \st(z)$ such that $|\sin(\theta_s + \theta_{s-1})| \geq \Theta_{II}(z) > 0$ and $|\sin(\theta_s + \theta_{s+1})| \geq \Theta_{II}(z) > 0$. Define
\[
\varphi_{s,-} = \psi_{s-1} \psi_z^2 t_{s-2} t_{s-2}^T, \quad \varphi_{s,+} = \psi_s \psi_z^2 t_{s+1} t_{s+1}^T.
\]
In $T_s$, compute:
\[
\div \varphi_{s,-}|_{T_s}(z) = \frac{\sin(\theta_s + \theta_{s-1})}{h_{s-2}} t_{s-2}, \quad \div \varphi_{s,+}|_{T_s}(z) = \frac{\sin(\theta_s + \theta_{s+1})}{h_s} t_{s+1}.
\]
Since $\sin(\theta_s + \theta_{s\pm 1}) \neq 0$ and $t_{s-2} \neq \pm t_{s+1}$, the vectors $\div \varphi_{s,-}|_{T_s}(z)$ and $\div \varphi_{s,+}|_{T_s}(z)$ form a basis for $\mathbb{R}^2$. Thus, for $q_s(z) = q|_{T_s}(z)$, there exist coefficients $\alpha$ and $\beta$ such that
\[
\alpha \div \varphi_{s,-}|_{T_s}(z) + \beta \div \varphi_{s,+}|_{T_s}(z) = q_s(z),
\]
where
\[
\alpha = \frac{q_s(z) \cdot n_{s+1} h_{s-2}}{(t_{s-2} \cdot n_{s+1}) \sin(\theta_s + \theta_{s-1})}, \quad \beta = \frac{q_s(z) \cdot n_{s-2} h_s}{(t_{s+1} \cdot n_{s-2}) \sin(\theta_s + \theta_{s+1})}.
\]
By shape regularity, $|\alpha|, |\beta| \lesssim \frac{|q_s(z)| h}{\Theta_{II}(z)^2}$. Define
\[
\tau_s = \alpha \varphi_{s,-} + \beta \varphi_{s,+},
\]
so
\[
\|\tau_s\|_{H^1} \lesssim \frac{|q_s(z)| h}{\Theta_{II}(z)^2} \lesssim \Theta_{II}(z)^{-2} \|q\|_{L^2(\st(z))}.
\]
Thus, $\tau_s$ satisfies:
\begin{enumerate}
\item $\div \tau_s|_T(z) = 0$ for $T \neq T_s$,
\item $\div \tau_s|_{T_s}(z) = q_s(z)$,
\item $\div \tau_s(y) = 0$ for all vertices $y \neq z$,
\item $\|\tau_s\|_{H^1} \lesssim \Theta_{II}(z)^{-2} \|q\|_{L^2(\st(z))}$.
\end{enumerate}

\textbf{Step 2:}  
Without loss of generality, let $s' = 0$. For each $r$ and $u \in \mathbb{R}^2$, define
\begin{equation}
\label{eq:xi-r}
\xi_r(u) = \psi_r \psi_z^2 \frac{u \cdot n_{r-1}}{n_{r-1} \cdot t_r} \frac{h_r}{\sin \theta_r} t_r t_r^T + \psi_r \psi_z^2 \frac{u \cdot n_r}{n_r \cdot t_{r-1}} \frac{h_{r-1}}{\sin \theta_r} (t_r t_{r-1}^T + t_{r-1} t_r^T).
\end{equation}
By definition, $\xi_r(u)$ is supported in $T_r \cup T_{r+1}$. In $T_r$,
\[
\div \left( \psi_r \psi_z^2 t_r t_r^T \right)|_{T_r}(z) = \frac{\sin \theta_r}{h_r} t_r, \quad \div \left( \psi_{r-1} \psi_z^2 (t_r t_{r-1}^T + t_{r-1} t_r^T) \right)|_{T_r}(z) = \frac{\sin \theta_r}{h_{r-1}} t_{r-1},
\]
so
\[
\div \xi_r(u)|_{T_r}(z) = u.
\]
In $T_{r+1}$,
\[
\div \left( \psi_r \psi_z^2 t_r t_r^T \right)|_{T_{r+1}}(z) = \frac{\sin \theta_{r+1}}{h_{r+1}} t_r,
\]
\[
\div \left( \psi_r \psi_z^2 (t_r t_{r-1}^T + t_{r-1} t_r^T) \right)|_{T_{r+1}}(z) = \frac{\sin \theta_{r+1}}{h_{r+1}} t_{r-1} + \frac{\sin(\theta_r + \theta_{r+1})}{h_{r+1}} t_r.
\]
Thus,
\[
\|\xi_r(u)\|_{H^1} \lesssim \frac{|u| h}{\Theta_{II}(z)^2}, \quad |\div \xi_r(u)|_{T_{r+1}}(z)| \lesssim |u|.
\]
Define sequentially:
\[
\tau'_0 = \xi_0(q_0(z)), \quad \tau'_1 = \xi_1(-\div \tau'_0|_{T_1}(z)), \quad \tau'_r = \xi_r(-\div \tau'_{r-1}|_{T_r}(z)), \quad r = 2, \ldots, s-1.
\]
In $T_r$,
\[
\div \tau'_{r-1}|_{T_r}(z) + \div \tau'_r|_{T_r}(z) = 0.
\]
By shape regularity,
\[
|\div \tau'_{r-1}|_{T_r}(z)| \lesssim |\div \tau'_{r-2}|_{T_{r-1}}(z)| \lesssim \cdots \lesssim |q_0(z)|,
\]
yielding
\[
\|\tau'_r\|_{H^1} \lesssim \Theta_{II}(z)^{-2} \|q\|_{L^2(\st(z))}.
\]
Define
\[
\tau_0 = \tau'_0 + \cdots + \tau'_{s-1} + \tau_s(-\div \tau'_{s-1}|_{T_s}(z)),
\]
which satisfies:
\begin{enumerate}
\item $\div \tau_0|_T(z) = 0$ for $T \neq T_0$,
\item $\div \tau_0|_{T_0}(z) = q_0(z),$
\item $\div \tau_0(y) = 0$ for all vertices $y \neq z$,
\item $\|\tau_0\|_{H^1} \lesssim \Theta_{II}(z)^{-2} \|q\|_{L^2(\st(z))}$.
\end{enumerate}

Finally, we can construct $\tau_{s'}$ for all other $T_{s'} \in \st(z)$, $s' \neq s$. Define $\sigma = \sum_{s'} \tau_{s'}$, which completes the proof.

%\begin{itemize}
%\item $\sigma$ is supported in $\st(z)$,
%\item $\div \sigma|_T(z) = q|_T(z)$ for all $T \in \st(z)$,
%\item $\div \sigma(y) = 0$ for all vertices $y \neq z$,
%\item $\|\sigma\|_{H^1} \lesssim \Theta_{II}(z)^{-2} \|q\|_{L^2(\st(z))}$.
%\end{itemize}
%This completes the proof.
\end{proof}


In what follows, we consider the case of the two types of singularities, which are critical to the overall analysis. We proceed by examining each type of singularity separately. The following lemma focuses on Type I singularities, indicating that \eqref{eq:lag-cond-typeI} is a sufficient condition. 

\begin{lemma}[Sufficient Conditions for Type I Singularity]
\label{lem:typeI-sufficient}
Suppose $z \in \mathcal{V}_I$ and $q \in Q_{k-1}^0$ satisfies \eqref{eq:lag-cond-typeI}. Then, there exists $\sigma \in \Sigma_k^0$ such that:
\begin{enumerate}
\item $\sigma$ is supported in $\st(z)$.
\item $\div \sigma(v) = 0$ for all $v \neq z$.
\item $\div \sigma|_T(z) = q|_T(z)$ for all $T \in \st(z)$.
\end{enumerate}
Moreover, the bound holds:
\[
\|\sigma\|_{H^1} \lesssim \|q\|_{L^2(\st(z))}.
\]
\end{lemma}

\begin{proof}
From Step 2 of \Cref{lem:nonsingular-sufficient}, recall the construction of $\xi_r(u)$ defined in \eqref{eq:xi-r}. For a Type I singularity at $z \in \mathcal{V}_I$, the geometric configuration implies four elements $\sin \theta_{r+2} = \sin \theta_r$ and $\sin(\theta_r + \theta_{r+1}) = 0$. Thus, it holds that
\[
\div \left( \psi_r \psi_z^2 (t_r t_{r-1}^T + t_{r-1} t_r^T) \right)|_{T_{r+1}}(z) = \frac{\sin \theta_{r+1}}{h_{r+1}} t_{r-1}.
\]
Since $\div \left( \psi_r \psi_z^2 t_r t_r^T \right)|_{T_{r+1}}(z) = \frac{\sin \theta_{r+1}}{h_{r+1}} t_r$, the divergence of $\xi_r(u)$ in $T_{r+1}$ becomes:
\begin{equation}
\label{eq:div-xi-r}
\div \xi_r(u)|_{T_{r+1}}(z) = u.
\end{equation}
It then follows from \eqref{eq:xi-r} that $\div \xi_r(u)|_{T_r}(z) = u$. Now we define:
\[
\tau_1 := \xi_1(q_1(z)), \quad \tau_2 := \xi_2(q_2(z) - q_1(z)), \quad \tau_3 := \xi_3(q_3(z) - q_2(z) + q_1(z)).
\]
Since \eqref{eq:lag-cond-typeI} gives $q_1(z) + q_3(z) = q_2(z) + q_4(z)$, it follows that $q_3(z) - q_2(z) + q_1(z) = q_4(z)$. Thus, $\tau_3 = \xi_3(q_4(z))$. Set $\sigma = \tau_1 + \tau_2 + \tau_3$. Then:
\begin{itemize}
\item In $T_1$: $\div \sigma|_{T_1}(z) = \div \tau_1|_{T_1}(z) = q_1(z)$, since $\tau_2, \tau_3$ are supported in $T_2 \cup T_3$ and $T_3 \cup T_4$, respectively.
\item In $T_2$: $\div \sigma|_{T_2}(z) = \div \tau_1|_{T_2}(z) + \div \tau_2|_{T_2}(z) = q_1(z) + (q_2(z) - q_1(z)) = q_2(z)$.
\item In $T_3$: $\div \sigma|_{T_3}(z) = \div \tau_2|_{T_3}(z) + \div \tau_3|_{T_3}(z) = (q_2(z) - q_1(z)) + q_4(z) = q_3(z)$, using \eqref{eq:lag-cond-typeI}.
\item In $T_4$: $\div \sigma|_{T_4}(z) = \div \tau_3|_{T_4}(z) = q_4(z)$.
\end{itemize}
Since each $\xi_r$ is supported in $T_r \cup T_{r+1}$ and $\div \xi_r(y) = 0$ for $y \neq z$, $\sigma$ satisfies conditions (1) and (2). Finally, note that $\|\xi_r(u)\|_{H^1} \lesssim |u| h$ (as $\sin \theta_r$ is bounded away from zero). Thus:
\[
\|\tau_r\|_{H^1} \lesssim \|q\|_{L^2(\st(z))}, \quad \|\sigma\|_{H^1} \leq \sum_{r=1}^3 \|\tau_r\|_{H^1} \lesssim \|q\|_{L^2(\st(z))},
\]
completing the proof.
\end{proof}
For Type II singularities, we adopt a similar approach to that used for Type I singularities. However, the analysis of Type II singularities introduces additional complexity due to their distinct geometric configurations, which are classified into nondegenerate and degenerate cases. Each configuration requires careful consideration of the local mesh geometry, leading to tailored technical details in the construction of the function $\sigma$. The following lemma addresses the nondegenerate Type II singularity case.

\begin{lemma}[Sufficient Conditions for Nondegenerate Type II Singularity]
\label{lem:suff-typeII}
Suppose $z \in \mathcal{V}_{II}$ is a nondegenerate vertex and $q \in Q_{k-1}^0$ satisfies \eqref{eq:lag-cond-typeII}. Then, there exists $\sigma \in \Sigma_k^0$ such that:
\begin{enumerate}
\item $\sigma$ is supported in $\st(z)$.
\item $\div \sigma|_T(z) = q|_T(z)$ for all $T \in \st(z)$.
\item $\div \sigma|_T(y) = 0$ for all $y \neq z$, $T \in \st(z)$.
\end{enumerate}
Moreover, the bound holds:
\[
\|\sigma\|_{H^1} \lesssim \|q\|_{L^2(\st(z))}.
\]
\end{lemma}

\begin{proof}
The construction is decomposed into two steps. First, we prove that there exists $\sigma \in \Sigma_k^0$ such that in each $T_i$, it holds that 
\begin{equation}
    (\div \sigma|_{T_i}(z) - q_i(z)) \cdot n_{i+1} = 0.
\end{equation}

Consider $\eta_s = \psi_s\psi_z^2 t_s t_s^T$. Note that $\eta_s$ is supported in $T_s \cup T_{s+1}$. In $T_s$, we have
$$ \div \eta_s|_{T_s} \cdot n_{s+1} = \frac{\sin \theta_s \sin \theta_{s+1}}{h_s} = \frac{\sin \theta_{s+1}}{|\overline{zy_s}|}, $$
while in $T_{s+1}$, 
$$ \div \eta_s|_{T_{s+1}} \cdot n_{s+2} = \frac{\sin \theta_s}{|\overline{zy_s}|}, $$
Therefore, by setting $\displaystyle \tau_s = \frac{|\overline{zy_s}|}{\sin \theta_s \sin \theta_{s+1}} \eta_s$, we have 

$$\div \tau_s|_{T_s} \cdot n_{s+1} \sin \theta_s = \div \tau_s|_{T_{s+1}} \cdot n_{s+2} \sin \theta_{s+1} = 1.$$
This is illustrated in \Cref{fig:first-step-nondegenerate}. Here the number inside each $T_s$ records the value $\div \tau|_{T_{s}} \cdot n_{s+1} \sin \theta_{s}$.

