The degenerate cases are similar, and the complete proof are displayed in the appendix. 

Combining all the above results, we have the following theorem.
\begin{theorem}
\label{thm:lagrange}
It holds that 
    \begin{equation}\begin{split} 
    \div \Sigma_k^0 = \Big\{   &q \in Q_{k-1}^{-1}  :\\ &  J_z : \nabla q_{1}(v)+  J_z : \nabla  q_{3}(v) =  J_z : \nabla  q_{2}(v)+  J_z : \nabla  q_{4}(v),\,\, \forall v \in \mathcal V_{I} \\ &   q_{1}(v)+   q_{3}(v) =  q_{2}(v)+  q_{4}(v),\,\, \forall v \in \mathcal V_{I}  \\
   &  \sum_{i = 1}^6 (-1)^i \sin\theta_i q_i(v) \cdot n_{i+1} = 0, \,\, \forall v \in \mathcal V_{II}.\Big\}
    \end{split}\end{equation}
    Moreover, if for all $x \in \mathcal V \setminus \mathcal V_{I} \setminus \mathcal V_{II}$, $\Theta_{II}(z)$ has a uniform lower bound $\theta_{II} > 0$, and $\mathcal T$ is shape regular. Then for each $ q \in \div \Sigma_k^1$, there exists $ \sigma \in \Sigma_k^1$ such that $\div \sigma = q$ and $\|\sigma\|_{H^1} \lesssim \theta_{II}^{-2} \|q\|_{L^2}$.
\end{theorem}
\begin{proof} 
The proof is similar to \Cref{thm:hermite}.
\end{proof}	

\subsection{Error Estimates}
\label{sec:error}

Based on the inf-sup stability conditions, the following error estimates are standard. Note that the constant for inf-sup condition and coercivity are independent of both parameters $\lambda$ and $\iota$. Therefore, the error estimates are also parameter robust \eqref{lsg-discrete}. 
\begin{theorem}
    Let $(\sigma,u)\in \Sigma\times Q$ be the exact solution of problem \eqref{lsg-weak}. 
    Let $\Sigma_h \times Q_h$ be one of the following pairs:

    \begin{enumerate}
        \item $\Sigma_k^2 \times Q_k^1$, provided $k \ge 7$;
        \item $\Sigma_k^1 \times Q_k^0$, provided $k \ge 7$ and $\Theta_I(z) > \theta_I$ for all interior vertices and $\theta_I > 0$;
        \item $\Sigma_k^0 \times Q_k^{-1}$, provided $k \ge 7$ and $\Theta_{I}(z) > \theta_{I}$ and $\Theta_{II}(z) > \theta_{II}$ for all interior vertices and $\theta_I, \theta_{II} > 0$.
    \end{enumerate}
    Let $(\sigma_h,u_h)\in \Sigma_h \times Q_h$ be the finite element solution of \eqref{lsg-discrete}.
    Then 
    \begin{equation}
    \|\sigma-\sigma_h\|_{\iota}+\|u-u_h\|_{L^2}\lesssim \inf_{\tau_h\in \Sigma_{h},~v_h\in Q_{h}}(\|\sigma-\tau_h\|_{\iota}+\|u-u_h\|_{L^2}).
    \end{equation}
Here the hidden constant is independent with $\iota$ and $\lambda$.
\end{theorem}

As a corollary, suppose that $\sigma\in H^{k+1}(\Omega;\mathbb{S}^2)$ and $u\in H^k(\Omega;\mathbb R^2)$, then we have
        \begin{equation}
    \|\sigma-\sigma_h\|_{\iota}+\|u-u_h\|_{L^2}\lesssim h^k(\|\sigma\|_{H^{k+1}}+\|u\|_{H^{k}}).
    \end{equation}
{Note that the norm of $\sigma$ and $u$ might depend on $\iota$.}
