\section{Technical Details of \Cref{sec:Sigma0}}

We first show the proof of \Cref{lem:necessary-type-II}.
\begin{proof}[Proof of \Cref{lem:necessary-type-II}]
Since $\sigma$ is continuous, and $\{ t_i t_i^T \}_{i=1,2,3}$ forms a basis for $\mathbb S^2$, we express
$\sigma = \alpha t_1 t_1^T + \beta t_2 t_2^T + \gamma t_3 t_3^T,
$ 
where $\alpha$, $\beta$, and $\gamma$ are continuous functions. On each element $T_i$, we write
\[
\sigma|_{T_i} = \alpha_i t_1 t_1^T + \beta_i t_2 t_2^T + \gamma_i t_3 t_3^T,
\]
where $\alpha_i = \alpha|_{T_i}(z)$, and $\beta_i$, $\gamma_i$ are similarly defined.

Computing the divergence projected onto $n_{i+1}$, we obtain:
\begin{align*}
\div \sigma|_{T_1}(z) \cdot n_2 &= (n_2 \cdot t_1) \partial_{t_1} \alpha_1 + (n_2 \cdot t_3) \partial_{t_3} \gamma_1 = -\sin \theta_2 \partial_{t_1} \alpha_1 + \sin \theta_3 \partial_{t_3} \gamma_1, \\
\div \sigma|_{T_2}(z) \cdot n_3 &= (n_3 \cdot t_2) \partial_{t_2} \beta_2 + (n_3 \cdot t_1) \partial_{t_1} \alpha_2 = -\sin \theta_3 \partial_{t_2} \beta_2 - \sin \theta_1 \partial_{t_1} \alpha_2, \\
\div \sigma|_{T_3}(z) \cdot n_4 &= (n_4 \cdot t_3) \partial_{t_3} \gamma_3 + (n_4 \cdot t_2) \partial_{t_2} \beta_3 = -\sin \theta_1 \partial_{t_3} \gamma_3 - \sin \theta_2 \partial_{t_2} \beta_3, \\
\div \sigma|_{T_4}(z) \cdot n_5 &= (n_5 \cdot t_1) \partial_{t_1} \alpha_4 + (n_5 \cdot t_3) \partial_{t_3} \gamma_4 = \sin \theta_2 \partial_{t_1} \alpha_4 - \sin \theta_3 \partial_{t_3} \gamma_4, \\
\div \sigma|_{T_5}(z) \cdot n_6 &= (n_6 \cdot t_2) \partial_{t_2} \beta_5 + (n_6 \cdot t_1) \partial_{t_1} \alpha_5 = \sin \theta_3 \partial_{t_2} \beta_5 + \sin \theta_1 \partial_{t_1} \alpha_5, \\
\div \sigma|_{T_6}(z) \cdot n_1 &= (n_1 \cdot t_3) \partial_{t_3} \gamma_6 + (n_1 \cdot t_2) \partial_{t_2} \beta_6 = \sin \theta_1 \partial_{t_3} \gamma_6 + \sin \theta_2 \partial_{t_2} \beta_6.
\end{align*}
Since $\alpha$, $\beta$, and $\gamma$ are continuous, we have $\alpha_i = \alpha_{i+1}$, $\beta_i = \beta_{i+1}$, and $\gamma_i = \gamma_{i+1}$ across adjacent elements. Additionally, $\sin \theta_i = \sin \theta_{i+3}$ due to the geometric structure around $z \in \mathcal{V}_{II}$. Summing the terms in \eqref{eq:lag-cond-typeII}, the contributions of $\partial_{t_j} \alpha_i$, $\partial_{t_j} \beta_i$, and $\partial_{t_j} \gamma_i$ cancel due to the alternating signs and periodicity of $\sin \theta_i$, yielding
\[
\sum_{i=1}^6 (-1)^i \sin \theta_i \, q_i(z) \cdot n_{i+1} = 0,
\]
as required.
\end{proof}


In the rest of this section, we consider the sufficient condition of the degenerate type II singular vertices. This is based on the following identity:
\begin{equation}
    \sin \theta_{i} n_{i+1} -  \sin \theta_{i+1} n_{i+2} = \sin(\theta_{i+1} + \theta_{i}) n_{i+3}.
\end{equation}


