\begin{lemma}[Sufficient Conditions for Type II-1 Singularity]
\label{lem:typeII-1-sufficient}
Suppose $z \in \mathcal{V}_{II}$ is a Type II-1 singularity (see \Cref{fig:typeII-1}), and $q \in Q_{k-1}^0$ satisfies \eqref{eq:lag-cond-typeII}. Then, there exists $\sigma \in \Sigma_k^0$ such that:
\begin{enumerate}
\item $\sigma$ is supported in $\st(z)$.
\item $\div \sigma|_T(z) = q|_T(z)$ for all $T \in \st(z)$.
\item $\div \sigma|_T(y) = 0$ for all $y \neq z$, $T \in \st(z)$.
\end{enumerate}
Moreover, the bound holds:
\[
\|\sigma\|_{H^1} \lesssim \|q\|_{L^2(\st(z))}.
\]
\end{lemma}

\begin{proof}
For a Type II-1 singularity at $z \in \mathcal{V}_{II}$, the star $\st(z)$ consists of five elements $T_1, T_2, T_3, T_4, T_{5,6}$, where $T_{5,6}$ is a single element sharing edges with $T_4$ and $T_1$, and $n_5 = -n_2$, $\sin \theta_4 = \sin \theta_{5,6}$ (see \Cref{fig:typeII-1}). The condition \eqref{eq:lag-cond-typeII} simplifies to:
\[
\sum_{i=1}^4 (-1)^i \sin \theta_i q_i(z) \cdot n_{i+1} + (-1)^5 \sin \theta_{5,6} q_{5,6}(z) \cdot n_2 = 0.
\]
Since $n_5 = -n_2$ and $\sin \theta_4 = \sin \theta_{5,6}$, this becomes:
\begin{equation}
\label{eq:typeII-1-cond}
\sum_{i=1}^3 (-1)^i \sin \theta_i q_i(z) \cdot n_{i+1} + \sin \theta_4 (q_4(z) - q_{5,6}(z)) \cdot n_2 = 0.
\end{equation}

Recall the function $\xi_r(u)$ from \eqref{eq:xi-r} in \Cref{lem:nonsingular-sufficient}:
\[
\xi_r(u) = \psi_r \psi_z^2 \frac{u \cdot n_{r-1}}{n_{r-1} \cdot t_r} \frac{h_r}{\sin \theta_r} t_r t_r^T + \psi_r \psi_z^2 \frac{u \cdot n_r}{n_r \cdot t_{r-1}} \frac{h_{r-1}}{\sin \theta_r} (t_r t_{r-1}^T + t_{r-1} t_r^T).
\]
For Type II-1 singularities, as in \Cref{lem:typeI-sufficient}, the mesh geometry implies $\sin(\theta_r + \theta_{r+1}) = 0$, so \eqref{eq:div-xi-r} holds: $\div \xi_r(u)|_{T_r}(z) = u$ and $\div \xi_r(u)|_{T_{r+1}}(z) = u$. For $r=4$, since $T_{5,6}$ is adjacent to $T_4$, we have:
\[
\div \xi_4(u)|_{T_4}(z) = u, \quad \div \xi_4(u)|_{T_{5,6}}(z) = u.
\]
Define $q' = q - \div \xi_4(q_{5,6}(z))$. Then:
\begin{itemize}
\item In $T_{5,6}$: $\div \xi_4(q_{5,6}(z))|_{T_{5,6}}(z) = q_{5,6}(z)$, so $q'_{T_{5,6}}(z) = q_{5,6}(z) - q_{5,6}(z) = 0$.
\item In $T_4$: $\div \xi_4(q_{5,6}(z))|_{T_4}(z) = q_{5,6}(z)$, so $q'_{T_4}(z) = q_4(z) - q_{5,6}(z)$.
\item In $T_i$, $i=1,2,3$: $\div \xi_4(q_{5,6}(z))|_{T_i}(z) = 0$, so $q'_{T_i}(z) = q_i(z)$.
\end{itemize}
