\section{Preliminaries}\label{sec:prelim}

\subsection*{Laurent polynomial ring and modules}

A (univariate) \emph{Laurent polynomial} with coefficients over $\Z$ is an expression of the form
\[
f = \sum_{i = p}^q a_i X^i, \quad \text{where $p, q \in \Z$ and $a_i \in \Z, i = p, p+1, \ldots, q$.}
\]
The set of all Laurent polynomials with coefficients over $\Z$ forms a ring and is denoted by $\Z[X^{\pm}]$.

Let $R$ be a commutative ring.
An $R$-module is defined as an abelian group $(M, +)$ along with an operation $\cdot \;\colon R \times M \rightarrow M$ satisfying $f \cdot (a+b) = f \cdot a + f \cdot b$, $(f + g) \cdot a = f \cdot a + g \cdot a$, $fg \cdot a = f \cdot (g \cdot a)$ and $1 \cdot a = a$.
We will denote by $\bzer$ the neutral element of an $R$-module $M$.
%For example, for any $d \in \N$, the additive group $\Z[X^{\pm}]$ can be seen as a $\Z[X^{\pm d}]$-module by $f \cdot g \coloneqq fg, \; f \in \Z[X^{\pm d}], g \in \Z[X^{\pm}]$.
%The generators of $\Z[X^{\pm}]$ as a $\Z[X^{\pm d}]$-module are $1, X, \ldots, X^{d-1}$.
%In general, in order to define a $\Z[X^{\pm d}]$-module structure on an abelian group $M$, it suffices to define $X^d \cdot m$ and $X^{-d} \cdot m$ for all $m \in M$.
%The value of $f \cdot m, \; f \in \Z[X^{\pm d}], m \in M,$ would then follow from the linearity of the operation $\cdot$.
%An \emph{ideal} of $R$ is a subset of $R$ that is an $R$-module.
%If $M$ is an $R$-module and $m \in M$, then $R \cdot m \coloneqq \{r \cdot m \mid r \in R\}$ is again an $R$-module.
If $N$ and $N'$ are $R$-submodule of $M$, then $N + N' \coloneqq \{n + n' \mid n \in N, n' \in N'\}$ is again an $R$-submodule of $M$.

For any $d \in \N$, the direct power $\Z[X^{\pm}]^d$ is a $\Z[X^{\pm}]$-module by $g \cdot (f_1, \ldots, f_d) \coloneqq (gf_1, \ldots, gf_d)$.
Throughout this paper, we use the bold symbol $\bff$ to denote a vector $(f_1, \ldots, f_d) \in \Z[X^{\pm}]^d$.
Given $\bff_1, \ldots, \bff_m \in \Z[X^{\pm}]^d$, we say they \emph{generate} the $\Z[X^{\pm}]$-module 
\[
\sum_{i=1}^m \Z[X^{\pm}] \cdot \bff_i \coloneqq \left\{\sum_{i=1}^m p_i \cdot \bff_i \;\middle|\; p_1, \ldots, p_m \in \Z[X^{\pm}] \right\}.
\]
%A module is called \emph{finitely generated} if it can be generated by a finite number of elements.
Given two $\Z[X^{\pm}]$-submodules $N, M$ of $\Z[X^{\pm}]^d$ such that $N \subseteq M$, we can define the quotient $M/N \coloneqq \{\overline{\bm} \mid \bm \in M\}$ where $\overline{\bm_1} = \overline{\bm_2}$ if and only if $\bm_1 - \bm_2 \in N$.
This quotient is also a $\Z[X^{\pm}]$-module.
We say that a $\Z[X^{\pm}]$-module $\mA$ is \emph{finitely presented} if it can be written as a quotient $M/N$ for two submodules $M, N$ of $\Z[X^{\pm}]^d$ for some $d \in \N$, where both $M$ and $N$ are generated by finitely many elements.
Such a pair $(M, N)$, given by their respective generators, is called a \emph{finite presentation} of $\mA$.
The element $\overline{\bm}$ of $\mA$ is effectively represented by $\bm \in \Z[X^{\pm}]^d$, this representation is unique modulo $N$.
In this paper, we will often write $\bm$ instead of $\overline{\bm}$, when the context is clear that this represents an element of the quotient $\mA = M/N$.

\subsection*{Abelian-by-cyclic groups}
We now formally define abelian-by-cyclic groups.
\begin{definition}
    A group $G$ is called \emph{abelian-by-cyclic} if it admits an abelian normal subgroup $\mA$ such that $G/\mA \cong \Z$.
\end{definition}

%Let $g \in G$ be any element such that $gA$ generates the infinite cyclic group $G/A$.
%It is a classic result~\cite[Section~3]{baumslag1973subgroups} that the conjugacy action $G/A \times A \rightarrow A, \; (gA, a) \mapsto g^{-1} a g,$ is well-defined (does not depend on the choice of $g$), and gives the abelian subgroup $A$ the structure of a $\Z[X^{\pm}]$-module.
%Here, the action of $X \in \Z[X^{\pm}]$ is defined by the action of $gA$ on $A$; that is, $X \cdot a \coloneqq g^{-1} a g$.
%We will use the calligraphic $\mA$ to denote the abelian group $A$ considered as a $\Z[X^{\pm}]$-module.

The abelian subgroup $\mA$ admits a natural $\Z[X^{\pm}]$-module structure in the following sense.
It is a classic result~\cite[p.17]{boler1976conjugacy} that every finitely generated abelian-by-cyclic group $G$ can be written as a \emph{semidirect product} $\mA \rtimes \Z$:
\begin{equation}
    \mA \rtimes \Z \coloneqq \left\{ (\ba, z) \;\middle|\; \ba \in \mA, z \in \Z \right\},
\end{equation}
where $\mA$ is a finitely presented $\Z[X^{\pm}]$-module.
The group law in $\mA \rtimes \Z$ is defined by
\[
(\ba, z) \cdot (\ba', z') = (\ba + X^z \cdot \ba', z + z'), \quad (\ba, z)^{-1} = (- X^{-z} \cdot \ba, -z).
\]
The neutral element of $\mA \rtimes \Z$ is $(\bzer, 0)$.
Intuitively, the element $(\ba, z)$ is analogous to a $2 \times 2$ matrix
$
\begin{pmatrix}
X^{z} & \ba \\
0 & 1 \\
\end{pmatrix}
$, where group multiplication is represented by matrix multiplication.
%By direct computation, for all $m \in \Z$, we have
%\begin{align*}
%(\ba, z)^m = 
%\begin{cases}
%    \left(\frac{X^{mz} - 1}{X^z - 1} \cdot \ba, mz\right), \quad & z \neq 0, \\
%    \left(m \cdot \ba, 0\right), \quad & z = 0. \\
%\end{cases}
%\end{align*}
We naturally identify $\mA$ with the normal subgroup $\left\{ (\ba, 0) \;\middle|\; \ba \in \mA\right\}$ of $\mA \rtimes \Z$.
In particular, the quotient $\left( \mA \rtimes \Z \right)/\mA$ is isomorphic to $\Z$, so $\mA \rtimes \Z$ is indeed abelian-by-cyclic.

\begin{example}
    Take $\mA \coloneqq \Z[X^{\pm}]$ considered as a $\Z[X^{\pm}]$-module, then we recover the definition~\eqref{eq:defwr} of the wreath product $\Z \wr \Z = \Z[X^{\pm}] \rtimes \Z$.
    If $\mA \coloneqq \Z_p[X^{\pm}] = \Z[X^{\pm}]/\left(\Z[X^{\pm}] \cdot p\right)$, then we obtain the lamplighter group $\Z_p \wr \Z = \Z_p[X^{\pm}] \rtimes \Z$.
    In general, if $A$ is any finitely generated abelian group, and let $A[X^{\pm}]$ denote the set of Laurent polynomials with coefficients in $A$, then $A[X^{\pm}]$ is a finitely presented $\Z[X^{\pm}]$-module (but not necessarily a ring), and the wreath product $A \wr \Z$ is defined as the semidirect product $A[X^{\pm}] \rtimes \Z$.
    %Here, $\Z_p[X, X^{-1}]$ is the same as the finitely presented module $\Z[X^{\pm}]/\left(\Z[X^{\pm}] \cdot p\right)$.

    If we take $\mA \coloneqq \Z[1/p] = \Z[X^{\pm}]/\left(\Z[X^{\pm}] \cdot (X - p)\right)$, then we recover the definition~\eqref{eq:defbs} of the Baumslag-Solitar group $\mathsf{BS}(1, p) = \Z[1/p] \rtimes \Z$.
    %Here, $\Z[1/p]$ is the same as the finitely presented module $\Z[X^{\pm}]/\left(\Z[X^{\pm}] \cdot (X - p)\right)$.
\end{example}

Throughout this paper, a finitely generated abelian-by-cyclic group $G$ is always represented as the semidirect product $\mA \rtimes \Z$, where $\mA$ is a $\Z[X^{\pm}]$-module given by a finite presentation.

\section{Linear equation with monomial constraints}\label{sec:lineq}

In this section, we prove undecidability of Theorem~\ref{thm:linequndec} by embedding Hilbert's tenth problem.
For $f, g \in \Z[X^{\pm}]$, we write $f \mid g$ if there exists $h \in \Z[X^{\pm}]$ such that $g = fh$.
We show undecidability of Theorem~\ref{thm:linequndec}, even for the following special case:

\begin{proposition}\label{prop:linequndec}
    There exist $k, n \in \N$, polynomials $p_1, \ldots, p_k \in \{0, (X-1)^2, (X-1)^3\}$, and $f_{ij} \in \Z[X^{\pm}]$, $i = 1, \ldots, n; \; j = 1, \ldots, k$, such that the following problem is undecidable:

    \smallskip
    \noindent \textbf{Input:} polynomials $f_{0j} \in \Z[X^{\pm}]$, $j = 1, \ldots, k$.

    \noindent \textbf{Question:} 
    whether there exist $z_1, \ldots, z_n \in \Z$ that satisfy the following system:
    \begin{align}\label{eq:sysmono}
        p_1 & \mid X^{z_1} f_{11} + \cdots + X^{z_n} f_{n1} - f_{01}, \nonumber\\
        p_2 & \mid X^{z_1} f_{12} + \cdots + X^{z_n} f_{n2} - f_{02}, \nonumber\\
        & \vdots \nonumber\\
        p_k & \mid X^{z_1} f_{1k} + \cdots + X^{z_n} f_{nk} - f_{0k}.
    \end{align}
    In particular, when $p_i = 0$, the expression $p_i \mid F$ means $F = 0$.
\end{proposition}

Note that Proposition~\ref{prop:linequndec} will immediately yield Theorem~\ref{thm:linequndec}. Indeed, let $p_1, \ldots, p_k \in \Z[X^{\pm}]$ be as in Proposition~\ref{prop:linequndec}, and let $\mA$ be the finitely presented $\Z[X^{\pm}]$-module $\Z[X^{\pm}]^k/Q$, where
\[
Q \coloneqq \{(g_1 p_1, g_2 p_2, \ldots, g_k p_k) \mid g_1, \ldots, g_k \in \Z[X^{\pm}]\}.
\]
Then for $\bff_0 = (f_{01}, \ldots, f_{0k}), \bff_1 = (f_{11}, \ldots, f_{1k}), \ldots, \bff_n = (f_{n1}, \ldots, f_{nk}) \in \mA$, we have $X^{z_1} \bff_1 + \cdots + X^{z_n} \bff_n = \bff_0$ if and only if the system~\eqref{eq:sysmono} is satisfied. Therefore, Proposition~\ref{prop:linequndec} implies Theorem~\ref{thm:linequndec}.
We now start proving Proposition~\ref{prop:linequndec}.

\begin{lemma}\label{lem:sqaure}
    Suppose $z_1, z_2, z_3 \in \Z$. We have
    \begin{equation}\label{eq:div3}
    (X-1)^3 \mid X^{z_1} + X^{z_2} (1-X) + X^{z_3} + (X - 3)
    \end{equation}
    if and only if $z_2 = z_1^2$ and $z_3 = - z_1$.
\end{lemma}

\begin{proof}
    Note that $(X-1)^3 \mid f$ if and only if $f(1) = f'(1) = f''(1) = 0$, where $f'$ and $f''$ denote the first and second derivatives of $f$. Taking $f = X^{z_1} + X^{z_2} (1-X) + X^{z_3} + (X - 3)$, then $f(1) = f'(1) = f''(1) = 0$ is equivalent to
    \[
    0 = z_1 + z_3 = z_1^2 - z_1 - 2 z_2 + z_3^2 - z_3 = 0,
    \]
    which is equivalent to $z_2 = z_1^2, z_3 = - z_1$.
\end{proof}

\begin{lemma}\label{lem:sum}
    Suppose $z_1, z_2, z_3 \in \Z$. We have
    \[
    (X-1)^2 \mid X^{z_1} + X^{z_2} - X^{z_3} - 1
    \]
    if and only if $z_3 = z_1 + z_2$.
\end{lemma}

\begin{proof}
    Note that $(X-1)^2 \mid f$ if and only if $f(1) = f'(1) = 0$. Taking $f = X^{z_1} + X^{z_2} - X^{z_3} - 1$, then $f(1) = f'(1) = 0$ is equivalent to
    $
    0 = z_1 + z_2 - z_3 = 0
    $.
\end{proof}

\begin{lemma}\label{lem:product}
    Suppose $z_i \in \Z, i = 1, 2, 3$. There exist $z_4, \ldots, z_{12} \in \Z$ satisfying
    \begin{align}
        (X-1)^3 & \mid X^{z_1} + X^{z_4} (1-X) + X^{z_{10}} + (X - 3), \label{eq:1}\\
        (X-1)^3 & \mid X^{z_2} + X^{z_5} (1-X) + X^{z_{11}} + (X - 3), \label{eq:2}\\
        (X-1)^2 & \mid X^{z_4} + X^{z_5} - X^{z_6} - 1, \label{eq:3} \\
        (X-1)^2 & \mid X^{z_1} + X^{z_2} - X^{z_7} - 1, \label{eq:4} \\
        (X-1)^3 & \mid X^{z_7} + X^{z_8} (1-X) + X^{z_{12}} + (X - 3), \label{eq:5}\\
        (X-1)^2 & \mid X^{z_3} + X^{z_3} - X^{z_9} - 1, \label{eq:6}\\
        (X-1)^2 & \mid X^{z_6} + X^{z_9} - X^{z_8} - 1, \label{eq:7}
    \end{align}
    if and only if $z_3 = z_1 z_2$.
\end{lemma}
\begin{proof}
    We apply Lemmas~\ref{lem:sqaure} or \ref{lem:sum} to each of the equations~\eqref{eq:1}-\eqref{eq:7}.
    Equations~\eqref{eq:1}, \eqref{eq:2} and \eqref{eq:3} are equivalent to
    \[
    z_4 = z_1^2, z_5 = z_2^2, z_6 = x_4 + x_5 = z_1^2 + z_2^2,
    \]
    and $z_{10} = - z_1, z_{11} = - z_2$.
    Equations~\eqref{eq:4} and \eqref{eq:5} are equivalent to
    \[
    z_7 = z_1 + z_2, z_8 = z_7^2 = z_1^2 + z_2^2 + 2 z_1 z_2,
    \]
    and $z_{12} = - z_7 = - z_1 - z_2$.
    Finally, Equations~\eqref{eq:6} and \eqref{eq:7} are equivalent to
    \[
    z_9 = z_3 + z_3, z_8 = z_6 + z_9 = z_6 + z_3 + z_3.
    \]
    Together with $z_8 = z_1^2 + z_2^2 + 2 z_1 z_2$ and $z_6 = z_1^2 + z_2^2$, this yields $z_3 = z_1 z_2$.
\end{proof}

We now combine Lemma~\ref{lem:sum} and \ref{lem:product} to prove Proposition~\ref{prop:linequndec} (and consequently, Theorem~\ref{thm:linequndec}).

\begin{proof}[Proof of Proposition~\ref{prop:linequndec} and Theorem~\ref{thm:linequndec}]
    By Matiyasevich’s proof of the undecidability of Hilbert’s tenth problem~\cite{matiyasevich1993hilbert}, there exists a polynomial $P_{uni} \in \Z[X_1, \ldots, X_d]$, such that the following problem is undecidable:

    \smallskip
    \noindent \textbf{Input:} an integer $a \in \Z$.

    \noindent \textbf{Question:} whether $P_{uni}(x_1, \ldots, x_d) = a$ has a solution $(x_1, \ldots, x_d) \in \Z^d$.
    \smallskip

    To embed the Hilbert's tenth problem into Equation~\eqref{eq:sysmono}, we will construct $k, n \in \N$, polynomials $p_1, \ldots, p_{k-1} \in \{0, (X-1)^2, (X-1)^3\}$, $f_{ij} \in \Z[X^{\pm}]$, $i = 1, \ldots, n; \; j = 1, \ldots, k$, and $f_{0j} \in \Z[X^{\pm}]$, $j = 1, \ldots, k-1$, such that $P_{uni}(z_1, \ldots, z_d) = a$ if and only if there exist $z_{d+1}, \ldots, z_n \in \Z$ such that
    \begin{align}\label{eq:sysmono2}
        p_1 & \mid X^{z_1} f_{11} + \cdots + X^{z_n} f_{n1} - f_{01}, \nonumber\\
        p_2 & \mid X^{z_1} f_{12} + \cdots + X^{z_n} f_{n2} - f_{02}, \nonumber\\
        & \vdots \nonumber\\
        p_{k-1} & \mid X^{z_1} f_{1, k-1} + \cdots + X^{z_n} f_{n, k-1} - f_{0, k-1}, \nonumber\\
        0 & \mid X^{z_n} - X^a.
    \end{align}

    First we rewrite the equation $P_{uni}(z_1, \ldots, z_d) = z_n$ into a system of polynomial equations, each of the form $z_k = z_i z_j$ or $z_k = z_i + z_j$ or $z_k = b, b \in \Z$, with $i, j, k \in \{1, 2, \ldots, n\}$.
    For example, ``$z_1^3 + 2 z_1 z_2 + 7 = z_n$'' can be rewritten as ``$z_3 = z_1 z_1, z_4 = z_1 z_3, z_5 = z_1 z_2, z_6 = z_5 + z_5, z_7 = z_4 + z_6, z_8 = 7, z_n = z_7 + z_8$''.

    Then, we use Lemma~\ref{lem:product} and \ref{lem:sum} respectively to express the equations $z_k = z_i z_j$ and $z_k = z_i + z_j$, and use $0 \mid X^{z_k} - X^b$ to express $z_k = b$. Finally, we add $0 \mid X^{z_n} - X^a$ to the system to fully express the equation $P_{uni}(z_1, \ldots, z_d) = a$.
    The resulting system have the form~\eqref{eq:sysmono2} and is equivalent to $P_{uni}(z_1, \ldots, z_d) = a$ (the variables $z_{d+1}, \ldots, z_n$ will be functions over $z_1, \ldots, z_d$ and do not impose extra constraints).

    Notice that the input $a \in \Z$ only appear once as $X^a$ in the system~\eqref{eq:sysmono2}, which corresponds to $f_{0k} = X^a$ in the system~\eqref{eq:sysmono}. Therefore the decision problem stated in Proposition~\ref{prop:linequndec} is undecidable.
    As explained after the statement of Proposition~\ref{prop:linequndec}, the correctness of Theorem~\ref{thm:linequndec} directly follows.
\end{proof}

\section{Equations over abelian-by-cyclic groups}\label{sec:reduction}

\subsection{Quadratic equation undecidable in an abelian-by-cyclic group}\label{subsec:quadeq}
\hfill

\noindent In this subsection, we prove Theorem~\ref{thm:quadeq}, showing that solving quadratic equations is undecidable in the abelian-by-cyclic group $\mA \rtimes \Z$, where $\mA$ is the $\Z[X^{\pm}]$-module constructed in Theorem~\ref{thm:linequndec}.
Our strategy is a reduction from Theorem~\ref{thm:linequndec}, by embedding the equation $X^{z_1} \bff_1 + \cdots + X^{z_n} \bff_n = \bff_0$ into a quadratic equation over $\mA \rtimes \Z$.
The key observation is that ``multiplying by $X^z$'' can be expressed by conjugacy:
$
    (\ba, z) (\bff, 0) (\ba, z)^{-1} = (X^{z} \bff, 0)
$.

\thmquadeq*
\begin{proof}
    We will reduce the problem from Theorem~\ref{thm:linequndec}.
    Let $\mA$ be the finitely presented $\Z[X^{\pm}]$-module constructed in the theorem.
    Take $h_1 = (\bff_1, 0), h_2 = (\bff_2, 0) \ldots, h_n = (\bff_n, 0)$, where $\bff_1, \ldots, \bff_n \in \mA$ are the elements constructed in Theorem~\ref{thm:linequndec}.
    For an instance of the decision problem in Theorem~\ref{thm:linequndec} with input $\bff_0 \in \mA$,
    we take the input $h_0 = (- \bff_0, 0)$ in the above decision problem.
    We show that there exist $g_0, g_1, \ldots, g_n \in \mA \rtimes \Z$, such that
    \begin{equation}\label{eq:qe}
        (g_0 h_0 g_0^{-1}) (g_1 h_1 g_1^{-1}) \cdots (g_n h_n g_n^{-1}) = e,
    \end{equation}
    if and only if there exist $z_1, \ldots, z_n \in \Z$, such that
    \begin{equation}\label{eq:qelinmono}
         X^{z_1} \bff_1 + \cdots + X^{z_n} \bff_n = \bff_0.
    \end{equation}

    If there exist $g_0, g_1, \ldots, g_n \in \mA \rtimes \Z$ that satisfy \eqref{eq:qe}, write $g_0 = (\ba_0, b_0), g_1 = (\ba_1, b_1), \ldots$, $g_n = (\ba_n, b_n)$.
    Then for $i = 1, \ldots, n$, we have 
    \[
    g_i h_i g_i^{-1} = (\ba_i, b_i) (\bff_i, 0) (- X^{-b_i} \ba_i, - b_i) = (X^{b_i} \bff_i, 0),
    \]
    and $g_0 h_0 g_0^{-1} = (- X^{b_0} \bff_0, 0)$.
    Therefore, Equation~\eqref{eq:qe} is equivalent to
    \begin{align*}
        \left( - X^{b_0} \bff_0 + X^{b_1} \bff_1 + \cdots + X^{b_n} \bff_n, 0 \right) = \left(\bzer, 0 \right),
    \end{align*}
    which is equivalent to
    \[
    X^{b_1 - b_0} \bff_1 + \cdots + X^{b_n - b_0} \bff_n = \bff_0.
    \]
    Thus, the integers $z_1 = b_1 - b_0, z_2 = b_2 - b_0, \ldots, z_n = b_n - b_0$ satisfy Equation~\eqref{eq:qelinmono}.

    Conversely, if Equation~\eqref{eq:qelinmono} has solutions $z_1, \ldots, z_m \in \Z$, take $g_0 = (\bzer, 0), g_1 = (\bzer, z_1), \ldots, g_n = (\bzer, z_n) \in \mA \rtimes \Z$.
    Then as above we have $g_0 h_0 g_0^{-1} = (- \bff_0, 0)$ and $g_i h_i g_i^{-1} = (X^{z_i} \bff_i, 0)$ for $i = 1, \ldots, n$.
    Therefore $g_0, g_1, \ldots, g_n$ satisfy Equation~\eqref{eq:qe}.

    By Theorem~\ref{thm:linequndec}, it is undecidable whether Equation~\eqref{eq:qelinmono} has integer solutions. Therefore, it is also undecidable whether Equation~\eqref{eq:qe} has solutions in $\mA \rtimes \Z$.
\end{proof}

\subsection{General system of equations undecidable in $\Z \wr \Z$}\label{subsec:ZwrZ}
\hfill

\noindent Recall that $\Z \wr \Z$ is defined as $\Z[X^{\pm}] \rtimes \Z$. 
Its elements are $(f, a)$ where $f \in \Z[X^{\pm}], a \in \Z$.
In this subsection we show that solving a general system of equations is undecidable in $\Z \wr \Z$ (Theorem~\ref{thm:syseq}). 

The difficulty of proving Theorem~\ref{thm:syseq}, compared to Theorem~\ref{thm:quadeq}, is that we can no longer rely on the structure of the abelian-by-cyclic group to embed the information on the module $\mA$ from Theorem~\ref{thm:linequndec}.
We therefore need to dig deeper, and prove Theorem~\ref{thm:syseq} by reducing it from Proposition~\ref{prop:linequndec} instead of Theorem~\ref{thm:linequndec}.
Recall that Proposition~\ref{prop:linequndec} states it is undecidable whether a system of equations of the form $p_j \mid X^{z_1} f_{1j} + \cdots + X^{z_n} f_{nj} - f_{0j}, \; j = 1, \ldots, k,$ has solutions $z_1, \ldots, z_n \in \Z$.
Furthermore, the divisors $p_j$ have either the form $0$, $(X-1)^2$, or $(X-1)^3$.
The key idea of embedding these equations into equations over $\Z \wr\Z$ is that divisibility by $(X-1)^k$ can be expressed by an equation over $\Z \wr\Z$ containing the \emph{$k$-th commutator words}.
For an alphabet $\mY = \{x, y, z, w\}$, define recursively the following commutator words over $\mY \cup \mY^{-1}$:
\begin{align*}
    [x, y] & \coloneqq x^{-1} y^{-1} xy, \\
    [[x, y], z] & \coloneqq [x^{-1}y^{-1}xy, z] = y^{-1} x^{-1} y x z^{-1} x^{-1} y^{-1} xyz, \\
    [[[x, y], z], w] & \coloneqq [[x^{-1}y^{-1}xy, z], w] = z^{-1} y^{-1} x^{-1} y x z x^{-1} y^{-1} xy w^{-1} y^{-1} x^{-1} y x z^{-1} x^{-1} y^{-1} xyz w.
\end{align*}

\begin{lemma}\label{lem:comms}
Let $(f, b) \in \Z \wr \Z$, let $e = (0, 0)$ denote the neutral element of $\Z \wr \Z$.
\begin{enumerate}[nosep, label=(\arabic*)]
    \item There exists $x, y \in \Z \wr \Z$ such that $(f, b) \cdot [x, y] = e$, if and only if $(X-1) \mid f$ and $b = 0$.
    \item There exists $x, y, z \in \Z \wr \Z$ such that $(f, b) \cdot [[x, y], z] = e$, if and only if $(X-1)^2 \mid f$ and $b = 0$.
    \item There exists $x, y, z, w \in \Z \wr \Z$ such that $(f, b) \cdot [[[x, y], z], w] = e$, if and only if $(X-1)^3 \mid f$ and $b = 0$.
\end{enumerate}
\end{lemma}
\begin{proof}
    (1) Write $x = (f_1, a_1), y = (f_2, a_2)$. By direct computation, 
    \[
    [x, y] = (f_1, a_1)^{-1} (f_2, a_2)^{-1} (f_1, a_1) (f_2, a_2) = ((1 - X^{a_2})X^{- a_1 - a_2} f_1 + (X^{a_1} - 1)X^{- a_1 - a_2} f_2, 0).
    \]
    If $(f, b) \cdot [x, y] = e$ for some $x = (f_1, a_1), y = (f_2, a_2)$, then $b = 0$ and $f = - (1 - X^{a_2})X^{- a_1 - a_2} f_1 - (X^{a_1} - 1)X^{- a_1 - a_2} f_2$. Since $X - 1 \mid 1 - X^{a}$ for all $a \in \Z$, we have $(X-1) \mid f$.
    Conversely, if $b = 0$ and $(X - 1) \mid f$, then one can take $x = (0, -1), y = (\frac{f}{X - 1}, 0)$, so we have $[x, y] = (-f, 0)$ and thus $(f, b) \cdot [x, y] = e$.

    (2) By (1), for any $x, y \in \Z \wr \Z$, we can write $[x, y]$ as $(F, 0)$ for some $(X - 1) \mid F$. And conversely for any $(X - 1) \mid F$ we can find $x, y \in \Z \wr \Z$ such that $[x, y] = (F, 0)$.
    Write $z = (f_3, a_3)$, then 
    \[
    [[x, y], z] = [(F, 0), (f_3, a_3)] = ((1 - X^{a_3})X^{- a_3} F, 0).
    \]
    Therefore, if there are $x, y, z \in \Z \wr \Z$ such that $(f, b) \cdot [[x, y], z] = e$, then $b = 0$ and $f = -(1 - X^{a_3})X^{- a_3} F$. Since $(X-1) \mid F$ and $(X-1) \mid 1 - X^{a_3}$, we have $(X-1)^2 \mid f$.
    Conversely, if $b = 0$ and $(X - 1)^2 \mid f$, then by (1) we can find $x, y \in \Z \wr \Z$ such that $[x, y] = (- \frac{f}{X-1}, 0)$. We then take $z = (0, -1)$, so $[[x, y], z] = (- f, 0)$ and $(f, b) \cdot [[x, y], z] = e$.

    (3) follows from (2) the same way (2) follows from (1).
\end{proof}

\thmsyseq*
\begin{proof}
    We will embed the decision problem from Proposition~\ref{prop:linequndec} into the problem of finding solutions to a system of equations in $\Z \wr \Z$.
    Let $k, n \in \N$,$p_1, \ldots, p_k \in \{0, (X-1)^2, (X-1)^3\}$, and $f_{ij} \in \Z[X^{\pm}]$, $i = 1, \ldots, n; \; j = 1, \ldots, k,$ be as defined in Proposition~\ref{prop:linequndec}.
    We will construct $k$ words $w_1, w_2, \ldots, w_k$ over $\mX \cup \mX^{-1} \cup G$, that has solution over $\Z \wr \Z$ if and only if the system of equations~\eqref{eq:sysmono} has integer solutions $z_1, \ldots, z_n$.

    For each $i = 1, \ldots, n,$ and $j = 1, \ldots, k$, define $h_{ij} \coloneqq (f_{ij}, 0)$, and $h_{0j} \coloneqq (- f_{0j}, 0)$.
    Let $\mX$ be the alphabet $\{x_0, x_1, \ldots, x_n\} \cup \{x_{11}, x_{12}, x_{13}, x_{14}\} \cup \cdots \cup \{x_{k1}, x_{k2}, x_{k3}, x_{k4}\}$.
    For each $j = 1, \ldots, k,$ define the word $w_j$ over the alphabet $\mX \cup \mX^{-1} \cup G$:
    \begin{align*}
        w_j \coloneqq
        \begin{cases}
            (x_0 h_{0j} x_0^{-1}) (x_1 h_{1j} x_1^{-1}) \cdots (x_n h_{nj} x_n^{-1}) \quad & \text{ if } p_j = 0, \\
            (x_0 h_{0j} x_0^{-1}) (x_1 h_{1j} x_1^{-1}) \cdots (x_n h_{nj} x_n^{-1}) [[x_{j1}, x_{j2}], x_{j3}] \quad & \text{ if } p_j = (X-1)^2, \\
            (x_0 h_{0j} x_0^{-1}) (x_1 h_{1j} x_1^{-1}) \cdots (x_n h_{nj} x_n^{-1}) [[[x_{j1}, x_{j2}], x_{j3}], x_{j4}] \quad & \text{ if } p_j = (X-1)^3.
        \end{cases}
    \end{align*}
    We claim that there exist $g_{j1}, g_{j2}, g_{j3}, g_{j4} \in \Z \wr \Z$, such that $g_0 = (F_0, b_0), g_1 = (F_1, b_1), \ldots, g_n = (F_n, b_n)$ satisfy $w_j(g_0, g_1, \ldots) = e$, if and only if $p_j \mid X^{b_1} f_{1j} + \cdots + X^{b_n} f_{nj} - X^{b_0} f_{0j}$.

    Indeed, as in the proof of Theorem~\ref{thm:quadeq}, we have
    \[
     (x_0 h_{0j} x_0^{-1}) (x_1 h_{1j} x_1^{-1}) \cdots (x_n h_{nj} x_n^{-1}) = \left( - X^{b_{0}} f_0 + X^{b_1} f_{1j} + \cdots + X^{b_n} f_{nj}, 0 \right)
    \]
    If $p_j = 0$, then $w_j(g_0, g_1, \ldots) = e$ if and only if $- X^{b_{0}} f_0 + X^{b_1} f_{1j} + \cdots + X^{b_n} f_{nj} = 0$.
    If $p_j = (X - 1)^2$, then by Lemma~\ref{lem:comms}(2), $w_j(g_0, g_1, \ldots) = e$ if and only if $p_j \mid - X^{b_{0}} f_0 + X^{b_1} f_{1j} + \cdots + X^{b_n} f_{nj}$.
    If $p_j = (X - 1)^3$ then Lemma~\ref{lem:comms}(3) gives the same result.

    Therefore, the system of $k$ word equations $w_1 , w_2, \ldots, w_k$, have solutions $g_0, g_1, \ldots, g_n$, $g_{11}, g_{12}$, $g_{13}, g_{14}$, $\ldots$, $g_{k1}, g_{k2}, g_{k3}, g_{k4} \in \Z \wr \Z$, if and only if the system of equations
    \begin{align}\label{eq:sysmono3}
        p_1 & \mid X^{b_1} f_{11} + \cdots + X^{b_n} f_{n1} - X^{b_0} f_{01}, \nonumber\\
        p_2 & \mid X^{b_1} f_{12} + \cdots + X^{b_n} f_{n2} - X^{b_0} f_{02}, \nonumber\\
        & \vdots \nonumber\\
        p_k & \mid X^{b_1} f_{1k} + \cdots + X^{b_n} f_{nk} - X^{b_0} f_{0k}.
    \end{align}
    admit solutions $b_0, b_1, \ldots, b_n \in \Z$.
    Note that this is equivalent to the system~\eqref{eq:sysmono} admitting solutions $z_1, \ldots, z_n \in \Z$, by de-homogenizing or homogenizing the equations.
    Therefore, Proposition~\ref{prop:linequndec} shows that it is undecidable whether a system of equations have solutions in $\Z \wr \Z$.
\end{proof}

\section{Knapsack Problem}\label{sec:KP}
In this section, we prove Theorem~\ref{thm:knapsack}, showing that the Knapsack Problem is undecidable in the abelian-by-cyclic group $\mA \rtimes \Z$, where $\mA$ is the $\Z[X^{\pm}]$-module constructed in Theorem~\ref{thm:linequndec}.
Undecidability of the Knapsack Problem in certain abelian-by-cyclic groups has already been observed by Mishchenko and Treier~\cite[Theorem~1]{mishchenko2017knapsack}.
Nevertheless, we deduce an alternative and more direct proof from Theorem~\ref{thm:linequndec}.
\thmknapsack*

\begin{proof}
    Take the integer $n \in \N$ and the $\Z[X^{\pm}]$-module $\mA$ from Theorem~\ref{thm:linequndec}.
    First, we show that in the abelian-by-cyclic group $\mA \rtimes \Z$, there exist $h_1, \ldots, h_n \in \mA \rtimes \Z$, such that the following ``integer'' variant of the Knapsack Problem is undecidable:

    \smallskip
    \noindent \textbf{Input:} an element $h_0 \in \mA \rtimes \Z$.

    \noindent \textbf{Question:} whether there exist $(b_1, \ldots, b_{n+1}) \in \Z^{n+1}$ that satisfy the following equation:
    \begin{equation}\label{eq:weakKP}
        (\bzer, b_1) \cdot h_1 \cdot (\bzer, b_2) \cdot h_2 \cdots (\bzer, b_n) \cdot h_n \cdot (\bzer, b_{n+1}) = h_0.
    \end{equation}
    \smallskip

    We will reduce the problem from Theorem~\ref{thm:linequndec}.
    Let $\mA$ be the finitely presented $\Z[X^{\pm}]$-module constructed in Theorem~\ref{thm:linequndec}.
    Take $h_1 = (\bff_1, 0), \ldots, h_n = (\bff_n, 0)$ where $\bff_1, \ldots, \bff_n \in \mA$ are defined in Theorem~\ref{thm:linequndec}.
    For an instance of the decision problem in Theorem~\ref{thm:linequndec} with input $\bff_0 \in \mA$,
    we take the input $h_0 = (\bff_0, 0)$ in the above decision problem.
    We show that Equation~\eqref{eq:weakKP} has a solution $(b_1, \ldots, b_{n+1}) \in \Z^{n+1}$ if and only if 
    \begin{equation}\label{eq:modeq}
        X^{z_1} \bff_1 + \cdots + X^{z_n} \bff_n = \bff_0.
    \end{equation}
    has a solution $(z_1, \ldots, z_n) \in \Z^n$.

    Indeed, direct computation shows that Equation~\eqref{eq:weakKP} is equivalent to 
    \begin{equation}\label{eq:weakKPequiv}
    \left(X^{b_1} \bff_1 + X^{b_1 + b_2} \bff_2 + \cdots + X^{b_1 + b_2 + \cdots + b_n} \bff_n, b_1 + \cdots + b_n + b_{n+1} \right) = \left(\bff_0, 0 \right).
    \end{equation}
    If this has a solution $(b_1, \ldots, b_{n+1}) \in \Z^{n+1}$, then $z_1 \coloneqq b_1, z_2 \coloneqq b_1 + b_2, \ldots, z_n \coloneqq b_1 + \cdots + b_n$, is a solution for \eqref{eq:modeq}.
    Conversely, if $(z_1, \ldots, z_n) \in \Z^n$ is a solution for \eqref{eq:modeq}, then $b_1 \coloneqq z_1, b_2 \coloneqq z_2 - z_1, \ldots, b_n \coloneqq z_n - z_{n-1}, b_{n+1} \coloneqq -z_n$, is a solution for \eqref{eq:weakKPequiv}.
    By Theorem~\ref{thm:linequndec}, it is undecidable whether Equation~\eqref{eq:modeq} has integer solutions. Therefore, it is also whether Equation~\eqref{eq:weakKP} (equivalently, \eqref{eq:weakKPequiv}) has solutions $(b_1, \ldots, b_{n+1}) \in \Z^{n+1}$.

    We then prove Theorem~\ref{thm:knapsack}.
    Equation~\eqref{eq:weakKP} can be rewritten as
    \begin{equation}\label{eq:intKP}
    g_1^{b_1} g_2^{b_2} \cdots g_{n+1}^{b_{n+1}} = g,
    \end{equation}
    where
    \begin{equation*}
    g_1 = (\bzer, 1), \; g_2 = h_1 (\bzer, 1) h_1^{-1}, \; g_3 = h_1 h_2 (\bzer, 1) h_2^{-1} h_1^{-1}, \ldots, \;
    g_{n+1} = h_1 h_2 \cdots h_n (\bzer, 1) h_n^{-1} \cdots h_2^{-1} h_1^{-1},
    \end{equation*}
    and $g = h_0 h_n^{-1} \cdots h_2^{-1} h_1^{-1}$.
    Finally, Equation~\eqref{eq:intKP} has integer solutions $b_1, \ldots, b_{n+1} \in \Z$ if and only if the knapsack equation
    \begin{equation}\label{eq:nKP}
    g_1^{z_1} \left(g_1^{-1}\right)^{z'_1} g_2^{z_2} \left(g_2^{-1}\right)^{z'_2} \cdots g_{n+1}^{z_{n+1}} \left(g_{n+1}^{-1}\right)^{z'_{n+1}} = g
    \end{equation}
    has \emph{non-negative} integer solutions $z_1, z'_1, z_2, z'_2, \ldots, z_{n+1}, z'_{n+1} \in \N$.
    Therefore, it is undecidable for the input $g$, whether Equation~\eqref{eq:nKP} has solutions $z_1, z'_1, z_2, z'_2, \ldots, z_{n+1}, z'_{n+1} \in \N$.
\end{proof}

\section{Coset Intersection}\label{sec:inter}
In this section we show that Coset Intersection is decidable in all finitely generated abelian-by-cyclic groups:

\thmcoset*

For reference, an overview of our decision procedure for Theorem~\ref{thm:coset} is given in Algorithm~\ref{alg:cosetinter}.
Our solution depends on effective computation in finitely presented modules over polynomial rings.
%There are numerous algorithms that solve a wide range of computational problems in this well-studied area.
We will make use of the following classic results.

\begin{lemma}[{\cite[Lemma~2.1,~2.2]{baumslag1981computable}}]\label{lem:classicdec}
    Let $\mA$ be a $\Z[X^{\pm}]$-module with a given finite presentation.
    The following problems are effectively solvable:
    \begin{enumerate}[nosep, label = (\roman*)]
        \item \textit{(Submodule Membership)} Given elements $\ba_1, \ldots, \ba_k, \ba \in \mA$, decide whether $\ba$ is in the submodule generated by $\ba_1, \ldots, \ba_k$.
        \item \textit{(Computing Syzygies)} Given elements $\ba_1, \ldots, \ba_k \in \mA$, compute a finite set of generators for the \emph{Syzygy module} $S \subseteq \Z[X^{\pm}]^k$:
        \[
        S \coloneqq \left\{(f_1, \ldots, f_k) \in \Z[X^{\pm}]^k \;\middle|\; f_1 \cdot \ba_1 + \cdots + f_k \cdot \ba_k = \bzer \right\}.
        \]
        %\item \textit{(Computing Intersection)} Given the generators $\ba_1, \ldots, \ba_k$ of a submodule $A \subseteq \mA$ and the generators $\bb_1, \ldots, \bb_m$ of a submodule $B \subseteq \mA$, compute a finite set of generators for the submodule $A \cap B$.
        \setcounter{DecideCounter}{\value{enumi}} 
    \end{enumerate}
\end{lemma}
In particular, for Lemma~\ref{lem:classicdec}(ii), it states that one can compute the generators for the solution set of any homogeneous linear equation.
%Alternatively, Lemma~\ref{lem:classicdec}(ii) can be understood as a procedure to compute the finite presentation $\Z[X^{\pm}]^k/S$ of the module $\sum_{i = 1}^k \Z[X^{\pm}] \cdot \ba_i$.
%For (iii), we will mainly use it to decide whether the intersection of two submodules is trivial (equal to $\{\bzer\}$).

The following lemma shows we can effectively compute the intersection of a submodule of $\Z[X^{\pm}]^k$ with $\Z^k$.

\begin{lemma}[{\cite[Corollary~2.5(2)]{baumslag1981computable}}]\label{lem:decinterZ}
    Suppose we are given $k \in \N$ and elements $\bg_1, \ldots, \bg_n$ of the $\Z[X^{\pm}]$-module $\Z[X^{\pm}]^k$.
    Let $\mM$ denote the $\Z[X^{\pm}]$-module generated by $\bg_1, \ldots, \bg_n$, and define $\Lambda \coloneqq \mM \cap \Z^k$.
    Then $\Lambda \subseteq \Z^k$ is a $\Z$-module, and a finite set of generators for $\Lambda$ can be effectively computed.
\end{lemma}

Let $d \geq 1$ be a positive integer. One can define the Laurent polynomial ring over the variable $X^d$:
\[
\Z[X^{\pm d}] \coloneqq \left\{\sum_{i = p}^q a_{di} X^{di} \in \Z[X^{\pm}] \;\middle|\; p, q \in \Z, a_{dp}, \ldots, a_{dq} \in \Z \right\}.
\]
The elements of $\Z[X^{\pm d}]$ are Laurent polynomials in $\Z[X^{\pm}]$ whose monomials have degrees divisible by $d$.
For any $d \geq 1$, the ring $\Z[X^{\pm}]$ is naturally a $\Z[X^{\pm d}]$-module generated by the elements $1, X, \ldots, X^{d-1}$, and $\Z[X^{\pm}]$ is isomorphic as a $\Z[X^{\pm d}]$-module to $\Z[X^{\pm d}]^{d}$.
Any finitely presented $\Z[X^{\pm}]$-module can be considered as a finitely presented $\Z[X^{\pm d}]$-module:

\begin{restatable}{lemma}{lemchangebase}\label{lem:changebase}
    Let $d \geq 2$.
    Given a finite presentation of a $\Z[X^{\pm}]$-module $\mA$, one can compute a finite presentation of $\mA$ as a $\Z[X^{\pm d}]$-module.
    Furthermore, let $\ba \in \mA$ be given in the finite presentation of $\mA$ as $\Z[X^{\pm}]$-module, then one can compute the representation of $\ba$ in $\mA$ considered as a $\Z[X^{\pm d}]$-module.
\end{restatable}

Let $\mA$ be a $\Z[X^{\pm}]$-module given by a finite presentation.
Recall that we naturally identify $\mA$ with the subgroup $\left\{ (\ba, 0) \;\middle|\; \ba \in \mA\right\}$ of $\mA \rtimes \Z$; that is, we will sometimes write $\ba$ instead of $(\ba, 0)$ when the context is clear.
The following lemma effectively describes finitely generated subgroups of $\mA \rtimes \Z$.
Such a description follows from the general description of subgroups of finitely generated metabelian groups~\cite[proof of Theorem~1]{romanovskii1974some}.
Here we give a systematic reformulation in the context of abelian-by-cyclic groups.
\begin{restatable}[Structural theorem of abelian-by-cyclic groups, see also~\cite{romanovskii1974some}]{lemma}{lemstruct}\label{lem:struct}
    Let $\gen{\mG}$ be a subgroup of $\mA \rtimes \Z$ generated by the elements $\mG = \{g_1 \coloneqq (\ba_1, z_1), \ldots, g_K \coloneqq (\ba_K, z_K)\}$.
    Then
    \begin{enumerate}[nosep, label = (\roman*)]
        \item If $z_1 = \cdots = z_K = 0$, then $\gen{\mG}$ is contained in $\mA$ and it is the $\Z$-module generated by $\ba_1, \ldots, \ba_K$.
        \item If $z_1, \ldots, z_K$ are not all zero, then $\gen{\mG} \not\subset \mA$.
        Let $d \in \N$ denote the greatest common divisor of $z_1, \ldots, z_K$. Consider the lattice \[
        \Lambda \coloneqq \left\{(s_1, \ldots, s_K) \in \Z^K \;\middle|\; s_1 z_1 + \cdots + s_K z_K = 0\right\}.
        \]
        Let $(s_{11}, \ldots, s_{1K}), \ldots, (s_{T1}, \ldots, s_{TK})$ be a finite set of generators for $\Lambda$.
        Then $\gen{\mG} \cap \mA$ is a $\Z[X^{\pm d}]$-submodule of $\mA$, generated by the set of elements
        \begin{equation}\label{eq:genmod}
        S \coloneqq \left\{g_i g_j g_i^{-1} g_j^{-1} \;\middle|\; 1 \leq i < j \leq K \right\} \cup \left\{g_1^{s_{i1}} \cdots g_K^{s_{iK}} \;\middle|\; i \in [1, T] \right\}.
        \end{equation}
        \item In case (ii), let $\ba \in \mA$ be any element such that $(\ba, d) \in \gen{\mG}$.
        Then $\gen{\mG}$ is generated by $\gen{\mG} \cap \mA$ and $(\ba, d)$ as a group.
        In other words, every element of $\gen{\mG}$ can be written as $(\bb, 0) \cdot (\ba, d)^m$ for some $\bb \in \gen{\mG} \cap \mA$ and $m \in \Z$.
    \end{enumerate}
\end{restatable}

We point out that in case~(ii), the subgroup $\gen{\mG} \cap \mA$ is finitely generated as a $\Z[X^{\pm d}]$-module; but it is not necessarily finitely generated as a group.

\begin{example}
    Let $\mA = \Z[X^{\pm}]$, considered as a $\Z[X^{\pm}]$-module.
    Let $\gen{\mG}$ be the subgroup of $\mA \rtimes \Z$ generated by the elements $g_1 = (X, 4), g_2 = (1+X, -6)$.
    Then $d = 2$, and $\gen{\mG} \cap \mA$ is the $\Z[X^{\pm 2}]$-module generated by the elements
    \begin{equation*}
    g_1 g_2 g_1^{-1} g_2^{-1} = (X^5 + X^4 - 1 - X^{-5}, 0), \quad
    g_1^3 g_2^2 = (X^{13} + X^{12} + X^{9} + X^{7} + X^{6} + X^{5} + X, 0).
    \end{equation*}

    For example, consider the element $g_1^2 g_2 g_1 g_2 \in \gen{\mG}$.
    By direct computation, its second entry is zero, therefore $g_1^2 g_2 g_1 g_2 \in \gen{\mG} \cap \mA$.
    Furthermore, $g_1^2 g_2 g_1 g_2$ can be written as 
    \begin{multline*}
        g_1^2 g_2 g_1 g_2 = g_1^2 (g_2 g_1) g_2 = g_1^2 (g_2 g_1 g_2^{-1} g_1^{-1}) (g_1 g_2) g_2 = g_1^2 (g_1 g_2 g_1^{-1} g_2^{-1})^{-1} g_1 g_2^2 \\
        = g_1^2 (g_1 g_2^2) (g_1 g_2^2)^{-1} (g_1 g_2 g_1^{-1} g_2^{-1})^{-1} (g_1 g_2^2) = g_1^3 g_2^2 \cdot (g_1 g_2^2)^{-1} (g_1 g_2 g_1^{-1} g_2^{-1})^{-1} (g_1 g_2^2) \\
        = (X^{13} + X^{12} + X^{9} + X^{7} + X^{6} + X^{5} + X, 0) \cdot (g_1 g_2^2)^{-1} (X^5 + X^4 - 1 - X^{-5}, 0)^{-1} (g_1 g_2^2) \\
        = (X^{13} + X^{12} + X^{9} + X^{7} + X^{6} + X^{5} + X) + X^{-8} \cdot (-1) \cdot (X^5 + X^4 - 1 - X^{-5}).
    \end{multline*}
    It is therefore indeed in the $\Z[X^{\pm 2}]$-module generated by $g_1 g_2 g_1^{-1} g_2^{-1} = X^5 + X^4 - 1 - X^{-5}$ and $g_1^3 g_2^2 = X^{13} + X^{12} + X^{9} + X^{7} + X^{6} + X^{5} + X$.

    Intuitively, modulo the generator $g_1 g_2 g_1^{-1} g_2^{-1}$, one can permute letters in any word over $\mG$ (in the above example, $g_1^2 g_2 g_1 g_2$ is congruent to $g_1^3 g_2^2$).
    Whereas the generator $g_1^3 g_2^2$ guarantees the second entry of the product to be zero.
\end{example}

Given finite sets $\mG, \mH \subseteq G$ and $h \in G$, Coset Intersection asks to decide whether $\gen{\mG} \cap h \gen{\mH} = \emptyset$.
We split into three cases according to whether $\gen{\mG}$ and $\gen{\mH}$ are contained in the subgroup $\mA$.
If at least one of $\gen{\mG}$ and $\gen{\mH}$ is contained in $\mA$ (Case 1 and 2 below), then the solutions to Subgroup and Coset Intersection are relatively straightforward using the standard algorithms in Lemma~\ref{lem:classicdec} and \ref{lem:decinterZ}.
If neither $\gen{\mG}$ nor $\gen{\mH}$ is contained in the subgroup $\mA$ (Case 3 below), then the solution is more complicated and we need to invoke Theorem~\ref{thm:onemono}.
The detailed procedure is summarized in Algorithm~\ref{alg:cosetinter}.

\subsection*{Case 1: $\gen{\mG}$ and $\gen{\mH}$ are both contained in $\mA$}

Suppose $\gen{\mG}$ is generated by the elements $g_1 = (\ba_1, 0), \ldots, g_K = (\ba_K, 0)$, and $\gen{\mH}$ is generated by the elements $h_1 = (\ba'_1, 0), \ldots, h_M = (\ba'_M, 0)$.

In this case, we have
\[
\gen{\mG} = \{y_1 \cdot \ba_1 + \cdots + y_K \cdot \ba_K \mid y_1, \ldots, y_K \in \Z\}, \quad \gen{\mH} = \{z_1 \cdot \ba'_1 + \cdots + z_M \cdot \ba'_M \mid z_1, \ldots, z_M \in \Z\}.
\]

Let $h = (\ba_h, z_h)$.
If $z_h \neq 0$ then $\gen{\mG} \cap h \gen{\mH} = \emptyset$.
Therefore we only need to consider the case where $z_h = 0$.
Then $\gen{\mG} \cap h \gen{\mH} = \emptyset$ if and only if there is no solution for $y_1 \cdot \ba_1 + \cdots + y_K \cdot \ba_K = z_1 \cdot \ba'_1 + \cdots + z_M \cdot \ba'_M + z \cdot \ba_h, \; y_1, \ldots, y_K, z_1, \ldots, z_M \in \Z, z = 1$.

Let $\mM'$ denote the $\Z[X^{\pm}]$-module
\begin{multline}\label{eq:M1c}
\mM' \coloneqq \Big\{ (y_1, \ldots, y_K, z_1, \ldots, z_M, z) \in \Z[X^{\pm}]^{K+M+1} \;\Big|\; \\
y_1 \cdot \ba_1 + \cdots + y_K \cdot \ba_K - z_1 \cdot \ba'_1 - \cdots - z_M \cdot \ba'_M - z \cdot \ba_h = \bzer \Big\}.
\end{multline}

\begin{observation}
    We have $\gen{\mG} \cap h \gen{\mH} = \emptyset$ if and only if $\big(\mM' \cap \Z^{K+M+1}\big) \cap \big(\Z^{K+M} \times \{1\}\big) = \emptyset$.
\end{observation}

The generators of $\mM'$ as a $\Z[X^{\pm}]$-module can be computed by Lemma~\ref{lem:classicdec}(ii).
Then, a $\Z$-basis for $\mM' \cap \Z^{K+M+1}$ can be computed by Lemma~\ref{lem:decinterZ}. Therefore, whether $\big(\mM' \cap \Z^{K+M+1}\big) \cap \big(\Z^{K+M} \times \{1\}\big) = \emptyset$ can be decided using linear algebra over $\Z$.

\subsection*{Case 2: one of $\gen{\mG}$ and $\gen{\mH}$ is contained in $\mA$}

We can without loss of generality suppose $\gen{\mH} \subseteq \mA$ and $\gen{\mG} \not\subset \mA$.
Otherwise notice that $\gen{\mG} \cap h \gen{\mH} = \emptyset$ if and only if $h^{-1} \gen{\mG} \cap \gen{\mH} = \emptyset$, so we can exchange the role of $\gen{\mG}$ and $\gen{\mH}$.

By Lemma~\ref{lem:struct}, suppose $\gen{\mG}$ is generated by the element $(\ba_{\mG}, d_{\mG})$ and the $\Z[X^{\pm d_{\mG}}]$-module $\gen{\mG} \cap \mA$, and $\gen{\mH}$ is generated by the elements $h_1 = (\ba'_1, 0), \ldots, h_M = (\ba'_M, 0)$.
The generators of the $\Z[X^{\pm d_{\mG}}]$-module $\gen{\mG} \cap \mA$ can be effectively computed by Lemma~\ref{lem:struct}.
Also, by Lemma~\ref{lem:changebase}, we can consider $\mA$ as a finitely presented $\Z[X^{\pm d_{\mG}}]$-module instead of a $\Z[X^{\pm}]$-module, and suppose the generators of $\gen{\mG} \cap \mA$ as well as $\ba'_1, \ldots, \ba'_M$ are given as elements of the $\Z[X^{\pm d_{\mG}}]$-module $\mA$.

Let $h = (\ba_h, z_h)$.
If $d_{\mG} \nmid z_h$ then $\gen{\mG} \cap h \gen{\mH} = \emptyset$.
Therefore we only need to consider the case where $z_h = z d_{\mG}$ for some $z \in \Z$.
Then $\gen{\mG} \cap h \gen{\mH} \neq \emptyset$ if and only if the equation
$
(\bb, 0) \cdot (\ba_{\mG}, d_{\mG})^z = (\ba_h, z_h) \cdot (\bc, 0)
$
has solutions $\bb \in \gen{\mG} \cap \mA,\; \bc \in \sum_{i = 1}^M \Z \cdot \ba'_i$.
Direct computation shows this is equivalent to
\[
    X^{z_h} \cdot \bc + \left(\ba_h - \frac{X^{z d_{\mG}} - 1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} \right) = \bb.
\]

Let $\mM'$ denote the $\Z[X^{\pm d_{\mG}}]$-module
\begin{multline}\label{eq:M2c}
\mM' \coloneqq \Bigg\{ (z_1, \ldots, z_M, z) \in \Z[X^{\pm d_{\mG}}]^{M+1} \;\Bigg|\; \\
X^{z_h} \cdot \left(z_1 \cdot \ba'_1 + \cdots + z_M \cdot \ba'_M\right) + z \cdot \left(\ba_h - \frac{X^{z_h} - 1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} \right) \in \gen{\mG} \cap \mA \Bigg\}. 
\end{multline}

\begin{observation}
We have $\gen{\mG} \cap h \gen{\mH} = \emptyset$ if and only if $d_{\mG} \nmid z_h$ and $\big(\mM' \cap \Z^{M+1}\big) \cap \big(\Z^{M} \times \{1\}\big) = \emptyset$.
\end{observation}

The generators of $\mM'$ as a $\Z[X^{\pm d_{\mG}}]$-module can be computed by Lemma~\ref{lem:classicdec}(ii), applied over the quotient module $\mA / \left(\gen{\mG} \cap \mA \right)$.
Then, a $\Z$-basis for $\mM' \cap \Z^{M+1}$ can be computed by Lemma~\ref{lem:decinterZ}. 
Therefore, whether $\big(\mM' \cap \Z^{M+1}\big) \cap \big(\Z^{M} \times \{1\}\big) = \emptyset$ can be decided using linear algebra over $\Z$.

\subsection*{Case 3: neither $\gen{\mG}$ nor $\gen{\mH}$ is contained in $\mA$}

By Lemma~\ref{lem:struct}, suppose $\gen{\mG}$ is generated by $\gen{\mG} \cap \mA$ and an element $(\ba_{\mG}, d_{\mG})$; and suppose $\gen{\mH}$ is generated by $\gen{\mH} \cap \mA$ and an element $(\ba_{\mH}, d_{\mH})$.
The elements $(\ba_{\mG}, d_{\mG})$ and $(\ba_{\mH}, d_{\mH})$ can be effectively computed from the generating sets $\mG, \mH$ by performing the Euclidean algorithm.
Furthermore, $\gen{\mG} \cap \mA$ is a $\Z[X^{\pm d_{\mG}}]$-module whose generators are explicitly given (by Equation~\eqref{eq:genmod}), and $\gen{\mH} \cap \mA$ is a $\Z[X^{\pm d_{\mH}}]$-module whose generators are explicitly given.

Let $h = (\ba_h, z_h)$.
Then $\gen{\mG} \cap h \gen{\mH} = \emptyset$ if and only if the equation
$
    (\bb, 0) \cdot (\ba_{\mG}, d_{\mG})^m = (\ba_h, z_h) \cdot (\bc, 0) \cdot (\ba_{\mH}, d_{\mH})^n
$
has solutions $\bb \in \gen{\mG} \cap \mA, \bc \in \gen{\mH} \cap \mA$, and $m, n \in \Z$.
By direct computation, this is equivalent to the system
\begin{equation}\label{eq:Cosetsys}
    \bb + \frac{X^{m d_{\mG}} - 1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} = \ba_h + X^{z_h} \cdot \bc + X^{z_h} \cdot \frac{X^{n d_{\mH}} - 1}{X^{d_{\mH}} - 1} \cdot \ba_{\mH}, \quad m d_{\mG} = n d_{\mH} + z_h.
\end{equation}

We define $d \coloneqq \lcm(d_{\mG}, d_{\mH})$ to be the least common multiplier of $d_{\mG}$ and $d_{\mH}$, and consider both $\gen{\mG} \cap \mA$ and $\gen{\mH} \cap \mA$ as $\Z[X^{\pm d}]$-modules, respectively generated by the sets $S_{\mG}$ and $S_{\mH}$.
The sets $S_{\mG}$ and $S_{\mH}$ can be effectively computed by Lemma~\ref{lem:changebase} from the generators of $\gen{\mG} \cap \mA$ as a $\Z[X^{\pm d_{\mG}}]$-module, and from the generators of $\gen{\mH} \cap \mA$ is a $\Z[X^{\pm d_{\mH}}]$-module.
We define the $\Z[X^{\pm d}]$-module 
\[
    \mM' \coloneqq (\gen{\mG} \cap \mA) + X^{z_h} \cdot (\gen{\mH} \cap \mA),
\]
which is generated by the set $S_{\mG} \cup \{X^{z_h} \cdot s \mid s \in S_{\mH}\}$.

If $m d_{\mG} = n d_{\mH} + z_h$ has no integer solutions $m, n$, then $\gen{\mG} \cap h \gen{\mH} = \emptyset$.
Otherwise, there exist $z_{\mG} \coloneqq m d_{\mG}, z_{\mH} \coloneqq n d_{\mH} \in \Z$ such that $d_{\mG} \mid z_{\mG},\; d_{\mH} \mid z_{\mH}$ and $z_{\mG} = z_{\mH} + z_h$.
Then, every solution $(m, n) \in \Z^2$ of the equation $m d_{\mG} = n d_{\mH} + z_h$ is of the form
\[
m = (z_{\mG} + z d)/d_{\mG}, \quad n = (z_{\mH} + z d)/d_{\mH}, \quad z \in \Z.
\]

\begin{restatable}{lemma}{lemcosettoeq}\label{lem:cosettoeq}
    Let $z_{\mG}, z_{\mH}$ be integers such that $d_{\mG} \mid z_{\mG},\; d_{\mH} \mid z_{\mH}$ and $z_{\mG} = z_{\mH} + z_h$.
    The intersection $\gen{\mG} \cap h \gen{\mH}$ is non-empty if and only if the equation
        \begin{equation}\label{eq:Coseteqz}
            X^{z d} \cdot \ba'_{\mG, \mH} - \ba''_{\mG, \mH} \in (X^d - 1) \cdot \mM'
        \end{equation}
        has solution $z \in \Z$.
        Here,
        \[
        \ba'_{\mG, \mH} \coloneqq X^{z_{\mG}} \cdot \left(\frac{X^d - 1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} - \frac{X^d - 1}{X^{d_{\mH}} - 1} \cdot \ba_{\mH}\right),
        \]
        \[
        \ba''_{\mG, \mH} \coloneqq \frac{X^d - 1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} - X^{z_h} \cdot \frac{X^d - 1}{X^{d_{\mH}} - 1} \cdot \ba_{\mH} + (X^d - 1) \cdot \ba_h.
        \]
\end{restatable}
\begin{proof}
    Suppose the $\gen{\mG} \cap h \gen{\mH}$ is non-empty. Let $(\ba, z') \in \gen{\mG} \cap h \gen{\mH}$, then $d_{\mG} \mid z'$ and $d_{\mH} \mid (z' - z_h)$.
    Hence $z' = z_{\mG} + zd = z_{\mH} + zd + z_h$ for some $z \in \Z$.
    Since $(\ba, z') \in \gen{\mG} \cap h \gen{\mH}$, the Equation~\eqref{eq:Cosetsys} has solution with $m d_{\mG} = z' = z_{\mG} + zd, \; n d_{\mH} = z' - z_h = z_{\mH} + zd$, meaning
    \begin{multline*}
        \frac{X^{z d} \cdot \ba'_{\mG, \mH} - \ba''_{\mG, \mH}}{X^d - 1} =
        \frac{X^{z_{\mG} + zd}}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} - \frac{X^{z_{\mG} + zd}}{X^{d_{\mH}} - 1} \cdot \ba_{\mH} - \frac{1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} + \frac{X^{z_h}}{X^{d_{\mH}} - 1} \cdot \ba_{\mH} - \ba_h \\
        = \frac{X^{z_{\mG} + zd} - 1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} - \frac{X^{z_{\mG} + zd} - X^{z_h}}{X^{d_{\mH}} - 1} \cdot \ba_{\mH} - \ba_h \\
        = \frac{X^{z_{\mG} + zd} - 1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} - X^{z_h} \cdot \frac{X^{z_{\mH} + zd} - 1}{X^{d_{\mH}} - 1} \cdot \ba_{\mH} - \ba_h = X^{z_h} \cdot \bc - \bb \in \mM'.
    \end{multline*}
    Therefore \eqref{eq:Coseteqz} is satisfied.

    Conversely, suppose Equation~\eqref{eq:Coseteqz} is satisfied.
    Then we have
    \[
    \frac{X^{z_{\mG} + zd} - 1}{X^{d_{\mG}} - 1} \cdot \ba_{\mG} - X^{z_h} \cdot \frac{X^{z_{\mH} + zd} - 1}{X^{d_{\mH}} - 1} \cdot \ba_{\mH} - \ba_h = \frac{X^{z d} \cdot \ba'_{\mG, \mH} - \ba''_{\mG, \mH}}{X^d - 1} \in \mM',
    \]
    so it can be written as $X^{z_h} \cdot \bc - \bb$ for some $\bb \in \gen{\mG} \cap \mA, \; \bc \in \gen{\mH} \cap \mA$.
    Hence the system~\eqref{eq:Cosetsys} has solutions $\bb \in \gen{\mG} \cap \mA,\; \bc \in \gen{\mH} \cap \mA,\; m = \frac{z_{\mG} + z d}{d_{\mG}},\; n = \frac{z_{\mH} + z d}{d_{\mH}}$.
\end{proof}

%We can decide if 
%\begin{equation}\label{eq:faainM}
%f \cdot \ba'_{\mG, \mH} - \ba''_{\mG, \mH} \in (X^d - 1) \cdot \mM'
%\end{equation}
%has solution $f \in \Z[X^{\pm d}]$ by deciding membership of $\ba''_{\mG, \mH}$ in the $\Z[X^{\pm d}]$-module generated by $\ba'_{\mG, \mH}$ and $\mM'$ (see Lemma~\ref{lem:classicdec}(i)).
%If Equation~\eqref{eq:faainM} does not have a solution $f \in \Z[X^{\pm d}]$, then \eqref{eq:Coseteqz} cannot have a solution $z \in \Z$; otherwise, we can compute a solution $f = f_0$ of Equation~\eqref{eq:faainM}.
%For example, $f_0$ can be computed by enumerating all elements $f \in \Z[X^{\pm d}]$ (there are countably many), and test for each one whether it satisfies Equation~\eqref{eq:faainM}.
%Since Equation~\eqref{eq:faainM} has a solution, this procedure must terminate.

By Lemma~\ref{lem:cosettoeq}, it suffices to decide whether Equation~\eqref{eq:Coseteqz} has a solution $z \in \Z$.
To do this, consider both $\mA$ and $(X^d - 1) \cdot \mM'$ as $\Z[X^{\pm d}]$-modules.
Equation~\eqref{eq:Coseteqz} is equivalent to the equation
\begin{equation}\label{eq:inquot}
\left(X^{d}\right)^z \cdot \ba'_{\mG, \mH} = \ba''_{\mG, \mH}
\end{equation}
in the quotient module $\mA / \left((X^d - 1) \cdot \mM'\right)$.
Applying Theorem~\ref{thm:onemono} to the variable $X^d$ (instead of $X$) and the finitely presented $\Z[X^{\pm d}]$-module $\mA / \left((X^d - 1) \cdot \mM'\right)$, we can decide whether the above equation has a solution $z \in \Z$.

Combining the three cases, we have proven Theorem~\ref{thm:coset}.

\begin{algorithm}[!h]
\caption{Algorithm for Coset Intersection}
\label{alg:cosetinter}
\begin{description} 
\item[Input:]
a finite presentation of the $\Z[X^{\pm}]$-module $\mA$, two finite sets of elements $\mG = \{(\ba_1, z_1), \ldots, (\ba_K, z_K)\},\; \mH = \{(\ba'_1, z'_1), \ldots, (\ba'_M, z'_M)\}$ in the group $\mA \rtimes \Z$, an element $h = (\ba_h, z_h)$.
\item[Output:] \textbf{True} (when $\gen{\mG} \cap h \gen{\mH} = \emptyset$) or \textbf{False} (when $\gen{\mG} \cap h \gen{\mH} \neq \emptyset$).
\end{description}
\begin{enumerate}[nosep, label=\arabic*.]
    \item \textbf{If $z_1, \ldots, z_K$ and $z'_1, \ldots, z'_M$ are all zero.}

    Compute generators of the module $\mM'$ defined in Equation~\eqref{eq:M1c}.

    Decide whether 
    $
    \big(\mM' \cap \Z^{K+M+1}\big) \cap \big(\Z^{K+M} \times \{1\}\big) = \emptyset
    $
    using Lemma~\ref{lem:classicdec} and \ref{lem:decinterZ}.
    If yes, return \textbf{True}, otherwise return \textbf{False}.

    \item \textbf{If one of the sets $\{z_1, \ldots, z_K\}$ and $\{z'_1, \ldots, z'_M\}$ is all zero.}

    Without loss of generality suppose $z'_1 = \cdots = z'_M = 0$, otherwise swap the sets $\mG, \mH$ and replace $h$ with $h^{-1}$.
    \begin{enumerate}[nosep, label = (\roman*)]
        \item Compute $d_{\mG} \coloneqq \gcd(z_1, \ldots, z_K)$, and compute generators of the $\Z[X^{\pm d_{\mG}}]$-module $\gen{\mG} \cap \mA$ using Lemma~\ref{lem:struct}.
        \item If $d_{\mG} \mid z_h$, continue, otherwise return \textbf{True}.
        \item Compute generators of the modules $\mM'$ defined in Equation~\eqref{eq:M2c}.

        Decide whether 
        $
        \big(\mM' \cap \Z^{M+1}\big) \cap \big(\Z^{M} \times \{1\}\big) = \emptyset
        $
        using Lemma~\ref{lem:classicdec} and \ref{lem:decinterZ}.
        If yes, return \textbf{True}, otherwise return \textbf{False}.
    \end{enumerate}
    \item \textbf{If none of the sets $\{z_1, \ldots, z_K\}$ and $\{z'_1, \ldots, z'_M\}$ is all zero.}
    \begin{enumerate}[nosep, label = (\roman*)]
        \item Compute $d_{\mG} \coloneqq \gcd(z_1, \ldots, z_K), d_{\mH} \coloneqq \gcd(z'_1, \ldots, z'_M), d \coloneqq \gcd(d_{\mG}, d_{\mH})$.
        \item Decide whether the equation $m d_{\mG} = n d_{\mH} + z_h$ has solutions $(m, n) \in \Z^2$.
        If yes, take any solution $(m, n)$ and let $z_{\mG} \coloneqq m d_{\mG},\; z_{\mH} \coloneqq n d_{\mH}$; otherwise return \textbf{True}.
        \item Compute the generators of the $\Z[X^{\pm d_{\mG}}]$-module $\gen{\mG} \cap \mA$ and the generators of the $\Z[X^{\pm d_{\mH}}]$-module $\gen{\mH} \cap \mA$ using Lemma~\ref{lem:struct}.
        Compute their respective generators $S_{\mG}, S_{\mH}$ as $\Z[X^{\pm d}]$-modules using Lemma~\ref{lem:changebase}.
        Let $\mM'$ be the $\Z[X^{\pm d}]$-module generated by $S_{\mG} \cup \{X^{z_h} \cdot s \mid s \in S_{\mH}\}$.
        \item %Compute a finite presentation of the $\Z[X^{\pm d}]$-module $\mA/\left((X^d - 1) \cdot \mM'\right)$ using Lemma~\ref{lem:changebase}. 
        Decide whether the Equation~\eqref{eq:inquot} over $\mA/\left((X^d - 1) \cdot \mM'\right)$ has a solution $z \in \Z$, using Theorem~\ref{thm:onemono}.
        If yes, return \textbf{False}, otherwise return \textbf{True}.
    \end{enumerate}
\end{enumerate}
\end{algorithm}

