\thmonemono*
\begin{proof}
We give a deduction of Theorem~\ref{thm:onemono} from Noskov's Lemma:
\begin{lemma}[{Noskov's Lemma~\cite{noskov1982conjugacy}, see also~\cite[Proposition~2.4]{baumslag1994algorithmic}}]
    There is an algorithm which, given a finitely generated commutative ring $R$ and a finite subset $S$ of the group of units $U(R)$, finds a finite presentation of the multiplicative subgroup $\langle S \rangle$.
\end{lemma}

Consider the ideal
\begin{equation}\label{eq:defI}
\mI \coloneqq \left\{f \in \Z[X^{\pm}] \;\middle|\; f \cdot \bff_1 = \bzer \right\}
\end{equation}
of $\Z[X^{\pm}]$, then a finite set of generators for $\mI$ can be computed by Lemma~\ref{lem:classicdec}(ii).

Using Lemma~\ref{lem:classicdec}(i), decide whether there exists $h_0 \in \Z[X^{\pm}]$ such that $h_0 \cdot \bff_1 = \bff_0$.
If such $h_0$ does not exist, then $X^z \cdot \bff_1 = \bff_0$ has no solution $z \in \Z$.
Otherwise, if such an $h_0$ exists, it can be found by enumerating through $\Z[X^{\pm}]$.
The solution set
\[
    \left\{f \in \Z[X^{\pm d}] \;\middle|\; f \cdot \bff_1 = \bff_0 \right\}
\]
is equal to $h_0 + \mI \coloneqq \{h_0 + f \mid f \in \mI\}$.
Consider the ideal $\mJ$ of $\Z[X^{\pm}, Y^{\pm}]$ generated by $\mI$ and the element $Y - h_0$.
Then $X^z \in h_0 + \mI$ if and only if $X^z - Y \in \mJ$, which is equivalent to the equation $X^z = Y$ in the quotient ring $\Z[X^{\pm}, Y^{\pm}]/\mJ$.
We then apply Noskov's Lemma on the quotient ring $R = \Z[X^{\pm}, Y^{\pm}]/\mJ$ and the subset $S = \{X, Y\}$ of its group of units.
This determines whether there exists $z \in \Z$ such that $X^z = Y$ in the quotient ring $\Z[X^{\pm}, Y^{\pm}]/\mJ$.
\end{proof}

\lemchangebase*
\begin{proof}
    Write $\mA = M/N$ where $M, N \subseteq \Z[X^{\pm}]^D$.
    Every element $\bg \in \Z[X^{\pm}]^D$ can be uniquely written as $\bg = \bg_0 + X \cdot \bg_1 + \cdots + X^{d-1} \cdot \bg_{d-1}$ where $\bg_0, \bg_1, \ldots, \bg_{d-1}$ are in $\Z[X^{\pm d}]^D$.
    This gives an effective isomorphism $\varphi \colon \Z[X^{\pm}]^D \rightarrow \Z[X^{\pm d}]^{Dd}$.
    The generators of $\varphi(M)$ can be obtained by simply applying $\varphi$ to the generators of $M$, similarly for $\varphi(N)$.
    Hence $\mA = \varphi(M)/\varphi(N)$ is a finite presentation of $\mA$ as a $\Z[X^{\pm d}]$-module.
\end{proof}

\lemstruct*
\begin{proof}
    (i) is obvious.
    For (ii), suppose $z_1, \ldots, z_K$ are not all zero and let $d \in \N$ be their greatest common divisor.
    Let $n_1, \ldots, n_K \in \Z$ be such that $n_1 z_1 + \cdots + n_K z_K = d$, then $g \coloneqq g_1^{n_1} \cdots g_K^{n_K}$ is of the form $(\bb, d), \bb \in \mA$.
    Then for any $\ba \in \gen{\mG} \cap \mA$, we have $\gen{\mG} \cap \mA \ni g^{-1} \ba g = (- X^{-d} \cdot \bb, -d) (\ba, 0) (\bb, d) = (X^d \cdot \ba, 0) = X^d \cdot \ba$.
    Similarly, $\gen{\mG} \cap \mA \ni g \ba g^{-1} = X^{-d} \cdot \ba$.
    Therefore, $\gen{\mG} \cap \mA$ is a $\Z[X^{\pm d}]$-module.

    On one hand, the elements in $S$ are obviously in $\gen{\mG} \cap \mA$, so the $\Z[X^{\pm d}]$-module generated by $S$ is a submodule of $\gen{\mG} \cap \mA$.
    On the other hand, we show that the quotient $(\gen{\mG} \cap \mA)/S$ is trivial.
    Notice that since $(g_i g_j g_i^{-1} g_j^{-1})^{-1} = g_j g_i g_j^{-1} g_i^{-1}$, we have $\left\{g_i g_j g_i^{-1} g_j^{-1} \;\middle|\; i, j \in [1, K] \right\} \subseteq S$.
    Therefore, the quotient by $S$ allows one to permute elements in any product $g_{i_1}^{\epsilon_1} \cdots g_{i_n}^{\epsilon_n} \in \gen{\mG} \cap \mA$ without changing their class in $(\gen{\mG} \cap \mA)/S$.
    More precisely, for $g, g' \in \gen{\mG}$ and $i, j \in [1, K]$, if $g g_i g_j g' \in \mA$ then we have $g g_i g_j g' + S = g g_j g_i g' + S$.
    Indeed, we have $g g_i g_j g' = g (g_i g_j g_i^{-1} g_j^{-1}) g_j g_i g' = g (g_i g_j g_i^{-1} g_j^{-1}) g^{-1} + g g_j g_i g'$ and $g (g_i g_j g_i^{-1} g_j^{-1}) g^{-1}$ is in the $\Z[X^{\pm d}]$-module generated by $S$.
    For every product $g_{i_1}^{\epsilon_1} \cdots g_{i_n}^{\epsilon_n} \in \gen{\mG} \cap \mA$, we must have 
    \[
    \left(\sum_{j \in [1, n], i_j = 1} \epsilon_j, \ldots, \sum_{j \in [1, n], i_j = K} \epsilon_j\right) \in \Lambda
    \]
    by looking at the second component.
    Since $(s_{11}, \ldots, s_{1K}), \ldots, (s_{T1}, \ldots, s_{TK})$ be are the generators for $\Lambda$, by permuting the elements in the product we can rewrite $g_{i_1}^{\epsilon_1} \cdots g_{i_n}^{\epsilon_n}$ as 
    \[
    \left(g_1^{s_{1 1}} \cdots g_K^{s_{1 K}}\right)^{j_1} \cdots \left(g_1^{s_{T 1}} \cdots g_K^{s_{T K}}\right)^{j_T},
    \]
    where $j_1, \ldots, j_T \in \Z$.
    Therefore, $g_{i_1}^{\epsilon_1} \cdots g_{i_n}^{\epsilon_n}$ is in the $\Z[X^{\pm d}]$-module generated by $S$.

    For (iii), $\ba \in \mA$ be any element such that $(\ba, d) \in \gen{\mG}$.
    Since $d \in \N$ is the greatest common divisor for $z_1, \ldots, z_K$, every element $g$ of $\gen{\mG}$ must be of the form $(\bc, md), \; \bc \in \mA, m \in \Z$.
    Then $g \cdot (\ba, d)^{-m} \in \gen{\mG} \cap \mA$. Let $(\bb, 0) \coloneqq g \cdot (\ba, d)^{-m}$, then $\ba \in \gen{\mG} \cap \mA$ and $g = (\bb, 0) \cdot (\ba, d)^m$.
\end{proof}

