%         \State $\mP^l \gets \Call{RowNorm}{\mP^l}$
%     \EndFor
% \EndProcedure
\end{algorithmic}
\caption{Forward pass for Interaction GNN layer. Inputs to the forward pass are the adjacency matrix for the graph $\mA\in \{0,1\}^{n\times n}$ stored in COO format, node features $\mX\in\mathbb{R}^{n\times f}$, and edge features $\mY\in\mathbb{R}^{m\times f}$. While each MLP (denoted by $\phi$) is distinct, superscripts are omitted for simplicity.} \label{alg:ignnlayer}
