\begin{restatable}{lemma}{lemtruthbfnonmono}\label{lem:truth-bf-nonmono}
\Cref{mechanism:nonmono-sm-conv} is truthful, budget feasible and individually rational.    
\end{restatable}

\begin{lemma}\label{lem:mechanism-nonmono-with-prediction}
    \Cref{mechanism:nonmono-sm-pred}, with access to a prediction $\omega=(1-\varepsilon)\cdot v(S^*)$ with $\varepsilon\in [0,1)$,  has an approximation ratio of $\min\!\left\{
    \frac{a\cdot (1-\varepsilon)\cdot p}{z},(1-p)\cdot(\frac{1}{4}-\frac{(1-\varepsilon)\cdot a)}{2}),(1-p)\cdot a\cdot (1-\varepsilon)\cdot\frac{z-1}{2\cdot z}\right\}$ in expectation.
\end{lemma}
\begin{proof}[Proof Sketch]
    The proof is quite similar to the one of \Cref{lem:mechanism-with-prediction}, it discriminates between the same three cases and proceeds in a similar way. In order to avoid repeating the same arguments, we will restrict this proof to the second case, which requires different calculations due to the non-monotonicity of the value functions. Also, we will use some extra notation, for an agent $i$ we denote as $S_{j(i)}$, $j(i)\in \{1,2\}$ the set in which agent $i$ had the greatest marginal contribution when arrived and with $S_j^{t_i}$ the set $S_j$ at the moment $t_i$ that agent $i$ arrived.
\begin{itemize}
        \item \underline{Each agent $i\in S^*\setminus (S_1\cup S_2)$ rejects the posted price and $v(i^*)\leq \frac{a\cdot (1-\varepsilon)}{z}$.}\\
From the definition of submodular functions we have that:
\begin{align*}
    v(S_1\cup S^*)+v(S_2\cup S^*)\geq v(S^*)+v(S_1\cup S_2\cup S^*)\geq v(S^*),
\end{align*}where the last inequality holds because the value function $v$ is non-negative. From the definition of submodularity again we get:
\begin{align*}
    v(S_1\cup S^*) &\leq v(S_1)+\sum\limits_{i\in S^*\setminus S_1}v(i|S_1)\\&=v(S_1)+\sum\limits_{i\in S^*\setminus(S_1\cup S_2)} v(i|S_1)+\sum\limits_{i\in (S^*\cap S_2)\setminus S_1} v(i|S_1)\\ &\leq v(S_1)+\sum\limits_{i\in S^*\setminus(S_1\cup S_2)} v(i|S_1^{t_i})+\sum\limits_{i\in (S^*\cap S_2)\setminus S_1} v(i|S_1^{t_i})\\&\leq v(S_1)+\sum\limits_{i\in S^*\setminus(S_1\cup S_2)} v(i|S_1^{t_i})+\sum\limits_{i\in (S^*\cap S_2)\setminus S_1} v(i|S_{2}^{t_i}) \\ &\leq v(S_1)+\sum\limits_{i\in S^*\setminus(S_1\cup S_2)} v(i|S_1^{t_i})+\sum\limits_{i\in S_2} v(i|S_{2}^{t_1})
    \\&= v(S_1)+v(S_2)+\sum\limits_{i\in S^*\setminus(S_1\cup S_2)} v(i|S_1^{t_i}),
\end{align*}
where the first inequality holds because $S_1^{t_i}\subseteq S_1$ and the second one due to the fact that each agent  $i\in S_2^*\cap S_2$ was added to set $S_2$, hence $v(i|S_1^{t_i})\leq v(i|S_2^{t_i})$. Symmetrically, we get that: 
\begin{align*}
    v(S_2\cup S^*)\leq v(S_2)+v(S_1)+\sum\limits_{i\in S^*\setminus(S_1\cup S_2)} v(i|S_2^{t_i}).
\end{align*}
Adding up, these two inequalities and dividing by 4, we have that: 
\begin{align*}
\frac{v(S_1)}{2}+\frac{v(S_2)}{2}\geq \frac{v(S^*)}{4}-\frac{1}{2} \sum\limits_{i\in S^*\setminus(S_1\cup S_2)} v(i|S_{j(i)}^{t_i}),
\end{align*} which combined with the fact that each agent $i\in S^*\setminus(S_1\cup S_2)$ rejected the posted price offered by the mechanism and also that $\mathbb{E}[v(S)]=\frac{v(S_1)}{2}+\frac{v(S_2)}{2}$, leads to: 
\begin{align*}
\EX[v(S)]&\geq \frac{v(S^*)}{4}-\frac{\sum\limits_{i\in S^*\setminus(S_1\cup S_2)} c_i \cdot a\cdot(1-\varepsilon)\cdot v(S^*)}{2\cdot B}
\\ &\geq  \frac{v(S^*)}{4}-\frac{ a\cdot(1-\varepsilon)\cdot v(S^*)}{2},
\end{align*}
where the last inequality holds due to budget feasibility of set $S^*$. \qedhere
\end{itemize}
\end{proof}

    \begin{restatable}{lemma}{lemmechanismnonmonowithoutprediction}\label{lem:mechanism-nonmono-without-prediction}
    \Cref{mechanism:nonmono-sm-withoutpred}, has an approximation ratio of:
    \begin{align*} 
    \min\{(1-q) \cdot \tilde{p} \cdot  \min{\left( \frac{1}{8}-\frac{\delta}{4}-\frac{\beta}{2}, \frac{z-1}{2\cdot z}\cdot\frac{\beta}{e}\cdot(\frac{1}{2}-\delta) \right)}, \frac{q}{e}\cdot \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta) \},
     \end{align*}
     in expectation, where $\tilde{p}=1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{\beta}{z\cdot e}\cdot(\frac{1}{2}-\delta))\cdot(\frac{1}{4}+ \frac{\delta}{3})}\right)}.$   
\end{restatable}

\subsection{The Non-Monotone Analogue of  \Cref{mechanism:mono-sm2} }
Here we will present a Mechanism, that follows the same approach as \Cref{mechanism:mono-sm2}, adapted for the non-monotone case, by building two solutions instead of a single one. Again, we can not simply return the best of the two solutions built, since this would violate the Random Order Model, so the mechanism selects beforehand, randomly which one will return, with probability $\frac{1}{2}$, for each solution. 
\begin{mechanism}[!ht]
\caption{Online mechanism for a general submodular function $v$, parameterized by tolerance $\tau \in [0,1)$.}\label{mechanism:non-mono-sm2}
\DontPrintSemicolon
\setstretch{1.1}
\SetInd{4pt}{7pt} 
% \color{red}
% \SetVline
\begin{algolabel}{}[\textbf{With probability} $q$\,\textbf{:}  \SetNoFillComment {\small \tcc*[f]{Dynkin's Algorithm}}]

Sample the first $\floor{n/e}$ agents; let $i^*$ be the most valuable among them.

From the remaining agents, return the first agent $j$ for whom $v(j)\geq v(i^*)$ and pay her $B$.
\end{algolabel}


\begin{algolabel}{}[\textbf{With probability $1-q$\,:}]


Draw $\xi_1$ from the binomial distribution $\mathcal{B}(n,\frac{1}{k})$. 


Let $N_1$ be the set of the first $\xi_1$ agents that arrive.  \

Let $T_1$ be a  $(\frac{1}{e})$-approximate solution to \eqref{eq:opt} on $N_1$, using the algorithm of \citet{kulik2013}. 


Set $t= a\cdot \omega +\beta\cdot v(T_1)$

Set $S=S_1=S_2=\emptyset$, $B_1=B_2=B$.

$S= S_j$, where $j$ is uniformly drawn from $\{1,2\}$.

\For{each round as $i \in N_2$ arrives}{
Let $j(i)=\argmax_{j\in\{1,2\}}v(i|S_j)$

\If{$c_i \leq \bar{p}_i:=\frac{B}{t} v(i \,|\, S_{j(i)}) $ and $B_{j(i)}-\bar{p}_i \geq 0$}{

   Add $i$ to $S_{j(i)}$, set $p_i=\bar{p}_i$ and $B_{j(i)}=B_{j(i)}-\bar{p}_i$.

}
}

Set $p_i = 0$ for any $i\notin S$.
\end{algolabel}
\nlset{15}\Return set $S$ and payments $\vec{p}$.
\end{mechanism}\smallskip
\begin{lemma}\label{lem:truth-bf-nonmono-2}
\Cref{mechanism:non-mono-sm2} is truthful, budget feasible and individually rational.    
\end{lemma}
The proof of this Lemma, is similar to the proof of \Cref{lem:truth-bf-nonmono}.
\begin{restatable}{theorem}{thmapproxnonmonosmtwo}\label{thm:approx-non-mono-sm2}
    \Cref{mechanism:non-mono-sm2}, given access to a prediction $\omega=(1-\varepsilon)\cdot v(S^*)$ with $\varepsilon\in[0,1)$, has an approximation guarantee of 
    \begin{align*}
        &\min\left\{ \frac{q}{e\cdot z}\cdot ( a\cdot (1-\varepsilon)+  \frac{\beta}{e}\cdot(\frac{1}{k}-\delta)),\right.\\ & \left. (1-q) \cdot \tilde{p}\cdot  \min\left(\left(\frac{1}{4}\cdot (\frac{k-1}{k}-\delta) -\frac{1}{2}\cdot ( a\cdot (1-\varepsilon)+ \beta)\right), \frac{z-1}{2\cdot z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot (\frac{1}{k}-\delta)) \right)\right\},
    \end{align*}
    where $\tilde{p}=1-2\cdot \displaystyle\exp{\left(-\frac{\delta^2/ 2 }{(\frac{k-1}{k^2}+\frac{\delta}{3})\cdot\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot (\frac{1}{k}-\delta))}\right)}$.
\end{restatable}
From the above Theorem, we obtain the following corollary, which gives us the in expectation consistency and robustness tradeoff of \Cref{mechanism:non-mono-sm2}.
\begin{corollary}\label{corolarry:cons-rob-non-mono-sm2}
    \Cref{mechanism:mono-sm-conv}, given access to a possibly erroneous prediction $\omega=(1-\varepsilon)\cdot v(S^*)$, with $\varepsilon\in [0,1)$, achieves in expectation, a consistency-robustness tradeoff of $228$ and $818$, by setting $q=0.61$, $z=2.47$, $\beta=0.155$, $a=0.035$, $\delta=0.164$ and $k=2.5$.
\end{corollary}

\section{An Impossibility Result}\label{sec:lower-bound}
Here we turn our attention to the \textit{offline} setting and present a lower bound of $2$ on the consistency guarantee for all universally truthful, budget-feasible, and individually rational randomized mechanisms \textit{with predictions}. Clearly, this impossibility result obviously extends to the online setting as well. Moreover, our result holds even when the instances are augmented with a prediction of the optimal set of agents $\hat{S} \subseteq N$, rather than merely the value of the optimal solution $\omega$ as assumed in \Cref{sec:mono-submodular,sec:nonmono-submodular}. Note that having access to $\hat{S}$ in the offline setting is at least as informative as having access to $\omega$, since the latter can be inferred from the former, i.e., given a prediction $\hat{S}$, we may set $\omega = v(\hat{S})$. We denote by $\mathcal{M}$ the class of universally truthful, budget-feasible, and individually rational randomized mechanisms, and by $\mathcal{M}^d \subseteq \mathcal{M}$ the subclass of deterministic mechanisms that are truthful, budget-feasible, and individually rational.
The main result of this section is \Cref{thm:randomized-lb-2}.

\begin{theorem}\label{thm:randomized-lb-2}
    For any $\varepsilon > 0$, no universally truthful, individually rational,  budget-feasible randomized mechanism that has access to a prediction of the optimal solution can be $(2-\varepsilon)$-consistent, even for  additive valuation functions.
\end{theorem}

To prove \Cref{thm:randomized-lb-2}, we focus on a family of augmented instances with just two agents that differ only in their cost profiles. Specifically, for each such instance, we set $v(\{1\}) = v(\{2\}) = 1$, denote the budget as $B$, and assume access to a prediction $\hat{S}=\{1,2\}$. We refer to these instances as \emph{canonical}. Note that the prediction is perfect only for cost profiles where the optimal solution coincides with it, i.e., when, given a profile $\vec{c} = (c_1, c_2)$, it holds that $c_1 + c_2 \leq B$.


One of the technical tools we use to prove \Cref{thm:randomized-lb-2} is Yao's Lemma (due to \citet{yao1977}). Intuitively, this idea enables us to show a lower bound on the performance of a universally truthful, individually rational and budget-feasible randomized mechanism $M \in \mathcal{M}$ by focusing on the performance of an (arbitrarily given) deterministic truthful, individually rational and budget-feasible mechanism $(A, p) \in \mathcal{M}^d$ instead. This is achieved by constructing an ``adversarial'' distribution of instances of canonical instances and reasoning about the performance of $(A, p)$ for the distribution. \Cref{lemma:yao} is a weaker version of Yao's Lemma for our procurement auction setting which is sufficient for our purposes. For completeness, we provide its proof in \Cref{app:sec6}.

\begin{restatable}{lemma}{lemmayao}\label{lemma:yao}
    Let $C$ be a set of cost profiles for canonical instances. For any mechanism $M=(A^r, p^r) \in \mathcal{M}$ and any discrete probability distribution P of profiles in $C$, we have
\begin{equation*}\label{eq:yao-minmax}
        \min_{\vec{c} \in C}\EX\left[\frac{v\left(A^r(\vec{c}) \right)}{v\left(S^*(\vec{c}) \right)} \right] \leq  \max_{{(A,p) \in 
        \mathcal{M}^d}} \EX_{\vec{c} \sim P}\left[\frac{v\left(A(\vec{c}) \right)}{v\left(S^*(\vec{c}) \right)} \right].
    \end{equation*}
\end{restatable}


