\section{Missing Material from  \Cref{sec:nonmono-submodular}}\label{app:sec5}

\lemtruthbfnonmono*
\begin{proof}
Regarding universal truthfulness, since the mechanism is a probability distribution on two different mechanisms, it suffices to argue about each of them separately. We will show that it holds for \Cref{mechanism:nonmono-sm-withoutpred} and the proof for \Cref{mechanism:nonmono-sm-pred} is similar. First, \Cref{mechanism:nonmono-sm-withoutpred} with probability $q$, runs Dynkin's, which is obviously truthful.   

Coming now to the second mechanism that is run with probability $1-q$,  fix an arrival sequence, as realized by the random arrival model, and fix also $\xi_1$, the number of agents that determine the set $N_1$.
Note that the agents have no control over the position in which they arrive. Hence, any agent $i \in N_1$ is always rejected by the mechanism, regardless of the cost she declares. 
Moreover, each agent $i \in N_2$ is offered a price $p_i$, which is independent of her declared cost, since agent $i$ has no control over her slot of arrival and thus cannot affect her marginal contribution.

For the sake of contradiction, assume that agent $j\in N_2$ can achieve a better outcome by misreporting a cost $b_j \neq c_j$, while all other agents keep the same reported costs. Suppose first that agent $j$ belongs to the winning set $S$, under the truthful profile. 
Then by misreporting, she receives the same payment as long as her declared cost is below the threshold $p_j$ which is still the same as before, since the algorithm runs in exactly the same way up until the time, that $i$ arrives. If the declared cost is above the threshold, she is rejected by the mechanism and receives a payment of 0. Hence, when $j \in S$, she cannot guarantee a better utility by misreporting her true cost. Suppose now that agent $j$ does not belong to the solution $S$, under truthful reporting. She certainly cannot benefit from reporting a higher cost than $c_j$, as that would still result in rejection by the mechanism. 
Additionally, if she reports a lower cost than $c_j$ and she is added to the solution $S$, this means that the reason for rejection before, was that the offered payment was less than her true cost $c_j$ (and not because of budget exhaustion). By reporting $b_c < c_j$, given that the payment offered by the mechanism remains the same, this results in negative utility for agent $j$. All of the above leads to the conclusion that no agent can benefit from misreporting her true cost.

For budget feasibility, note first that in the case the mechanism runs Dynkin's algorithm, the mechanism pays exactly $B$. Otherwise, the second inequality in the if-condition in line 13 guarantees that for the solution $S$ returned by the mechanism, $\sum_{i \in S} p_i \leq B$, which ensures the budget feasibility of the solution $S$.

Finally, through the first inequality of the if condition in line 13, individual rationality is ensured, since for any agent $i$ added in $S$, it holds that $p_i\geq c_i$. 

\end{proof}

\lemmechanismnonmonowithoutprediction*
\begin{proof}

This proof resembles a lot the proof of \Cref{lem:mechanism-without-prediction}, so again in order to avoid repetition we will present the proof briefly. We will use the same extra notation, that was introduced in the proof of \Cref{lem:mechanism-nonmono-with-prediction}. We discriminate between three cases, as we did in all the proofs of performance gurantees.
\medskip

\noindent\textbf{Case 1:} \underline{Agent $i^*$ has significant value, i.e.:} $v(i^*) > \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta)\cdot v(S^*)$.\\
For this case,  with probability $q$ we run Dynkin's algorithm, which gives a  factor of $1/e$ over single-agent solutions. Therefore, independently of what our mechanism does with the remaining probability, the expected value for $v(S)$ will be at least:
\[E[v(S)] \geq \frac{q}{e}\cdot \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta)\cdot v(S^*).\]

\noindent For the case that $v(i^*) \leq \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta)\cdot v(S^*)$, we can use Bernstein's inequality (\Cref{thm:bernstein}), as we did in \Cref{lem:Hoeffding} and get that with probability at least $1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{\beta}{z\cdot e}\cdot(\frac{1}{2}-\delta))\cdot(\frac{1}{4}+ \frac{\delta}{3})}\right)}$, it holds that $(\frac{1}{2}-\delta)\cdot v(S^*)\leq v(S_1^*)$, $(\frac{1}{2}-\delta)\cdot v(S^*)\leq v(S_2^*) $, where $\delta$ is a positive constant, that we will set to a certain value later.
\medskip

\noindent\textbf{Case 2:} \underline{Each agent $i\in S_2^*\setminus (S_1\cup S_2)$ rejects the posted price and $v(i^*) \leq \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta)\cdot v(S^*)$.}\\ 
 By using the same analysis as in the proof of \Cref{lem:mechanism-nonmono-with-prediction} case we obtain the same inequality:
    \begin{align*}
        v(S_2^*)\leq 2\cdot v(S_1)+2\cdot v(S_2)+2\sum\limits_{i\in S_2^*\setminus(S_1\cup S_2)} v(i|S_{j(i)}^{t_i})
    \end{align*}
    Since each agent in $S_2^*\setminus(S_1\cup S_2)$ rejects the posted price offered by the mechanism:
    \begin{gather*}
        v(S_2^*)\leq 2\cdot v(S_1) +2\cdot v(S_2)+ 2\sum\limits_{i\in S_2^*\setminus(S_1\cup S_2)} \frac{c_i\cdot \beta \cdot v(T_1)}{B}\implies\\ 2\cdot v(S_1)+2\cdot v(S_2)\geq v(S_2^*)-2\beta\cdot V(S^*),
    \end{gather*}
    where the last inequality due to the fact that $c(S_2^*)\leq B$ and $ v(T_1)\leq v(S^*)$. Therefore by dividing by 4, we get that $\EX[v(S)]\geq \frac{v(S_2^*)}{4}-\frac{\beta\cdot v(S^*)}{2}$, (since $\EX[v(S)]=\frac{v(S_1)}{2}+\frac{v(S_2)}{2}$).

    Combining the above inequality with the fact that $v(S_2^*)\geq(\frac{1}{2}-\delta)\cdot v(S^*) $: 
    \[\EX[v(S)]\geq \left( \frac{1}{8}-\frac{\delta}{4}-\frac{\beta}{2}\right) v(S^*),\] with probability at least $1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{\beta}{z\cdot e}\cdot(\frac{1}{2}-\delta))\cdot(\frac{1}{4}+ \frac{\delta}{3})}\right)}$. 
    \medskip

    \noindent\textbf{Case 3:} \underline{There is an agent $i\in S_2^*\setminus (S_1\cup S_2)$ such that $c_i\leq p_i$ but $p_i>B_{j(i)}$}\\ \underline{and $v(i^*) \leq \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta)\cdot v(S^*)$.}\\
    Let $i\in S_2^*\setminus (S_1\cup S_2)$ be the first that has this property.
    We start by showing that $B'_{j(i)}\leq\frac{B}{z}$, we have that:
    \begin{align*}
        B'_{j(i)}<p_i=\frac{B}{t}(v(S_{j(i)}^{t_i}\cup \{i\})-v(S_{j(i)}^{t_i}))\leq \frac{B\cdot v(i)}{t}\leq \frac{B\cdot v(i^*)}{\beta \cdot v(T_1)} \leq \frac{B}{z}, 
    \end{align*}
 the last inequality holds due to submodularity and the fact that $v(i)\leq v(i^*)\leq \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta)\cdot v(S^*)$, which is lower or equal to $\frac{\beta \cdot v(T_1)}{z}$, when $v(S_1^*)\geq (\frac{1}{2}-\delta)\cdot v(S^*)$ and hence lower or equal to $B'_{j(i)}\leq\frac{B}{z}$.

\noindent So it holds that $B_{j(i)}'\leq \frac{B}{z}$ i.e. $\sum\limits_{k\in S_{j(i)}}p_k\geq B-\frac{B}{z}=\frac{(z-1)\cdot B}{z}$. Hence,
    \begin{align*}
        &\frac{z-1}{z}B\leq \sum\limits_{k\in S_{j(i)}}p_k=\frac{\sum\limits_{k\in S_{j(i)}} v(k|S_{j(i)}^{t_k}) \cdot B}{\beta \cdot v(T_1)}\\ & \Rightarrow v(S_{j(i)})\geq \frac{z-1}{z}\frac{\beta}{e} v(S_1^*)\\ &\Rightarrow \max\{v(S_1),v(S_2)\} \geq  \frac{z-1}{z}\cdot\frac{\beta}{e} v(S_1^*)
    \end{align*}
    Again, combining the last inequality with the fact that $v(S_1^*)\geq (\frac{1}{2}-\delta)\cdot v(S^*)$, with probability at least $1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{\beta}{z\cdot e}\cdot(\frac{1}{2}-\delta))\cdot(\frac{1}{4}+ \frac{\delta}{3})}\right)}$, we get that $\max\{v(S_1),v(S_2)\}\geq \frac{z-1}{z}\cdot\frac{\beta}{e}\cdot(\frac{1}{2}-\delta)\cdot v(S^*)$. So $\EX[X]\geq \frac{z-1}{2\cdot z}\cdot\frac{\beta}{e}\cdot(\frac{1}{2}-\delta)\cdot v(S^*)$
    \\
Piecing everything together,

\begin{itemize}[leftmargin=*]
    \item For the case that $v(i^*) \leq \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta)\cdot v(S^*)$, with probability $1-q$ we run the mechanism below line 4, which gives the factor \[(1-q) \cdot \tilde{p} \cdot  \min{\left( \frac{1}{8}-\frac{\delta}{4}-\frac{\beta}{2}, \frac{z-1}{2\cdot z}\cdot\frac{\beta}{e}\cdot(\frac{1}{2}-\delta) \right)},\] where $\tilde{p}=1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{\beta}{z\cdot e}\cdot(\frac{1}{2}-\delta))\cdot(\frac{1}{4}+ \frac{\delta}{3})}\right)}$. 
     \item For the case that $v(i^*) >\frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta)\cdot v(S^*)$ , with probability $q$ we run Dynkin's algorithm , which gives the factor
    \begin{equation}
        \frac{q}{e}\cdot \frac{\beta}{z}\cdot \frac{1}{e}\cdot (\frac{1}{2}-\delta).\tag*{\qedhere}
    \end{equation}
\end{itemize} 

\end{proof}

\thmapproxnonmonosmtwo*
\begin{proof}


For this proof, we will consider the same three cases as we have done so far, for all the mechanisms.
\medskip

\noindent\textbf{Case 1:} \underline{Agent $i^*$ has significant value, i.e.:} $v(i^*) >\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*)$.\\
For this case, we will utilize the fact that with probability $q$ we run Dynkin's algorithm, which gives a  factor of $1/e$ over single-agent solutions. Therefore, independently of what our mechanism does with the remaining probability, the expected value for $v(S)$ will be at least:
\[E[v(S)] \geq \frac{q}{e\cdot z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*).\] 

\noindent Using a similar approach as in \Cref{lem:Hoeffding}, for the case that $v(i^*) \leq \frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+  \frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*)$, by applying Bernstein's inequality (\Cref{thm:bernstein}), we get that $(\frac{1}{k}-\delta)\cdot v(S^*)\leq v(S_1^*)$, $(\frac{k-1}{k}-\delta)\cdot v(S^*)\leq v(S_2^*) $, with probability greater or equal to $1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{k-1}{k^2}+\frac{\delta}{3})\cdot\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+\frac{\beta}{e}\cdot (\frac{1}{k}-\delta))}\right)}$.
\medskip


\noindent\textbf{Case 2:} \underline{Each agent $i\in S_2^*\setminus (S_1\cup S_2)$ rejects the posted price and}\\ \underline{$v(i^*) \leq\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*)$.}\\ 
In the same way as we did in the proof of \Cref{lem:mechanism-nonmono-with-prediction}, we obtain the two following inequalities: 
\begin{align*}
    v(S_2\cup S^*)\leq v(S_2)+v(S_1)+\sum\limits_{i\in S_2^*\setminus(S_1\cup S_2)} v(i|S_2^{t_i}), \\ v(S_1\cup S^*)\leq v(S_2)+v(S_1)+\sum\limits_{i\in S_2^*\setminus(S_1\cup S_2)} v(i|S_1^{t_i}).
\end{align*}
Adding them up and dividing by 4, we get:
\begin{align*}
\frac{v(S_1)}{2}+\frac{v(S_2)}{2}\geq \frac{v(S_2^*)}{4}-\frac{1}{2} \sum\limits_{i\in S_2^*\setminus(S_1\cup S_2)} v(i|S_{j(i)}^{t_i}),
\end{align*} 
which combined with the fact that each agent $i\in S_2^*\setminus(S_1\cup S_2)$ rejected the posted price offered by the mechanism and also that $\mathbb{E}[v(S)]=\frac{v(S_1)}{2}+\frac{v(S_2)}{2}$, we get that : 
\begin{align*}
\EX[v(S)]\geq  \frac{v(S_2^*)}{4}-\frac{ a\cdot(1-\varepsilon)\cdot v(S^*)+\beta\cdot v(T_1)}{2}\geq \frac{v(S_2^*)}{4}-\frac{(a\cdot(1-\varepsilon)+\beta)\cdot v(S^*)}{2}.
\end{align*}
Combining with the fact that $(\frac{k-1}{k}-\delta)\cdot v(S^*)\leq v(S_2^*) $, with probability greater or equal to $1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{k-1}{k^2}+\frac{\delta}{3})\cdot\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot (\frac{1}{k}-\delta))}\right)}$, we obtain that for this case:
\[\EX[v(S)]\geq \left (\frac{1}{4}\cdot (\frac{k-1}{k}-\delta) -\frac{1}{2}\cdot ( a\cdot (1-\varepsilon)+ \beta)\right) \cdot v(S^*)\]
with probability at least $1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{k-1}{k^2}+\frac{\delta}{3})\cdot\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot (\frac{1}{k}-\delta))}\right)}$. \medskip

\noindent\textbf{Case 3:} \underline{There is an agent $i\in S_2^*\setminus (S_1\cup S_2)$ such that $c_i\leq p_i$ but $p_i>B_{j(i)}$ and also}\\ \underline{$v(i^*) \leq\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*)$.}\\[.5cm]
Let $i\in S_2^*\setminus (S_1\cup S_2)$ be the first that has this property.
    First, we will show that $B'_{j(i)}\leq\frac{B}{z}$, we have that:
    \begin{align*}
        B'_{j(i)}<p_i=\frac{B}{t}(v(S_{j(i)}^{t_i}\cup \{i\})-v(S_{j(i)}^{t_i}))\leq \frac{B\cdot v(i)}{t}\leq \frac{B\cdot v(i^*)}{a\cdot \omega+\beta \cdot v(T_1)} \leq \frac{B}{z}, 
    \end{align*}
 the last inequality holds due to submodularity and the fact that $v(i)\leq v(i^*)\leq \frac{1}{z}\cdot (a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot (\frac{1}{k}-\delta))\cdot v(S^*)$, which is lower or equal to $\frac{a\cdot \omega+\beta \cdot v(T_1)}{z}$, when $v(S_1^*)\geq (\frac{1}{k}-\delta)\cdot v(S^*)$ and hence lower or equal to $B'_{j(i)}\leq\frac{B}{z}$.

\noindent Since $B'\leq \frac{B}{z}$, it means that  $\sum\limits_{k\in S_{j(i)}}p_k\geq B-\frac{B}{z}=\frac{(z-1)\cdot B}{z}$. So,
    \begin{align*}
        &\frac{z-1}{z}B\leq \sum\limits_{k\in S_{j(i)}}p_k=\frac{\sum\limits_{k\in S_{j(i)}} v(k|S_{j(i)}^{t_k}) \cdot B}{a\cdot \omega +\beta \cdot v(T_1)}\\ & \Rightarrow v(S_{j(i)})\geq \frac{z-1}{z}(a\cdot \omega+\frac{\beta}{e} \cdot v(S_1^*))\\ &\Rightarrow \max\{v(S_1),v(S_2)\} \geq  \frac{z-1}{z}\cdot(a\cdot \omega+\frac{\beta}{e}\cdot  v(S_1^*)).
    \end{align*}
    Again, combining the last inequality with the fact that $v(S_1^*)\geq (\frac{1}{k}-\delta)\cdot v(S^*)$, we get that $\max\{v(S_1),v(S_2)\} \allowbreak \geq \frac{z-1}{z}\cdot(a\cdot (1-\varepsilon)+\frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*)$. So $\EX[X]\geq \frac{z-1}{2\cdot z}\cdot(a\cdot (1-\varepsilon)+\frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*)$, with probability at least $1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{k-1}{k^2}+\frac{\delta}{3})\cdot\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot (\frac{1}{k}-\delta))}\right)}$.
    \\
Piecing everything together,

\begin{itemize}[leftmargin=*]
    \item For the case that $v(i^*) \leq \frac{1}{z}\cdot (a\cdot (1-\varepsilon)+ \ \frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*)$, with probability $1-q$ we run the mechanism below line 4, which gives the factor \[(1-q) \cdot \tilde{p}\cdot  \min{\left(\frac{1}{4}\cdot (\frac{k-1}{k}-\delta) -( a\cdot (1-\varepsilon)+ \beta), \frac{z-1}{2\cdot z}\cdot(a\cdot (1-\varepsilon)+\frac{\beta}{e}\cdot(\frac{1}{k}-\delta)) \right)},\] where $\tilde{p}=1-2\cdot \exp{\left(-\frac{\delta^2/ 2 }{(\frac{k-1}{k^2}+\frac{\delta}{3})\cdot\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+\frac{\beta}{e}\cdot (\frac{1}{k}-\delta))}\right)}$. 

    \item For the case that $v(i^*) \ge\frac{1}{z}\cdot ( a\cdot (1-\varepsilon)+ \frac{\beta}{e}\cdot(\frac{1}{k}-\delta))\cdot v(S^*)$ , with probability $q$ we run Dynkin's algorithm , which gives the factor
    \begin{equation}
        \frac{q}{e\cdot z}\cdot ( a\cdot (1-\varepsilon)+  \frac{\beta}{e}\cdot(\frac{1}{k}-\delta)). \tag*{\qedhere}
    \end{equation}
\end{itemize} 

\end{proof}


