\lemmayao*
\begin{proof}
  We use $\supp(D)$ to denote the support of a discrete probability distribution $D$; we extend this notation to randomized mechanisms, since each such mechanism defines a discrete probability distribution over deterministic mechanisms.
  Also, let $\Bar{\vec{c}}$ be a random variable on cost profiles. For every mechanism $(A^r, p^r) \in \mathcal{M}$ and every probability distribution $P$ over canonical instances with $\supp(P) \subseteq C$, the following holds:
\begin{align*}
    \min_{\vec{c} \in C}\EX\left[\frac{v\left(A^r(\vec{c}) \right)}{v\left(S^*(\vec{c}) \right)} \right] 
    &\leq \min_{\vec{c} \in \supp(P)}\EX\left[\frac{v\left(A^r(\vec{c}) \right)}{v\left(S^*(\vec{c}) \right)} \right] \\
    &= \min_{\vec{c} \in \supp(P)} \sum_{(A, p) \in \supp((A^r, p^r))}\Pr[A^r=A] \cdot \frac{v\left(A(\vec{c}) \right)}{v\left(S^*(\vec{c}) \right)} \\
    &\leq \sum_{\vec{c} \in \supp(P)}\Pr[\Bar{\vec{c}}= \vec{c}] \cdot \sum_{(A, p) \in \supp((A^r, p^r))}\Pr[A^r=A] \cdot \frac{v\left(A(\vec{c}) \right)}{v\left(S^*(\vec{c}) \right)} \\
    &= \sum_{(A, p) \in \supp((A^r, p^r))}\Pr[A^r=A] \cdot \sum_{\vec{c} \in \supp(P)}\Pr[\Bar{\vec{c}}= \vec{c}] \cdot \frac{v\left(A(\vec{c}) \right)}{v\left(S^*(\vec{c}) \right)} \\
    &= \sum_{(A, p) \in \supp((A^r, p^r))}\Pr[A^r=A] \cdot \EX_{\Bar{\vec{c}} \sim P}\left[\frac{v\left(A(\Bar{\vec{c}}) \right)}{v\left(S^*(\Bar{\vec{c}}) \right)}\right] \\
    &\leq \max_{(A, p) \in \supp((A^r, p^r))}\EX_{\Bar{\vec{c}} \sim P}\left[\frac{v\left(A(\Bar{\vec{c}}) \right)}{v\left(S^*(\Bar{\vec{c}}) \right)}\right] \\
    &\leq \max_{(A, p) \in \mathcal{M}^d}\EX_{\Bar{\vec{c}} \sim P}\left[\frac{v\left(A(\Bar{\vec{c}}) \right)}{v\left(S^*(\Bar{\vec{c}}) \right)}\right].
\end{align*}
The second and third inequalities follow from the standard fact that, for a set of $k$ numbers $\{x_1, \dots, x_k\}$ and non-negative weights $w_1, \dots, w_k$ with $\sum_{i=1}^k w_i = 1$, it holds that $
\min_{i \in [k]} x_i \leq \sum_{i=1}^k w_i x_i \leq \max_{i \in [k]} x_i$.
Finally, the last inequality follows from the fact that, for any mechanism $(A^r, p^r) \in \mathcal{M}$, it holds that $\supp(A^r, p^r) \subseteq \mathcal{M}^d$. 
\end{proof}

