\section{Preliminaries}
\label{sec:prelim}
We provide a brief introduction to STL and related terminologies. See \cite{LeungArechigaEtAl2021,MalerNickovic2004} for a more in-depth description.
%

\subsection{Signals and trajectories}
\label{subsec:signals}
%

\noindent \textbf{Signals and subsignals.} STL formulas are interpreted over one-dimensional \emph{signals} $\signal=(s_0,\ldots,s_T)$, a sequence of scalars sampled at uniform timesteps $\Delta t$ (i.e., continuous-time outputs sampled at finite time intervals) from any system of interest.
%
Given a signal $\signal=(s_0,\ldots,s_T)$, a \emph{subsignal} is a contiguous fragment of a signal. By default, we assume a subsignal will start at timestep $t$ and end at the last timestep $T$. We denote such a subsignal by $\signal_t =(s_t,\ldots,s_T)$.
If a subsignal ends at a different timestep from $T$, we denote it by $\signal_t^K=(s_t,\ldots,s_K)$.
%
\noindent\emph{Note}: The absence of a sub(super)script on $\signal$ implies that the signal starts (ends) at timestep 0 ($T$).

\noindent \textbf{States, trajectories, and subtrajectories.}
Given a system of interest, let $x_t\in\mathbb{R}^n$ denote the state at timestep $t$. Let $\trajectory=(x_0, \ldots, x_T)$ denote a sequence of states sampled at uniform time steps $\Delta t$.
Similar to how subsignals are defined, we denote a subtrajectory by $\trajectory_t=(x_t, \ldots, x_T)$

\noindent \textbf{From trajectories to signals.}
In this work, we focus specifically on signals computed from a robot's trajectory. As we will see in the next section, core to any STL formula are predicates which are functions mapping state to a scalar value, $\mu : \mathbb{R}^n \rightarrow \mathbb{R}$, with $s_t = \mu(x_t)$, $t = 0, \dots, T$.
A signal can represent, for example, a robot's forward speed.
%


\subsection{Signal Temporal Logic: Syntax and Semantics}
\label{subsec:stl syntax and semantics}

STL formulas are defined recursively according to the following grammar \cite{BartocciDeshmukhEtAl2018,MalerNickovic2004},

\vspace{-3mm}

\begin{equation}
    \centering
    \begin{tabular}{cc|c|c|c|c}
       $\phi::=$  &  $\top$ &    $\mu_c$   &    $\neg\phi$   &    $\phi \wedge \psi$   &     $\phi\,\Until_{[a,b]}\,\psi$ \\
                  & True & Predicate & Not   & And & Until
    \end{tabular}.
    \label{eq:STL grammar}
    %
\end{equation}


The grammar \eqref{eq:STL grammar} describes a set of recursive operations that, when combined, can create a more complex formula.
The time interval $[a,b]$ refers to timesteps rather than specific time values. When the time interval is dropped in the temporal operators, it defaults to the entire length of the input signal.
%
%
%
%
%
%
%
%
%
%
Other commonly used logical connectives and temporal operators can be derived as follows: \emph{Or} ($\phi \vee \psi := \neg(\neg\phi \wedge \neg\psi)$), \emph{Eventually} ($\Eventually_{[a,b]}~\phi := \top~\mathcal{U}_{[a,b]}~\phi$) and \emph{Always} ($\Always_{[a,b]}~\phi := \neg F_{[a,b]}~\neg\phi$).



\begin{mybox}{\textbf{Boolean Semantics}}{\small
\begin{equation}
\begin{aligned}
    \trajectory & \models \mu_c &\Leftrightarrow  \quad& \; \mu(x_0) > c\\
    \trajectory & \models \neg \phi  &\Leftrightarrow  \quad& \; \neg(\trajectory \models \phi)\\
    \trajectory & \models \phi \wedge \psi & \Leftrightarrow  \quad& \; (\trajectory \models \phi) \wedge (\trajectory \models \psi)\\
    %
    %
    \trajectory & \models \Eventually_{[a,b]} \phi & \Leftrightarrow  \quad& \; \exists t \in [a, b] \;\;\mathrm{s.t.} \; \trajectory_t \models \phi\\
    \trajectory & \models \Always_{[a,b]} \phi & \Leftrightarrow  \quad& \; \forall t \in [a, b] \;\;\mathrm{s.t.} \;  \trajectory_t \models \phi\\
    \trajectory & \models \phi \,\Until_{[a,b]}\, \psi & \Leftrightarrow  \quad& \; \exists t \in [a, b] \;\;s.t. \; (\trajectory_t \models \psi)\; \\
    %
    &&& \quad  \wedge \;(\forall \tau \in [0, t], \, \trajectory_\tau \models  \phi)
\end{aligned}
\label{eq:boolean}
\end{equation}
}
\end{mybox}

\begin{mybox}{\textbf{Quantitative Semantics (Robustness Formulas)}}{\small
\begin{equation}
\begin{aligned}
\rho(\trajectory, \top) & \:= \: \rho_{\max} \qquad \text{where $\rho_{max} > 0$}\\
\rho(\trajectory, \mu_c) & \:= \: \mu(x_0) - c\\
\rho(\trajectory, \neg \phi) & \:= \: -\rho(\trajectory,\phi)\\
\rho(\trajectory, \phi \wedge \psi) & \:= \: \min(\rho(\trajectory,\phi), \rho(\trajectory,\psi))\\
%
%
\rho(\trajectory, \Eventually_{[a,b]} \phi) & \:= \: \max_{t \in [a, b]}\rho(\trajectory_t,\phi)\\
\rho(\trajectory, \Always_{[a,b]} \phi) & \:= \: \min_{t \in [a, b]}\rho(\trajectory_t,\phi)\\
\rho(\trajectory, \phi \,\Until_{[a,b]}\psi) & = \max_{t \in [a, b]} \bigg\{\min\left( \min_{\tau\in [0, t]} \rho(\trajectory_{\tau}, \phi), \rho(\trajectory_t, \psi) \right)\bigg\}.
\end{aligned}
\label{eq:quantitative}
\end{equation}
}
\end{mybox}


A predicate $\mu_c: \mathbb{R}^n \rightarrow \mathbb{R}$ is a function that takes, for example, a robot state and outputs a scalar (e.g., speed).
Then, given a state trajectory $\trajectory=(x_0,\ldots, x_T),\ x_t \in \mathbb{R}^n$, we use the notation \(\trajectory \models \phi\) to denote that the trajectory \(\trajectory\) satisfies \(\phi\) according to the Boolean semantics \eqref{eq:boolean}.



STL also admits a notion of \emph{robustness}---the \emph{quantitative semantics} in \eqref{eq:quantitative} describes how much a signal satisfies or violates a formula. Positive robustness values indicate satisfaction, while negative robustness values indicate violation.




