\section{Sensitivity of $J$ respect to $\omega$ and $\alpha$}
\label{sec:sensitivity_analysis} 
In this section, we present the derivative of $\JKV(\omega, \alpha)$ with respect to $\omega$, followed by its derivative with respect to $\alpha$. 
For notational convenience, when one argument is fixed, we omit the functional's dependence on that argument.
%--------------------------  SHAPE DERIVATIVES --------------------------
%--------------------------  SHAPE DERIVATIVES --------------------------
%--------------------------  SHAPE DERIVATIVES --------------------------
\subsection{Shape derivative of $J$ with respect to $\omega$}
\label{sec:shape_derivative}
Let us consider Problem~\ref{prob:min_problem} and suppose that $\alpha \in \Aad$ is fixed.
For ${\varphi},{\psi}\in H^{1}(\Omega)$, we define 
\[
	a(\alpha;{\varphi},{\psi}) = \intO{\nabla \varphi \cdot \nabla \psi} + \intG{ \alpha \varphi \psi}.
\]
%
%
The variational formulations of \eqref{eq:state_un} are \eqref{eq:state_ud} are as follows:
\begin{align}
	&\text{Find ${\ud} \in H^{1}(\Omega)$, $\ud|_{\Sigma} = f$, such that $a(\alpha;\ud,\psi) = 0$, $\forall\psi \in {V}(\Omega)$};\label{eq:weak_ud}\\
	&\text{Find ${\un} \in H^{1}(\Omega)$ such that  $a(\alpha;\un,\psi) = \inS{g, \psi}_{\Sigma}$, $\forall\psi \in H^{1}(\Omega)$\label{eq:weak_un}},
\end{align}
The weak forms \eqref{eq:weak_ud} and \eqref{eq:weak_un} are known to be well-posed if $(f,g) \in H^{1/2}(\Sigma) \times H^{-1/2}(\Sigma)$ and $\Omega$ is Lipschitz regular, as established by the Lax-Milgram lemma (see, e.g., \cite[p. 46]{AfraitesRabago2025}).
Meanwhile, the existence of a minimizer for $\JKV$ can be shown under an appropriate topology, provided that the admissible domain satisfies the a \textit{uniform cone property} \cite[Thm. 2.4.7, p. 56]{HenrotPierre2018}. 
While we do not prove this claim here, the arguments used in \cite{RabagoAzegami2019b,AfraitesRabago2024} can be followed to verify it.

To numerically solve Problem~\ref{prob:min_problem}, we will use a shape-gradient-based technique combined with the finite element method (FEM). 
To implement this, we require the expression for the shape derivative of $\JKV$, which has already been derived in \cite[Prop. 3.4]{AfraitesRabago2025}. 
Therefore, we direct the reader to \cite{AfraitesRabago2025} for the detailed characterization of the shape gradient.
%
\begin{proposition}[Shape gradient of $J$]
	\label{prop:shape_gradient}
	Let $D_{\delta}$ be an open set with a ${C}^{\infty}$ boundary, such that $\{ x \in D \mid \text{$d(x,\partial D) > \delta/2$}\} \subset D_{{\delta}} \subset \{ x\in D \mid \text{$d(x,\partial D) > \delta/3$}\}$. 
	Define $\sfTheta$ as the collection of ${C}^{2,1}(\mathbb{R}^{d})^{d}$ vector fields with compact support in $\overline{D}_{\delta}$. 
	Assume that $\Omega \in {C}^{2,1}$ is an admissible domain, i.e., $\Omega = D\setminus\overline{\omega}$ where $\omega \in \Uad$ and ${\VV} \in \sfTheta$.
	Then, the map $t \mapsto \JKV(\omega_{t})$, is ${C}^1$ in a neighborhood of $0$, and its shape derivative at $0$ is given by
	\[
	d\JKV(\omega)[\VV] = \intG{\left[- F(\un,w) + |\nabla w|^{2} + \frac{\alpha}{2} \left( 2 w \dn{w} + \kappa w^{2} \right) \right] \Vn}
		=: \inS{\kernel,\Vn}_{\Gamma},
	\]
	%
	%
	%
	where $w = \ud - \un$, and $F(v,q) = -\nabla_{\Gamma} v \cdot \nabla_{\Gamma} q - \alpha \left( \dn{v} + \kappa v \right)q -\dn \alpha v q$, for $v, q \in H^{2}(\Omega)$.
	Here, $\nabla_{\Gamma}$ denotes the tangential gradient operator while $\kappa$ represents the mean curvature of the free boundary $\Gamma = \partial{\omega}$.
\end{proposition}
%
%
An important feature of the Kohn-Vogelius functional $\JKV$ is that its gradient does not depend on the derivatives of the states. 
This is a characteristic commonly found in energy-type cost functionals, allowing the gradient to be computed numerically without the need for adjoint variables. 
We highlight that this approach differs from the one presented in \cite{Fang2022}, which requires the use of adjoint variables.
%
From a numerical standpoint, our method only needs for a regularization functional for $\alpha$, in contrast to \cite{Fang2022}, as the proposed objective functional inherently includes a smoothing effect. 
This enhances stability and provides a more accurate approximation of the minimizer, offering a solution to the inverse problem of simultaneously recovering $\alpha$ and $\Gamma$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Derivative of $J$ with respect to $\alpha$}
\label{functional_KV_respect_alpha}
Let $\Omega$ be a given admissible domain.
For simplicity, we denote the derivative of $\ui$ with respect to $\alpha$ by $\dui = \dalp{\ui}$.
Hereinafter, without further notice, we assume $i \in \{D, N\}$, indicating the solutions to equations \eqref{eq:state_ud} and \eqref{eq:state_un}.
%
Given $\alpha, \rho \in \Aad$, there exists a real number $\varepsilon=\varepsilon(\alpha,\rho) > 0$ such that $\alpe=\alpha+\varepsilon \rho \in \Aad$.
Consequently, $\alpe$ is a perturbation of $\alpha$ in the direction $\rho$.
%
%
\begin{proposition}[{\cite{ChaabaneJaoua1999}}] \label{eq:Frechet_derivative}
	Let $\Omega$ be a given admissible domain and $\alpha, \rho \in \Aad$.
	There exist $\dui, {O}(\varepsilon^{2}) \in H^{1}(\Omega)$  such that
\begin{equation}\label{eq:u_perturbed}
    \uie=\ui+\varepsilon {\dui}+{O}(\varepsilon^{2})
    \quad\text{and}\quad 
    \lim_{\varepsilon \searrow 0}{O}(\varepsilon^{2})=0,
\end{equation} 
where $\dui$ solves the variational equation
%
%
\begin{equation}\label{eq:perturbed_variational}
	a(\dui, \psi) = -\intG{\rho {u_i} \psi},
\end{equation}
for all $\psi \in H^{1}(\Omega)$ when $i=N$ and for all $\psi \in V(\Omega)$ when $i=D$.
%
Additionally, $J$ is Gateaux differentiable at $\alpha$ in the $\rho$ direction, and its derivative is given by
\[
	d\JKV(\alpha)\rho =\frac{1}{2}\intG{ \rho (\ud^{2}-\un^{2})}.
\]
\end{proposition}
%
%
\begin{proof}
Let $\Omega$ be a given admissible domain and $\alpha, \rho \in \Aad$.
The differentiability of the states and the cost functional with respect to $\alpha$ can be shown by standard arguments, so we omit it.
Let us first establish the structure of the derivatives of the states with respect to $\alpha$.
To do this, we let $\varepsilon=\varepsilon(\alpha,\rho) > 0$ be such that $\alpe=\alpha+\varepsilon \rho \in \Aad$ and consider the following perturbed state problems:
% 
\begin{align}
    a(\alpe;\une, \psi) &= \intS{g\psi}, \quad \forall \psi \in H^{1}(\Omega),\label{eq:perturb_state_un}\\
    a(\alpe;\ude, \psi) &= 0, \quad \forall \psi \in {V}(\Omega).\label{eq:perturb_state_ud}
\end{align} 
%
Note that $g$ represents an observation on the boundary $\Sigma$. 
Since the perturbation of $\alpha$ does not affect $g$, we have $g^{\varepsilon} = g$ on $\Sigma$.

Subtracting \eqref{eq:state_un} from \eqref{eq:perturb_state_un}, we obtain 
\begin{equation}\label{eq:difference_un}
	a(\alpha;\une-\un, \psi) = -\intG{\varepsilon \rho \un \psi}, \qquad \forall \psi \in H^{1}(\Omega).
\end{equation}
For any $\varepsilon > 0$, equation \eqref{eq:difference_un} has a unique weak solution $\une - \un \in H^{1}(\Omega)$.  
By substituting $\psi = \une - \un$ into the above equation, we deduce that $\norm{\une - \un}_{H^1(\Omega)} = {O}(\varepsilon)$, which suffices for computing $d\JKV(\alpha)\rho$.  
Additionally, the strong convergence of $\left\{\frac{1}{\varepsilon}(\une - \un)\right\}$ in $H^1(\Omega)$ can be established, though we omit the proof here.  

To proceed, we divide equation \eqref{eq:difference_un} by $\varepsilon$ and take the limit as $\varepsilon \to 0$. Utilizing \eqref{eq:u_perturbed}, we deduce that $\dun \in H^{1}(\Omega)$ satisfies the weak formulation
\[
	a(\alpha; \dun, \psi) = -\intG{\rho \un \psi}, \quad \forall \psi \in H^1(\Omega).
\]  
Similarly, by applying the same approach, we find that $\dud \in V(\Omega)$ satisfies 
\[
	a(\alpha; \dud, \psi) = -\intG{\rho \ud \psi}, \quad \forall \psi \in V(\Omega).
\]

Let us denote $\wdn = \ud-\un$ and $\wdne = \ude-\une$.
Now, the derivative of $\JKV(\alpha)$ with respect to $\alpha$ in the direction $\rho$ is givem by
\begin{align*}
	d\JKV(\alpha)\rho
	=\lim_{\varepsilon \searrow 0} \frac{\JKV(\alpha + \varepsilon \rho)-\JKV(\alpha)}{\varepsilon}
	=\lim_{\varepsilon \searrow 0}\frac{1}{2\varepsilon} \left[ a(\alpe; \wdne, \wdne) - a(\alpha;\wdn,\wdn) \right].
\end{align*}
%
Observe that the expression on the right contains the difference ${(\uie-\ui)}/{\varepsilon} = {\dui}+{O}(\varepsilon)$.
Hence, evaluating the limit leads to the expression
%
\begin{align*}
	d\JKV(\alpha)\rho 
	&=  a(\alpha; \dwdn, \wdn) + \frac12\intG{ \rho |\wdn|^{2} }\\
	&=  a(\alpha; \dud, \ud) - a(\alpha; \dud, \un)  - a(\alpha; \dun, \wdn) + \frac12\intG{ \rho |\wdn|^{2} }.
\end{align*}
%
We eliminate $\dwdn \in H^{1}(\Omega)$ appearing on the above expression.
To do this, first, we consider \eqref{eq:perturbed_variational} for $i=N$ and choose $\psi = \wdn = \ud - \un \in H^{1}(\Omega)$ to obtain
\[
	-a(\alpha; \dun, \wdn) = \intG{ \rho \un (\ud - \un) }.
\]
%%We again consider \eqref{eq:perturbed_variational}, but now with $i=D$ and take $\psi = \ud \in V(\Omega)$ to get
%%\[
%%	a(\alpha; \dud, \ud) = - \intG{ \rho \ud^{2} }.
%%\]
Next, we consider \eqref{eq:weak_ud} and take $\psi = \dud \in V(\Omega) \subset H^{1}(\Omega)$ to get
\[
	a(\alpha; \ud, \dud) = 0.
\]
%
Finally, we consider \eqref{eq:weak_un} and choose $\psi = \dud \in V(\Omega) \subset H^{1}(\Omega)$ (i.e., $\dud|_{\Sigma} = 0$) to obtain
\[
	a(\alpha; \dud, \un) = a(\alpha; \un, \dud) =  \inS{g, \dud}_{\Sigma} = 0.
\]
%
Thus, we arrive at the following simplication (i.e., eliminating $\dwdn$)
\begin{align*}
	d\JKV(\alpha)\rho  
%%%	&=  a(\alpha; \dud, \ud) + a(\alpha; \dud, \un)  - a(\alpha; \dun, \wdn) + \frac12\intG{ \rho |\wdn|^{2} }\\
%%%	&=  \intG{ \rho \un (\ud - \un) } + \frac12\intG{ \rho \abs{\ud - \un}^{2} }\\
	&= \intG{ ( \rho \un \ud - \rho \un^{2} ) } + \frac12\intG{ \rho (\ud^{2} - 2\ud\un + \un^{2})}\\ 
	&= \frac12\intG{ \rho (\ud^{2} - \un^{2})}.
\end{align*}
That is, $d\JKV(\alpha)=\frac12{(\ud^{2} - \un^{2})}$. This proved the proposition.
\end{proof}
