\chapter{AMF Pseudocode}
\label{amf_pseudo}

\begin{algorithmic}[1]
\Procedure{Update State}{$Offset, BlockNumber, Epoch, EpochSpan, RoundSpan$}
\State $selector \gets Epoch ~~mod~~(2)$;
\If{$Epoch < \floor*{ \frac{BlockNumber - Offset}{EpochSpan} }$}
	\State $Epoch \gets \floor*{ \frac{BlockNumber - Offset}{EpochSpan} }$;
	\State $Round \gets \floor*{ \frac{(BlockNumber - Offset) ~~mod~~ (EpochSpan)}{RoundSpan} }$;
	\State $Capacity \gets Capacity + EpochCapacity$\;
	\State $Share \gets \floor*{Capacity / TotalWeight[selector]}$;
	\State return;
\EndIf
\If{$Round < \floor*{ \frac{(BlockNumber - Offset) \% ES}{RS} }$}
	\State $Round \gets \floor*{ \frac{(BlockNumber - Offset) ~~mod~~ (EpochSpan)}{RoundSpan} }$;
	\State $Share \gets Capacity / TotalWeight[selector]$;
	\State return;
\EndIf
\State return;
\EndProcedure
\Procedure{Demand}{$User, Volume$}
\State \Call{updateState}{$Offset, BlockNumber, Epoch, EpochSpan, RoundSpan$}
\State $selector \gets (E + 1)~~mod~~(2)$;
\If{$User.demandEpoch[selector] \neq Epoch$}
	\State $User.demand[selector] \gets Volume$;
	\State $User.demandEpoch[selector] \gets Epoch$;
	\If{$ResetEpoch < Epoch$}
		\State $TotalWeight[selector] \gets User.weight$;
		\State $ResetEpoch \gets Epoch$;
	\Else
		\State $TotalWeight[selector] \gets TotalWeight[selector] + User.weight $;
	\EndIf
\EndIf
\State return;
\EndProcedure
\Procedure{Claim}{$User$}
\State \Call{updateState}{$Offset, BlockNumber, Epoch, EpochSpan, RoundSpan$}
\State $selector \gets Epoch ~~mod~~(2)$;
\If{$User.demandEpoch[selector] \neq Epoch - 1$ \textbf{or} $Capacity = 0$
					\item[] \hfill \textbf{or} $User.demand[selector] = 0$}
	\State return;
\EndIf
\If{$User.claimEpoch = Epoch$}
	\If{$User.claimRound = Round$}
		\State return;
	\EndIf
\Else
	\State $User.claimEpoch \gets Epoch$;
\EndIf
\State $User.claimRound \gets Round$;
\State $User.balance \gets User.balance + \min{(User.demand[selector], Share * User.weight)}$;
\State $User.demand[selector] \gets User.demand[selector] - \min{(User.demand[selector], Share * User.weight)}$;
\State $Capacity \gets Capacity - \min{(User.demand[selector], Share * User.weight)}$;
\If{$User.demand[selector] = 0$}
	\State $TotalWeight[selector] \gets TotalWeight[selector] - User.weight$;
\EndIf
