\chapter{WQMF Pseudocode}
\label{wqmf_pseudo}

\begin{algorithmic}[1]
\Procedure{Demand}{User, Volume}\Comment{Make a Demand}
\State \Call{Update\_State()}{};
\State $selector \gets (epoch + 1) \pmod{2}$;
\If{$User.demandEpoch[selector] = Epoch$}
    \State return;
\EndIf
\State $User.demandEpoch[selector] \gets Epoch$;
\State $index \gets \ceil*{\frac{Volume}{User.weight}}$;
\If{$ResetEpoch[selector][index] \neq Epoch$}
    \State $ResetEpoch[selector][index] \gets Epoch$;
    \State $Demands[selector][index] \gets Volume$;
    \State $Weights[selector][index] \gets User.Weight$;
\Else
    \State $Demands[selector][index] \gets Demands[selector][index] + Volume$; 
    \State $Weights[selector][index] \gets Weights[selector][index] + User.weight$;
\EndIf
\State $User.demand[selector] \gets Volume$;
\State $TotalDemands \gets TotalDemands + Volume$;
\State $TotalWeights \gets TotalWeights + User.weight$;
\EndProcedure
\Procedure{Claim}{User}\Comment{Claim User Share}
\State \Call{Update\_State()}{};
\State $selector \gets Epoch \pmod{2}$;
\If{$User.demandEpoch[selector] = Epoch$}
    \State return;
\EndIf
\If{$User.claimEpoch = Epoch$}
    \State return;
\EndIf
\State $User.claimEpoch \gets Epoch$;
\State $share \gets User.weight * UnitShare$;
\State $User.balance \gets min(share, User.demand[selector])$;
\State $Capacity \gets Capacity - min(share, User.demand[selector])$;
\EndProcedure
\Procedure{Calculate\_Unit\_Share()}{}
\State $selector \gets Epoch \pmod{2}$;
\State $cumulativeDemands \gets 0$;
\State $cumulativeWeights \gets 0$;
\For{$i \gets 1, Quanta$}
    \If{$ResetEpoch[selector][i] = Epoch - 1$}
        \State $cumulativeDemands \gets cumulativeDemands + Demands[selector][i]$;
        \State $cumulativeWeights \gets cumulativeWeights + Weights[selector][i]$;
    \EndIf
    \If{$Capacity < cumulativeDemands + i * (totalWeights - cumulativeWeights) $}
        \State \Return $i - 1$;
    \EndIf
\EndFor
\State \Return $Quanta$;
\EndProcedure
\end{algorithmic}

