    \State return;
\EndIf
\If{$User.claimEpoch = Epoch$}
    \State return;
\EndIf
\State $User.claimEpoch \gets Epoch$;
\If{$User.demandEpoch[1 - selector] = Epoch$}
    \State $Share \gets UnitShare * \floor*{\frac{Precision}{User.totalDemand - User.demand[selector]}}$;
\Else
    \State $share \gets UnitShare * \floor*{\frac{Precision}{User.totalDemand}}$;
\EndIf
\State $User.balance \gets min(share, User.demand[selector])$;
\State $Capacity \gets Capacity - min(share, User.demand[selector])$;
\EndProcedure
\item[]
\Procedure{Calculate\_Unit\_Share()}{}
\State $selector \gets Epoch \pmod{2}$;
\State $heap[0] \gets \emptyset$;\Comment{Initiate Empty Heaps}
\State $heap[1] \gets \emptyset$;
\State $simulatedCapacity = Capacity * Precision$;
\State $simulatedShare \gets 0$;
\State $simulatedUnitShare \gets 0$;
\State $totalWeight \gets 0$;
\State $result \gets 0$;
\For{$i \gets 1, NumberOfUsers$}
    \If{$User[i].demandEpoch[selector] = Epoch - 1$}
    \State $userWeight \gets \floor*{\frac{Precision}{User.totalDemand}}$
    \State $node \gets \{User.demand[selector], userWeight\}$
    \State $\Call{insert}{heap[0], node}$;
    \State $totalWeight \gets totalWeight + userWeight$;
    \EndIf
\EndFor
\While{$heap[selector].length > 0 \And simulatedCapacity \geq totalWeight$}
    \State $simulatedUnitShare \gets \floor*{\frac{simulatedCapacity}{totalWeight}}$;
    \State $result \gets result + simulatedShare$;
    \While{$heap[selector].length > 0 $}
        \State $simulatedShare \gets heap[selector][0].weight * simulatedUnitShare$;
    \If{$simulatedShare = 0$}
        \State $totalWeight \gets totalWeight - heap[selector][0].weight$;
        \State $\Call{deleteMin}{heap[selector]}$
        \ElsIf{$heap[selector][0].volume \leq simulatedShare$}
            \State $simulatedCapacity \gets simulatedCapacity - heap[selector][0].volume$;
            \State $\Call{deleteMin}{heap[selector]}$;
        \Else 
        \State $node \gets \{heap[selector][0].volume - simulatedShare,$ \hfill
            \item[] \hfill $heap[selector][0].weight\}$;
            \State $\Call{deleteMin}{heap[selector]}$;
            \State $\Call{insert}{heap[1 - selector], node}$;
    \EndIf
    \State $selector \gets 1 - selector$;
    \EndWhile
