    \begin{tabular}{@{}lccccccc@{}}
    \toprule
      & $v_1$ & $v_2$ & $v_3$ & $v_4$ & $v_5$ & $v_6$ & $v_7$ \\ \midrule
    $c_1$ & $\times$ & $\times$ &  &        &        &        \\
    $c_2$ &  &  & $\times$ & $\times$       &        &        \\
