\subsection{Coding effort}

\begin{algorithm}[htb!]
\caption{A code sample for multi-instantiating SUP-based kernels with packing instructions conditionally (depending on the values of macro arguments \texttt{pa} and \texttt{pb}) fused in to handle all the four cases required by the FIP approach.}
\label{alg:multi_instantiate}
\begin{lstlisting}[language=C]
