#define cond_inst_true(_1) _1

#define kernel_def(pa, pb) \
\
void fused_kernel_## pa ##_## pb ( /* func params */ ) \
{ \
  __asm__ volatile \
  ( \
    /* ... */ \
\
    /* Multiply and accumulate: ymm0 holds A, ymm2 holds B and ymm4 holds C fractions */ \
    "vfmadd231pd %ymm0, %ymm2, $ymm4 \n\t" \
\
    /* Optionally store ymm2 to the packing space indicated by rdx. */ \
