\subsection{Proof of Theorem~\ref{T1}}
(i) Convergence rate when $F(\boldsymbol{x})$ is strongly convex.

By defining $\vartheta_{w(i)}^{t}\triangleq\sum_{j\in\mathcal{N}_{i}}w_{ij}\vartheta_{j(i)}^{t}$ and using the projection inequality, we have 
\begin{equation}
\textstyle\|\bar{x}_{(i)}^{t+1}- x_{i}^{*}\|^2\leq\|\bar{x}_{(i)}^{t}+\bar{\vartheta}_{w(i)}^{t}-\frac{\lambda_{x}^{t}}{m}u_{i}^{t}-x_{i}^{*}\|.\label{T11}
\end{equation}
Based on the definitions of $\boldsymbol{u}^{t}$ and $\boldsymbol{x}^{t}$, we have
\begin{flalign}
&\textstyle\mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}- \boldsymbol{x}^{*}\|^2]\leq\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*}-\frac{\lambda_{x}^{t}}{m}\boldsymbol{u}^{t}\|^2]+\mathbb{E}[\|\boldsymbol{\bar{\vartheta}}_{w}^{t}\|^2]\nonumber\\
&\textstyle\leq \mathbb{E}[\|\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*}\|^2]+\frac{(\lambda_{x}^{t})^2}{m^2}\mathbb{E}[\|\boldsymbol{u}^{t}\|^2]+n(\sigma_{x}^{t})^2\nonumber\\
&\textstyle\quad-\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[\langle\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*},\boldsymbol{u}^{t}\rangle].\label{1tApp1}
\end{flalign}

Using the relations $\mathbb{E}[\|\boldsymbol{u}_{(i)}^{t}\|^2]\!=\! \mathbb{E}[\|u_{i}^{t}\|^2]$ and $\mathbb{E}[\|\boldsymbol{u}^{t}\|^2]\!=\! \sum_{i=1}^{m}\mathbb{E}[\|u_{i}^{t}\|^2]$, we substitute~\eqref{ratez} into~\eqref{1AppL9} to obtain
\begin{equation}
\vspace{-0.2em}
\textstyle \frac{(\lambda_{x}^{t})^2}{m^2}\mathbb{E}[\|\boldsymbol{u}^{t}\|^2]\leq \frac{c_{2}}{(t+1)^{\varrho_{1}}},\label{1tApp2}
\vspace{-0.2em}
\end{equation}
where $\varrho_{1}=\min\{2v_{x}+2\varsigma_{y}-2v_{y},2v_{x}+2\varsigma_{z}-2v_{z}\}$ and $c_{2}=\frac{C_{z}c_{u1}(\lambda_{x}^{0})^2}{m^2(\lambda_{z}^{0})^2}+\frac{c_{u1}r(\lambda_{x}^{0})^2\sigma_{z}^2}{m(\lambda_{z}^{0})^2}+\frac{c_{u2}(\lambda_{x}^{0})^2}{m}$.

The $\mu$-strong convexity of $F(x)$ implies that the third term on the right hand side of~\eqref{1tApp1} satisfies
\begin{equation}
\vspace{-0.2em}
\begin{aligned}
&\textstyle-\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[\langle\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*},\boldsymbol{u}^{t}\rangle]\leq-\frac{\lambda_{x}^{t}\mu}{m}\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}-\boldsymbol{x}^*\|^2]\\
&\textstyle\quad+\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[\langle\boldsymbol{\bar{x}}^{t}\!-\!\boldsymbol{x}^*,\boldsymbol{\breve{u}}^{t}-\boldsymbol{u}^{t}\rangle].\label{1tApp4}
\end{aligned}
\vspace{-0.2em}
\end{equation}

By substituting~\eqref{uhatbound} into~\eqref{1tApp4} and further substituting~\eqref{1tApp2} and~\eqref{1tApp4} into~\eqref{1tApp1}, we obtain
\begin{equation}
\vspace{-0.2em}
\begin{aligned}
&\textstyle\mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}- \boldsymbol{x}^{*}\|^2]\\
&\textstyle\leq \left(1-\frac{\lambda_{x}^{t}\mu}{m}+\frac{(9+2(\sigma_{g,1}^2\!+L_{g}^2))\lambda_{x}^{t}\kappa}{2m}\right)\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*}\|^2]\\
&\textstyle+\frac{2b_{5}\lambda_{x}^{t}}{\kappa m(t+1)^{\beta_{1}}}+\frac{2b_{6}\lambda_{x}^{t}}{ m(t+1)^{\beta_{3}}}+\frac{c_{2}}{(t+1)^{\varrho_{1}}}+\frac{n\sigma_{x}^2}{(t+1)^{2\varsigma_{x}}}.\label{1tApp5}
\end{aligned}
\vspace{-0.2em}
\end{equation}
By letting $\kappa=\frac{\mu}{9+2(\sigma_{g,1}^2\!+L_{g}^2)}$, inequality~\eqref{1tApp5} reduces to
\begin{equation}
\vspace{-0.2em}
\textstyle\mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}\!-\! \boldsymbol{x}^{*}\|^2]\!\leq\! (1-\frac{\lambda_{x}^{t}\mu}{2m})\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}\!-\! \boldsymbol{x}^{*}\|^2]\!+\!\frac{c_{3}}{(t+1)^{\varrho_{2}}},\label{1tApp6}
\end{equation}
where $\varrho_{2}=\min\{2\varsigma_{x},v_{x}+\frac{1}{2}-v_{y}+\varsigma_{y},v_{x}+\frac{1}{2}-v_{z}+\varsigma_{z}\}$ and $c_{3}=c_{2}+n\sigma_{x}^2+\frac{2b_{5}\lambda_{x}^{0}}{\mu m(9+2(\sigma_{g,1}^2\!+L_{g}^2))}+\frac{2b_{6}\lambda_{x}^{0}}{m}.$

Using the relations $\varsigma_{y}>v_{y}-\frac{1}{2}$,~$\varsigma_{z}>v_{z}-\frac{1}{2}$, and $\varsigma_{x}>\frac{v_{x}}{2}$ from the theorem statement, we have $\varrho_{2}>v_{x}$. Therefore, according to~Lemma 4 in~\cite{Tailoring}, there exists a constant $c_{4}\triangleq\frac{\lambda_{x}^{0}\mu}{2mc_{3}}\max\{\mathbb{E}[\|\boldsymbol{\bar{x}}^{0}-\boldsymbol{x}^*\|^2],\frac{2mc_{3}}{\lambda_{x}^{0}\mu-2m(\varrho_{2}-v_{x})}\}$ such that the following inequality always holds:
\begin{equation}
\textstyle\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}\!-\! \boldsymbol{x}^{*}\|^2]\leq \frac{2mc_{3}c_{4}}{\lambda_{x}^{0}\mu(t+1)^{\varrho_{2}-v_{x}}}=\frac{2mc_{3}c_{4}}{\lambda_{x}^{0}\mu(t+1)^{\beta}},\label{1tApp7}
\end{equation}
where $\beta=\min\{2\varsigma_{x}-v_{x},\frac{1}{2}-v_{y}+\varsigma_{y},\frac{1}{2}-v_{z}+\varsigma_{z}\}$.

By using~\eqref{ratex} and~\eqref{1tApp7}, we arrive at
\begin{equation}
\begin{aligned}
&\textstyle \mathbb{E}[\|\boldsymbol{x}^{t}-\boldsymbol{x}^*\|^2]\leq 2 \sum_{i=1}^{m}\mathbb{E}[\|\boldsymbol{x}_{(i)}^{t}\!-\!\boldsymbol{1}_{m}\otimes \bar{x}_{(i)}^{t}\|^2]\\
&\textstyle\quad+2\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}\!-\! \boldsymbol{x}^{*}\|^2]\leq \frac{2C_{x}+4mc_{3}c_{4}(\lambda_{x}^{0}\mu^{-1})}{(t+1)^{\beta}},\label{strongconvexresult}
\end{aligned}
\end{equation}
which implies~\eqref{Theorem1results1} with $C_{x}$ given in~\eqref{ratex}, $c_{3}$ given in~\eqref{1tApp6}, and $c_{4}$ given in the paragraph above~\eqref{1tApp7}.
\vspace{0.3em}

(ii) Convergence rate when $F(\boldsymbol{x})$ is general convex.

Recalling the definition of $\breve{u}_{i}^{t}$ given in~\eqref{udefinition}, we have $\sum_{i=1}^{m}\breve{u}_{i}^{t}=\nabla F(\boldsymbol{x}^{t})$. Using this and the convexity of $F$, the last term on the right hand side of~\eqref{1tApp1} satisfies
\begin{equation}
\begin{aligned}
&\textstyle -\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[\langle\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*},\boldsymbol{u}^{t}\rangle]\leq  -\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[F(\boldsymbol{x}^{t})-F(\boldsymbol{x}^{*})]\\
&\textstyle\quad-\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[\langle\boldsymbol{\bar{x}}^{t}\!-\! \boldsymbol{x}^{t},\boldsymbol{\breve{u}}^{t}\rangle]\!+\!\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[\langle\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*},\boldsymbol{\breve{u}}^{t}-\boldsymbol{u}^{t}\rangle].\label{2tApp2}
\end{aligned}
\end{equation}
The second term on the right hand side of~\eqref{2tApp2} satisfies
\begin{flalign}
\textstyle -\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[\langle\boldsymbol{\bar{x}}^{t}\!-\! \boldsymbol{x}^{t},\boldsymbol{\breve{u}}^{t}\rangle]\leq\frac{2(L_{f}+L_{g}L_{f})\sqrt{C_{x}}\lambda_{x}^{0}}{m(t+1)^{\varsigma_{x}+v_{x}}}\triangleq\frac{c_{5}}{(t+1)^{\varsigma_{x}+v_{x}}},\nonumber
\end{flalign}
where in the derivation we have used~\eqref{ratex}.

Substituting the preceding inequality and~\eqref{uhatbound} into~\eqref{2tApp2} and letting $\kappa=\frac{2a_{t}}{(9+2(\sigma_{g,1}^2\!+L_{g}^2))\lambda_{x}^{t}}$ for any $a_{t}>0$, we obtain
\begin{equation}
\vspace{-0.2em}
\begin{aligned}
&\textstyle -\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[\langle\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*},\boldsymbol{u}^{t}\rangle]\leq  -\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[F(\boldsymbol{x}^{t})-F(\boldsymbol{x}^{*})]\\
&\textstyle\quad  +\frac{a_{t}}{m}\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}-\boldsymbol{x}^*\|^2]+\frac{(9+2(\sigma_{g,1}^2\!+L_{g}^2))b_{5}(\lambda_{x}^{t})^2}{a_{t}m(t+1)^{\beta_{1}}}\\
&\textstyle\quad+\frac{2b_{6}\lambda_{x}^{t}}{m(t+1)^{\beta_{3}}}+\frac{c_{5}}{(t+1)^{\varsigma_{x}+v_{x}}}.\label{2tApp3}
\end{aligned}
\vspace{-0.2em}
\end{equation}

Further substituting~\eqref{2tApp3} into~\eqref{1tApp1} leads to
\begin{equation}
\vspace{-0.2em}
\begin{aligned}
&\textstyle\mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}-\boldsymbol{x}^*\|^2]\leq -\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[F(\boldsymbol{x}^{t})-F(\boldsymbol{x}^{*})]\\
&\textstyle\quad+(1+\frac{a_{t}}{m})\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}-\boldsymbol{x}^*\|^2]+\Phi_{t},\label{2tApp4}
\end{aligned}
\vspace{-0.2em}
\end{equation}
where the term $\Phi_{t}$ is given by
\begin{equation}
\vspace{-0.2em}
\begin{aligned}
&\textstyle \Phi_{t}=\frac{(\lambda_{x}^{t})^2}{m^2}\mathbb{E}[\|\boldsymbol{u}^{t}\|^2]+n(\sigma_{x}^{t})^2+\frac{(9+2(\sigma_{g,1}^2\!+L_{g}^2))b_{5}(\lambda_{x}^{t})^2}{a_{t}m(t+1)^{\beta_{1}}}\\
&\textstyle\quad+\frac{2b_{6}\lambda_{x}^{t}}{m(t+1)^{\beta_{3}}}+\frac{c_{5}}{(t+1)^{\varsigma_{x}+v_{x}}}.\label{2tApp5}
\end{aligned}
\vspace{-0.2em}
\end{equation}

Since $F(\boldsymbol{x}^{t})\geq F(\boldsymbol{x}^{*})$ always holds, we drop the negative term 
$-\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[F(\boldsymbol{x}^{t})-F(\boldsymbol{x}^{*})]$ in~\eqref{2tApp4} to obtain
\begin{equation}
\vspace{-0.2em}
\begin{aligned}
&\textstyle \mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}-\boldsymbol{x}^*\|^2]\leq (1+\frac{a_{t}}{m})\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}-\boldsymbol{x}^*\|^2]+\Phi_{t}\\
&\textstyle \leq \left(\prod_{t=0}^{T}(1+a_{t})\right)\left(\mathbb{E}[\|\boldsymbol{\bar{x}}^{0}-\boldsymbol{x}^*\|^2]+\sum_{t=0}^{T}\Phi_{t}\right).\label{2tApp6}
\end{aligned}
\vspace{-0.2em}
\end{equation}
Using $\ln(1+u)\leq u$ holding for any $u>0$ and letting $a_{t}=\frac{1}{(t+1)^{s}}$ with $1<s<2v_{x}$ and $a_{0}=1$, we have
\begin{equation}
\vspace{-0.2em}
\begin{aligned}
&\textstyle \ln\left(\prod_{t=0}^{T}(1+a_{t})\right)=\sum_{t=0}^{T}\ln(1+a_{t})\leq \sum_{t=0}^{T}a_{t}\nonumber\\
&\textstyle\leq \sum_{t=0}^{T}\frac{1}{(t+1)^{s}}\leq 1+\int_{1}^{\infty}\frac{1}{x^{s}}dx\leq 1+\frac{1}{s-1},\label{2tApp7}
\end{aligned}
\vspace{-0.2em}
\end{equation}
which implies $\prod_{t=0}^{T}(1+a_{t})\leq e^{\frac{s}{s-1}}$. Then, inequality~\eqref{2tApp4} can be rewritten as follows:
\begin{equation}
\vspace{-0.2em}
\textstyle \mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}\!-\!\boldsymbol{x}^*\|^2]\leq  e^{\frac{s}{s-1}}\left(\mathbb{E}[\|\boldsymbol{\bar{x}}^{0}\!-\!\boldsymbol{x}^*\|^2]\!+\!\sum_{t=0}^{T}\Phi_{t}\right).\label{2tApp8}
\end{equation}
Next, we estimate an upper bound on $\sum_{t=0}^{T}\Phi_{t}$. Substituting~\eqref{1tApp2} into~\eqref{2tApp5} and using the following inequality:
\begin{equation}
\vspace{-0.2em}
\textstyle \sum_{t=0}^{T}\frac{1}{(t+1)^{s}}\leq 1+\int_{1}^{\infty}\frac{1}{x^{s}}dx\leq\frac{s}{s-1},\label{2tApp10}
\end{equation}
for any $1<s<2v_{x}$, we obtain
\begin{flalign}
&\textstyle \sum_{t=0}^{T}\Phi_{t}\leq c_{2}\max\{\frac{2v_{x}+2\varsigma_{y}-2v_{y}}{2v_{x}+2\varsigma_{y}-2v_{y}-1},\frac{2v_{x}+2\varsigma_{z}-2v_{z}}{2v_{x}+2\varsigma_{z}-2v_{z}-1}\}\nonumber\\
&\textstyle+\frac{n\sigma_{x}^2(2\varsigma_{x})}{2\varsigma_{x}-1}+\frac{(9+2(\sigma_{g,1}^2\!+L_{g}^2))b_{5}(\lambda_{x}^{0})^2(1+2v_{x}-s)}{m(2v_{x}-s)}\!+\!\frac{c_{5}(v_{x}+\varsigma_{x})}{v_{x}+\varsigma_{x}-1}\nonumber\\
&\textstyle+\frac{2b_{6}\lambda_{x}^{0}}{m}\max\{\frac{v_{x}+\frac{1}{2}-v_{y}+\varsigma_{y}}{v_{x}+\frac{1}{2}-v_{y}+\varsigma_{y}-1},\frac{v_{x}+\frac{1}{2}-v_{z}+\varsigma_{z}}{v_{x}+\frac{1}{2}-v_{z}+\varsigma_{z}-1}\}\triangleq\frac{c_{6}}{m}.\label{2tApp11}
\end{flalign}

Substituting~\eqref{2tApp11} into~\eqref{2tApp8}, we arrive at
\begin{equation}
\textstyle \mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}-\boldsymbol{x}^*\|^2]\leq  e^{\frac{s}{s-1}}\left(\mathbb{E}[\|\boldsymbol{\bar{x}}^{0}-\boldsymbol{x}^*\|^2]+\frac{c_{6}}{m}\right).\label{2tApp12}
\end{equation}

We proceed to sum both sides of~\eqref{2tApp4} from $0$ to $T$ ($T$ can be any positive integer):
\begin{flalign}
&\textstyle\sum_{t=0}^{T}\frac{2\lambda_{x}^{t}}{m}\mathbb{E}[F(\boldsymbol{x}^{t})-F(\boldsymbol{x}^{*})]\leq -\sum_{t=0}^{T}\mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}- \boldsymbol{x}^{*}\|^2]\nonumber\\
&\textstyle\quad+\sum_{t=0}^{T}(1+\frac{a_{t}}{m})\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*}\|^2]+\sum_{t=0}^{T}\Phi_{t}.\label{2tApp13}
\end{flalign}
The first and second terms on the right hand side of~\eqref{2tApp13} can be simplified as follows:
\begin{flalign}
&\textstyle \sum_{t=0}^{T}(1+\frac{a_{t}}{m})\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*}\|^2]-\sum_{t=0}^{T}\mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}- \boldsymbol{x}^{*}\|^2]\nonumber\\
&\textstyle \leq \frac{a_{0}}{m}\mathbb{E}[\|\boldsymbol{\bar{x}}^{0}- \boldsymbol{x}^{*}\|^2]+\sum_{t=1}^{T}\frac{a_{t}}{m}\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}- \boldsymbol{x}^{*}\|^2]\nonumber\\
&\textstyle\quad+\mathbb{E}[\|\boldsymbol{\bar{x}}^{0}- \boldsymbol{x}^{*}\|^2]-\mathbb{E}[\|\boldsymbol{\bar{x}}^{T+1}- \boldsymbol{x}^{*}\|^2]\leq\frac{c_{7}}{m},\label{2tApp14}
\end{flalign}
with $\frac{c_{7}}{m}=(\frac{se^{\frac{s}{s-1}}}{m(s-1)}+1+\frac{1}{m})\mathbb{E}[\|\boldsymbol{\bar{x}}^{0}-\boldsymbol{x}^{*}\|^2]+\frac{c_{6}s}{m(s-1)}$. Here, we have used~\eqref{2tApp10} and~\eqref{2tApp12} in the last inequality.

Substituting~\eqref{2tApp11} and~\eqref{2tApp14} into~\eqref{2tApp13} yields the inequality $\sum_{t=0}^{T}2\lambda_{x}^{t}\mathbb{E}[F(\boldsymbol{x}^{t})-F(\boldsymbol{x}^{*})]\leq c_{6}+c_{7}$. Further using $\lambda_{x}^{T}\leq \lambda_{x}^{t}$ holding for any $t\in[0,T]$, we arrive at
\begin{equation}
\textstyle\frac{1}{T+1}\sum_{t=0}^{T}\mathbb{E}[F(\boldsymbol{x}^{t})-F(\boldsymbol{x}^{*})]\leq \frac{c_{6}+c_{7}}{2\lambda_{x}^{0}(T+1)^{1-v_{x}}},\label{2tApp15}
\end{equation}
which implies~\eqref{Theorem1results2}.
\vspace{0.2em}

(iii) Convergence rate when $F(\boldsymbol{x})$ is nonconvex.

To prove the convergence of Algorithm~\ref{algorithm1} for nonconvex objective functions, we first need to estimate an upper bound on $\mathbb{E}[\langle \nabla F(\boldsymbol{\bar{x}}^{t})-\nabla F(\boldsymbol{x}^{*}),\boldsymbol{\breve{u}}^{t}-\boldsymbol{u}^{t}\rangle]$. 

By using an argument similar to the derivation of~\eqref{1TApp3}, we use the following decomposition:
\begin{flalign}
&\textstyle\mathbb{E}[\langle \nabla F(\boldsymbol{\bar{x}}^{t})-\nabla F(\boldsymbol{x}^{*}),\boldsymbol{\breve{u}}^{t}-\boldsymbol{u}^{t}\rangle]=\mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t})\!-\!\nabla F(\boldsymbol{x}^{*}),\nonumber\\
&\textstyle\quad\nabla_{x}\boldsymbol{f}(\boldsymbol{x}^{t},\boldsymbol{1}_{m}\otimes g(\boldsymbol{x}^{t}))-\nabla_{x}\boldsymbol{f}^{t}(\boldsymbol{x}^{t},\boldsymbol{\tilde{y}}^{t})\rangle]\nonumber\\
&\textstyle\quad+\mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t})-\nabla F(\boldsymbol{x}^{*}),\nabla \boldsymbol{g}(\boldsymbol{x}^{t})\nonumber\\
&\textstyle\quad\times(\boldsymbol{1}_{m}\otimes \nabla_{y}\bar{f}(\boldsymbol{x}^{t},\boldsymbol{1}_{m}\otimes g(\boldsymbol{x}^{t}))-\nabla \boldsymbol{g}^{t}(\boldsymbol{x}^{t})\boldsymbol{\tilde{z}}^{t})\rangle].\label{3TApp3}
\end{flalign}

By using an argument similar to the derivation of~\eqref{firstlemmaresult}, the first term on the right hand side of~\eqref{3TApp3} satisfies
\begin{flalign}
&\textstyle\mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t})\!-\!\nabla F(\boldsymbol{x}^{*}),\!\nabla_{x}\boldsymbol{f}(\boldsymbol{x}^{t},\!\boldsymbol{1}_{m}\!\otimes\! g(\boldsymbol{x}^{t}))\!-\!\nabla_{x}\boldsymbol{f}^{t}(\boldsymbol{x}^{t},\boldsymbol{\tilde{y}}^{t})\rangle]\nonumber\\
&\textstyle\leq \frac{\kappa}{2}\mathbb{E}[\|\nabla F(\boldsymbol{\bar{x}}^{t})\!-\!\nabla F(\boldsymbol{x}^{*})\|^2]+\frac{b_{1}}{\kappa(t+1)^{\beta_{1}}}+\frac{L_{F}b_{2}}{(t+1)^{\beta_{2}}},\label{firstlemmaresult1}
\end{flalign}
where $b_{1}$ and $b_{2}$ are the same as those given in~\eqref{firstlemmaresult} and $L_{F}$ is from Lemma~\ref{lemmaLF}.

We characterize the second term on the right hand side of~\eqref{3TApp3} by estimating an upper bound on the term $\mathbb{E}[\|\Xi_{x}^{\prime t}-\Xi_{x}^{\prime t-1}\|]$ with $\Xi_{x}^{\prime t}\triangleq \nabla \boldsymbol{g}^{t}(\boldsymbol{x}^{t})^{\top}\nabla F(\boldsymbol{\bar{x}}^{t})$. By using an argument similar to the derivation of~\eqref{2TApp10}, we have
\begin{flalign}
&\textstyle \mathbb{E}[\|\Xi_{x}^{\prime t}-\Xi_{x}^{\prime t-1}\|^2]\nonumber\\
&\textstyle\leq \mathbb{E}[\|(\nabla \boldsymbol{g}^{t}(\boldsymbol{x}^{t})-\nabla \boldsymbol{g}(\boldsymbol{x}^{t}))^{\top}\nabla F(\boldsymbol{\bar{x}}^{t})\|^2]\nonumber\\
&\textstyle\quad+\mathbb{E}[\|(\nabla \boldsymbol{g}^{t-1}(\boldsymbol{x}^{t-1})-\nabla \boldsymbol{g}(\boldsymbol{x}^{t-1}))^{\top}\nabla F(\boldsymbol{\bar{x}}^{t-1})\|^2]\nonumber\\
&\textstyle\quad+2\mathbb{E}[\|(\nabla \boldsymbol{g}(\boldsymbol{x}^{t-1})-\nabla \boldsymbol{g}(\boldsymbol{x}^{t}))^{\top}\nabla F(\boldsymbol{\bar{x}}^{t})\|]\nonumber\\
&\textstyle\quad+2\mathbb{E}[\|\nabla F(\boldsymbol{\bar{x}}^{t})-\nabla F(\boldsymbol{\bar{x}}^{t-1})\|^2\|\nabla \boldsymbol{g}(\boldsymbol{x}^{t-1})\|^2]\nonumber\\
&\textstyle\leq  \frac{2m\sigma_{g,1}^2L_{f}^2}{t}+2\bar{L}_{g}^2L_{f}^2\mathbb{E}[\|\boldsymbol{x}^{t}-\boldsymbol{x}^{t-1}\|^2]\nonumber\\
&\textstyle\quad+2L_{g}^2L_{F}^2\mathbb{E}[\|\boldsymbol{\bar{x}}^{t}-\boldsymbol{\bar{x}}^{t-1}\|^2].\label{3tApp1}
\end{flalign}
Substituting~\eqref{1TApp18} and~\eqref{2TApp12} into~\eqref{2TApp10} yields
\begin{equation}
\begin{aligned}
\textstyle \mathbb{E}[\|\Xi_{x}^{\prime t}-\Xi_{x}^{\prime t-1}\|^2]&\textstyle\leq\frac{2m\sigma_{g,1}^2L_{f}^2}{t+1}+\frac{L_{f}^2\bar{L}_{g}^22^{2\varsigma_{x}+1}d_{6}}{(t+1)^{2\varsigma_{x}}}\\
&\textstyle\quad+\frac{2^{2\varsigma_{x}+1}d_{1}L_{g}^2L_{F}^2}{(t+1)^{2\varsigma_{x}}}\leq\frac{d_{7}^{\prime}}{(t+1)^{\beta_{1}}},\label{3TApp2}
\end{aligned}
\end{equation}
with  $d_{7}^{\prime}=2m\sigma_{g,1}^2L_{f}^2+2^{2\varsigma_{x}+1}d_{6}L_{f}^2\bar{L}_{g}^2+2^{2\varsigma_{x}+1}d_{1}L_{g}^2L_{F}$ and $\beta_{1}=\min\{2\varsigma_{x},1\}$.

By using an argument similar to the derivation of~\eqref{secondlemmaresult} with replacing an upper bound on $\mathbb{E}[|\Xi_{x}^{t}-\Xi_{x}^{ t-1}|^2]$ with the one provided in~\eqref{3TApp2}, we obtain that the second term on the right hand side of~\eqref{3TApp3} satisfies
\begin{flalign}
&\textstyle \mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t})-\nabla F(\boldsymbol{x}^{*}),\nabla \boldsymbol{g}(\boldsymbol{x}^{t})\nonumber\\
&\textstyle\quad\times(\boldsymbol{1}_{m}\otimes \nabla_{y}\bar{f}(\boldsymbol{x}^{t},\boldsymbol{1}_{m}\otimes g(\boldsymbol{x}^{t}))-\nabla \boldsymbol{g}^{t}(\boldsymbol{x}^{t})\boldsymbol{\tilde{z}}^{t})\rangle]\nonumber\\
&\textstyle\leq \frac{(7+2(\sigma_{g,1}^2\!+L_{g}^2))\kappa}{4}\mathbb{E}[\|\nabla F(\boldsymbol{\bar{x}}^{t})-\nabla F(\boldsymbol{x}^{*})\|^2]\nonumber\\
&\textstyle\quad+\frac{b_{3}}{\kappa(t+1)^{\beta_{1}}}\!+\!\frac{b_{4}^{\prime}}{(t+1)^{\beta_{3}}},\label{secondlemmaresult2}
\end{flalign}
where $b_{4}^{\prime}$ is the same as that in~\eqref{secondlemmaresult} except that $d_{7}$ is replaced with $d_{7}^{\prime}=2m\sigma_{g,1}^2L_{f}^2+2^{2\varsigma_{x}+1}d_{6}L_{f}^2\bar{L}_{g}^2+2^{2\varsigma_{x}+1}d_{1}L_{g}^2L_{F}$. 

By substituting~\eqref{firstlemmaresult1} and~\eqref{secondlemmaresult2} into~\eqref{3TApp3}, we obtain
\begin{equation}
\begin{aligned}
&\textstyle \mathbb{E}[\langle \nabla F(\boldsymbol{\bar{x}}^{t})-\nabla F(\boldsymbol{x}^{*}),\boldsymbol{\breve{u}}^{t}-\boldsymbol{u}^{t}\rangle]\\
&\textstyle\leq\frac{(9+2(\sigma_{g,1}^2\!+L_{g}^2))\kappa}{4}\mathbb{E}[\|\nabla F(\boldsymbol{\bar{x}}^{t})-\nabla F(\boldsymbol{x}^{*})\|^2]\\
&\textstyle\quad+\frac{b_{5}}{\kappa(t+1)^{\beta_{1}}}+\frac{b_{6}^{\prime}}{(t+1)^{\beta_{3}}},\label{uhatbound2}
\end{aligned}
\end{equation}
with $\beta_{1}=\min\{2\varsigma_{x},1\}$, $\beta_{3}=\min\{\varsigma_{x}-v_{y}+\varsigma_{y},\varsigma_{x}-v_{z}+\varsigma_{z},\frac{1}{2}-v_{y}+\varsigma_{y},\frac{1}{2}-v_{z}+\varsigma_{z}\}$, $b_{5}$ given in~\eqref{uhatbound}, and $b_{6}^{\prime}=L_{F}b_{2}+b_{4}^{\prime}$.  

Building on~\eqref{uhatbound2}, we continue to prove Theorem~\ref{T1}-(iii). 

The Lipschitz continuity of $F(\boldsymbol{x})$ implies
\begin{equation}
\begin{aligned}
&\textstyle \mathbb{E}[F(\boldsymbol{\bar{x}}^{t+1})-F(\boldsymbol{\bar{x}}^{t})]\leq \mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t}), \boldsymbol{\bar{x}}^{t+1}-\boldsymbol{\bar{x}}^{t}\rangle]\\
&\textstyle\quad+\frac{L_{F}^2}{2}\mathbb{E}[\|\boldsymbol{\bar{x}}^{t+1}-\boldsymbol{\bar{x}}^{t}\|^2].\label{3tApp3}
\end{aligned}
\end{equation}

According to the relation $\boldsymbol{\bar{x}}^{t+1}=\boldsymbol{\bar{x}}^{t}+\boldsymbol{\bar{\vartheta}}_{w}^{t}-\frac{\lambda_{x}^{t}}{m}\boldsymbol{u}^{t}$, which holds due to $\Omega=\mathbb{R}^{n}$ given in the theorem statement, the first term on the right hand side of~\eqref{3tApp3} satisfies
\begin{flalign}
&\textstyle \mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t}), \boldsymbol{\bar{x}}^{t+1}-\boldsymbol{\bar{x}}^{t}\rangle]=-\mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t}), \frac{\lambda_{x}^{t}}{m}\boldsymbol{u}^{t}\rangle]\nonumber\\
&\textstyle\leq \frac{\lambda_{x}^{t}}{m}\mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t}),\boldsymbol{\breve{u}}^{t}- \boldsymbol{u}^{t}\rangle]-\frac{\lambda_{x}^{t}}{m}\mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t}),\nabla F(\boldsymbol{\bar{x}}^{t})\rangle]\nonumber\\
&\textstyle \quad-\frac{\lambda_{x}^{t}}{m}\mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t}),\boldsymbol{\breve{u}}^{t}-\nabla F(\boldsymbol{\bar{x}}^{t})\rangle].\label{3tApp4}
\end{flalign}
By using the Young's inequality, for any $\kappa>0$, the last term on the right hand side of~\eqref{3tApp4} satisfies
\begin{equation}
\begin{aligned}
&\textstyle \mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t}),\boldsymbol{\breve{u}}^{t}-\nabla F(\boldsymbol{\bar{x}}^{t})\rangle]\\
&\textstyle\leq \frac{\kappa}{4}\mathbb{E}[\|\nabla F(\boldsymbol{\bar{x}}^{t})\|^2]+\frac{1}{\kappa}\mathbb{E}[\|\boldsymbol{\breve{u}}^{t}-\nabla F(\boldsymbol{\bar{x}}^{t})\|^2].\label{3tApp5}
\end{aligned}
\end{equation}
By using the definition of $\breve{u}_{i}^{t}$ in~\eqref{udefinition}, we have
\begin{flalign}
&\textstyle \mathbb{E}[\|\boldsymbol{\breve{u}}^{t}-\nabla F(\boldsymbol{\bar{x}}^{t})\|^2]\nonumber\\
&\textstyle\leq (2\bar{L}_{f}^2(1+L_{g}^2)(1+2L_{g}^2)+4\bar{L}_{g}^2L_{f}^2)\mathbb{E}[\|\boldsymbol{x}^{t}-\boldsymbol{\bar{x}}^{t}\|^2]\nonumber\\
&\textstyle\leq\frac{c_{8}}{(t+1)^{2\varsigma_{x}}},\label{3tApp6}
\end{flalign}
where $c_{8}$ is given by $c_{8}=C_{x}(2\bar{L}_{f}^2(1+L_{g}^2)(1+2L_{g}^2)+4\bar{L}_{g}^2L_{f}^2)$ with $C_{x}$ given in~\eqref{ratex}. Here, we have used $\mathbb{E}[\|\boldsymbol{x}^{t}-\boldsymbol{\bar{x}}^{t}\|^2]\leq \sum_{i=1}^{m}\mathbb{E}[\|\boldsymbol{x}_{(i)}^{t}-\boldsymbol{1}_{m}\otimes \bar{x}_{(i)}^{t}\|^2]\leq\frac{C_{x}}{(t+1)^{2\varsigma_{x}}}$ in the last inequality.

By substituting~\eqref{3tApp6} into~\eqref{3tApp5} and further substituting~\eqref{uhatbound2} and~\eqref{3tApp5} into~\eqref{3tApp4}, we arrive at
\begin{equation}
\begin{aligned}
&\textstyle \mathbb{E}[\langle\nabla F(\boldsymbol{\bar{x}}^{t}), \boldsymbol{\bar{x}}^{t+1}-\boldsymbol{\bar{x}}^{t}\rangle]\leq -\frac{\lambda_{x}^{t}}{2m}\mathbb{E}[\|\nabla F(\boldsymbol{\bar{x}}^{t})\|^2]\\
&\textstyle\quad
+\frac{b_{5}\lambda_{x}^{t}}{m\kappa(t+1)^{\beta_{1}}}+\frac{b_{6}^{\prime}\lambda_{x}^{t}}{m(t+1)^{\beta_{3}}}+\frac{c_{8}}{\kappa(t+1)^{2\varsigma_{x}}}.\label{3tApp7}
\end{aligned}
\end{equation}

Substituting~\eqref{3tApp7} into~\eqref{3tApp3} and letting $\kappa\!=\!\frac{1}{5+\sigma_{g,1}^2+L_{g}^2}$ yield
\begin{equation}
\textstyle \mathbb{E}[F(\boldsymbol{\bar{x}}^{t+1})-F(\boldsymbol{\bar{x}}^{t})]\leq -\frac{\lambda_{x}^{t}}{2m}\mathbb{E}[\|\nabla F(\boldsymbol{\bar{x}}^{t})\|^2]+\Phi_{t},\label{3tApp8}
\end{equation}
where the term $\Phi_{t}$ is given by
\begin{equation}
\Phi_{t}\textstyle=\frac{b_{5}(5+\sigma_{g,1}^2+L_{g}^2)\lambda_{x}^{0}}{m(t+1)^{\beta_{1}+v_{x}}}\!+\!\frac{b_{6}^{\prime}\lambda_{x}^{0}}{m(t+1)^{\beta_{3}+v_{x}}}\!+\!\frac{c_{8}(5+\sigma_{g,1}^2+L_{g}^2)+2^{2\varsigma_{x}}d_{1}L_{F}^2}{(t+1)^{2\varsigma_{x}}}.\label{3tApp9}
\end{equation}

Summing both sides of~\eqref{3tApp8} from $0$ to $T$ and using the relationship $F(\boldsymbol{x}^*)\leq F(\boldsymbol{\bar{x}}^{T+1})$, we obtain
\begin{equation}
\textstyle\sum_{t=0}^{T}\!\lambda_{x}^{t}\mathbb{E}[\|\nabla F(\boldsymbol{\bar{x}}^{t})\|^2] \!\leq\! 2m\mathbb{E}[F(\boldsymbol{\bar{x}}^{0})-F(\boldsymbol{x}^{*})]+2m\sum_{t=0}^{T}\Phi_{t}.\nonumber
\end{equation}

Combining the preceding inequality and the relationship $\|\nabla F(\boldsymbol{x}^{t})\|^2\leq 2\|\nabla F(\boldsymbol{x}^{t})-\nabla F(\boldsymbol{\bar{x}}^{t})\|^2+2\|\nabla F(\boldsymbol{\bar{x}}^{t})\|^2$ yields
\begin{equation}
\begin{aligned}
&\textstyle \textstyle\sum_{t=0}^{T}\lambda_{x}^{t}\mathbb{E}[\|\nabla F(\boldsymbol{x}^{t})\|^2] \leq 4m\mathbb{E}[F(\boldsymbol{\bar{x}}^{0})-F(\boldsymbol{x}^{*})]\\
&\textstyle\!+\!4m\sum_{t=0}^{T}\Phi_{t}\!+\!2\sum_{t=0}^{T}\lambda_{x}^{t}\mathbb{E}[\|\nabla F(\boldsymbol{x}^{t})\!-\!\nabla F(\boldsymbol{\bar{x}}^{t})\|^2].\label{3tApp10}
\end{aligned}
\end{equation}

By using~\eqref{2tApp10},~\eqref{3tApp9}, and~\eqref{ratex}, the second and third terms on the right hand side of~\eqref{3tApp10} satisfy
\begin{flalign}
&\textstyle 4m\sum_{t=0}^{T}\Phi_{t}\!+\!2\sum_{t=0}^{T}\lambda_{x}^{t}\mathbb{E}[\|\nabla F(\boldsymbol{x}^{t})\!-\!\nabla F(\boldsymbol{\bar{x}}^{t})\|^2]\nonumber\\
&\textstyle\leq \frac{2\lambda_{x}^{0}L_{F}C_{x}(v_{x}+2\varsigma_{x})}{v_{x}+2\varsigma_{x}-1}+\frac{4b_{5}(5+\sigma_{g,1}^2+L_{g}^2)\lambda_{x}^{0}(1+v_{x})}{v_{x}}\nonumber\\
&\textstyle\quad +4b_{6}^{\prime}\lambda_{x}^{0}\max\{\frac{v_{x}+\frac{1}{2}-v_{y}+\varsigma_{y}}{v_{x}+\frac{1}{2}-v_{y}+\varsigma_{y}-1},\frac{v_{x}+\frac{1}{2}-v_{z}+\varsigma_{z}}{v_{x}+\frac{1}{2}-v_{z}+\varsigma_{z}-1}\}\nonumber\\
&\textstyle\quad+\frac{4mc_{8}(5+\sigma_{g,1}^2+L_{g}^2)2\varsigma_{x}}{2\varsigma_{x}-1}+\frac{m2^{2\varsigma_{x}}d_{1}L_{F}^2\varsigma_{x}+2}{2\varsigma_{x}-1}\triangleq c_{9}.\label{3tApp11}
\end{flalign}

We define $c_{10}=4m\mathbb{E}[F(\boldsymbol{\bar{x}}^{0})-F(\boldsymbol{x}^{*})]$ and substitute~\eqref{3tApp11} into~\eqref{3tApp10} to obtain
\begin{equation}
\textstyle\frac{1}{T+1}\sum_{t=0}^{T}\mathbb{E}[\|\nabla F(\boldsymbol{x}^{t})\|^2]\leq\frac{c_{9}+c_{10}}{\lambda_{x}^{0}(T+1)^{1-v_{x}}},\label{nonconvexresult}
\end{equation}
which implies~\eqref{Theorem1results3}.

\subsection{Proof of Corollary~\ref{tradeoff}}
By applying the following inequality:
\begin{equation}
\begin{aligned}
\textstyle\sum_{t=1}^{T}\frac{1}{(t+1)^{r}}\leq \int_{0}^{T}\frac{1}{(t+1)^{r}}dx=\frac{1}{1-r}((T+1)^{1-r}-1),\nonumber
\end{aligned}
\end{equation}
to~\eqref{4T19}, we can obtain
\begin{equation}
\textstyle\epsilon_{i}\leq \frac{\sqrt{2}C_{x}}{\sigma_{i,x}(v_{x}-v_{z}-\varsigma_{i,x})}+\frac{\sqrt{2}C_{y}}{\sigma_{i,x}(v_{y}-\varsigma_{i,y})}+\frac{\sqrt{2}C_{z}}{\sigma_{i,x}(v_{z}-\varsigma_{i,z})}.\label{TC2}
\end{equation}

We denote the given cumulative privacy budget as $\hat{\epsilon}_{i}>0$. According to~\eqref{TC2}, we can choose DP-noise parameters as $\sigma_{i,x}\!=\!\frac{3\sqrt{2}C_{x}}{(v_{x}-v_{z}-\varsigma_{i,x})\hat{\epsilon}_{i}}$, $\sigma_{i,y}\!=\!\frac{3\sqrt{2}C_{y}}{(v_{y}-\varsigma_{i,y})\hat{\epsilon}_{i}}$, and $\sigma_{i,z}\!=\!\frac{3\sqrt{2}C_{y}}{(v_{z}-\varsigma_{i,z})\hat{\epsilon}_{i}}$, where the parameters $v_{x}$, $v_{y}$, $v_{z}$, $\varsigma_{x}$, $\varsigma_{y}$, and $\varsigma_{z}$ are  predetermined constants (e.g., parameters given in Corollary~\ref{complexity}) that satisfy the conditions given in Theorem~\ref{T4}. It is clear that a smaller $\hat{\epsilon}_{i}$ leads to larger values of $\sigma_{i,x}$, $\sigma_{i,y}$, and $\sigma_{i,z}$.

Next, we analyze the convergence rate of Algorithm~\ref{algorithm1} under a strongly convex $F(x)$. According to~\eqref{strongconvexresult}, we have $\mathbb{E}[\|\boldsymbol{x}^{t}-\boldsymbol{x}^*\|^2]\leq \frac{2C_{x}+4mc_{3}c_{4}(\lambda_{x}^{0}\mu^{-1})}{(t+1)^{\beta}}$. The definitions of $C_{x}$, $c_{3}$, and $c_{4}$ (which are given in~\eqref{ratex},~\eqref{1tApp6}, and the paragraph above~\eqref{1tApp7}, respectively) imply that they are positively correlated with the DP-noise parameters $\sigma_{x}^2$, $\sigma_{y}^2$, and $\sigma_{z}^2$, which are all inversely proportional to $\hat{\epsilon}_{i}^2$. Therefore, we obtain $\mathbb{E}[\|\boldsymbol{x}^{t}-\boldsymbol{x}^*\|^2]\leq \mathcal{O}(\frac{T^{-\beta}}{\min_{i\in [m]}\{\hat{\epsilon}_{i}^2\}})$.

Similarly, according to~\eqref{2tApp15} and~\eqref{nonconvexresult}, the convergence rates of Algorithm~\ref{algorithm1} under a convex and nonconvex $F(\boldsymbol{x})$ satisfies $ \frac{c_{6}+c_{7}}{2\lambda_{x}^{0}(T+1)^{1-v_{x}}}$ and $\frac{c_{9}+c_{10}}{\lambda_{x}^{0}(T+1)^{1-v_{x}}}$, respectively. Given that $c_{6}+c_{7}$ and $c_{9}+c_{10}$ are both positively correlated with DP-noise parameters $\sigma_{x}^2$, $\sigma_{y}^2$, and $\sigma_{z}^2$ which are all inversely proportional to $\hat{\epsilon}_{i}^2$, we arrive at the result in Corollary~\ref{tradeoff}. 
