\title[K.~Max et al.]{Synthetic Biology Meets Neuromorphic Computing: Towards a Bio-Inspired Olfactory Perception System}


\author{Kevin Max$^{1,2}$, Larissa Sames$^{3}$, Shimeng Ye$^{4}$,   Jan Steink\"uhler$^{3,5}$, and Federico Corradi$^{4}$}


\address{$^{1}$Neural Computation Unit, Okinawa Institute of Science and Technology, Japan}
