\section{Proof of Lemma \ref{thm_corr}}
\label{appendix_lemma_proof}
\begin{proof}
    It is obvious that
    $m^{directed}=\sum_i{k^{in}_i}+\sum_i{k^{out}_i}=2m$. By the modularity definition \eqref{eq_modularity_directed} of any directed graph $G_d$, we prove that
    \begin{align}
        Q&=\frac{1}{m^{directed}}\sum_{ij}\sum_{u} \left[A_{ij}-\frac{k^{in}_ik^{out}_j}{m^{directed}}\right]S_{iu}S_{ju}\\
        &=\frac{1}{2m}\sum_{ij}\sum_{u} \left[A_{ij}-\frac{k_ik_j}{2m}\right]S_{iu}S_{ju}.
    \end{align}
\end{proof}

\section{Proof of Theorem \ref{thm-fm}}
\label{appendix_theorem_proof}
\begin{proof}
    Considering $\Tr\left(S^TDS\right)$, it can be expanded into a summation
    \begin{align}
        \Tr\left(S^TDS\right)&=\sum_{ij} \sum_{u}D_{ij}\delta_{C_u}(i,j)\\
        &=\sum_{ij}\sum_{u}\sum_{w}\delta_{C_u}(i,j)\delta_{P_w}(i,j)\\
        %&=\sum_{u}\sum_{w}\sum_{v_i,v_j\in C_u\cap P_w}1\\
        &=\sum_{u}\sum_{w}\left(\sum_{v_i\in C_u\cap P_w}1\right)^2\\
        &=\sum_{u=1}^k\sum_{w=1}^r |C_u\cap P_w|^2,
    \end{align}
    where $\delta_{P_w}(i,j)=1$ if $v_i,v_j$ are in the same $P_w$, and $\delta_{P_w}(i,j)=0$ otherwise. Similarly, $\delta_{C_u}(i,j)=1$ if $v_i,v_j$ are in the same $C_u$, and $\delta_{C_u}(i,j)=0$ otherwise.

    Then considering
    \begin{equation}
        \Tr\left(S^TK^P(K^P)^TS\right)=\|(K^P)^TS\|_F^2,
    \end{equation}
    $i$-th entry of $(K^P)^TS$ is $\sum_{w=1}^r|C_u\cap P_w||P_w|$. Thus
    \begin{equation}
        \|(K^P)^TS\|_F^2=\sum_{u=1}^k\left(\sum_{w=1}^r|C_u\cap P_w||P_w|\right)^2.
    \end{equation}

    Using Cauchy-Schwarz Inequality, we have
    \begin{equation}\label{cauchy_schwarz}
        \left(\sum_{w=1}^r|C_u\cap P_w||P_w|\right)^2\le \sum_{w=1}^r|C_u\cap P_w|^2\sum_{w=1}^r|P_w|^2.
    \end{equation}
    Thus
    \begin{equation}
    \begin{split}
        Q^P&=\frac{1}{2m^P}\left[\sum_{u=1}^k\sum_{w=1}^r |C_u\cap P_w|^2-\frac{1}{2m^P}\sum_{u=1}^k\left(\sum_{w=1}^r|C_u\cap P_w||P_w|\right)^2\right]\\
        &\ge \frac{1}{2m^P}\left[\sum_{u=1}^k\sum_{w=1}^r |C_u\cap P_w|^2-\frac{1}{2m^P}\sum_{w=1}^r|C_u\cap P_w|^2\sum_{w=1}^r|P_w|^2\right]\\
        &=0.
    \end{split}
    \label{eq_fm_eq0}
    \end{equation}

    The equality of \eqref{cauchy_schwarz} and \eqref{eq_fm_eq0} holds when
    \begin{equation} \label{eq_equality}
        \frac{|C_u\cap P_1|}{|P_1|}=\frac{|C_u\cap P_2|}{|P_2|}=\cdots=\frac{|C_u\cap P_r|}{|P_r|}=c
    \end{equation}
    for any $u=1,\cdots,k$.

    Observing that $\sum_{w=1}^r|C_u\cap P_w|=|C_u|$ and $\sum_{w=1}^r|P_w|=n$, we obtain
    \begin{equation}
        c=\frac{|C_u|}{n}.
    \end{equation}
    So
    \begin{equation}
        \frac{|C_u\cap P_w|}{|C_u|}=\frac{|P_w|}{n}
    \end{equation}
    for any $u$ and $w$, which means that the partitioning is fair.
\end{proof}

\section{Properties of fairness-modularity}
\label{appendix_property}

The range of the {\em fairness-modularity} $Q^P$ can be further obtained as follows:
\begin{corollary}
    $0\le Q^P\le 1-\frac{1}{2m^P}$.
    \label{thm_range}
\end{corollary}
\begin{proof}
    According to the equation \eqref{eq_fm_eq0}, the lower bound of fairness-modularity is 0. The upper bound of fairness-modularity is similar to the clique \citep{np_completeness}. Suppose that the protected group network is divided into $r$ communities and each maximal clique is a community (in other words, it means $\mathbb{C}=\mathbb{P}$). This partition has modularity
    \begin{align}
        &\quad\frac{1}{2m^P}\left[\sum_{u=1}^k\sum_{w=1}^r |P_u\cap P_w|^2-\frac{1}{2m^P}\sum_{u=1}^k\left(\sum_{w=1}^r|P_u\cap P_w||P_w|\right)^2\right]\\
        &=\frac{1}{2m^P}\left[\sum_{w=1}^r|P_w|^2-\frac{1}{2m^P}\sum_{w=1}^r|P_w|^2\right]\\
        &=1-\frac{1}{2m^P}.
    \end{align}
\end{proof}

We can also prove that the fairness-modularity in the situation where every vertex belongs to a different community is
\begin{equation}
    \frac{1}{2m^P}\left(n-\frac{1}{2m^P}\sum_{w=1}^r|P_w|^3\right).
\end{equation}
This shows that the situation in which each node belongs to a different community is not a solution of $Q^P=0$. It excludes some trivial cases.

From the equality \eqref{eq_equality}, it is easy to see that
\begin{proposition}
    Given the fair community partition $\mathbb{C}=\{C_1,C_2,\cdots,C_k\}$, if the two communities $C_i$ and $C_j$ are merged into one community $\widetilde{C} = C_i\cup C_j$, then the new community partition
    \[
    \mathbb{C}=(\{C_1,C_2,\cdots,C_k\}\backslash\{C_i,C_j\})\cup\{\widetilde{C}\}
    \]
    is also a fair community partition.
\end{proposition}
This result implies that the number of communities does not affect the minimum of $Q^P$. Thus, the best number of communities depends only on the modularity $Q$.

\section{Datasets details}
\label{appendix_dataset}

\textbf{LFR benchmark:} The network generated by the LFR benchmark has the following parameters: 1000 nodes, an average degree exponent of 2, a community size exponent of 1.1, and a mixing parameter of 0.1, which features a minimum degree of 20 and a maximum degree of 100. The protected groups of vertices in the LFR network of Figure \ref{fig_lfr_prop} and Figure \ref{fig_lfr_metric} are uniformly sampled from the distribution $(0.5,0.5)$.

For the protected groups of Figure \ref{fig_lfr_net}, we randomly assign a probability $p_k$ ranging from 0.2 to 0.8 for each community $k$ and generate protected groups in the community $k$ from a binomial distribution $B(1,p_k)$. The method can generate unfair communities, while the proportion of protected groups in the whole network keeps nearly $1:1$.

\textbf{Synthetic clustering datasets:} The protected groups are obtained by random sampling of a given distribution. Synthetic-equal dataset has a distribution of $(0.5,0.5)$, which is a balanced dataset. Synthetic-unequal dataset has a distribution of $(0.02,0.48,0.5)$, which is an unbalanced dataset.

\textbf{Real datasets:} Adult dataset contains 32561 samples. Five numeric features of the dataset are chosen for using, and the protected group is gender.
Bank dataset contains 41188 samples. Six numeric attributes are chosen, and the protected group is marital status. We remove the samples with an "unknown" marital status.
Census1990 dataset is a large dataset that contains 2458285 samples. Twenty-five numeric attributes is chosen, and the protected group is gender.
Creditcard dataset contains 30000 samples. Attributes LIMIT\_BAL, AGE, BILL\_AMT1$\sim$6 and PAY\_AMT1$\sim$6 are chosen, and the protected group is sex.
Diabetic dataset contains 101766 samples. Seven numeric attributes are chosen, and the protected group is gender.
All of them are subsampled to 5000 samples.

FairFN processes network data, and we construct the network using $k$-nearest neighbor ($k=10$), as in VFC and FSCN.

