\subsubsection{Piecewise Sobolev Spaces and Inner Products}
\par We begin by defining the triangulation of the domain and associated sets:
\begin{itemize}
    \item Let $\mct$ denote a shape-regular simplicial triangulation of $\Ome$ \cite{FEM:BS2008,FEM:ciarlet2002finite} with mesh size $h := \max_{T \in \mct} h_T$, where $h_T$ is the diameter of the simplex $T \in \mct$.
    \item Let $\mce := \bigcup_{T \in \mct} \partial T$ denote the set of all edges in $\mct$.
    \item Let $\mce^B := \bigcup_{T \in \mct} \partial T \cap \partial \Ome$ indicate the set of boundary edges, while $\mce^I := \mce \setminus \mce^B$ represents the set of interior edges.
\end{itemize}

The set $W^{m,p}(\Ome)$ consists of all functions within $L^p(\Ome)$ whose weak derivatives up to order $m$ are also elements of $L^p(\Ome)$. In the special case where $p=2$, the space $H^m(\Ome)$, defined as $W^{m,2}(\Ome)$, becomes a Hilbert space. Furthermore, $W^{m,p}_0(\Ome)$ represents the subset of $W^{m,p}(\Ome)$ composed of functions whose traces vanish up to order $m-1$ on $\partial\Ome$. Accordingly, $H^m_0(\Ome)$ is equivalent to $W^{m,2}_0(\Ome)$. Additionally, given that $\Omega$ is a subset of $\mathbb{R}^2$, the index $i$ referenced in subsequent sections consistently assumes the values $i = 1, 2$.
\begin{itemize}
    \item Define the piecewise Sobolev spaces $W^{m.p}\left(\mathcal{T}_h\right)$ and $\bW^{m,p}(\mct)$ by:
    \begin{align*}  
        W^{m,p}(\mct)   & := \{v : v \vert_T \in W^{m,p}(T) \quad \forall T \in \mct \},                                            \\
        \bW^{m,p}(\mct) & :=\{\boldsymbol{v}: \boldsymbol{v} \vert_T \in W^{m,p}(T) \times W^{m,p}(T)  \quad \forall T \in \mct  \}.
    \end{align*}
    \item Define the inner products $\left(\cdot, \cdot\right)_{\mct}$ and $\langle \cdot, \cdot \rangle_{\mce}$, and norm $\|\cdot\|_{L^2(\mct)}$ by:
    \begin{align*}
        \ds (v, w)_{\mct} := \sum \limits_{T \in \mct}\int_T v  w \; dx,\; \; \ds \langle v, w \rangle_{\mce} := \sum \limits_{e \in \mce}\int_e v  w \; ds,\; \; \text{and} \; \; \|v\|^2_{\lt{\mct}} := (v, v)_{\mct}.
    \end{align*}
    \item Define the special subspaces $\cV_h$ and $\bcV_h$ by:
    \begin{align*}
        \cV_h:=W^{1,1}(\mct)\cap C^0(\mct) \qquad \text{and} \qquad \bcV_h:=\cV_h \times \cV_h.
    \end{align*}
\end{itemize}

\subsubsection{DG Spaces}
\begin{itemize}
    \item Define the DG space of piecewise linear polynomials $V_h$ by:
    \begin{align*}  
        V_h := \{v : v \vert_T \in \bbp_1(T) \; \; \forall T \in \mct \},
    \end{align*}
    where $\bbp_1(T)$ denotes polynomials of degree $\leq 1$ on $T$.
    \item Define the corresponding vector-valued space $\bV_h$ by:
    \begin{align*}
        \bV_h:= V_h \times V_h.
    \end{align*}
    \item[] Notice that $V_h \subset \cV_h$ and $\bV_h \subset \bcV_h$.
\end{itemize}

\subsubsection{Jump and Average Operators}
\begin{itemize}
    \item For $e = \partial T^+ \cap \partial T^- \in \mce^I$, define the jump and average operators by:
    \begin{align*}
    \jump{v}|_e:= v^+ - v^-,\qquad \avg{v}|_e:= \frac12\big( v^+ + v^-\big)\qquad \forall \, v\in \cV_h,
    \end{align*}
    where $v^\pm := v|_{T^\pm}$. Here, we denote $T^+$, $T^- \in \mct$ such that the global numbering of $T^+$ is more than that of $T^-$.
    \item For $e \in \mce^B$ (e.g., $e = \partial T^+ \cap \partial \Ome$), define the jump and average operators by:
    \begin{align*}
    \jump{v}|_e:= v^+,\qquad \avg{v}|_e:= v^+ \qquad \forall \, v\in \cV_h.
\end{align*}
\end{itemize}

\subsubsection{Trace Operators}
\begin{itemize}
    \item For $e \in \mce^I$, define $\bn_e = (n_e^{(1)},n_e^{(2)})^T := \bn_{T^-} \vert_{e} = -\bn_{T^+} \vert_{e}$ to be the unit normal vector. % $\bn_e = (n_e^{(1)},n_e^{(2)})^T := \bn_{T^+} \vert_{e} = -\bn_{T^-} \vert_{e}$
    \item Define the trace operators $Q_i^{\pm}(v)$ for $v \in \cV_h$ on edge $e \in \mce$ in the $x_i$ direction by:
    \begin{align*}
    \mathcal{Q}_i^+(v) :=
    \begin{cases}
        v \vert_{T^+} , & n_e^{(i)} > 0 \\
        v \vert_{T^-} , & n_e^{(i)} < 0 \\
        \{v\},          & n_e^{(i)} = 0 \\
    \end{cases}, \; \; \;
    \mathcal{Q}_i^-(v) :=
     & \begin{cases}
           v \vert_{T^-} , & n_e^{(i)} > 0 \\
           v \vert_{T^+} , & n_e^{(i)} < 0 \\
           \{v\},          & n_e^{(i)} = 0 \\
       \end{cases}.
    \end{align*}
    This definition allows us to interpret $Q_i^+(v)$ and $Q_i^-(v)$ (see Figure \ref{dgfec:sec-notation and discrete dg derivatives:fig:the trace operator}) as ``forward'' and ``backward'' limits in the $x_i$ direction on $e \in \mce^I$.
    \item For $e = \partial T^+ \cap \partial \Ome \in \mce^B$, we define $Q_i^+(v)$ by:
    \begin{align*}
        Q_i^{\pm}(v) := v^+.
    \end{align*}
\end{itemize}

