\subsection{The Discrete Problem} \label{sec:optimality condn}
%In this subsection, we present the DWDG formulation. First of all, 
We first present the first-order optimality conditions for the continuous problem \eqref{intro:sec-eocp:continuous minimization problem}/\eqref{intro:sec-eocp:reduced minimization problem}. It is standard that \eqref{intro:sec-eocp:continuous minimization problem}/\eqref{intro:sec-eocp:reduced minimization problem} is equivalent to the following  variational inequality:
\begin{align}\label{eocp:sec-optimality conditions:continuous VI}
    %\big(J'(\ol{u}),u - \ol{u}\big)_{\lt\Ome} & = 
    \big(A^{\star}\big(A(\ol{u})-y_d\big)+\beta \ol{u},u-\ol{u}\big)_{\lt\Ome} \; \;  \geq  \hspace{0.1in} 0 \qquad \forall u \in \Uad,
\end{align}
where $A^{\star}: \lt\Ome \rightarrow \lt\Ome$ is the adjoint operator of A.  Since for every $u \in \lt\Ome$ there exists a unique $y = A(u) \in \lt\Ome$, we define $p:=A^{\star}\big(A(u)-y_d\big) = A^{\star}(y - y_d) .$ As a result, we have the \emph{adjoint equation},
\begin{subequations}\label{eocp:sec-optimality conditions:adj eqn}
    \begin{empheq}{align}
        &-\Delta p = y - y_d \quad \text{ in } \Omega, \label{theADJ}\\
        &\hspace{0.31in} p = 0 \quad \hspace{0.275in} \text{ on } \Gamma.
    \end{empheq}
\end{subequations}
\par The solution to \eqref{eocp:sec-optimality conditions:adj eqn} is the \emph{adjoint state} $p \in H^1_0(\Ome).$ 
Finally, we have the following first-order optimality conditions for the solution $(\bar{y}, \bar{u}, \bar{p}) \in H^1_0(\Omega) \times H^1_0(\Omega) \times U_{ad}$: 
\begin{subequations}\label{eocp:sec-optimality conditions:continuous KKT}
    \begin{empheq}{align}
        (\nab\ol{y} , \nab{v})_{\lt{\Ome}} -
        (\ol{u} , v)_{\lt{\Ome}} &= 0 \qquad \forall v \in H^1_0(\Ome) \label{eocp:sec-optimality conditions:continuous KKT PDE weakform},  \\
        (\nab\ol{p} , \nab{v})_{\lt{\Ome}} - (\ol{y} - y_d, v)_{\lt{\Ome}} &= 0 \qquad \forall v \in H^1_0(\Ome) \label{eocp:sec-optimality conditions:continuous KKT adj weakform}, \\
        \big(\ol{p}+\beta \ol{u},u-\ol{u}\big)_{\lt\Ome} \; \; &\geq 0 \qquad \forall u \in \Uad \label{eocp:sec-optimality conditions:continuous KKT VI}.
    \end{empheq}
\end{subequations}
\par The coupled system \eqref{eocp:sec-optimality conditions:continuous KKT} is the first order necessary and sufficient optimality system for solving \eqref{intro:sec-eocp:continuous minimization problem}/\eqref{intro:sec-eocp:reduced minimization problem} because $J: H^1_0(\Ome) \times U_{ad} \rightarrow \mathbb{R}$ is a convex functional.  Furthermore, in view of \eqref{eocp:sec-optimality conditions:continuous KKT PDE weakform}-\eqref{eocp:sec-optimality conditions:continuous KKT adj weakform} and the convexity of the domain, we can guarantee the regularity of $\ol{y} \in H^2(\Ome)$ and $\ol{p} \in H^2(\Ome)$ (see \cite{OCP:elliptic:savare1998regularity, OCP:elliptic:troltzsch2010finite}). Also, using \eqref{eocp:sec-optimality conditions:continuous KKT VI}, it can be shown that $\ol{u} \in H^1(\Ome)$ (cf. \cite{OCP:elliptic:casas2003error} and the references therein).

Now we define the discrete admissible sets for the control variable by
\begin{align*}
    U_{ad,h}^{k} := \{v \in U_{ad}: v|_{T} \in \mathbb{P}_k(T) \; \; \forall T \in \mct \} \qquad \text{for}\; k \in \{0,1\}.
\end{align*} 
%\par The discrete state space is $V_h$ as defined earlier in Section \ref{sec:DG operators}. We follow the discretize-then-optimize approach. For a fixed $k,$ using $U_{ad,h}^k$, $V_h$, and the DWDG method, we obtain the following finite dimensional optimization problem by discretizing the problem \eqref{intro:sec-eocp:continuous minimization problem}:
Then the discrete problem is as follows:
\begin{subequations}\label{eocp:sec-optimality conditions:discrete minimization}
    \begin{empheq}{align}
        &\mini_{(y_h,u_h) \in V_h \times U_{ad,h}^k} &&J_h(y_h,u_h) := \frac{1}{2} \|y_h-y_{d}\|^2 + \frac{\beta}{2} \|u_h\|^2
        \label{eocp:sec-optimality conditions:discrete functional} \\
        &\text{subject to } &&a_h(y_h,v_h) = (u_h,v_h)_{\cT_h} \quad \forall v_h \in V_h
        \label{eocp:sec-optimality conditions:discrete weak form}
    \end{empheq}
\end{subequations}
where
\begin{align}\label{eq:ah}
     & a_h(v_h,w_h) :=\ds \frac{1}{2} \Big( \big(\nabla_{h,0}^+ v_h, \nabla_{h,0}^+ w_h\big)_{\cT_h} + \big(\nabla_{h,0}^- v_h, \nabla_{h,0}^- w_h\big)_{\cT_h} \Big) + \bigg\langle  \frac{\gamma_e}{h_e} \jump{v_h},\jump{w_h} \bigg\rangle_{\mce}
\end{align}
for $\gamma_e$, a parameter defined on $e \in \mathcal{E}_h$ that will be determined later. 

%{\color{red} add properties of a here.}
% and  $y_{d_h} \in V_h$ is the  $L^2$ projection of $y$.
\par Similar to the continuous case, there exists a unique solution pair: $(\ol{y}_h,\ol{u}_h) \in V_h \times U_{ad,h}^k$ satisfying \eqref{eocp:sec-optimality conditions:discrete minimization}. 
We define a discrete solution operator $A_h: U^k_{ad,h} \rightarrow V_h$ to \eqref{eocp:sec-optimality conditions:discrete weak form}   
and the discrete adjoint state $\ol{p}_h:=A_h^{\star}\left(A_h(\ol{u}_h) - y_{d}\right) = A_h^{\star}\left(\ol{y}_h - y_{d}\right) \in V_h$, where $A^{\star}_h$ denotes the adjoint operator of $A_h$. 
Finally, we have a discrete coupled system satisfied by $(\ol{y}_h, \ol{u}_h, \ol{p}_h) \in V_h \times U^k_{ad,h} \times V_h$:
\begin{subequations}\label{eocp:sec-optimality conditions:discrete KKT}
    \begin{empheq}{align}
        a_h(\ol{y}_h,v_h) &= (\ol{u}_h,v_h)_{\cT_h} \; \; &&\forall v_h \in V_h \label{eocp:sec-optimality conditions:discrete KKT PDE weakform},  \\
        a_h(\ol{p}_h,v_h) &= (\ol{y}_h - y_{d},v_h)_{\cT_h} \; \;  &&\forall v_h \in V_h\label{eocp:sec-optimality conditions:discrete KKT adj weakform}, \\
        \big(\ol{p}_h+\beta \ol{u}_h,u_h-\ol{u}_h\big)_{\cT_h} &\geq 0 \qquad &&\forall u_h \in \Uadh  \label{eocp:sec-optimality conditions:discrete KKT VI}.
    \end{empheq}
\end{subequations}
Similar to \eqref{eocp:sec-optimality conditions:continuous VI}, we have the following discrete variational inequality:
\begin{align}
        \big(A_h^{\star}(A_h\ol{u}_h-y_{d})+\beta \ol{u}_h,u_h-\ol{u}_h\big)_{\lt\Ome}  &\geq 0   \qquad \forall u_h \in U_{ad,h}^{k}. \label{sec:err estimate:discrete VI operator form}
\end{align}
