\section{An \emph{a Priori} Error Estimate of the Control Variable}\label{sec:a priori analysis}
%
In this section, we provide an \emph{a priori} error estimate for the control variable. We follow the standard approach in \cite{OCP:elliptic:casas2003error}. The key is to construct suitable projection operators. We also need the error estimates of DWDG methods for Poisson equations (cf. \cite{DWDG:LN2014}).

\subsection{Preliminary Estimates}

We introduce the following notations:
\begin{subequations}
    \begin{empheq}{align}
        \|v_h\|^2_{1,h} &:= \frac12 \Big( \|\nab_{h,0}^+ v_h\|_{L^2(\Ome)}^2
        + \|\nab_{h,0}^- v_h\|_{L^2(\Ome)}^2\Big) \qquad \forall \, v_h \in V_h, \\
        \energy{v_h} &:= \|v_h\|^2_{1,h} + \sum_{e\in \mce} \frac{\gamma_e}{h_e} \big\|\jump{v_h}\big\|_{L^2(e)}^2 \qquad \forall \, v_h \in V_h. \label{sec:a priori analysis:energynorm}
    \end{empheq}
\end{subequations}



\begin{theorem}\label{sec:a priori analysis:thm:estimate controlling the jump}
    Let $\gamma_{\min}:= \min_{e\in \mce} \gamma_e$. Then
    \begin{align}
        \gamma_{\min}\sum_{e\in \mce} h_e^{-1}\big\|\jump{v_h}\big\|_{L^2(e)}^2 \le \energy{v_h}^2 \qquad \forall \, v_h \in V_h. \label{sec:a priori analysis:controlling the jump by energy norm pos penalty}
    \end{align}
    provided $\gamma_{\min} > 0$. Moreover, if the triangulation $\mct$ is quasi-uniform and each $T \in \mct$ has at most one boundary edge, then there exists a constant $C_* > 0$ independent of h and $\gamma_e \hspace{0.05in} \forall e \in \mce$ such that
    \begin{align}
        \big(C_*+\gamma_{\min}\big)\sum_{e\in \mce} h_e^{-1}\big\|\jump{v_h}\big\|_{L^2(e)}^2 \le \energy{v_h}^2 \qquad \forall \, v_h\in V_h.
            \label{sec:a priori analysis:controlling the jump by energy norm neg penalty} 
    \end{align}
\end{theorem}
\begin{proof}
    The proof of Theorem \ref{sec:a priori analysis:thm:estimate controlling the jump} can be found in \cite{DWDG:LN2014}.
\end{proof} 
