\subsection{$\mathbb{P}_1$ Approximation of the Control}\label{sec:p1 approx control}

\par It was shown in \cite{PVI:kinderlehrer2000introduction} that the optimal control $\bar{u} \in W^{1, \infty}(\Omega)$. In this subsection, an improved bound on the error associated with the control variable is established in the $L^2$ norm when the finite-dimensional admissible set is $U_{ad,h}^{1}.$ 

\par Note that the $L^2$ projection of $\bar{u}$ does not belong to $U_{ad}$. Instead, we will consider the standard interpolation operator $\piho: \Uad\longrightarrow \ddUad$.  
%As in \cite{OCP:elliptic:rosch2006error}, we assume that the optimal control $\ol{u}$ is Lipschitz continuous. This assumption is supported by various examples in the literature (refer to \cite{PDAS:bergounioux1999primal} for instance). 
The following estimate (cf. \cite{FEM:BS2008}) is standard for $\bar{u}\in W^{1,\infty}(\Omega)$
\begin{equation}\label{eq:w1infesti}
    \|\bar{u}-\piho(\bar{u})\|^2_{L^2(T)}\le Ch^2_T\int_T |\nabla \bar{u}|^2\ \!dx\le Ch_T^2\|\bar{u}\|^2_{W^{1,\infty}(T)}\text{meas}(T)\le Ch_T^4\|\bar{u}\|^2_{W^{1,\infty}(T)}
\end{equation}
for any $T\in\cT_h$. However we need to modify the operator $\piho$ since it does not satisfy the orthogonal property with respect to the $L^2$ inner product as the operator $\Pi_h^0$ did in the previous section. 
When $h$ is sufficiently small, it is reasonable to assume there is no $T \in \mct$ such that $\min \limits_{\bar{T}} \olu = u_a$ and $\max \limits_{\bar{T}} \olu = u_b$ at the same time. We then define $\tluh \vert_T \in \ddUad$ as follows \cite{OCP:elliptic:rosch2005linear}:
\begin{align*}
    \tluh \vert_T:=
    \begin{cases}
        u_a,         & \min \limits_{\bar{T}} \olu = u_a \\
        u_b,         & \max \limits_{\bar{T}} \olu = u_b \;.\\
        \piho(\olu), & \text{otherwise}
    \end{cases}
\end{align*}


\begin{lemma}\label{eocp:sec-p1 approx control:lemma:auxiliary control satisfies continuous VI}
    For sufficiently small $h > 0$, we have 
    \begin{align}
    \big(\ol{p} + \beta \olu, u - \tluh \big)_{\ltO} \geq 0 \qquad \forall u \in U_{ad}.
    \end{align}
\end{lemma}
\begin{proof} 
    \par We decompose the domain $\Omega$ into three parts $\Ome = \Ome_a \cup \Ome_b \cup \mathcal{N}$, where 
    \begin{align*}
        \Ome_a &:= \{ x \in \Ome: \bar{u}(x) = u_a \}, \\
        \Ome_b &:= \{ x \in \Ome: \bar{u}(x) = u_b \}, \\
        \mathcal{N} &:= \Omega \setminus (\Ome_a \cup \Ome_b). 
    \end{align*}
    From \eqref{eocp:sec-optimality conditions:continuous KKT VI}, we conclude that $\ol{p} + \beta \olu \geq 0$ on $\Ome_a$, $\ol{p} + \beta \olu \leq 0$ on $\Ome_b$, and $\ol{p} + \beta \olu = 0$ on $\mathcal{N}$. 

    For any $u \in \Uad$ and $T \in \mathcal{T}_h$, we will show $\big(\ol{p} + \beta \olu, u - \tluh \big)_{T} \geq 0$. First, consider $T \in \mct$ in which there exists a $x \in T$ such that $\olu(x) = u_a$. Then, by definition, $\tluh = u_a $ on $T$. Thus, $u - \tluh \geq 0$ on $T$. For sufficiently small $h > 0$, we have $T \subset \Ome_a \cup \mathcal{N}$ and, thus, $\ol{p} + \beta \olu \geq 0$ on $T$. These imply $\big(\ol{p} + \beta \olu, u - \tluh \big)_{T} \geq 0$ on such a $T \in \mathcal{T}_h$. Similarly, consider $T \in \mct$ in which there exists a $x \in T$ such that $\olu(x) = u_b$. Then $u - \tluh = u - u_b \leq 0$ on $T$. In this case, we have $T \subset \Ome_b \cup \mathcal{N}$ and, thus, $\ol{p} + \beta \olu \leq 0$ on $T$ for sufficiently small $h > 0$. We also have $\big(\ol{p} + \beta \olu, u - \tluh \big)_{T} \geq 0$. Finally, consider $T \in \mct$ in which $\min \limits_{\bar{T}} \olu \neq u_a$ and $\max \limits_{\bar{T}} \olu \neq u_b$. Then $T \subset \mathcal{N}$. In this case, $\ol{p} + \beta \olu = 0$ and, thus, $\big(\ol{p} + \beta \olu, u - \tluh \big)_{T} = 0$. 
    % Consequently, on $T$, for any $u \in U_{ad}, \; u - \tluh \geq 0$. Since $\ol{p} + \beta \ol{u} \geq 0$ is a necessary condition for \eqref{eocp:sec-optimality conditions:continuous KKT VI} to be true, hence we have $\big(\ol{p} + \beta \olu, u - \tluh \big)_{\lt{T}} \geq 0$.
    % \par Next, when there exists $x \in T$ such that $\olu(x) = u_b$ then $\tluh = u_b$ on $T$. Thus, on $T$, for any $ u \in U_{ad}, \; u - \tluh \leq 0$. We then conclude that $\big(\ol{p} + \beta \olu, u - \tluh \big)_{\lt{T}} \geq 0$ as $\ol{p} + \beta \olu \leq 0$ since \eqref{eocp:sec-optimality conditions:continuous KKT VI} has to be satisfied.
    % \par Now, suppose $u_a < \olu <u_b$ on $T \in \mct$. Then, from \eqref{eocp:sec-optimality conditions:continuous KKT VI}, we can conclude that $J'(\ol{u}) = \ol{p} + \beta \olu = 0$ and $\big(\ol{p} + \beta \olu, u - \tluh \big)_{\lt{T}} = 0$. So the result follows.
\end{proof} 

To obtain improved error estimates, we introduce the following sets:
        \begin{align*}
            \omct &:= \{T \in \mct: \olu = u_a \text{ or } \olu = u_b\}, \\
            \twmct &:= \{T \in \mct: u_a < \olu < u_b\}, \\
            \thmct &:= \mct \setminus \left(\omct \cup \twmct \right).
        \end{align*}
        \par Notice that for any $T \in \thmct$, there exists $x_1, x_2 \in T$ such that $\olu(x_1) = u_a$ or $\olu(x_1) = u_b$ and $u_a<\olu(x_2)<u_b.$ Additionally, we suppose that there exists $C$ independent of $h$ such that \cite{OCP:superconvergenceOfControl}
\begin{align}\label{assump:thmct}
    \text{meas}(\thmct) \leq C h.
\end{align}
\begin{theorem}\label{eocp:sec-p1 approx control:thm:L2 err in exact and discrete control}
    % For $\ol{u} \in  U_{ad} \cap H^1(\Ome) \cap C^0(\ol{\Ome})$ and $\ol{u}_h \in \ddUad \subset U_{ad}$ the solutions of the problems - \eqref{intro:sec-eocp:continuous minimization problem} and \eqref{eocp:sec-optimality conditions:discrete minimization} respectively, there exists a constant C that depends on $\|\ol{u}\|_{H^1(\Omega)}$ and independent of $h$ such that \\
    % \begin{align}\label{linear conv control}
    %   \|\ol{u} - \ol{u}_h \|_{L^2(\Omega)} \leq Ch.
    % \end{align}
 %    Additionally, for $\olu \in U_{ad} \cap W^{1,\infty}(\Omega)$, there exists a constant C that depends on $|\ol{u}|_{W^{1,\infty}(\Omega)}$ and independent of $h$ such that \\
    % \begin{align}\label{higher order conv control}
    %   \|\ol{u} - \ol{u}_h \|_{L^2(\Omega)} \leq Ch^{\frac32}.
    % \end{align}
    Let $\olu \in U_{ad} \cap W^{1,\infty}(\Omega)$ and $\ol{u}_h \in \ddUad \subset U_{ad}$ be the solutions of the problems \eqref{intro:sec-eocp:continuous minimization problem} and \eqref{eocp:sec-optimality conditions:discrete minimization}, respectively. Assume the assumption \eqref{assump:thmct} holds. Then there exists a constant C that depends on $|\ol{u}|_{W^{1,\infty}(\Omega)}$ and is independent of $h$ such that
    \begin{align}\label{higher order conv control}
        \|\ol{u} - \ol{u}_h \|_{L^2(\Omega)} \leq Ch^{\frac32} 
    \end{align}
    for sufficiently small $h > 0$.
\end{theorem}

\begin{proof}
    \par Using Lemma \ref{eocp:sec-p1 approx control:lemma:auxiliary control satisfies continuous VI} and choosing $u = \ol{u}_h \in \ddUad \subset U_{ad}$, we have
        \begin{align}
            0 &\leq \left(\ol{p}+\beta \ol{u},\ol{u}_h-\tluh\right)_{\ltO} \label{sec:p1 approx control:p1 proof continuous VI}.
        \end{align}
    By choosing $u_h = \tluh \in U^1_{ad,h}$ in the inequality \eqref{sec:err estimate:discrete VI operator form}, we have
    \begin{align}
        0 &\leq \big(-\left(\ol{p}_h + \beta \oluh\right) ,\ol{u}_h-\tluh \big)_{\ltO} \label{sec:p1 approx control:p1 proof discrete VI}.
    \end{align}
    \par Adding the inequalities \eqref{sec:p1 approx control:p1 proof continuous VI} and \eqref{sec:p1 approx control:p1 proof discrete VI}, we have
        \begin{align*}
              0 &\leq \big(\ol{p} - \ol{p}_h + \beta(\ol{u} - \ol{u}_h), \ol{u}_h - \tluh\big)_{\ltO} \notag \\
                  &= \left(\ol{p} - \ol{p}_h,\ol{u}_h - \tluh \right)_{\ltO} + \beta\left(\ol{u} - \ol{u}_h, \ol{u}_h - \tluh\right)_{\ltO} \notag \\
                  &=\left(\ol{p} - \ol{p}_h,\ol{u}_h - \tluh \right)_{\ltO} - \beta \|\ol{u} - \oluh\|^2_{\ltO} + \beta \left(\ol{u} - \oluh, \ol{u} - \tluh \right)_{\ltO}.
            \end{align*}
        \par Consequently,
            \begin{align}
                 \|\ol{u} - \oluh\|^2_{\ltO} &\leq\dfrac{1}{\beta}\left(\ol{p} - \ol{p}_h,\ol{u}_h - \tluh \right)_{\ltO} + \left(\ol{u} - \ol{u}_h, \ol{u}_h - \tluh\right)_{\ltO} \notag \\
                  &=\dfrac{1}{\beta}\left(\ol{p} - \ol{p}_h,\ol{u}_h - \ol{u} \right)_{\ltO} + \dfrac{1}{\beta}\left(\ol{p} - \ol{p}_h,\ol{u} - \tluh \right)_{\ltO} + \left(\ol{u} - \oluh, \ol{u} - \tluh \right)_{\ltO} \notag \\
                  &\leq \dfrac{1}{\beta}\left(\ol{p} - \ol{p}_h,\ol{u}_h - \ol{u} \right)_{\ltO} + \dfrac{1}{\beta}\left(\ol{p} - \ol{p}_h,\ol{u} - \tluh \right)_{\ltO} +  C\eps_1\|\ol{u} - \oluh\|^2_{\ltO} + \dfrac{C}{\eps_1}\|\ol{u} - \tluh \|^2_{\ltO} \notag \\
                  &=\underbrace{\dfrac{1}{\beta}\left(A^{\star}\left(A\ol{u} - y_d\right)-A_h^{\star}\big(A_h\ol{u}_h - y_d\right), \ol{u}_h-\ol{u}\big)_{\lt{\Ome}}}_{S_1} \notag \\
                  &\hspace{0.2in}+\underbrace{\dfrac{1}{\beta}\big(A^{\star}\left(A\ol{u} - y_d\right)-A_h^{\star}\left(A_h\ol{u}_h - y_d\right), \ol{u}-\tluh\big)_{\lt{\Ome}}}_{S_2} \notag\\
                  &\hspace{0.2in}+C\eps_1\|\ol{u} - \oluh\|^2_{\ltO} + \dfrac{C}{\eps_1}\|\ol{u} - \tluh \|^2_{\ltO}. \label{intermediatebound}
            \end{align}
        \par To estimate the terms $S_1$ and $S_2$, we follow the steps of the inequalities \eqref{boundT1}--\eqref{boundT2} to arrive at
        \begin{align}
            |S_1| &\leq Ch^4 (\|\ol{u}\|_{\ltO}^2 + \|y_d\|_{\ltO}^2) + \eps_2 \; \|\ol{u} - \oluh\|^2_{\ltO} \label{boundT7},\\
            |S_2| &\leq Ch^4 (\|\ol{u}\|_{\ltO}^2 + \|y_d\|_{\ltO}^2) + \eps_3 \; \|\ol{u} - \tluh\|^2_{\ltO}. \label{boundT8}
        \end{align}
        \par By combining the inequalities \eqref{intermediatebound}--\eqref{boundT8} and by appropriately choosing $\eps_1, \eps_2, \eps_3$, we have
        \begin{align} \label{link intermediate estimate}
            \|\ol{u} - \oluh\|^2_{\ltO} &\leq  Ch^4 (\|\ol{u}\|_{\ltO}^2 + \|y_d\|_{\ltO}^2) + C\|\ol{u} - \tluh\|^2_{\ltO}.
        \end{align}
        \par The remaining task is to estimate $\|\ol{u} - \tluh\|^2_{\ltO}.$ %Before estimating $\|\olu - \tluh\|^2_{\ltO}$, 
        % Further, we assume that there exists a $C$ independent of $h$ such that $meas(\thmct) \leq Ch$.
        Consider 
        \begin{align*}
            \|\olu - \tluh\|^2_{\ltO} = \underbrace{\sum_{T \in \omct} \|\olu - \tluh\|^2_{\lt{T}}}_{S_3} + \underbrace{\sum_{T \in \twmct} \|\olu - \tluh\|^2_{\lt{T}}}_{S_4} + \underbrace{\sum_{T \in \thmct} \|\olu - \tluh\|^2_{\lt{T}}}_{S_5}.
        \end{align*}
        \par By the definition of $\tluh$ and $\omct$, We have $S_3 = 0$. 
        \par To estimate $S_4$, it follows from the definition of $\tluh$ and \eqref{eq:w1infesti} that
        \[S_4 = \sum_{T \in \twmct} \|\olu - \tluh\|^2_{\lt{T}} =  \sum_{T \in \twmct} \|\olu - \piho(\olu)\|^2_{\lt{T}} \leq Ch^4 \|\olu\|^2_{W^{1,\infty}(\twmct)}.\]
        \par Before estimating $S_5$, for any $T \in \thmct$, consider $\hat{x}_T \in T$ such that, without loss of generality, $\olu(\hat{x}_T) = u_a$. Note that, for $T\in \cT_{h,3},$ there holds
        \begin{align*}
                    \|\ol{u} - \tluh\|^2_{\lt{T}}   &= \|\ol{u} - u_a\|^2_{\lt{T}} \\
                                                            &= \ds \int_{T} |\ol{u} - u_a|^2 \; dT \\
                                                            &= \ds \int_{T} |\ol{u}(x) - \ol{u}(\hat{x}_T)|^2 \; dT \\
                                                            &=  \ds \mathlarger{\mathlarger{\int}}_{T} \left|\sum_{|\alpha|=1} \left(x - \hat{x}_T\right)^\alpha \int_0^1\dfrac{1}{\alpha!}D^\alpha \olu\big(x + s(\hat{x}_T - x)\big)\;ds \right|^2 \; dT \\
                        % &= \ds \int_{T} \left|(x_1 - \hat{x}_{T,1})\int_0^1\partial_{x_1}\olu\left(x + s(\hat{x} - x)\right)\;ds + (x_2 - \hat{x}_{T,2})\int_0^1\partial_{x_2}\olu\left(x + s(\hat{x} - x)\right)\;ds \right|^2 \; dx \\
                        % &= \ds \int_{T} \left|\int_0^1(x_1 - \hat{x}_{T,1})\partial_{x_1}\olu\left(x + s(\hat{x} - x)\right) +(x_2 - \hat{x}_{T,2})\partial_{x_2}\olu\left(x + s(\hat{x} - x)\right) \;ds \right|^2 \; dx \\
                        &= \ds \int_{T} \left|\int_0^1 (x - \hat{x}_T) \cdot \nabla\olu\big(x + s(\hat{x}_T - x)\big) \; ds \right|^2 \; dT \\
                        &\leq \ds \int_{T} \int_0^1\left|(x - \hat{x_T})\right|^2 \; ds  \int_0^1\left|\nabla\olu\big(x + s(\hat{x}_T - x)\big)\right|^2 \; ds \; dT \\
                        &\leq C h_{T}^2 \ds  \int_0^1   \int_{T}\|\nabla\olu\|^2_{L^{\infty}(T)} \; dT \; ds \\
                        &\leq C h_{T}^2 \ds  \int_0^1   \|\nabla\olu\|^2_{L^{\infty}(T)} \int_{T} 1 \; dT \; ds \\
                        &\leq C h_{T}^2 \|\nab \olu \|^2_{L^{\infty}(T)} \text{meas}(T).
                    \end{align*}                   
        \par Using the assumption \eqref{assump:thmct}, we have 
        \begin{align}
            S_5 = \sum_{T \in \thmct} \|\olu - \tluh\|^2_{\lt{T}} 
            %\leq \sum_{T \in \thmct} C h_{T}^3 \|\nab \olu \|^2_{L^{\infty}(T)}
            \leq Ch^{3} |\ol{u}|_{W^{1,\infty}(\thmct)}.
        \end{align}
        \par Ultimately, the desired estimate \eqref{higher order conv control} is obtained by combining the inequality \eqref{link intermediate estimate} with the bounds for $S_3,S_4,$ and $S_5.$
