\subsection{An a priori Error Estimate on the State and the Adjoint State}\label{eocp:sec-state}
\par This section is devoted to estimating $\energy{\ol{y} - \ol{y}_h}$ and $\energy{\ol{p} - \ol{p}_h}$. 
%Using the analysis in \cite{DWDG:LN2014, EVI:DWDG:LRZ2020}, 
We will first establish an intermediate error estimate for $\energy{\ol{y} - y_h(\olu)}$, where $y_h(\olu)$ satisfies %that we use in the subsequent analysis: %$\\| y(u) - y_h(u) \\| \leq Ch \quad \forall u \in U_{ad}$. \par Consequently,
%\begin{align}
%   \energy{\ol{y} - y_h(\olu)} \leq Ch \label{sec:state:dwdg err estimate}
%\end{align}
\begin{align}
a_h\big(y_h(\ol{u}), v_h\big) = (\ol{u},v_h)_{\cT_h} \qquad \forall v_h \in V_h.
\end{align} %and $C > 0$ is a constant independent of $h$.

\begin{lemma}\label{sec:state:lemma:intermediate result}
    There exists a $C > 0$ independent of $h$ such that
    \begin{align*}
        \energy{ y_h(\olu) -  \ol{y}_h} \leq C \|\olu - \oluh \|_{\lt{\Ome}}.
    \end{align*}
    %where $y_h(\olu)$ satisfies $a_h\big(y_h(\olu), v_h\big) = (\olu,v_h) \; \; \forall v_h \in V_h$.
\end{lemma}
\begin{proof}
    \par Note that, by definition,
    \begin{align*}
        \energy{ y_h(\olu) -  \ol{y}_h }^2
         & =
        a_h\big( y_h(\olu) -  \ol{y}_h,y_h(\olu) -  \ol{y}_h \big) \notag \\
         & =
        \big(\olu - \oluh,y_h(\olu) -  \ol{y}_h\big)_{\lt{\Ome}} \notag   \\
         & \leq
        \|\olu - \oluh \|_{\lt{\Ome}} \; \|y_h(\olu) -  \ol{y}_h\|_{\lt{\Ome}}.
    \end{align*}
    \par By Lemma \ref{sec:a priori analysis:lemma:DWDG Poincare},  we have
    \begin{align*}
        \|y_h(\olu) -  \ol{y}_h\|_{\lt{\Ome}} \leq C \energy{y_h(\olu) -  \ol{y}_h}.
    \end{align*}
    \par Hence, we have
    \begin{align}
        \energy{y_h(\olu) -  \ol{y}_h}^2 \leq C \|\olu - \oluh \|_{\lt{\Ome}} \; \energy{y_h(\olu) -  \ol{y}_h}. 
        %\label{sec:state:consequence of DWDG Poincare}.
    \end{align}
    The desired result immediately follows.
    % \par Finally, by dividing both sides of inequality \eqref{sec:state:consequence of DWDG Poincare} by $\energy{y_h(\olu) -  \ol{y}_h}$, and applying Theorems \ref{sec:p0 approx control:thm:L2 err in exact and discrete control} and \ref{eocp:sec-p1 approx control:thm:L2 err in exact and discrete control}, we obtain the desired result.
\end{proof}
\begin{theorem} \label{sec:state:thm:energy err in exact and discrete state}
    Let $\ol{y} \in  H^2(\Ome)$ and $\ol{y}_h \in V_h$ be the solutions of the problems \eqref{intro:sec-eocp:continuous minimization problem} and \eqref{eocp:sec-optimality conditions:discrete minimization}, respectively. There exists a constant C that depends on $|\ol{y}|_{H^2(\Omega)}$ and is independent of $h$ such that \\
    \begin{align*}
        \energy{\ol{y} - \ol{y}_h} \leq Ch.
    \end{align*}
\end{theorem}
\begin{proof}
    \par Note that $\bar{y}_h(\bar{u})$ is the DWDG approximation of $\bar{y}$ defined by \eqref{eocp:sec-optimality conditions:continuous KKT PDE weakform}; hence, we have (cf. \cite{DWDG:LN2014}) $$\energy{\bar{y}-\bar{y}_h(\bar{u})}\le Ch.$$ Therefore, by the triangle inequality, we have
    \begin{equation}
        \energy{\bar{y}-\bar{y}_h}\le \energy{\bar{y}-\bar{y}_h(\bar{u})}+\energy{\bar{y}_h(\bar{u})-\bar{y}_h}\le Ch
    \end{equation}
    where we used Lemma \ref{sec:state:lemma:intermediate result}, Theorem \ref{sec:p0 approx control:thm:L2 err in exact and discrete control}, and Theorem \ref{eocp:sec-p1 approx control:thm:L2 err in exact and discrete control}.
    %and, inequality \eqref{sec:state:dwdg err estimate}, 
    %the desired estimate follows.
\end{proof}
