%\section{An \emph{a priori} Error Estimates on the Adjoint Variable}\label{eocp:sec-adj}
\par %In this section, 
Next, we state a theorem that provides the error estimate for the adjoint state in the energy norm. First, we prove the following lemma:

\begin{lemma} \label{sec:adj:lemma:intermediate result}
    Let $\ol{y} \in  H^2(\Ome)$ be the solution of the problem \eqref{intro:sec-eocp:continuous minimization problem}. There exists a constant C that depends on $|\ol{y}|_{H^2(\Omega)}$ and is independent of $h$ such that \\
    \begin{align*}
        \energy{p_h(\ol{y}) - \ol{p}_h} \leq Ch,
    \end{align*}
    where  $p_h(\ol{y})$ satisfies $a_h\big(p_h(\ol{y}), v_h\big) = (y_{d} - \ol{y},v_h)_{\cT_h} \quad \text{for all } v_h \in V_h$.
\end{lemma}
\begin{proof}
    \par We have by the definition of $\energy{\cdot}$ that
    \begin{align*}
        \energy{p_h(\ol{y}) - \ol{p}_h}^2 & = a_h \big( p_h(\ol{y}) - \ol{p}_h , p_h(\ol{y}) - \ol{p}_h \big)                \\
                                          & = \big(y_{d} - \ol{y} - (y_{d} - \ol{y}_h), p_h(\ol{y}) - \ol{p}_h\big)_{L^2(\Ome)}  \\
                                          & = \big(\ol{y}_h - \ol{y}, p_h(\ol{y}) - \ol{p}_h\big)_{L^2(\Ome)}                        \\
                                          & \leq \|\ol{y}_h - \ol{y}\|_{L^2(\Ome)} \; \|p_h(\ol{y}) - \ol{p}_h\|_{L^2(\Ome)}.
    \end{align*}
    \par Notice that by Lemma \ref{sec:a priori analysis:lemma:DWDG Poincare}, $\|p_h(\ol{y}) - \ol{p}_h\|_{L^2(\Ome)} \leq \energy{p_h(\ol{y}) - \ol{p}_h}$.
    Subsequently, let $\Pi_h (\ol{y})$ be the standard nodal interpolant of $\ol{y}$ in $V_h$. By using the triangle inequality and Lemma \ref{sec:a priori analysis:lemma:DWDG Poincare}, we have
    \begin{align}
         \|\ol{y}_h - \ol{y}\|_{L^2(\Ome)} 
         %&= \|\ol{y}_h -\Pi_h(y) + \Pi_h(y) - \ol{y}\|_{L^2(\Ome)} \notag                                                                                                                      \\
         & \leq \|\ol{y}_h -\Pi_h(\ol{y}) \|_{L^2(\Ome)} + \|\Pi_h(\ol{y}) - \ol{y}\|_{L^2(\Ome)} \notag                                                                                 \\
         & \leq \energy{\ol{y}_h -\Pi_h(\ol{y})}+ \|\Pi_h(\ol{y}) - \ol{y}\|_{L^2(\Ome)}    \notag                                                                                      \\
         %& = \energy{\ol{y}_h - \ol{y} + \ol{y} -\Pi_h(\ol{y})}+ \|\Pi_h(\ol{y}) - \ol{y}\|_{L^2(\Ome)}     \notag                                                                      \\
         & \leq\energy{\ol{y}_h - \ol{y}} + \energy{\ol{y} -\Pi_h(\ol{y})}+ \|\Pi_h(\ol{y}) - \ol{y}\|_{L^2(\Ome)}\label{sec:adj:consequence of DWDG Poincare and nodal interpolation}.
    \end{align}
    \par It is standard that $\|\Pi_h(\ol{y}) - \ol{y}\|_{L^2(\Ome)} \leq Ch^2 |\ol{y}|_{H^2(\Ome)}$ (cf. \cite{FEM:BS2008,FEM:ciarlet2002finite}) and $\energy{\ol{y} -\Pi_h(\ol{y})} \leq Ch |\ol{y}|_{H^2(\Ome)}$ (cf. \cite{EVI:DWDG:LRZ2020}).
     Finally, by Theorem \ref{sec:state:thm:energy err in exact and discrete state}, we have the desired estimate.
\end{proof}
\begin{theorem} \label{sec:adj:thm:energy err in exact and discrete adj}
    Let $\ol{p} \in  H^2(\Ome)$ and $\ol{p}_h \in V_h$ be the solutions to \eqref{eocp:sec-optimality conditions:continuous KKT adj weakform} and \eqref{eocp:sec-optimality conditions:discrete KKT adj weakform}, respectively. There exists a constant C that depends on $|\ol{p}|_{H^2(\Omega)}$ and is independent of $h$ such that \\
    \begin{align*}
        \energy{\ol{p} - \ol{p}_h} \leq Ch.
    \end{align*}
\end{theorem}
\begin{proof}
    Due to a similar argument as used in Theorem \ref{sec:state:thm:energy err in exact and discrete state} and the analysis presented in \cite{DWDG:LN2014, EVI:DWDG:LRZ2020}, it follows that $\energy{\ol{p} - p_h(\ol{y})} \leq Ch.$ The final result then follows from Lemma \ref{sec:adj:lemma:intermediate result} and the triangle inequality.
\end{proof}

