\section{Numerical Experiments}\label{eocp:sec-numerical experiments}
\par In this section, we present several numerical examples to demonstrate the robustness of the proposed scheme and validate the theoretical results. These examples are generated using in-house MATLAB codes. The finite-dimensional problem obtained through the DWDG method is solved using the primal-dual active set algorithm \cite{PDAS:bergounioux1999primal,PDAS:hintermuller2002primal}.

\subsection{Example 1}\label{eocp:ex1}
\par In this example, we set $u_a = -\infty$, $u_b = \infty$, $y_d = (1+4\pi^4) \sin(\pi x_1) \sin(\pi x_2) $ and seek $(\ol{y}_h,\ol{u}_h,\ol{p}_h) \in V_h \times \Uadh \times V_h$ for $k \in \{0,1\}$ which solves the system \eqref{eocp:sec-optimality conditions:discrete KKT} on $\Ome = [0,1]^2$. This is an optimal control problem without control constraints.
\par The exact solution $(\ol{y},\ol{u},\ol{p}) \in H^2(\Ome) \times U_{ad} \times H^2(\Ome)$ is given by 
\begin{subequations}\label{sec:num results:ex1 exact solution}
    \begin{empheq}{align}
        \ol{y}(x_1,x_2) &= \sin(\pi x_1) \sin(\pi x_2) \label{sec:num results:ex1 exact y}\, ,
        \\
        \ol{u}(x_1,x_2) &= 2 \pi^2 \sin(\pi x_1) \sin(\pi x_2) \label{sec:num results:ex1 exact u}\, , \\
        \ol{p}(x_1,x_2) &= -2 \pi^2 \sin(\pi x_1) \sin(\pi x_2) \label{sec:num results:ex1 exact p}\, .
    \end{empheq}
\end{subequations}
\par Tables \ref{sec:num results:Table1:ex1_y_p0_u}, \ref{sec:num results:Table2:ex1_y_p1_u}, \ref{sec:num results:Table3:ex1_p_p0_u}, and \ref{sec:num results:Table4:ex1_p_p1_u} show the convergence of $\ol{y}_h$ to $\ol{y}$ and the convergence of $\ol{p}_h$ to $\ol{p}$ in the \emph{energy norm} for three different penalty parameters as $h \rightarrow 0$ respectively. We see a convergence of order 1 in the \emph{energy norm} as proved in Theorems \ref{sec:state:thm:energy err in exact and discrete state} and \ref{sec:adj:thm:energy err in exact and discrete adj}.
